  ('official_bank_bua205', 'keep', 1, $official_bank_source${"itemId":"2fb8d50b-9ce4-57f6-924e-8e0e614d12ce","revise":true,"payload":{"prompt":"Crisis communication becomes a governance priority primarily because ____","options":["Legal departments mandate frequent public statements","Internal reporting structures demand daily updates","Media organizations require constant content during emergencies","Unmanaged information gaps intensify public uncertainty and distrust"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"In a crisis, if official information is missing or unclear, rumours fill the gap and public uncertainty and distrust grow, so managing communication becomes a governance priority. Legal requirements (A), internal reporting demands (B) and media appetite for content (C) may exist, but they are not the main reason crisis communication matters for governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 2, $official_bank_source${"itemId":"d79de501-5455-5189-be17-ba86641c9227","revise":true,"payload":{"prompt":"Civic responsibility encourages citizens to protect __________________","options":["Personal authority","Public resources","Elite interests","Private advantage"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civic responsibility means citizens care for what belongs to everyone, so they are expected to protect public resources such as roads, schools and public funds. Options A, C and D point to personal or narrow gains, which is the opposite of acting as a responsible citizen."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 3, $official_bank_source${"itemId":"be20e1d3-f8c9-56a1-8c93-6500953b2e0d","revise":true,"payload":{"prompt":"In social contract ethics, injustice occurs when __________________","options":["Agreements favor some unfairly","Authority weakens","Laws change frequently","Traditions are abandoned"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Social contract ethics judges rules by whether all members could fairly accept them, so injustice arises when an agreement unfairly favours some people over others. Options B, C and D describe change or weakness in a system, which is not in itself unjust."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 4, $official_bank_source${"itemId":"5a765f39-7bab-5186-a3ff-06de1e399398","revise":true,"payload":{"prompt":"Transparency mechanisms in governance often involve __________________ access to records.","options":["Symbolic","Discretionary","Restricted","Public"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Transparency means information is freely available and directly accessible to the people affected by decisions, so it involves public access to records. Options B and C keep access in the hands of officials, and A suggests access that exists only on paper."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 5, $official_bank_source${"itemId":"1246e834-060b-5c1c-bc39-70c0669dd8b3","revise":true,"payload":{"prompt":"Stakeholder engagement enhances governance adaptability by incorporating __________________","options":["Diverse perspectives","Institutional uniformity","Static regulations","Hierarchical directives"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Bringing different stakeholders into governance adds diverse perspectives, which helps institutions spot new problems and adjust their policies. Options B, C and D describe sameness, fixed rules and top-down orders, which make governance less adaptable, not more."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 6, $official_bank_source${"itemId":"b1d62e66-d54b-5228-8ff6-ac9357c7836d","revise":true,"payload":{"prompt":"Effective leaders recognise that followers possess __________________","options":["No meaningful influence","Purely operational roles","Limited responsibility","Valuable skills and insights"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Modern thinking treats followers as partners in leadership who bring valuable skills, ideas and insights. Options A, B and C reflect the old view of followers as passive people who only carry out instructions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 7, $official_bank_source${"itemId":"648c350e-9fc2-56e1-a56b-1512b8533289","revise":true,"payload":{"prompt":"Public governance strengthens service delivery by __________________","options":["Reducing oversight","Encouraging discretion","Aligning processes with objectives","Limiting evaluation"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Public governance improves service delivery by making sure processes and resources are aligned with the objectives the service is meant to achieve. Options A, B and D weaken oversight and evaluation, which usually makes service delivery worse."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 8, $official_bank_source${"itemId":"d9e77569-4ac9-5e55-ac44-b8fbc3a3d74e","revise":true,"payload":{"prompt":"Leadership that adapts based on task complexity and follower capability is described as __________________","options":["Bureaucratic leadership maintaining order","Charismatic leadership inspiring loyalty","Autocratic leadership issuing commands","Situational leadership responding to needs"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Situational leadership holds that there is no single best style, so the leader adjusts how directive or supportive to be based on the task and on followers' ability and readiness. Options A, B and C describe fixed styles that do not change with the situation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 9, $official_bank_source${"itemId":"1af3b6c7-636d-5c41-aa8f-1b56c3c3028d","revise":true,"payload":{"prompt":"The Open Government Partnership links open governance to improved __________________ outcomes for society.","options":["Exclusionary","Developmental","Coercive","Restrictive"],"correctOption":1,"section":"Open Government Partnerships","explanation":"The Open Government Partnership links openness to better development outcomes, such as improved public services and more responsive policies. Options A, C and D are negative outcomes that open government is meant to prevent."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 10, $official_bank_source${"itemId":"ce4f3eeb-8f99-5b8e-8ba9-758d8768ef0d","revise":true,"payload":{"prompt":"When leaders motivate followers through contingent rewards tied directly to performance, the approach reflects __________________","options":["Transactional leadership","Democratic leadership","Charismatic leadership","Servant leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Transactional leadership is based on exchange: the leader rewards good performance and sanctions poor performance, and contingent reward is one of its main elements. Option C (charismatic) and option D (servant) rely on inspiration and serving followers, and option B (democratic) is about shared decision-making, not rewards."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 11, $official_bank_source${"itemId":"2093040f-be1a-5e71-a643-8c423e1e8a83","revise":true,"payload":{"prompt":"A leadership style that seeks to empower followers and encourage self-leadership reflects __________________","options":["Transactional leadership managing compliance","Bureaucratic leadership enforcing structure","Autocratic leadership centralizing power","Servant leadership emphasizing empowerment"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Servant leadership puts followers' needs and growth first and focuses on empowering them so they can lead themselves. Options A, B and C keep control with the leader through compliance, rules or centralised power."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 12, $official_bank_source${"itemId":"06f75c3a-b5bf-5cd7-b00a-3dc241d42b39","revise":true,"payload":{"prompt":"Open Government Partnership reforms often improve policy quality by __________________","options":["Incorporating diverse inputs","Centralizing decisions","Limiting consultation","Excluding stakeholders"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Open government reforms bring citizens and civil society into policy-making, and these diverse inputs help produce better-informed policies. Options B, C and D narrow participation, which goes against the whole idea of open government."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 13, $official_bank_source${"itemId":"d79850a2-0587-5e51-b928-b8df71b74dde","revise":true,"payload":{"prompt":"Public governance emphasizes long-term societal outcomes because __________________","options":["Short-term efficiency is irrelevant","Stakeholders prefer uncertainty","Markets determine social priorities","Public policies shape intergenerational welfare"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Public policies on matters such as education, health and the environment affect not just today's citizens but future generations, so public governance must look at long-term outcomes. Option A is wrong because efficiency still matters, and options B and C are not reasons governments focus on the long term."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 14, $official_bank_source${"itemId":"3df7f598-2ba6-5318-b1a8-9b307a0a5df0","revise":true,"payload":{"prompt":"Path-goal theory identifies directive, supportive, participative and __________________ leadership styles.","options":["Coercive","Achievement-oriented","Autocratic","Bureaucratic"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Path-goal theory says leaders help followers reach goals by choosing among four styles: directive, supportive, participative and achievement-oriented. Options A, C and D are not part of this theory; autocratic and bureaucratic are separate traditional styles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 15, $official_bank_source${"itemId":"271501b5-1563-5286-8a05-d4b5e7275b28","revise":true,"payload":{"prompt":"The Open Government Partnership emphasizes transparency as a means to improve __________________","options":["Dominance","Trust","Secrecy","Control"],"correctOption":1,"section":"Open Government Partnerships","explanation":"When governments open up information about their decisions and spending, citizens can see what is happening, and this builds trust between them and the state. Options A, C and D describe the closed, controlling behaviour that transparency is meant to replace."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 16, $official_bank_source${"itemId":"51723132-f484-54de-a64d-329d2bbc340e","revise":true,"payload":{"prompt":"Transparency initiatives help prevent misuse of __________________","options":["Private wealth","Personal data","Academic research","Public authority"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Transparency lets citizens see how officials use the power entrusted to them, which makes it harder to misuse public authority for personal gain. Options A, B and C are private or academic matters rather than the public power governance is concerned with."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 17, $official_bank_source${"itemId":"8ed7a29d-58cd-5d1c-bfa1-ccc0b3b2b37a","revise":true,"payload":{"prompt":"A leader guided by social contract theory bases authority primarily on __________________","options":["Collective agreement and legitimacy","Personal moral intuition","Inherited moral virtue","Religious doctrine"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Social contract theory explains government as arising from an agreement among members of society, so a leader's authority rests on collective agreement and the legitimacy it gives. Options B, C and D ground authority in personal feeling, inheritance or religion rather than agreement."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 18, $official_bank_source${"itemId":"6cc955da-e782-5776-a9a7-826346889370","revise":true,"payload":{"prompt":"Leadership legitimacy is strengthened when leaders ____","options":["Avoid follower input","Demonstrate fairness and competence","Exercise coercive control","Centralise power excessively"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Followers accept a leader as legitimate when they see the leader acting fairly and doing the job well. Ignoring follower input (A), using coercion (C) and over-centralising power (D) all weaken legitimacy because they make the leader look unfair or self-serving."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 19, $official_bank_source${"itemId":"a4449f76-262e-5db6-a7ef-f1018d5b7c10","revise":true,"payload":{"prompt":"Governance legitimacy is enhanced when procedures are perceived as __________________","options":["Fair","Opaque","Biased","Arbitrary"],"correctOption":0,"section":"Governance in the Public Services","explanation":"People accept the authority of an institution more readily when its procedures are fair, open and applied the same way to everyone. Options B, C and D (opaque, biased, arbitrary) all damage public trust and legitimacy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 20, $official_bank_source${"itemId":"67ee629d-936a-5cbd-b808-bdb98ca8c0b9","revise":true,"payload":{"prompt":"A leadership style that builds influence through credibility and values is __________________","options":["Bureaucratic leadership","Transactional leadership","Authentic leadership","Autocratic leadership"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Authentic leadership rests on self-awareness, a strong moral perspective and being true to one's values, so the leader's influence comes from credibility. Option B relies on rewards and sanctions, while A and D rely on rules and commands."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 21, $official_bank_source${"itemId":"eecf237b-c4b4-5418-806b-3aa580cccfd7","revise":true,"payload":{"prompt":"The emphasis on fairness and moral duty in leadership decision making is central to __________________","options":["Care ethics","Ethical egoism","Deontological philosophy","Moral relativism"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Deontology is the moral philosophy of duty: an action is right if it follows moral rules such as fairness, whatever the consequences. Option A centres on relationships and caring, option B on self-interest, and option D holds that morality simply varies by culture."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 22, $official_bank_source${"itemId":"cb4ac496-4748-5e63-99d5-e0895a5c9ef8","revise":true,"payload":{"prompt":"Clearly articulated service standards enhance __________________","options":["Participation","Inclusiveness","Adaptability","Predictability"],"correctOption":3,"section":"Governance in the Public Services","explanation":"When service standards are clearly stated, citizens know in advance what service to expect, how long it will take and how it will be delivered, which makes services predictable. Options A, B and C are also governance values, but they come from involving people or allowing flexibility, not from setting fixed standards."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 23, $official_bank_source${"itemId":"e4085835-d7fa-5f74-9be7-bce47db59249","revise":true,"payload":{"prompt":"Leadership moral reasoning shaped by cultural context reflects __________________","options":["Moral relativism","Deontological ethics","Virtue ethics","Ethical absolutism"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Moral relativism holds that what counts as right or wrong depends on the culture or context, so reasoning shaped by cultural context reflects this view. Options B and D treat moral rules as fixed and universal, while option C focuses on a leader's character traits."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 24, $official_bank_source${"itemId":"306e1d99-a953-5ed7-8f8b-75a7d2ba3541","revise":true,"payload":{"prompt":"Social contract ethics interprets rights as __________________","options":["Mutually recognized protections","Cultural symbols","Emotional claims","Absolute freedoms"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"In social contract thinking, rights are protections that members of society agree to recognise for one another as part of their agreement. Option D is wrong because people give up some freedoms under the contract, so rights are not unlimited; A and B miss the idea of mutual agreement."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 25, $official_bank_source${"itemId":"73c60507-0c6d-5a37-82e7-1de422fa6688","revise":true,"payload":{"prompt":"Social contract ethics interprets moral obligation as __________________","options":["Rationally accepted constraint","Inherited responsibility","Emotional commitment","Enforced duty"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Social contract ethics sees moral obligation as a limit that reasonable people freely accept because they benefit from living under shared rules. Option D sounds close, but the point of the contract is that the duty is accepted by agreement, not simply forced on people; B and C miss the role of reason."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 26, $official_bank_source${"itemId":"ffa73cc3-f8d6-55e7-a59c-eb60dc124ebf","revise":true,"payload":{"prompt":"Leadership effectiveness improves when followers perceive __________________ communication.","options":["Delayed","Selective","Restricted","Transparent"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Followers trust and cooperate more when leaders communicate openly and honestly, so transparent communication improves leadership effectiveness. Options A, B and C hold back information, which breeds suspicion and confusion."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 27, $official_bank_source${"itemId":"f7a3aeea-e11e-56ea-8728-cf02954c33c7","revise":true,"payload":{"prompt":"Stakeholder engagement supports innovation in governance by encouraging __________________","options":["Procedural finality","Administrative dominance","Collaborative problem-solving","Regulatory inertia"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Engaging stakeholders brings different groups together to work on problems jointly, and this collaborative problem-solving produces new ideas. Options A, B and D describe closed or rigid processes that discourage innovation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 28, $official_bank_source${"itemId":"20e2c311-2044-5991-9697-2f6d980cae7e","revise":true,"payload":{"prompt":"Leadership requires the capacity to __________________ others.","options":["Influence","Replace","Silence","Isolate"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leadership is commonly defined as a process of influencing, guiding and inspiring others towards shared goals. Options B, C and D describe pushing people aside, which is not leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 29, $official_bank_source${"itemId":"3c21996c-87b9-5176-9088-1cd043bffad8","revise":true,"payload":{"prompt":"A leadership style that motivates through contingent rewards is identified as __________________","options":["Transactional leadership using incentives","Laissez-faire leadership avoiding involvement","Transformational leadership inspiring change","Democratic leadership encouraging dialogue"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Contingent reward means followers receive rewards when they meet agreed targets, which is the core of transactional leadership. Option C (transformational) inspires through vision rather than rewards, option B gives little direction at all, and option D is about involving followers in decisions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 30, $official_bank_source${"itemId":"0ce3dbfa-18e5-54d1-96cc-ece32607b427","revise":true,"payload":{"prompt":"Open government practices are expected to enhance __________________ efficiency.","options":["Symbolic","Coercive","Administrative","Political"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Open government practices such as publishing data and simplifying public processes help agencies work faster and waste less, improving administrative efficiency. Options A and B are not goals of good governance, and D is not the type of efficiency open government targets."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 31, $official_bank_source${"itemId":"059e764a-301a-5950-988a-13cbfe637d7f","revise":true,"payload":{"prompt":"Situational leadership assumes leaders can __________________ their style.","options":["Adjust flexibly","Eliminate entirely","Permanently fix","Never change"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Situational leadership assumes there is no one best style, so leaders adjust their style flexibly to fit the task and the followers. Options C and D describe a fixed style, and option B would mean no leadership at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 32, $official_bank_source${"itemId":"92a45bb2-ae6b-5a76-9802-9f4bc7bcb0df","revise":true,"payload":{"prompt":"Leadership accountability mechanisms protect citizenship by ensuring __________________","options":["Dominance","Unchecked authority","Secrecy","Answerability"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Accountability means leaders must explain their actions and face consequences, so accountability mechanisms make leaders answerable to citizens. Options A, B and C describe the abuse of power that accountability is meant to prevent."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 33, $official_bank_source${"itemId":"c5ca0aa8-762b-5e3c-8ebf-acb2d2572ca6","revise":true,"payload":{"prompt":"Policy coherence in governance ensures that government actions are __________________","options":["Isolated across sectors","Aligned and mutually reinforcing","Driven by individual agencies","Contradictory in purpose"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Policy coherence means the actions of different ministries and agencies support one another instead of working against each other. Options A, C and D describe fragmented or conflicting policies, which is exactly what coherence avoids."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 34, $official_bank_source${"itemId":"2689d917-b1e4-5b3b-8c69-ac96f6ac1dbb","revise":true,"payload":{"prompt":"The Open Government Partnership promotes __________________, allowing governments to benchmark their progress against peers.","options":["Competitive secrecy","Unilateral reporting","Comparative accountability","Policy isolation"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Countries in the Open Government Partnership make public commitments that are reviewed and can be compared across members, which creates comparative accountability and lets governments benchmark against peers. Options A and D keep governments closed off, and B leaves out the shared review that makes comparison possible."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 35, $official_bank_source${"itemId":"c19d6522-681f-509e-8bc7-06a2207f67c7","revise":true,"payload":{"prompt":"Legal citizenship is usually acquired through birth, registration, or __________________","options":["Social participation","Long residence alone","Community service","Naturalisation"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizenship is legal membership of a country, and the usual legal routes are birth, registration and naturalisation; Nigeria's 1999 Constitution recognises these three. Option B is wrong because living in a country for a long time does not by itself make someone a citizen without formal naturalisation, while A and C are forms of civic activity, not legal routes."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 36, $official_bank_source${"itemId":"3a107f88-b823-5575-ab74-340bdadba89f","revise":true,"payload":{"prompt":"The concept of shared leadership emphasises that leadership roles can be __________________","options":["Eliminated in team settings","Distributed among group members","Replaced entirely by procedures","Restricted to top management only"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Shared leadership means leadership tasks are spread across members of a group, so different people lead at different times based on their skills. Option D is the opposite, keeping leadership at the top only, and options A and C remove people from leadership altogether."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 37, $official_bank_source${"itemId":"83642966-ffe5-514e-aa4f-9fcb248d08eb","revise":true,"payload":{"prompt":"The Open Government Partnership emphasizes learning from failure as a way to __________________","options":["Discourage experimentation","Restrict participation","Assign blame","Improve future reforms"],"correctOption":3,"section":"Open Government Partnerships","explanation":"Open government treats reform as a learning process, so failures are studied to see what went wrong and to design better reforms next time. Option C is tempting, but blaming people discourages honest reporting, and A and B would slow progress."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 38, $official_bank_source${"itemId":"0c053d14-ad9c-551d-8694-af15facb9f48","revise":true,"payload":{"prompt":"One major importance of governance in public services is that it promotes __________________ in the allocation of public resources.","options":["Discretionary favoritism","Political bargaining dominance","Fairness and equity","Informal negotiation outcomes"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Good governance applies rules and criteria openly, so public resources are shared fairly and equitably rather than by favour. Option B, along with A and D, describes resources being shared through influence and private deals, which is a failure of governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 39, $official_bank_source${"itemId":"4aace551-2336-50d6-bdb5-b4a4b959a676","revise":true,"payload":{"prompt":"Citizenship enables citizens to claim protection under __________________","options":["Personal authority","National law","Informal rules","Social customs"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizenship is a legal relationship with the state, and it entitles a person to the rights and protection provided under national law. Options C and D are informal norms that are not legally enforceable, and A is personal power rather than legal protection."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 40, $official_bank_source${"itemId":"cdac73dc-b1c7-578b-8a43-89149393217d","revise":true,"payload":{"prompt":"Governance professionalism requires adherence to __________________ standards.","options":["Shifting","Established","Informal","Political"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Professionalism in governance means following established standards, rules and codes consistently instead of changing them to suit individuals. Options A, C and D allow standards to bend to convenience or politics, which undermines professionalism."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 41, $official_bank_source${"itemId":"b65bf70a-eae1-56a4-8b4a-bd133f336c22","revise":true,"payload":{"prompt":"Regulatory reforms within the public sector focus on simplifying rules to reduce __________________","options":["Public sector employment levels","Administrative burden and compliance costs","Policy coordination mechanisms","Democratic accountability"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Regulatory reform simplifies rules and procedures so that citizens and businesses spend less time and money complying, reducing administrative burden and compliance costs. Option A confuses regulatory reform with downsizing, while C and D are things reforms aim to strengthen, not reduce."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 42, $official_bank_source${"itemId":"c50a93d7-7e42-5443-9564-96cd3f2ac366","revise":true,"payload":{"prompt":"Tracking reform performance using dashboards is an example of __________________","options":["Management information systems","Fiscal expenditure audit","Legislative oversight review","Ethical risk profiling"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Dashboards collect and display performance data for managers, which makes them a management information system tool for tracking reform progress. Options B, C and D are audit, oversight or risk exercises, not continuous data-tracking systems."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 43, $official_bank_source${"itemId":"a1ae278c-4552-57cb-bd7a-ce3b2a5df3c3","revise":true,"payload":{"prompt":"Public sector reforms that institutionalize outcome reporting aim to present __________________","options":["Achieved results against targets","Administrative secrecy","Activities only","Informal narratives"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Outcome reporting shows what was actually achieved compared with the targets that were set. Option C is tempting, but listing activities only describes effort and outputs, not results; B and D defeat the purpose of reporting."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 44, $official_bank_source${"itemId":"02f0a7a0-fec6-5ea9-9a79-86f4b87ff11b","revise":true,"payload":{"prompt":"Transparency requirements are generally more stringent in public governance due to __________________","options":["The protection of trade secrets","The presence of competitive markets","The use of public resources and authority","Contractual confidentiality obligations"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Public institutions spend taxpayers' money and exercise state power on behalf of citizens, so they are expected to be more open than private firms. Options A, B and D are reasons private companies may keep information confidential, not reasons for stricter public transparency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 45, $official_bank_source${"itemId":"a794964c-c74c-554c-b97a-7cf478c2b0b3","revise":true,"payload":{"prompt":"A core element in most leadership definitions is the ability to __________________","options":["Dominate discussion","Control resources","Influence behavior","Enforce compliance"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Most definitions describe leadership as the process of influencing people's behaviour towards shared goals. Option D is tempting, but enforcing compliance relies on formal authority, which is closer to management or command; A and B are not the core of leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 46, $official_bank_source${"itemId":"4a140bf3-d53c-55a8-8d50-07f11c5d44e4","revise":true,"payload":{"prompt":"Successful reforms emphasise __________________ management to align staff performance with reform goals.","options":["Personnel","Performance","Conflict","Crisis"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Performance management sets targets, appraises staff and links their work to the goals of the reform. Option A (personnel management) handles general staffing matters such as hiring and records, while C and D deal with conflicts and emergencies."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 47, $official_bank_source${"itemId":"64408911-cb7c-5c2b-a5e7-79bdd0546f4b","revise":true,"payload":{"prompt":"Leadership that derives influence from personal values and consistency rather than formal authority is __________________","options":["Authentic leadership","Transactional leadership","Autocratic leadership","Bureaucratic leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Authentic leaders influence others through self-awareness, a strong moral perspective and consistency between their values and actions, not through their position. Option D relies on rules and formal authority, B on rewards and sanctions, and C on control."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 48, $official_bank_source${"itemId":"d502cc71-66d7-5bc3-8ad4-53e9a05071f5","revise":true,"payload":{"prompt":"Laissez-faire leadership is sometimes described as __________________ leadership.","options":["Directive","Participative","Controlling","Absent"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire means 'leave it alone': the leader gives little or no direction and leaves followers to decide, which is why it is sometimes called absent leadership or non-leadership. Option C is the opposite, and A and B describe leaders who are actively involved."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 49, $official_bank_source${"itemId":"a0164dcd-1cf0-5370-8ad0-a6a768373c61","revise":true,"payload":{"prompt":"Leadership effectiveness declines when followers experience __________________","options":["Clarity of purpose","Role understanding","Chronic disengagement","Mutual trust"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"When followers are chronically disengaged, they stop contributing effort and ideas, so even a capable leader achieves less. Options A, B and D are conditions that improve leadership effectiveness, not reduce it."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 50, $official_bank_source${"itemId":"7843341c-a3a7-51f1-a926-67fa6ae342d5","revise":true,"payload":{"prompt":"In social contract reasoning, laws are justified when they __________________","options":["Promote stability regardless of fairness","Align with principles citizens would accept","Reflect the ruler's personal values","Preserve existing power hierarchies"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Social contract reasoning holds that a law is justified when it rests on principles that free, reasonable citizens would agree to. Option A ignores fairness, while C and D tie laws to the ruler or to existing power rather than to consent."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 51, $official_bank_source${"itemId":"5cd47e88-9fb3-5050-b9f2-f29e8dfb6c58","revise":true,"payload":{"prompt":"Public sector governance seeks to balance efficiency with __________________","options":["Secrecy","Centralization","Discretion","Equity"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Public sector governance aims to use resources efficiently while also treating all groups fairly, so efficiency is balanced with equity. Option C is tempting, but discretion is a tool officials use, not a goal to balance against efficiency; A and B are not governance goals."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 52, $official_bank_source${"itemId":"5cec5e45-742c-55f3-93d3-eb565f87b778","revise":true,"payload":{"prompt":"Leadership credibility is primarily built through ____","options":["Formal job titles","Organisational policies","Consistent words and actions","Hierarchical status"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Credibility grows when people see that a leader does what he or she says, again and again. Job titles (A), organisational policies (B) and hierarchical status (D) may give authority, but they do not make people believe and trust the leader."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 53, $official_bank_source${"itemId":"51cabbb7-f5b8-5bce-867b-cbb890b4f7fc","revise":true,"payload":{"prompt":"The importance of governance in public services is reflected in its role in reducing __________________ within public institutions.","options":["Administrative documentation","Public sector employment","Corruption and misuse of power","Institutional learning"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Good governance builds in transparency, accountability and sanctions, which reduce corruption and the misuse of power in public institutions. Options A, B and D are not problems that governance sets out to reduce; institutional learning, for example, is something it encourages."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 54, $official_bank_source${"itemId":"e9ee566b-ee56-5890-b5ee-eac4001758ea","revise":true,"payload":{"prompt":"Stakeholder engagement supports governance adaptability by facilitating __________________ feedback.","options":["Restricted","Filtered","Continuous","Delayed"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Governance can only adjust to change if it keeps hearing from stakeholders, so engagement supports adaptability through continuous feedback. Options A, B and D limit or slow the feedback, making it harder for institutions to respond."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 55, $official_bank_source${"itemId":"32309eb0-a027-5523-b087-1154dfccc670","revise":true,"payload":{"prompt":"Citizen participation strengthens governance by enhancing __________________","options":["Policy responsiveness","Centralized control","Elite dominance","Administrative isolation"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"When citizens take part in governance, leaders learn what people need and can shape policies to match, which makes policy more responsive. Options B, C and D concentrate power or cut government off from citizens, which participation works against."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 56, $official_bank_source${"itemId":"6eb03a87-0245-5f27-a3f0-0b83532445d4","revise":true,"payload":{"prompt":"Stakeholder participation enhances service delivery when it __________________","options":["Excludes users","Prioritizes administrative rules","Limits adaptability","Integrates user feedback into design"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Stakeholder participation improves service delivery when the views of service users are fed into how the service is designed. Option B keeps the focus on internal rules instead of users, and A and C shut users out or make the service rigid."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 57, $official_bank_source${"itemId":"068d977d-24be-56a5-9aac-9d3f34998087","revise":true,"payload":{"prompt":"The ethical goal of social contract reasoning is to make social rules __________________","options":["Culturally dominant","Fair and acceptable","Historically continuous","Emotionally compelling"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"The aim of social contract reasoning is to arrive at social rules that are fair and that every member of society could reasonably accept. Options A, C and D base rules on dominance, history or emotion rather than fair agreement."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 58, $official_bank_source${"itemId":"77e14bb5-b21a-554a-92e6-744b0dd9d262","revise":true,"payload":{"prompt":"Stakeholder engagement in public governance is closely linked to the principle of __________________","options":["Transparency","Procedural rigidity","Administrative autonomy","Institutional secrecy"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Engaging stakeholders means sharing information with them and explaining decisions, so it goes hand in hand with transparency. Option D is the opposite, and B and C keep institutions closed to outside input."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 59, $official_bank_source${"itemId":"c8197bcb-9e27-5606-a0d1-2ed8d6234551","revise":true,"payload":{"prompt":"Strengthening asset management systems under public sector reforms improves __________________","options":["Informal asset use","Discretionary control","Political influence","Tracking and utilization of public assets"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Asset management systems record and monitor government property, which improves the tracking and proper utilisation of public assets. Options A, B and C describe the informal or political use of assets that such systems are designed to stop."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 60, $official_bank_source${"itemId":"334bfc36-884d-550d-8966-fdf337d7a0ea","revise":true,"payload":{"prompt":"When a leader inspires followers through a compelling picture of the future, this reflects the quality of __________________","options":["Operational supervision","Rule enforcement","Vision","Routine administration"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Vision is a leader's ability to picture a desirable future and inspire people to work towards it. Options A, B and D are routine management tasks that keep things running but do not inspire."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 61, $official_bank_source${"itemId":"01fb29f4-cef0-5f98-9090-ce11fe8ea114","revise":true,"payload":{"prompt":"Social contract ethics assumes that moral rules gain strength from __________________","options":["Shared endorsement","Tradition","Authority","Fear"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Under social contract ethics, moral rules are strong because members of society share in endorsing them through their agreement. Options B, C and D ground rules in custom, power or fear rather than shared agreement."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 62, $official_bank_source${"itemId":"b778bca3-1bc7-589f-93fb-cfebb9ce7fa0","revise":true,"payload":{"prompt":"Regulatory governance ensures that rules are __________________","options":["Selectively applied","Arbitrarily enforced","Informally negotiated","Fairly implemented"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Regulatory governance makes sure that rules are applied fairly and consistently to everyone. Options A, B and C describe uneven, arbitrary or behind-the-scenes application of rules, which is poor governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 63, $official_bank_source${"itemId":"fab753f0-788f-5f38-a70d-100c8c9d69e5","revise":true,"payload":{"prompt":"Governance that balances immediate service delivery with future sustainability emphasizes __________________","options":["Responsiveness","Efficiency","Supervision","Strategic vision"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Strategic vision means looking beyond today's demands to plan for long-term sustainability while still meeting present needs. Option B is tempting, but efficiency is about making the best use of resources now, while A and C focus on immediate responses and control."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 64, $official_bank_source${"itemId":"354d8dbd-83de-5687-b28a-df4ec9ab6490","revise":true,"payload":{"prompt":"The establishment of service delivery benchmarks under public sector reforms enables __________________","options":["Administrative secrecy","Informal service variation","Political influence over agencies","Objective assessment of performance"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Benchmarks set clear service standards, so the performance of agencies can be measured objectively against them. Option B is what benchmarks are meant to reduce, and A and C would make performance harder to judge fairly."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 65, $official_bank_source${"itemId":"04872974-c708-5906-a576-f81f3af53e3e","revise":true,"payload":{"prompt":"Public sector reforms that integrate climate considerations aim to support __________________","options":["Political symbolism","Sustainability and resilience","Administrative secrecy","Short-term budgeting"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Building climate considerations into reforms helps the public sector plan for environmental risks, supporting sustainability and resilience. Option D is the opposite of long-term planning, and A and C have nothing to do with climate goals."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 66, $official_bank_source${"itemId":"6e670dbf-c84b-5998-a79b-08779c1b3fc9","revise":true,"payload":{"prompt":"Accountability mechanisms deter misconduct by increasing the likelihood of __________________","options":["Detection","Discretion","Concealment","Normalization"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Accountability mechanisms such as audits, reporting and oversight make it more likely that wrongdoing will be detected, which discourages misconduct. Option C is what accountability prevents, and B and D would make misconduct easier, not harder."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 67, $official_bank_source${"itemId":"453daa33-fafb-52a3-afc2-af36b87848d8","revise":true,"payload":{"prompt":"Leadership ethics guide decision-making by providing ____","options":["Procedural shortcuts","Authority justification","Moral principles and standards","Performance incentives"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Ethics gives leaders a set of moral principles and standards for judging what is right or wrong when making decisions. Procedural shortcuts (A), justifying authority (B) and performance incentives (D) are not ethical guides; ethics is about doing what is right, not what is convenient or rewarded."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 68, $official_bank_source${"itemId":"46747c6d-13c2-5468-aa96-df88abeb20a7","revise":true,"payload":{"prompt":"The social contract explains moral norms as sustained through __________________","options":["Fear alone","Tradition","Mutual expectation and trust","Emotion"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Social contract theory sees moral norms as lasting because people trust that others will keep to the agreement and expect the same of each other. Option A is tempting because fear features in some accounts of life before the contract, but norms in society are sustained by mutual expectation, not fear alone."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 69, $official_bank_source${"itemId":"bf702615-2915-53d2-96da-1d5e9f3f3fe7","revise":true,"payload":{"prompt":"Civic society organisations often act as a bridge between citizens and __________________","options":["Traditional families","The state","Private corporations","Foreign governments"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society organisations operate between the state and the private sector, representing citizens' interests and carrying their concerns to government. Option C is tempting, but the bridge they mainly provide is between citizens and the state; A and D are not their main role."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 70, $official_bank_source${"itemId":"6928dad9-b1ce-5e32-abda-2ccf119f54a9","revise":true,"payload":{"prompt":"Followership includes the responsibility to support leadership while maintaining __________________","options":["Dependence","Personal integrity","Passivity","Blind loyalty"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Good followership means supporting leaders while keeping one's own integrity, including the courage to question unethical practices. Options A, C and D describe passive or blindly loyal followers, who can enable poor leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 71, $official_bank_source${"itemId":"3c1c506a-e0c1-5c54-a11b-44a6b59c274f","revise":true,"payload":{"prompt":"A benefit of stakeholder participation is enhanced __________________, supporting trust-based governance relationships.","options":["Transparency norms","Discretionary secrecy","Administrative concealment","Institutional suspicion"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"When people participate in governance, decisions and information are shared more openly, which strengthens transparency norms and builds trust. Options B, C and D are signs of closed governance that participation helps to remove."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 72, $official_bank_source${"itemId":"45d36484-1bef-5e14-991e-33b3dbb1df10","revise":true,"payload":{"prompt":"Stakeholder-based governance enhances accountability by:","options":["Increasing mutual monitoring","Concentrating authority","Reducing transparency","Diffusing responsibility"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"When many stakeholders have a recognised role in governance, each group can watch, question and check the others, so no actor escapes scrutiny. This mutual monitoring is what makes those in authority answerable. Option D is tempting because responsibility is shared, but diffused responsibility makes it harder to hold anyone to account, while options B and C weaken accountability outright."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 73, $official_bank_source${"itemId":"930c8276-eeae-5786-9d3f-e9a41a816b90","revise":true,"payload":{"prompt":"Public sector governance requires mechanisms to manage:","options":["Market competition","Uncertainty and risk","Shareholder dividends","Private ownership"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Public bodies operate under uncertain conditions, from revenue shortfalls to emergencies, so good public governance includes systems for identifying and managing risk, such as internal control, audit and oversight. Option A is a market matter handled mainly through economic and regulatory policy, while shareholder dividends and private ownership (options C and D) belong to private sector governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 74, $official_bank_source${"itemId":"1f572e62-76be-5f17-a01f-0e9f014497d3","revise":true,"payload":{"prompt":"Civil society organisations often depend on ______ for their sustainability.","options":["Voluntary support","Compulsory levies","Judicial authority","State enforcement"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society organisations are voluntary, non-governmental bodies, so they survive mainly on voluntary support such as member contributions, donations, grants and volunteer time. Options D and B rely on state power, which would compromise their independence from government, and judicial authority (option C) belongs to the courts, not to civil society."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 75, $official_bank_source${"itemId":"975fdb3f-effd-5e2a-9e19-f543449f742b","revise":true,"payload":{"prompt":"Open consultation forums in governance primarily strengthen:","options":["Supervision","Participation","Rigidity","Hierarchy"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Open consultation forums, such as public hearings and town hall meetings, give citizens and stakeholders a direct voice in decisions before they are made, which is the essence of participation. Option A, supervision, is about overseeing work rather than involving people, and rigidity and hierarchy (options C and D) are the opposite of what open forums aim for."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 76, $official_bank_source${"itemId":"938db542-23f2-5e78-a3c3-2d62483a5bac","revise":true,"payload":{"prompt":"Leadership that treats moral rules as unbreakable in every situation reflects:","options":["Pragmatic ethics","Moral relativism","Ethical absolutism","Situational ethics"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Ethical absolutism holds that certain moral rules apply everywhere and must never be broken, whatever the circumstances or consequences. Situational ethics (option D) and moral relativism (option B) say that what is right depends on the situation or culture, and pragmatic ethics (option A) judges actions by what works in practice, so none of them treats rules as unbreakable."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 77, $official_bank_source${"itemId":"01a56d17-038d-5802-a0f3-4279b307e69d","revise":true,"payload":{"prompt":"Stakeholder engagement strengthens democracy by:","options":["Limiting representation","Broadening participation channels","Concentrating authority","Reducing deliberation"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Stakeholder engagement opens more ways for citizens and groups to take part in decisions, such as consultations, hearings and partnerships, which deepens democracy beyond voting at elections. Options A, C and D all shrink the space for public input, so they weaken democracy rather than strengthen it."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 78, $official_bank_source${"itemId":"5139ac0c-e214-5183-9abb-cd0a1c89363b","revise":true,"payload":{"prompt":"Hersey and Blanchard's Situational Leadership Theory emphasises adapting leadership style to the followers':","options":["Emotional stability","Maturity or readiness","Cultural background","Intelligence level"],"correctOption":1,"section":"An Overview of Leadership","explanation":"In Hersey and Blanchard's model, the leader chooses a style (telling, selling, participating or delegating) according to how able and willing followers are to perform a task, which is called their maturity or readiness. Culture, emotional stability and intelligence (options C, A and D) may matter in real life, but they are not the variable the model uses to choose a style."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 79, $official_bank_source${"itemId":"e25ece97-4990-54bc-b15f-e22b159d6957","revise":true,"payload":{"prompt":"Strategic leadership focuses on aligning ____","options":["Supervision with compliance","Daily routines with policies","Vision, resources, and capabilities","Authority with hierarchy"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Strategic leadership is about setting a long-term vision and then lining up the organisation's resources and capabilities so that vision can actually be achieved. Options A and B describe routine supervision and administration, while D is about formal structure, none of which is the strategic alignment the question describes."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 80, $official_bank_source${"itemId":"5986fcc4-beb4-5547-8e46-bfb7b0962024","revise":true,"payload":{"prompt":"In leadership studies, influence is best understood as the leader's capacity to ____","options":["Shape attitudes, beliefs, and behaviours","Impose sanctions consistently","Centralise decision-making authority","Dominate organisational structures"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Influence is the heart of leadership: it is the leader's ability to shape what people think, believe and do, usually without forcing them. Option B describes punishment, and C and D describe control over structures and decisions, which are forms of authority rather than true influence."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 81, $official_bank_source${"itemId":"b9e7a70a-b958-578a-a6da-d0641ad1088c","revise":true,"payload":{"prompt":"Leadership development focuses on enhancing ____","options":["Organisational control systems","Technical expertise alone","Positional authority","Influence and interpersonal capability"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Leadership development aims to grow a person's ability to influence, inspire and work well with others. Option B is too narrow because technical skill alone does not make someone a leader, and A and C are about control systems and formal position rather than personal leadership capability."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 82, $official_bank_source${"itemId":"39df62a0-863f-5ba3-b300-c224ca6c717d","revise":true,"payload":{"prompt":"Power derived from expertise is referred to as ____","options":["Reward power","Coercive power","Legitimate power","Expert power"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Expert power comes from the special knowledge, skill or experience a person has, which makes others willing to follow their lead. Reward power (A) rests on giving incentives, coercive power (B) on the ability to punish, and legitimate power (C) on holding a formal position."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 83, $official_bank_source${"itemId":"8b8ee44c-e3a7-53e7-a196-c805553e5c10","revise":true,"payload":{"prompt":"Leadership communication that builds alignment focuses on ____","options":["Information volume","Message clarity and relevance","Directive tone","Formal language"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Communication builds alignment when people clearly understand the message and see why it matters to them, so clarity and relevance are what count. Sending more information (A) can actually confuse people, and a directive tone (C) or formal language (D) does not by itself create shared understanding."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 84, $official_bank_source${"itemId":"b358be49-a5be-50a1-bdc2-c561323184b0","revise":true,"payload":{"prompt":"Leadership influence that develops through consistent expertise demonstrates ____","options":["Reward power","Legitimate power","Expert power","Referent power"],"correctOption":2,"section":"An Overview of Leadership","explanation":"When people follow a leader because that leader has repeatedly shown real knowledge and skill, the influence is expert power. Referent power (D) is tempting, but it comes from admiration and personal liking, not competence; reward power (A) and legitimate power (B) rest on incentives and formal position."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 85, $official_bank_source${"itemId":"06f682cf-8116-585d-967c-172a25c5300f","revise":true,"payload":{"prompt":"Relationship-oriented leadership places greatest emphasis on ____","options":["Interpersonal support and trust","Rigid performance monitoring","Technical supervision","Procedural control"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Relationship-oriented leaders focus on the people side of work: supporting followers, building trust and caring about their well-being. Options B, C and D all describe task-oriented behaviour, where the emphasis is on monitoring, supervising and controlling the work itself."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 86, $official_bank_source${"itemId":"4e9b8ac9-aac1-5b47-af22-0209309de90e","revise":true,"payload":{"prompt":"Leadership resilience refers to the capacity to ____","options":["Resist feedback","Maintain authority at all costs","Persist and adapt under pressure","Avoid challenges"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Resilience is the ability to keep going and adjust when things get hard, bouncing back from pressure and setbacks. Resisting feedback (A), holding on to authority at all costs (B) or avoiding challenges (D) are signs of rigidity or fear, not resilience."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 87, $official_bank_source${"itemId":"c743dd08-e82e-5e5b-b34d-6f8363696958","revise":true,"payload":{"prompt":"Effective leadership decision-making balances ____","options":["Analysis and judgement","Hierarchy and control","Compliance and enforcement","Speed and authority"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Good leadership decisions combine careful analysis of facts with sound judgement about the situation and people involved. Options B, C and D focus on control, enforcement and speed, which may matter at times but do not describe the balance that makes decisions effective."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 88, $official_bank_source${"itemId":"bc3de8bc-fa3e-5503-9990-1df03e4349ed","revise":true,"payload":{"prompt":"Leadership clarity reduces organisational ____","options":["Accountability","Participation","Innovation","Ambiguity and confusion"],"correctOption":3,"section":"An Overview of Leadership","explanation":"When a leader is clear about goals, roles and expectations, people know what to do, so ambiguity and confusion go down. Accountability (A), participation (B) and innovation (C) are things clear leadership should increase, not reduce."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 89, $official_bank_source${"itemId":"bebff8b7-7ffa-576a-9193-9d16b4dfc142","revise":true,"payload":{"prompt":"Leadership development through coaching prioritises ____","options":["Personalised feedback and growth","Authority reinforcement","Task surveillance","Directive instruction"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Coaching is a one-to-one development approach built around personalised feedback that helps a person grow. Reinforcing authority (B), watching over tasks (C) and simply giving instructions (D) are control activities, not coaching."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 90, $official_bank_source${"itemId":"29cbabe0-992a-5840-b952-4bfd058f7421","revise":true,"payload":{"prompt":"Leadership culture within an organisation reflects ____","options":["Individual leader traits","Market competition levels","Shared norms and values shaped by leaders","Formal policies alone"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Leadership culture is the set of shared norms and values that leaders shape and that people across the organisation come to live by. Option A is too narrow because culture is shared, not one person's traits; D is wrong because written policies alone do not create culture, and B is an external market factor."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 91, $official_bank_source${"itemId":"4dfeaa39-8ea6-53bd-95b8-8b4ee9f51940","revise":true,"payload":{"prompt":"Leadership succession planning focuses on ____","options":["Maintaining current structures","Immediate authority transfer","Developing future leadership capacity","Reducing training costs"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Succession planning means preparing people now so that capable leaders are ready to take over in future. It is not about keeping current structures unchanged (A), handing over authority on the spot (B) or cutting training costs (D); it is a long-term investment in leadership capacity."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 92, $official_bank_source${"itemId":"1a87b9c0-f829-5ae3-b560-1fc4241748fd","revise":true,"payload":{"prompt":"Leadership behaviour that focuses on structuring tasks and clarifying roles reflects ____","options":["Task-oriented leadership","Visionary leadership","Relationship-oriented leadership","Servant leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Task-oriented leaders concentrate on getting the work done by organising tasks, setting standards and making roles clear. Relationship-oriented leadership (C) focuses on people and support instead, while visionary (B) and servant leadership (D) emphasise future direction and serving followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 93, $official_bank_source${"itemId":"db512dd3-cd41-5c70-9d9d-7f6e4b0c894b","revise":true,"payload":{"prompt":"Leadership influence that endures beyond formal authority is rooted in ____","options":["Control systems","Enforcement power","Legitimacy and trust","Position"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Influence that lasts even when the leader has no formal power over people comes from being seen as rightful and trustworthy. Control systems (A), enforcement power (B) and position (D) only work while the formal authority is in place, so they cannot explain influence beyond it."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 94, $official_bank_source${"itemId":"c4f3e425-7398-5627-98f1-5094dd70a639","revise":true,"payload":{"prompt":"Leadership communication is most effective when it is ____","options":["One-directional","Clear and purposeful","Complex and technical","Excessively formal"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Communication works best when the message is clear and has a definite purpose that people can act on. One-way communication (A) shuts out feedback, while complex technical language (C) and excessive formality (D) make messages harder to understand."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 95, $official_bank_source${"itemId":"a000a991-3efc-53c1-aa89-3a90a200d1bc","revise":true,"payload":{"prompt":"One defining feature that distinguishes leadership from management is leadership's emphasis on ____","options":["Formal organisational hierarchy","Strict rule enforcement","Long-term vision and direction","Detailed operational control"],"correctOption":2,"section":"An Overview of Leadership","explanation":"A common way to separate the two is that leaders set long-term vision and direction, while managers plan, organise and control day-to-day operations. Options A, B and D, hierarchy, rule enforcement and detailed operational control, are features usually linked to management rather than leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 96, $official_bank_source${"itemId":"3eb8b6e3-febc-54b6-b817-6ad7cc23c496","revise":true,"payload":{"prompt":"Leadership assessment often includes evaluation of ____","options":["Organisational size","Follower compliance alone","Leader popularity","Influence processes and outcomes"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Assessing a leader means looking at how they influence people and what results that influence produces. Organisation size (A) says nothing about the leader, compliance alone (B) ignores outcomes and commitment, and popularity (C) is not the same as effectiveness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 97, $official_bank_source${"itemId":"50288ba7-3d38-5829-b367-6774317dbaca","revise":true,"payload":{"prompt":"Situational leadership emphasises adapting leadership style based on ____","options":["Organisational size","Leader personality","Follower readiness and task demands","Industry characteristics"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Situational leadership says the best style depends on how ready followers are (their ability and willingness) and on what the task requires. The leader's own personality (B), the size of the organisation (A) and the industry (D) are not the factors this approach uses to choose a style."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 98, $official_bank_source${"itemId":"982154f7-5fb8-576b-bf47-5e9424237ccf","revise":true,"payload":{"prompt":"Leadership influence that depends on offering incentives is associated with ____","options":["Coercive power","Referent power","Reward power","Expert power"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Reward power is the ability to influence people by offering things they value, such as pay rises, praise or promotion. Coercive power (A) works through the threat of punishment, referent power (B) through personal admiration, and expert power (D) through knowledge and skill."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 99, $official_bank_source${"itemId":"8b3fbc90-a85a-5eda-bd96-48b434e5b03b","revise":true,"payload":{"prompt":"Leadership influence that shapes organisational norms is referred to as ____","options":["Cultural leadership","Technical leadership","Coercive leadership","Transactional leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Leadership that shapes the shared norms, values and habits of an organisation is called cultural leadership. Technical leadership (B) is about expertise in tasks, coercive leadership (C) relies on threats, and transactional leadership (D) is about exchanging rewards for performance, not shaping norms."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 100, $official_bank_source${"itemId":"196bec73-5db3-5250-be2b-fe78cea2da95","revise":true,"payload":{"prompt":"Emotional intelligence in leadership primarily supports ____","options":["Procedural compliance","Financial decision accuracy","Technical efficiency","Interpersonal effectiveness"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Emotional intelligence is the ability to understand and manage your own emotions and those of others, so its main benefit is better relationships and interpersonal effectiveness. Procedural compliance (A), financial accuracy (B) and technical efficiency (C) depend on other skills, not on emotional awareness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 101, $official_bank_source${"itemId":"69698362-90d2-5c27-8604-b4b22cc6bc7d","revise":true,"payload":{"prompt":"Leadership presence is most closely associated with ____","options":["Physical dominance","Confidence and authenticity","Procedural knowledge","Formal authority symbols"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Leadership presence is the way a leader comes across to others, and it is built mainly on genuine confidence and being authentic. Physical dominance (A) and formal symbols of authority (D) may impress briefly but do not create real presence, and procedural knowledge (C) is a technical skill."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 102, $official_bank_source${"itemId":"b7d92941-dd8e-5191-b65b-5329b5a1e211","revise":true,"payload":{"prompt":"Leadership self-regulation primarily supports ____","options":["Authority expansion","Hierarchical dominance","Emotional control and discipline","Follower dependence"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Self-regulation means controlling your impulses and emotions so you act calmly and with discipline. It is part of emotional intelligence and has nothing to do with expanding authority (A), dominating others (B) or making followers depend on you (D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 103, $official_bank_source${"itemId":"9f78a4d9-772a-50e7-bd9f-17a60473a3c5","revise":true,"payload":{"prompt":"Leadership alignment across departments supports ____","options":["Functional isolation","Coordinated organisational performance","Decentralised conflict","Competitive internal rivalry"],"correctOption":1,"section":"An Overview of Leadership","explanation":"When leaders across departments share the same goals and priorities, units work together and the organisation performs in a coordinated way. Isolation (A), conflict (C) and internal rivalry (D) are exactly the problems that alignment is meant to prevent."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 104, $official_bank_source${"itemId":"657c902e-98ea-571e-b1ba-ac1c85b2882c","revise":true,"payload":{"prompt":"Leadership is commonly described as the process through which an individual influences others to achieve ____","options":["Shared organisational goals","Routine administrative compliance","Personal popularity","Informal social status"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leadership is widely defined as a process of influencing, guiding and inspiring others towards shared goals. Routine compliance (B) is closer to administration, while personal popularity (C) and social status (D) are personal gains, not the common goals leadership is meant to achieve."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 105, $official_bank_source${"itemId":"77fc2ea4-6a64-5763-a7a8-4b53d8d86f4f","revise":true,"payload":{"prompt":"Transformational leadership focuses on inspiring followers by emphasising ____","options":["Strict procedural adherence","Extrinsic reward structures","Routine task compliance","Shared values and vision"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Transformational leaders inspire followers by appealing to shared values and a compelling vision, encouraging them to go beyond self-interest. Extrinsic rewards (B) are the tool of transactional leaders, while strict procedures (A) and routine compliance (C) fit bureaucratic styles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 106, $official_bank_source${"itemId":"9ca158b6-e917-5f7d-8548-2279a4b95f44","revise":true,"payload":{"prompt":"Leadership continuity within organisations is strengthened by ____","options":["Succession and talent development","Centralised power retention","Rigid structural control","Reliance on individual charisma"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leadership continuity comes from planning succession and developing talent so new leaders are always ready. Holding on to power centrally (B) and rigid control (C) do not prepare successors, and relying on one person's charisma (D) creates a gap when that person leaves."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 107, $official_bank_source${"itemId":"c168f539-a149-56cf-9b78-d7554c80f8e7","revise":true,"payload":{"prompt":"Leadership authority becomes sustainable when it is supported by ____","options":["Coercive mechanisms","Trust and legitimacy","Formal rules alone","Constant supervision"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Authority lasts when followers trust the leader and accept the leader's right to lead. Coercion (A) and constant supervision (D) produce only short-term compliance, and formal rules alone (C) cannot keep people committed if trust is missing."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 108, $official_bank_source${"itemId":"175924c7-68be-51a5-a67b-243e1e01ad9b","revise":true,"payload":{"prompt":"Legitimate power is primarily based on ____","options":["Fear of punishment","Organisational position","Personal charisma","Control of rewards"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Legitimate power comes from the formal position or office a person holds, which gives them the recognised right to make requests. Fear of punishment (A) is coercive power, personal charisma (C) is referent power, and control of rewards (D) is reward power."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 109, $official_bank_source${"itemId":"332d6cab-7043-5765-bbb4-e1cd8e8341e6","revise":true,"payload":{"prompt":"Leadership effectiveness over time depends on continuous ____","options":["Procedural standardisation","Control reinforcement","Authority consolidation","Learning and adaptation"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Because situations, people and environments keep changing, leaders stay effective only by continually learning and adapting. Standardising procedures (A), reinforcing control (B) and consolidating authority (C) do not help a leader respond to change."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 110, $official_bank_source${"itemId":"44fbdf3b-396d-5c48-9362-8774bde65477","revise":true,"payload":{"prompt":"Vision in leadership serves to ____","options":["Enforce compliance","Replace operational planning","Limit strategic flexibility","Provide long-term direction"],"correctOption":3,"section":"An Overview of Leadership","explanation":"A vision is a picture of where the organisation wants to be, so its role is to give long-term direction. It does not exist to enforce compliance (A), it supports rather than replaces operational planning (B), and it should guide rather than limit strategic flexibility (C)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 111, $official_bank_source${"itemId":"38f6a041-e9b9-5a6f-b485-e3ca5851b386","revise":true,"payload":{"prompt":"Leadership consistency contributes to ____","options":["Rigidity","Reduced accountability","Predictability and trust","Resistance to change"],"correctOption":2,"section":"An Overview of Leadership","explanation":"When a leader behaves consistently, people know what to expect, and that predictability builds trust. Consistency does not mean rigidity (A) or resistance to change (D), and it increases rather than reduces accountability (B)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 112, $official_bank_source${"itemId":"0e86bbae-fc1f-56ba-bd56-ad1e39fe606d","revise":true,"payload":{"prompt":"Leadership authority that stems from personal attraction and identification is known as ____","options":["Legitimate authority","Referent authority","Expert authority","Coercive authority"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Referent power or authority comes from followers liking, admiring and identifying with the leader as a person. Legitimate authority (A) is based on position, expert authority (C) on knowledge and skill, and coercive authority (D) on the ability to punish."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 113, $official_bank_source${"itemId":"b43cc794-de24-53e1-8e0e-68aad0cfb671","revise":true,"payload":{"prompt":"Leadership sustainability over time is reinforced through ____","options":["Rigid standardisation","Continuous learning and renewal","Authority accumulation","Reduced participation"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Leadership stays strong over time when leaders keep learning and renewing their ideas and skills. Rigid standardisation (A), piling up authority (C) and reducing participation (D) make leadership stale and less able to cope with change."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 114, $official_bank_source${"itemId":"2f4f4f94-8cac-50be-b789-8cae243d3b36","revise":true,"payload":{"prompt":"Autocratic leadership is most accurately characterised by ____","options":["Decentralised authority","High follower autonomy","Minimal leader involvement","Unilateral decision-making"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"An autocratic leader keeps decision-making power to himself or herself and decides alone with little or no input from the group. Decentralised authority (A) and high follower autonomy (B) describe the opposite, and minimal leader involvement (C) describes laissez-faire leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 115, $official_bank_source${"itemId":"a637daed-fe65-5785-b234-2bd35225ef84","revise":true,"payload":{"prompt":"The idea that no single leadership style is universally effective reflects the ____","options":["Classical leadership assumption","Bureaucratic leadership model","Autocratic leadership doctrine","Contingency view of leadership"],"correctOption":3,"section":"An Overview of Leadership","explanation":"The contingency view holds that there is no one best way to lead; the right style depends on the situation. Classical (A), bureaucratic (B) and autocratic (C) thinking tend to assume a single correct way of leading or managing, which is exactly what the contingency view rejects."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 116, $official_bank_source${"itemId":"8d581461-ebf6-58ed-a7ed-049982ae1ee7","revise":true,"payload":{"prompt":"Leadership is often regarded as a dynamic process because it continuously involves ____","options":["Ongoing interaction between leaders and followers","Fixed authority relationships","Predetermined behavioural outcomes","Permanent organisational structures"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leadership is called dynamic because it is a relationship that keeps developing through ongoing interaction between leaders and followers. Fixed relationships (B), predetermined outcomes (C) and permanent structures (D) describe something static, which is the opposite of dynamic."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 117, $official_bank_source${"itemId":"203053e7-10d3-5356-a205-2df7ed1b65d7","revise":true,"payload":{"prompt":"Leadership styles that grant maximum autonomy to followers are described as ____","options":["Bureaucratic","Transactional","Laissez-faire","Autocratic"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire leaders take a hands-off approach and give followers as much freedom as possible to set goals and make decisions. Transactional leadership (B) is tempting but it relies on rewards and monitoring, while bureaucratic (A) and autocratic (D) styles keep tight control."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 118, $official_bank_source${"itemId":"d7922cf1-8916-5ec3-ac6d-7b1d706414ea","revise":true,"payload":{"prompt":"Leadership reflection enhances effectiveness by promoting ____","options":["Rigid consistency","Critical self-examination","Authority preservation","Habitual behaviour"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Reflection makes leaders more effective because it pushes them to examine their own actions, decisions and assumptions honestly. Rigid consistency (A), protecting authority (C) and habitual behaviour (D) are what reflection helps leaders move away from."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 119, $official_bank_source${"itemId":"095e3b2b-7627-55e2-9d25-bc8ddf4cc997","revise":true,"payload":{"prompt":"Leadership influence across cultures requires sensitivity to ____","options":["Uniform behavioural expectations","The cultural norms and values of the people being led","Identical communication styles","Standardised authority models"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Leading across cultures requires sensitivity to the norms and values of each cultural group involved, since what works in one culture may offend in another. Options A, C and D assume that one uniform style of behaviour, communication or authority will work everywhere, which is the mistake cultural sensitivity avoids."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 120, $official_bank_source${"itemId":"fa06e532-bafb-519b-8351-19d9abb3aa11","revise":true,"payload":{"prompt":"Leadership resilience is strengthened through ____","options":["Rigid adherence to plans","Learning from adversity","Denial of setbacks","Avoidance of challenge"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Leaders become more resilient by learning from difficulties and setbacks and using those lessons next time. Rigidly sticking to plans (A), denying setbacks (C) and avoiding challenges (D) prevent the growth that builds resilience."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 121, $official_bank_source${"itemId":"ef9621ff-8d29-5080-bdae-985971998225","revise":true,"payload":{"prompt":"Leadership inclusiveness involves ____","options":["Selective participation","Exclusion of dissent","Rigid conformity","Valuing diverse perspectives"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Inclusive leadership means actively welcoming and valuing people's different perspectives and backgrounds. Selective participation (A), excluding dissent (B) and demanding conformity (C) are all forms of exclusion."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 122, $official_bank_source${"itemId":"8214771c-60fd-5048-85a5-b10e94ce9b41","revise":true,"payload":{"prompt":"The leadership function of directing involves ____","options":["Motivating and guiding subordinates","Recruiting organisational members","Allocating financial resources","Evaluating financial performance"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Directing is the function of guiding, instructing and motivating subordinates so that plans are carried out. Recruiting members (B) belongs to staffing, while allocating financial resources (C) and evaluating financial performance (D) relate to planning, budgeting and controlling."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 123, $official_bank_source${"itemId":"c2f31ca2-996b-5291-8900-c291e383df91","revise":true,"payload":{"prompt":"Followership is best understood as ____","options":["Independent isolation","Active engagement in leadership processes","Resistance to authority","Passive obedience"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Followership is the active role people play in supporting, influencing and sometimes constructively challenging their leaders to achieve shared goals. Followers are partners, not passive subordinates, so passive obedience (D) is wrong, and isolation (A) or simple resistance (C) do not describe working with leaders."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 124, $official_bank_source${"itemId":"0330fbdd-45af-59f1-adc3-bcff2aa70a46","revise":true,"payload":{"prompt":"Leadership communication that encourages dialogue is described as ____","options":["Directive","Coercive","Transactional","Interactive"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Interactive communication is two-way: the leader shares information and also invites questions, ideas and feedback, which creates dialogue. Directive (A) and coercive (B) communication flow one way from the top, and transactional (C) refers to exchanging rewards for performance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 125, $official_bank_source${"itemId":"5edcf22d-66fb-5e04-bfa5-7f82b60bccdd","revise":true,"payload":{"prompt":"Leadership learning from failure emphasises ____","options":["Reflection and improvement","Avoidance of risk","Punishment enforcement","Blame assignment"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Learning from failure means reflecting on what went wrong and using that insight to improve. Avoiding risk (B), punishing people (C) and blaming others (D) discourage honest reflection and stop real learning."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 126, $official_bank_source${"itemId":"009210d8-c5a6-548c-8b74-3800b873cbf4","revise":true,"payload":{"prompt":"Leadership accountability requires leaders to ____","options":["Avoid delegation","Limit transparency","Accept responsibility for outcomes","Prioritise personal authority"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Accountability means leaders take responsibility for the results of their decisions and actions, whether good or bad. Avoiding delegation (A), limiting transparency (B) and putting personal authority first (D) all work against being answerable to others."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 127, $official_bank_source${"itemId":"078688d5-f087-5179-a39c-f1d791ff9e07","revise":true,"payload":{"prompt":"Leadership effectiveness in teams depends heavily on ____","options":["Minimal interaction","Strict supervision","Individual competition","Role clarity and coordination"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Teams perform well when each member knows their role and the leader coordinates everyone's effort towards the common goal. Minimal interaction (A) and individual competition (C) break teamwork apart, and strict supervision (B) controls people without building coordination."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 128, $official_bank_source${"itemId":"9ec53aeb-e370-5b54-a7c1-99023a81846a","revise":true,"payload":{"prompt":"Leadership influence across virtual teams relies heavily on ____","options":["Informal observation","Hierarchical supervision","Physical presence","Clear communication and trust"],"correctOption":3,"section":"An Overview of Leadership","explanation":"In virtual teams the leader cannot rely on being physically present, so clear communication and mutual trust become the main tools of influence. Physical presence (C), informal observation (A) and close hierarchical supervision (B) are hard or impossible when people work remotely."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 129, $official_bank_source${"itemId":"47634315-2fcd-5b75-adfc-45a1e3a82ef8","revise":true,"payload":{"prompt":"Leadership influence becomes transformational when leaders ____","options":["Emphasise transactions only","Appeal to higher values and purpose","Rely on authority enforcement","Avoid emotional engagement"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Leadership becomes transformational when the leader appeals to higher values, ideals and a sense of purpose that inspire followers. Focusing only on transactions (A) is transactional leadership, and relying on enforcement (C) or avoiding emotional engagement (D) cannot inspire people."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 130, $official_bank_source${"itemId":"0eeda61e-2357-5682-892d-7d46e65a7573","revise":true,"payload":{"prompt":"Leadership influence through inspiration differs from control because it relies on ____","options":["Procedural compliance","Emotional and value-based appeal","Hierarchical authority","Enforcement mechanisms"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Inspiration works by touching people's emotions and values, so they want to act rather than feel forced to. Procedural compliance (A), hierarchical authority (C) and enforcement mechanisms (D) are the tools of control, which is what inspiration is being contrasted with."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 131, $official_bank_source${"itemId":"213024d0-2a4b-5cb1-b6b1-7b8804a55c28","revise":true,"payload":{"prompt":"Leadership commitment from followers is strongest when leaders create ____","options":["Shared meaning and purpose","Fear of sanctions","Strict monitoring systems","Clear incentives only"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Followers are most committed when they understand and believe in the meaning and purpose of their work. Fear of sanctions (B) and strict monitoring (C) produce compliance rather than commitment, and incentives alone (D) keep people only as long as the rewards last."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 132, $official_bank_source${"itemId":"b3969760-bc35-52dc-9e02-3aabfb9d3d18","revise":true,"payload":{"prompt":"Servant leadership places primary emphasis on ____","options":["Competitive dominance","Leader authority","Follower development and well-being","Organisational hierarchy"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Servant leadership puts people first: the leader's main concern is the needs, growth and well-being of followers. Competitive dominance (A), leader authority (B) and hierarchy (D) put the leader or the structure first, which is the opposite of this approach."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'keep', 133, $official_bank_source${"itemId":"8f5bf697-68d3-5e02-91de-c22245926832","revise":true,"payload":{"prompt":"The ethical dimension of leadership emphasises ____","options":["Power maximisation","Performance outcomes alone","Absolute authority","Moral responsibility and integrity"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Ethical leadership is about acting with integrity and taking moral responsibility for how decisions affect people. Power maximisation (A) and absolute authority (C) ignore ethics, and focusing on performance outcomes alone (B) leaves out whether the means used were right."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 134, $official_bank_source${"itemId":"f11d2038-d631-5b07-94f7-9d0ca0df45f0","revise":true,"payload":{"prompt":"A leader who encourages participation and shared decision-making is demonstrating ____","options":["Autocratic leadership","Democratic leadership","Laissez-faire leadership","Transactional leadership"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Democratic, or participative, leadership involves group members in discussion and shares decision-making with them. Autocratic leaders (A) decide alone, laissez-faire leaders (C) leave decisions to the group with little involvement, and transactional leaders (D) focus on rewarding performance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 135, $official_bank_source${"itemId":"6fd35332-6dcf-58f9-8d5f-8f8d17d5d731","revise":true,"payload":{"prompt":"Transactional leadership primarily relies on ____","options":["Emotional appeal and vision","Symbolic influence","Reward and exchange mechanisms","Follower self-direction"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Transactional leadership is built on exchange: followers are rewarded for meeting targets and sanctioned for poor performance. Emotional appeal and vision (A) and symbolic influence (B) belong to transformational leadership, while follower self-direction (D) is closer to laissez-faire."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 136, $official_bank_source${"itemId":"f7fdb79f-317c-592e-b45e-ebfe7305b236","revise":true,"payload":{"prompt":"Leadership effectiveness across levels depends on ____","options":["Elimination of autonomy","Rigid hierarchy","Contextual awareness","Uniform leadership style"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Leaders at different levels face different people, tasks and pressures, so they need contextual awareness to adjust their approach. A uniform style (D), rigid hierarchy (B) and removing autonomy (A) ignore context and reduce effectiveness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 137, $official_bank_source${"itemId":"3eee90fe-41ac-5353-a1e1-30bf51e4da56","revise":true,"payload":{"prompt":"Leadership development initiatives primarily aim to build ____","options":["Procedural knowledge alone","Behavioural flexibility and competence","Organisational hierarchy","Positional authority"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Leadership development aims to build real competence and the flexibility to behave in the way each situation needs. Procedural knowledge alone (A) is too narrow, and hierarchy (C) and positional authority (D) come from structure, not from development."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 138, $official_bank_source${"itemId":"584a7b41-6144-5263-9d7c-6114c02e59a9","revise":true,"payload":{"prompt":"Leadership decision legitimacy increases when followers perceive decisions as ____","options":["Fair and well-reasoned","Arbitrary","Opaque","Leader-centred"],"correctOption":0,"section":"An Overview of Leadership","explanation":"People accept decisions more readily when they see them as fair and based on sound reasoning. Arbitrary (B), opaque or secretive (C) and leader-centred (D) decisions make followers suspicious and reduce legitimacy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 139, $official_bank_source${"itemId":"928d676a-bad2-54c7-9497-f446d28bb292","revise":true,"payload":{"prompt":"Leadership effectiveness is enhanced when leaders demonstrate ____","options":["Self-awareness and reflection","Rigid consistency","Unilateral control","Emotional detachment"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Self-aware leaders understand their own strengths, weaknesses and emotions, and reflection helps them improve over time. Rigid consistency (B), unilateral control (C) and emotional detachment (D) make leaders less responsive to people and situations."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 140, $official_bank_source${"itemId":"92917808-aaa7-516c-bbaa-5a132a1b631c","revise":true,"payload":{"prompt":"Leadership stability is enhanced when organisational values are ____","options":["Ignored in practice","Imposed without discussion","Inconsistently applied","Clearly articulated and lived"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Values provide stability when leaders state them clearly and actually live by them every day. Values that are ignored (A), imposed without discussion (B) or applied inconsistently (C) create cynicism and confusion instead of stability."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'keep', 141, $official_bank_source${"itemId":"90329700-a425-5645-a8a6-967f0eb0497f","revise":true,"payload":{"prompt":"Leadership role modelling affects followers primarily through ____","options":["Positional authority","Observed behaviour and example","Formal instruction","Policy enforcement"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Role modelling works because followers watch what leaders do and copy that example. Positional authority (A), formal instruction (C) and policy enforcement (D) tell people what to do, but role modelling influences them by showing."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'retire', 1, $official_bank_source$"5804a601-1db7-5ef2-bebb-21d282792cd6"$official_bank_source$::jsonb),
