insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'retire', 14, $official_bank_source$"e54d45c0-42c2-5763-8721-bea98f982ba2"$official_bank_source$::jsonb),
  ('official_bank_bua205', 'retire', 15, $official_bank_source$"1c28d3c0-b86d-513b-b2ef-73dfa4572c7c"$official_bank_source$::jsonb),
