insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 1, $official_bank_source${"itemId":"5d0cbd57-1351-5ad5-bdff-0f179174450d","questionId":"6211cede-8fe9-54aa-a285-2dfa23745054","sourceKey":"bank:BUA205:PQ-022-b","payload":{"prompt":"A leader who influences subordinates mainly through the threat of punishment, such as queries, demotion or dismissal, is using ____","options":["Expert power","Referent power","Reward power","Coercive power"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Coercive power rests on the ability to punish or withhold things people value, so followers comply out of fear. Reward power (C) is the opposite, working through incentives, referent power (B) rests on admiration of the leader, and expert power (A) on knowledge and skill."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 2, $official_bank_source${"itemId":"02208769-e876-56ff-ab42-ec198f8b8d4e","questionId":"1a334db1-dfe7-5fbb-8756-6e9d24140227","sourceKey":"bank:BUA205:PQ-068","payload":{"prompt":"Leadership adaptability becomes critical in environments characterised by ____","options":["Strict regulation","Predictable demand","Rapid change and uncertainty","Routine stability"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Adaptability matters most when the environment changes quickly and the future is uncertain, because yesterday's approach may no longer work. Strict regulation (A), predictable demand (B) and routine stability (D) describe settings where established methods usually still work."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 3, $official_bank_source${"itemId":"b119e52a-4321-5d95-9450-5fa24086806b","questionId":"5d0810ce-faa4-508e-aaab-1bdc4f6256ec","sourceKey":"bank:BUA205:PQ-069","payload":{"prompt":"Leadership influence through rewards primarily appeals to ____","options":["Moral obligation","Extrinsic motivation","Intrinsic motivation","Emotional attachment"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Rewards such as pay, bonuses and promotion are external incentives, so they appeal to extrinsic motivation. Intrinsic motivation (C) comes from enjoying or valuing the work itself, while moral obligation (A) and emotional attachment (D) are internal reasons for acting."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 4, $official_bank_source${"itemId":"bff7a743-fd74-59d9-a87e-c83a291cdadd","questionId":"13f28e9d-4c71-5213-9f5f-232d6354bd32","sourceKey":"bank:BUA205:PQ-070","payload":{"prompt":"The concept that leadership is not confined to formal authority positions highlights leadership as a ____","options":["Hierarchical entitlement","Bureaucratic obligation","Procedural responsibility","Social influence process"],"correctOption":3,"section":"An Overview of Leadership","explanation":"If anyone can lead without holding a formal post, then leadership is really a process of social influence among people. Hierarchical entitlement (A), bureaucratic obligation (B) and procedural responsibility (C) all tie leadership to positions or rules."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 5, $official_bank_source${"itemId":"13decda2-88e8-513c-8f30-89c711897b3b","questionId":"79f5452c-69f0-5784-b940-da00dc68a1a0","sourceKey":"bank:BUA205:PQ-071","payload":{"prompt":"A central assumption in modern leadership thought is that leadership can be ____","options":["Inherited through organisational tenure","Exercised only by senior executives","Learned and developed over time","Enforced through formal rules"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Modern leadership thinking assumes leaders are not only born but can be made, so leadership can be learned and developed. It is not inherited through years of service (A), not limited to senior executives (B) and not something rules can enforce (D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 6, $official_bank_source${"itemId":"b06f6cfc-8166-558f-98d7-0b9b9352d88f","questionId":"f760678b-aae5-595c-8a8c-e8bc4138f7f3","sourceKey":"bank:BUA205:PQ-072","payload":{"prompt":"Leadership motivation is strengthened when leaders ____","options":["Discourage autonomy","Align tasks with intrinsic values","Minimise feedback","Rely solely on authority"],"correctOption":1,"section":"An Overview of Leadership","explanation":"People are more motivated when their tasks connect with what they personally value and find meaningful. Discouraging autonomy (A), giving little feedback (C) and relying only on authority (D) all reduce motivation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 7, $official_bank_source${"itemId":"db217f3a-3170-5327-ac14-0ddbbf711f28","questionId":"7d462d53-2fe2-590d-adb0-e20e358255c1","sourceKey":"bank:BUA205:PQ-073","payload":{"prompt":"Leadership judgement is best described as the ability to ____","options":["Avoid uncertainty","Apply rules mechanically","Integrate experience with situational insight","Delegate all decisions"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Good judgement means combining past experience with a clear reading of the current situation to choose the right course of action. Applying rules mechanically (B) ignores the situation, and avoiding uncertainty (A) or delegating every decision (D) is avoiding judgement altogether."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 8, $official_bank_source${"itemId":"afb27a12-c3ad-5953-be5a-7bf307fa73fc","questionId":"378513ef-58a6-5537-b820-eef17282b545","sourceKey":"bank:BUA205:PQ-074","payload":{"prompt":"Leadership learning is most effective when it is ____","options":["Experiential and reflective","Limited to formal training","Purely theoretical","Isolated from practice"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leaders learn best by doing and then reflecting on what happened, which is experiential and reflective learning. Limiting learning to formal training (B), keeping it purely theoretical (C) or separating it from practice (D) cuts it off from real experience."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 9, $official_bank_source${"itemId":"05cf30c2-0f62-58d0-a0a3-2b1074d804fe","questionId":"d64c5eb3-fa3d-59cd-b72a-1890aa05a97f","sourceKey":"bank:BUA205:PQ-075","payload":{"prompt":"Leadership direction becomes clearer when goals are ____","options":["Vaguely defined","Constantly changing","Specific and shared","Imposed without explanation"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Direction is clear when goals are specific and understood and shared by everyone involved. Vague goals (A), constantly changing goals (B) and goals imposed without explanation (D) leave people unsure what they are working towards."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 10, $official_bank_source${"itemId":"1b483a33-90ef-56ca-8f0d-09b136b0e28f","questionId":"206a4155-96e0-509c-aa7d-5ea2bafb61cd","sourceKey":"bank:BUA205:PQ-076","payload":{"prompt":"The primary role of leadership in change management is to ____","options":["Reduce uncertainty through rules","Enforce compliance rapidly","Centralise control mechanisms","Communicate purpose and direction"],"correctOption":3,"section":"An Overview of Leadership","explanation":"During change, people need to understand why it is happening and where it is heading, so the leader's main role is to communicate purpose and direction. Rules (A), fast enforcement (B) and centralised control (C) may force compliance but do not win support for change."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 11, $official_bank_source${"itemId":"9e19ec22-4af2-5eb2-96a5-63a1e768d3fe","questionId":"5d3c66a9-29bc-5d64-b474-8533424d4430","sourceKey":"bank:BUA205:PQ-077","payload":{"prompt":"Leadership adaptability refers to the leader's ability to ____","options":["Avoid decision-making","Maintain rigid consistency","Delegate all authority","Adjust behaviour to context"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Adaptability is the ability to change one's behaviour to suit the situation, the people and the task at hand. Avoiding decisions (A), rigid consistency (B) and delegating everything (C) are not adapting at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 12, $official_bank_source${"itemId":"8fbb19a4-a2b4-5b3a-ad83-ad2a8eb41753","questionId":"68380b36-6327-5b74-86b1-414ce620133b","sourceKey":"bank:BUA205:PQ-078","payload":{"prompt":"Behavioural leadership theories primarily examine what leaders ____","options":["Actually do in practice","Are born with","Inherit socially","Believe internally"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Behavioural theories shifted attention from who leaders are to what they actually do, such as how they handle tasks and relate to people. Traits leaders are born with (B) are the focus of trait theories, while inherited status (C) and inner beliefs (D) are not what behavioural theories measure."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 13, $official_bank_source${"itemId":"64f71225-aa93-518e-8ba6-9eec73e0462e","questionId":"a07bedf0-07b0-51db-b270-687c8a0bbe21","sourceKey":"bank:BUA205:PQ-079","payload":{"prompt":"Leadership credibility is undermined when leaders ____","options":["Act inconsistently with stated values","Communicate openly","Accept responsibility","Encourage participation"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Credibility collapses when a leader's actions do not match the values he or she preaches, because people stop believing what the leader says. Open communication (B), accepting responsibility (C) and encouraging participation (D) all build credibility rather than undermine it."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 14, $official_bank_source${"itemId":"40d1717a-baff-53ad-9967-b6b3cae206a2","questionId":"68d33e9a-6400-5ae3-8753-9c4cfb863455","sourceKey":"bank:BUA205:PQ-080","payload":{"prompt":"Leadership trustworthiness is reinforced when leaders consistently ____","options":["Avoid difficult decisions","Restrict information","Honour commitments","Prioritise self-interest"],"correctOption":2,"section":"An Overview of Leadership","explanation":"People trust leaders who keep their promises consistently. Avoiding hard decisions (A), restricting information (B) and putting self-interest first (D) all signal that the leader cannot be relied upon."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 15, $official_bank_source${"itemId":"bd742e50-9e55-5c1b-973b-49b452a8d4b2","questionId":"3f3cca0e-3eb3-5d50-a492-c863ac1cda86","sourceKey":"bank:BUA205:PQ-130","payload":{"prompt":"Setting goals, clarifying roles and aligning group efforts toward shared outcomes are all part of which core component of leadership?","options":["Managing change and conflict","Maintaining ethical standards","Providing direction","Motivating followers"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Providing direction means setting a clear vision, defining goals, clarifying roles and aligning everyone's efforts toward shared outcomes. Option A (managing change and conflict) deals with guiding people through transitions and disagreements, while Option D (motivating followers) is about inspiring commitment rather than setting the course."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 16, $official_bank_source${"itemId":"7e882b3e-72e0-588d-8d99-efb546b40ec0","questionId":"0ea41c0b-b37f-5b42-b215-a85df3130252","sourceKey":"bank:BUA205:PQ-154","payload":{"prompt":"A leader who evaluates outcomes honestly and admits mistakes when necessary is displaying which characteristic of an effective leader?","options":["Emotional intelligence","Accountability and responsibility","Vision and strategic thinking","Communication skills"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Accountability and responsibility means leaders own their decisions, judge results honestly and admit mistakes, which builds public confidence. Option A (emotional intelligence) is about managing emotions and empathy, and Option C (vision and strategic thinking) is about anticipating the future rather than reviewing past outcomes."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 17, $official_bank_source${"itemId":"6ff05817-4ce7-5598-940f-be4436fcbea8","questionId":"5bec6124-f97b-551b-8c7d-8a6d7f5f0ae5","sourceKey":"bank:BUA205:PQ-178","payload":{"prompt":"Which of the following BEST defines leadership in an organisational context?","options":["The process of influencing others to achieve a common goal","The management of organisational resources for profit","The capacity to delegate tasks to subordinates efficiently","The ability to command obedience through positional authority"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leadership is a process of influencing, guiding and inspiring people toward shared goals, and it works through trust and commitment rather than position alone. Option D describes the use of formal authority, which can exist without real leadership, while delegation (option C) and managing assets for profit (option B) are management activities rather than definitions of leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 18, $official_bank_source${"itemId":"ed08a7ce-faa8-59a6-9daa-2fa7d66b063b","questionId":"ba128d5e-ff67-5ea4-b3bd-10e8bc17298e","sourceKey":"bank:BUA205:PQ-179","payload":{"prompt":"The Trait Theory of leadership argues that leaders are:","options":["Chosen democratically by their followers","Made through training and environmental conditioning","Defined by the situation they find themselves in","Born with inherent personal attributes that distinguish them"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Trait Theory, which grew out of the 'great man' view, holds that effective leaders possess inborn qualities such as intelligence, confidence and determination that set them apart from non-leaders. Option B reflects the behavioural view that leadership can be learned, and option C reflects situational or contingency thinking, while option A is about how leaders are selected, not what makes them leaders."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 19, $official_bank_source${"itemId":"87968470-3149-54ad-bd1f-e7b3d74d5c61","questionId":"d1ba2e23-3c68-5158-ad2b-965af79e1596","sourceKey":"bank:BUA205:PQ-180","payload":{"prompt":"Contingency theories of leadership suggest that leadership effectiveness depends on:","options":["A fixed set of universal leadership traits","The moral character of the leader alone","The number of followers a leader controls","The match between leadership style and situational factors"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Contingency theories, such as Fiedler's model, argue that no single style works everywhere: a leader is effective when his or her style fits the situation, including the task, the followers and the leader's position power. Option A is the trait view that contingency theories reject, and options B and C ignore the situation entirely."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 20, $official_bank_source${"itemId":"471d211f-419f-5cca-956d-c7599b22d3f8","questionId":"42b764e7-80fe-569e-8024-534d8aad4eca","sourceKey":"bank:BUA205:PQ-181","payload":{"prompt":"Which of the following is NOT typically considered a characteristic of an effective leader?","options":["Integrity and ethical behaviour","Visionary thinking and strategic foresight","Emotional intelligence","Authoritarian imposition of personal views"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Effective leaders influence people through vision, integrity, good communication and emotional intelligence, and they listen to others rather than force their opinions on them. Imposing personal views reduces participation, creativity and trust. Options C, A and B are all commonly listed qualities of effective leaders."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 21, $official_bank_source${"itemId":"2e7110d4-5114-5513-92bf-a63ead1ff397","questionId":"b77084e6-dbb2-556e-adfe-9976ebdb187a","sourceKey":"bank:BUA205:PQ-182","payload":{"prompt":"The Behavioural Theory of leadership differs from the Trait Theory in that it focuses on:","options":["The situational demands placed on leaders","What leaders are born with","Follower personality and emotional needs","What leaders actually do rather than their innate qualities"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Behavioural theories, such as the Ohio State and Michigan studies, shifted attention from who leaders are to how they behave, for example how much they focus on tasks or on people. This implies that leadership can be learned. Option B describes Trait Theory itself, and option A describes situational or contingency theories."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 22, $official_bank_source${"itemId":"e160556c-d79b-5021-ae6c-96e161802e22","questionId":"d85e63a2-a947-5259-bf46-e92dc1ef5d34","sourceKey":"bank:BUA205:PQ-183","payload":{"prompt":"Which leadership function primarily involves inspiring followers to work willingly toward a shared vision?","options":["Organising","Motivating and inspiring","Budgeting","Controlling"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Motivating and inspiring followers goes beyond giving instructions: it involves communicating meaningful goals, recognising achievements and building commitment so that people contribute willingly. Controlling (option D) checks performance against standards, organising (option A) arranges tasks and structures, and budgeting (option C) allocates money, none of which is mainly about inspiration."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 23, $official_bank_source${"itemId":"c44d42e9-58a8-5517-809f-3fd7ee66b52c","questionId":"bce08c23-c10d-5045-9bf4-564ed873ace9","sourceKey":"bank:BUA205:PQ-184","payload":{"prompt":"Path-Goal Theory, developed by Robert House, proposes that a leader's primary role is to:","options":["Apply reward and punishment consistently","Prioritise organisational structure over human relations","Establish rigid organisational hierarchies","Clarify paths to goals and remove obstacles for followers"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Path-Goal Theory says leaders motivate followers by making the route to goals clear, removing obstacles and providing the support or direction followers need, choosing among directive, supportive, participative and achievement-oriented behaviours. Option A sounds close because rewards matter in the theory, but consistent reward and punishment is the core of transactional leadership, not the main idea of Path-Goal Theory."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 24, $official_bank_source${"itemId":"ef12c1f5-ce8b-5adb-a32f-1b7febf68d56","questionId":"4690556c-7cea-5d28-96af-2476a150a064","sourceKey":"bank:BUA205:PQ-185","payload":{"prompt":"The concept of 'leadership role' is BEST described as:","options":["The remuneration package attached to a leadership position","A fixed job description assigned by HR","The behaviours expected of a leader within an organisational or social context","The legal authority granted to a public official"],"correctOption":2,"section":"An Overview of Leadership","explanation":"A leadership role is the set of behaviours people expect from a leader in a given setting, such as giving direction, motivating others, making decisions and setting ethical standards. A job description (option B) is a formal document, legal authority (option D) is a basis of power, and pay (option A) is a reward attached to a position, so none captures what a role means."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 25, $official_bank_source${"itemId":"0464e2dd-f58a-59c2-91f0-17f0d5cf4a6a","questionId":"f2dd8287-6add-5c04-83d2-acb438762444","sourceKey":"bank:BUA205:PQ-238-a","payload":{"prompt":"A commonly cited limitation of the Trait Theory of leadership is that:","options":["It assumes leadership can be learned through training","Researchers have not agreed on a consistent set of traits that guarantees effective leadership","It ignores the personal qualities of leaders","It focuses too heavily on situational factors"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Decades of trait research produced long and inconsistent lists of qualities, and people with the 'right' traits do not always lead well, so the theory cannot reliably predict who will be effective. It also ignores the situation and the followers. Option D is the opposite of the theory's weakness, option C is false because traits are its whole focus, and option A is the behavioural view."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 26, $official_bank_source${"itemId":"0dcd5ab3-06ff-5ed8-9dca-39d5636bf3fa","questionId":"e0f5ce6e-b438-5430-b213-91082373dfa7","sourceKey":"bank:BUA205:PQ-238-b","payload":{"prompt":"A major limitation of the Behavioural Theory of leadership is that it:","options":["Assumes that leaders are born, not made","Focuses only on followers' maturity levels","Ignores what leaders actually do","Has not identified a single style of behaviour that is effective in every situation"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Behavioural studies classified leaders by what they do, such as task-oriented or people-oriented behaviour, but they could not show that any one style works best everywhere, because they paid little attention to the situation. Option A is a criticism of Trait Theory, option C contradicts the theory's focus on behaviour, and option B describes Hersey and Blanchard's situational model."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 27, $official_bank_source${"itemId":"7c6c12c3-92a5-51e8-885a-d77690003f78","questionId":"f62011bd-babc-55c4-a57b-7fab264cf525","sourceKey":"bank:BUA205:PQ-238-e","payload":{"prompt":"Which leadership function involves setting a clear vision, defining objectives and clarifying roles and responsibilities for followers?","options":["Providing direction","Managing change and conflict","Motivating followers","Maintaining ethical standards"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Providing direction means establishing a vision, setting achievable objectives, clarifying who does what and aligning group effort toward shared outcomes; without it, institutions suffer confusion and conflict. Managing change and conflict (option B) deals with transitions and disagreements, maintaining ethical standards (option D) with integrity, and motivating followers (option C) with building commitment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 28, $official_bank_source${"itemId":"a7d94b79-6268-5abc-9d3f-0fe45d860e19","questionId":"b97a9ca1-8bdb-5809-9ae3-77bfb025c577","sourceKey":"bank:BUA205:OVR-001","payload":{"prompt":"Contemporary governance and management studies describe leadership as a 'relational process'. What does this mean?","options":["Leadership is the formal authority attached to a job title or office","Leadership emerges through interaction between leaders and followers in a specific context","Leadership is a fixed relationship in which followers simply obey the leader","Leadership is a personal quality carried by one person regardless of followers"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Seeing leadership as relational means it is not a one-person activity: it grows out of the interaction between leaders and followers within an organisational, social or political setting. Option D treats leadership as something one person holds alone, and option A reduces it to position, which is exactly the one-person view the relational idea rejects. Option C makes followers passive, which also misses the two-way interaction."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 29, $official_bank_source${"itemId":"d9a55eaf-ab6f-5b34-91dc-209cd66b314a","questionId":"8cf02bd1-91c8-52f3-b953-35b39ef968e9","sourceKey":"bank:BUA205:OVR-002","payload":{"prompt":"Effective leadership is said to depend on four things. Which of the following is NOT one of them?","options":["Legitimacy","Trust","Shared commitment to common objectives","Inherited social status"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Effective leadership rests on trust, communication, legitimacy and shared commitment to common objectives, all of which are built through the leader-follower relationship. Inherited social status is not part of that list; a person can inherit a title and still fail to lead. Options B, A and C are all on the list."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 30, $official_bank_source${"itemId":"f971fe36-394d-56a9-8d84-73f3cc1d604e","questionId":"ac1a6ba6-77f0-558e-8d1a-cd08f320cc5f","sourceKey":"bank:BUA205:OVR-003","payload":{"prompt":"Which of the following is NOT one of the core components of leadership?","options":["Providing direction","Motivating followers","Managing change and conflict","Preparing the organisation's statutory financial statements"],"correctOption":3,"section":"An Overview of Leadership","explanation":"The core components of leadership are providing direction, motivating followers, making decisions, maintaining ethical standards, and managing change and conflict. Preparing statutory financial statements is an accounting task, not a component of leadership. Options A, B and C are all core components."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 31, $official_bank_source${"itemId":"70c1cf86-882c-5899-9ca5-1eadd2aa5153","questionId":"f69d5b3a-ba8e-58b2-a538-3ddad558ad44","sourceKey":"bank:BUA205:OVR-004","payload":{"prompt":"The new managing director of a Lagos logistics firm announces a five-year vision, sets achievable quarterly objectives, clarifies who is responsible for what, and aligns all departments behind the same targets. Which core component of leadership is she mainly demonstrating?","options":["Managing change and conflict","Providing direction","Motivating followers","Maintaining ethical standards"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Providing direction means setting a vision, setting achievable objectives, clarifying roles and responsibilities, and aligning group efforts toward shared outcomes, which is exactly what she is doing. Option A is about guiding people through transitions and disagreements, and option D is about integrity and fairness. Option C is about building morale and commitment, which is related but not the focus here."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 32, $official_bank_source${"itemId":"f5734ef3-9d99-53e7-9331-9bb417488ec4","questionId":"afc8c87a-167d-553f-9c5c-ad3bdd2599a1","sourceKey":"bank:BUA205:OVR-005","payload":{"prompt":"When an organisation or governance system lacks clear direction from its leaders, what does it often experience?","options":["Confusion, inefficiency and conflict","Higher innovation and faster decisions","Stronger legitimacy and public trust","Greater follower independence and commitment"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Without a clear vision and priorities, people pull in different directions, so organisations often experience confusion, inefficiency and conflict. Options B, C and D are all positive outcomes that come from good leadership, not from its absence."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 33, $official_bank_source${"itemId":"fd3e5a6a-fec8-538f-98bf-b57f3e982cf0","questionId":"a7bd7ae3-c703-5a51-934d-b746dcbfc7e6","sourceKey":"bank:BUA205:OVR-006","payload":{"prompt":"Which of the following is NOT a way effective leaders motivate followers?","options":["Communicating meaningful goals","Demonstrating empathy and fairness","Recognising achievements","Relying only on issuing instructions to get work done"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Motivation goes beyond issuing instructions; it involves encouraging commitment, building morale and giving people a sense of purpose. Leaders do this by recognising achievements, communicating meaningful goals, creating a supportive environment, showing empathy and fairness, and building trust. Options C, A and B are all genuine ways of motivating followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 34, $official_bank_source${"itemId":"ea1edb6b-82ea-5df5-9152-2c907eb7a3f0","questionId":"23649767-be96-51dc-94eb-4f23071e985a","sourceKey":"bank:BUA205:OVR-007","payload":{"prompt":"Good leadership decision-making requires all of the following EXCEPT:","options":["Risk assessment","Choosing the first available option to save time","Consultation with stakeholders","Evaluation of alternatives"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Good decisions need critical thinking and analysis, consultation with stakeholders, evaluation of alternatives, risk assessment and accountability for outcomes. Grabbing the first available option skips the evaluation of alternatives altogether. Options C, D and A are all requirements of good decision-making."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 35, $official_bank_source${"itemId":"2ecfe973-e99e-58fb-a353-787148c9bb75","questionId":"abb01c17-4a03-5a66-b64e-9822139982b4","sourceKey":"bank:BUA205:OVR-008","payload":{"prompt":"After a new state policy on market levies sparks protests by traders, the commissioner holds town-hall meetings, explains the transition clearly, listens to traders' concerns and negotiates a phased compromise. Which core component of leadership is this?","options":["Providing direction","Managing change and conflict","Maintaining ethical standards","Making decisions"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Managing change and conflict involves communicating clearly during transitions, encouraging dialogue, addressing resistance and concerns, negotiating solutions and keeping stability, which matches the commissioner's actions. Option A is about setting vision and objectives in the first place, and option C is about integrity and fairness. Option D is part of the process, but the situation is mainly about handling resistance to a change."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 36, $official_bank_source${"itemId":"d9432685-394a-5381-9d57-60284dd82f2d","questionId":"69a929eb-1029-54b6-881c-1e8695fedcf0","sourceKey":"bank:BUA205:OVR-009","payload":{"prompt":"In governance contexts, effective conflict management by leaders mainly helps to:","options":["Prevent social unrest and promote inclusive decision-making","Remove the need for consultation with citizens","Guarantee that every policy is popular","Concentrate decision power in the leader's hands"],"correctOption":0,"section":"An Overview of Leadership","explanation":"When leaders handle disagreement constructively, they prevent social unrest and make decision-making more inclusive. Option D describes centralisation, which often worsens conflict, and option B is the opposite of inclusive decision-making. Option C overstates what any leader can achieve."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 37, $official_bank_source${"itemId":"70c3e437-f0a7-584f-b48d-009bedfcb2eb","questionId":"16460f64-e83d-5a34-baea-fa9f2bdb3dfa","sourceKey":"bank:BUA205:OVR-010","payload":{"prompt":"Maintaining ethical standards as a leader involves all of the following EXCEPT:","options":["Upholding fairness and justice","Keeping decisions hidden from those affected by them","Ensuring responsible use of resources","Respecting diversity and human rights"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Ethical leadership involves promoting transparency and accountability, upholding fairness and justice, avoiding corruption and abuse of power, respecting diversity and human rights, and using resources responsibly. Hiding decisions from those affected is the opposite of transparency. Options A, D and C are all part of maintaining ethical standards."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 38, $official_bank_source${"itemId":"eeb5c8a5-2280-5e51-b15f-da75e2a30034","questionId":"91fe8c63-d09f-5f0a-ad84-a8e034545efb","sourceKey":"bank:BUA205:OVR-011","payload":{"prompt":"As a characteristic of effective leaders, emotional intelligence refers to the ability to:","options":["Use followers' emotions to secure obedience","Understand and manage one's own emotions while recognising the feelings of others","Hide all emotions so that followers cannot read the leader","Think logically without being affected by people's feelings"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Emotional intelligence is the ability to understand and manage your own emotions while recognising how others feel, which helps leaders handle stress, resolve conflict and show empathy. Option C confuses emotional control with concealment, and option A describes manipulation. Option D ignores the 'others' side of emotional intelligence entirely."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 39, $official_bank_source${"itemId":"cd7540e4-f342-5c43-a574-d41c38ac534b","questionId":"0592276d-66d6-5e21-a0ef-3d656915005b","sourceKey":"bank:BUA205:OVR-012","payload":{"prompt":"Before investing N500 million in a new product line, the CEO of an Ibadan manufacturing firm studies emerging market trends, anticipates risks over the next decade and aligns company resources with long-term goals. Which characteristic of an effective leader does this show?","options":["Emotional intelligence","Vision and strategic thinking","Accountability and responsibility","Communication skills"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Vision and strategic thinking is the ability to foresee future opportunities and challenges and develop strategies for them: setting long-term goals, anticipating risks, identifying trends and aligning resources. Option A concerns managing emotions and empathy, and option D concerns sharing ideas and listening. Option C is about owning the results of decisions afterwards."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 40, $official_bank_source${"itemId":"d3f459a1-ba9b-5a4d-b2d1-c822a82abf34","questionId":"f4bbefe5-096d-5cb3-ab20-48c40d45cefc","sourceKey":"bank:BUA205:OVR-013","payload":{"prompt":"Integrity is described as the foundation of a leader's:","options":["Length of tenure","Popularity","Credibility","Formal authority"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Integrity, meaning honesty, transparency and fairness, is the foundation of leadership credibility because it makes followers and stakeholders trust the leader. Option D comes from position rather than character, and option B can be won without integrity. Option A has nothing to do with integrity."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 41, $official_bank_source${"itemId":"4fb9cf0c-870f-5a49-a05a-77d2c056d8a0","questionId":"2a9bf1a4-1a46-5707-8b35-7a5b9ab44897","sourceKey":"bank:BUA205:OVR-014","payload":{"prompt":"Ethical failures in leadership often result in:","options":["Stronger follower commitment","Greater institutional resilience","Governance crises and institutional breakdown","Faster policy implementation"],"correctOption":2,"section":"An Overview of Leadership","explanation":"When leaders are corrupt or dishonest, trust collapses and institutions stop working, so ethical failures often lead to governance crises and institutional breakdown. Options D, B and A are benefits of good leadership, not consequences of ethical failure."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 42, $official_bank_source${"itemId":"1556728a-81c7-5862-94b5-194c33a72dd4","questionId":"9aecf68a-5de9-52f1-942a-a82501fdc47c","sourceKey":"bank:BUA205:OVR-015","payload":{"prompt":"In governance systems, a leader's adaptability and innovation mainly support:","options":["Institutional resilience","Institutional stagnation","Leader dependence on informal networks","Rigid adherence to old procedures"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Adaptable leaders embrace new ideas, adjust strategies to changing conditions and encourage creative problem-solving, which helps institutions bounce back from shocks, that is, institutional resilience. Options B and D are what happens when leaders fail to adapt. Option C is an effect of weak institutions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 43, $official_bank_source${"itemId":"849ecf27-e5e9-55c1-bbb2-9095c4548e10","questionId":"8a93573a-a16e-53be-bfa5-a5d481e998bf","sourceKey":"bank:BUA205:OVR-016","payload":{"prompt":"After the university's new online course-registration portal crashes, the registrar publicly admits the rollout was poorly planned, accepts responsibility and orders an honest review of what went wrong. Which characteristic of effective leaders is he displaying?","options":["Vision and strategic thinking","Emotional intelligence","Adaptability and innovation","Accountability and responsibility"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Responsible leaders accept responsibility for their decisions, evaluate outcomes honestly, admit mistakes and stay transparent, which is exactly the registrar's response. Option A is about planning for the future, and option C is about embracing new ideas. Option B concerns managing emotions and empathy rather than owning a failure."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 44, $official_bank_source${"itemId":"f7f2cd7d-f601-5ac5-836f-aacc761e9e7d","questionId":"e3e7c9d2-7a4f-5188-96ad-97335595ffe9","sourceKey":"bank:BUA205:OVR-017","payload":{"prompt":"Effective communication by a leader mainly helps to:","options":["Enhance cooperation and reduce misunderstandings","Reduce the need for feedback from followers","Replace the need for clear decisions","Keep information within the top management"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Strong leaders communicate clearly, listen actively, encourage open dialogue and manage information responsibly, and this builds cooperation and cuts down misunderstandings. Option B is wrong because good communicators actively seek feedback, and option D contradicts open dialogue. Option C is wrong because communication supports decisions but does not replace them."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 45, $official_bank_source${"itemId":"a5428519-fa67-5f28-abd4-42fbe8fc8f5a","questionId":"3e978157-f31a-5e2e-8b16-f53384d117b7","sourceKey":"bank:BUA205:OVR-018","payload":{"prompt":"Leaders with high emotional intelligence typically do all of the following EXCEPT:","options":["Resolve conflicts constructively","Build strong interpersonal relationships","Show empathy toward followers","React to stress by shifting blame onto subordinates"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Emotionally intelligent leaders handle stress well, resolve conflicts constructively, show empathy and build strong relationships. Blaming subordinates under pressure shows poor emotional control. Options A, C and B all describe high emotional intelligence."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 46, $official_bank_source${"itemId":"3d819a9d-ed00-5cda-a4b4-4db4f1fa0ebc","questionId":"30ea0bfa-ae19-5eb0-8bf6-69dfdec19b46","sourceKey":"bank:BUA205:OVR-019","payload":{"prompt":"In leadership and governance, the situation in which leaders use their authority for personal gain rather than for public or organisational benefit is called:","options":["Low citizen trust","Political interference","Weak institutions","Corruption and misuse of power"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Corruption happens when leaders use their authority for personal gain instead of the public good, for example through bribery, embezzlement, nepotism or abuse of resources. Option B is when outside actors push decisions for partisan interests, and option C is when organisations lack structures or capacity. Option A is usually a result of corruption, not its definition."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 47, $official_bank_source${"itemId":"021f7407-ded1-5a6c-8ab1-77866fe05487","questionId":"554b16b2-cb2f-515d-8cee-42bfda473586","sourceKey":"bank:BUA205:OVR-020","payload":{"prompt":"A senator repeatedly pressures the head of a federal agency to award jobs and contracts to party loyalists rather than to qualified applicants. Which leadership challenge in governance does this illustrate?","options":["Weak institutions","Lack of transparency","Political interference","Low citizen trust"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Political interference is when outside actors influence a leader's decisions for personal or partisan interests rather than the common good, which is what the senator is doing. Option B is about secrecy in decision-making, and option A is about a lack of structures or capacity. Option D may follow from such interference but is not the challenge described."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 48, $official_bank_source${"itemId":"d20a3e97-3eee-5563-9426-db3c3f780a5c","questionId":"cb997d08-1941-54b1-b3b6-499b6b7c9beb","sourceKey":"bank:BUA205:OVR-021","payload":{"prompt":"Which leadership response is most directly recommended for dealing with political interference?","options":["Promoting merit-based decision-making","Centralising all decisions in one office","Increasing reliance on informal networks","Reducing professional standards to avoid conflict"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Leaders respond to political interference by upholding professional ethics, strengthening institutional safeguards and promoting merit-based decisions, so that choices rest on qualification rather than loyalty. Option C makes interference easier, and option D is actually a consequence of interference. Option B does not protect decisions from outside pressure."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 49, $official_bank_source${"itemId":"53b6f58d-a63e-5396-9d5e-2f4497575604","questionId":"65b6ff87-c13a-5ba9-8100-28ebeb55ee25","sourceKey":"bank:BUA205:OVR-022","payload":{"prompt":"Which of the following is an effect of weak institutions in governance?","options":["Leadership dependence on informal networks","More efficient service delivery","Greater organisational autonomy","Improved regulatory enforcement"],"correctOption":0,"section":"An Overview of Leadership","explanation":"When organisations lack effective structures, capacity or independence, the effects include inefficient service delivery, poor regulatory enforcement and leaders relying on informal networks to get things done. Options D and B are the opposite of those effects. Option C is not an effect of weak institutions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 50, $official_bank_source${"itemId":"f1f82cbc-3b30-5ce6-91d0-7fb6a10f0432","questionId":"3f7ae64f-2b7e-59ed-89d1-c2652241c8d9","sourceKey":"bank:BUA205:OVR-023","payload":{"prompt":"Which of the following is NOT a cause of low citizen trust in leaders?","options":["Delivering tangible results to communities","Poor service delivery","Corruption scandals","Lack of accountability"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Low citizen trust is caused by corruption scandals, poor service delivery and lack of accountability. Delivering tangible results is one of the leadership responses that rebuilds trust, not a cause of losing it. Options C, B and D are the listed causes."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 51, $official_bank_source${"itemId":"642805ad-52c0-5f30-84b0-46de665efc7d","questionId":"5284ebf3-d166-5483-ad4e-caa84cb20357","sourceKey":"bank:BUA205:OVR-024","payload":{"prompt":"A local government council is accused of hiding how it spends its N2 billion annual budget. Which leadership response best addresses this lack of transparency?","options":["Setting up public reporting systems on spending","Reducing the number of public consultations","Keeping budget details with the chairman only","Restricting journalists' access to council records"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Responses to a lack of transparency include open communication channels, public reporting systems and inclusive policy discussions, all of which let citizens see how money is used. Options D, B and C all increase secrecy and would make the problem worse."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 52, $official_bank_source${"itemId":"25f9ed5a-7f26-5799-8ecf-9cb728e0b595","questionId":"8f67946d-7f30-59c7-86d5-b8c0dbbed9cd","sourceKey":"bank:BUA205:OVR-025","payload":{"prompt":"Leadership is particularly important in governance because leaders:","options":["Remove the need for followers to participate","Shape institutional direction, set ethical standards and manage competing interests","Replace laws and institutions with personal authority","Guarantee that citizens never disagree with policy"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Leaders matter in governance because they shape institutional direction, establish ethical standards, coordinate collective action and manage competing interests. Option A contradicts the idea that followers are partners, and option C describes personal rule rather than good governance. Option D is unrealistic."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 53, $official_bank_source${"itemId":"87314a45-0395-5456-94d4-ab9426c7a800","questionId":"59c96975-6f80-5a19-b6c4-9e9238efa54f","sourceKey":"bank:BUA205:OVR-026","payload":{"prompt":"In governance, the quality of leadership most directly determines which of the following?","options":["Policy direction, institutional performance and citizens' trust in institutions","Only the size of the civil service","Only the personal wealth of the leader","Only the number of political parties"],"correctOption":0,"section":"An Overview of Leadership","explanation":"In governance, leadership determines policy direction, how well institutions perform, and how much citizens trust public institutions. Options C, B and D each pick a narrow factor that leadership quality does not mainly decide."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 54, $official_bank_source${"itemId":"d617d220-c032-59d3-940c-71f8b39be4cf","questionId":"22d1f2df-2d54-5a9b-95a0-264065d387b0","sourceKey":"bank:BUA205:OVR-027","payload":{"prompt":"The 'Great Man' theory of leadership is most closely linked to which approach?","options":["The trait approach","The behavioural approach","The transactional approach","The contingency approach"],"correctOption":0,"section":"An Overview of Leadership","explanation":"The Great Man theory holds that great leaders are born with special qualities, which is the starting point of the trait approach. Option B studies what leaders do rather than who they are, and option D argues that effectiveness depends on the situation. Option C is about reward-based exchange."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 55, $official_bank_source${"itemId":"38ee23e8-cb49-5723-9411-4857108c54bb","questionId":"34163460-7b9c-555c-90f2-a59f28867c7a","sourceKey":"bank:BUA205:OVR-028","payload":{"prompt":"A major criticism of the trait approach to leadership is that it:","options":["Focuses too heavily on the needs of followers","Assumes leadership style must change with every task","Relies on rewards and punishments to explain behaviour","Has not produced a consistent list of traits and ignores the situation"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Researchers who reviewed trait studies found no consistent set of traits that always separates leaders from non-leaders, and the approach ignores the situation in which leadership happens. Option A fits servant leadership more than trait theory, and option C describes transactional leadership. Option B is a contingency idea."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 56, $official_bank_source${"itemId":"d4974a5d-2b51-58ab-a0d2-ce5a65ded8f1","questionId":"965739c1-af20-54ff-8add-8412e390b947","sourceKey":"bank:BUA205:OVR-029","payload":{"prompt":"The Ohio State leadership studies identified two dimensions of leader behaviour. What were they?","options":["Contingent reward and management by exception","Concern for production and concern for people","Initiating structure and consideration","Task structure and position power"],"correctOption":2,"section":"An Overview of Leadership","explanation":"The Ohio State studies described leader behaviour in terms of initiating structure (organising tasks and roles) and consideration (concern for subordinates' welfare and respect). Option B is the language of the Blake and Mouton Managerial Grid, and option D names factors in Fiedler's contingency model. Option A lists elements of transactional leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 57, $official_bank_source${"itemId":"bf192e04-6ff7-5ecf-b773-320872fddb5e","questionId":"c0b9455c-af54-5799-bc62-523cb0f8af3a","sourceKey":"bank:BUA205:OVR-030","payload":{"prompt":"A supervisor at a bottling plant in Ikeja is known for being friendly, respecting his workers' ideas and showing real concern for their welfare. In the Ohio State studies, this behaviour is called:","options":["Initiating structure","Position power","Management by exception","Consideration"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Consideration describes leader behaviour that shows trust, respect and concern for followers' welfare, which matches this supervisor. Option A is the task side, such as assigning work and setting standards. Option C is a transactional practice of intervening when things go wrong, and option B is a Fiedler situational factor."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 58, $official_bank_source${"itemId":"ab7bc647-a2df-5a12-be73-5cf4239169ca","questionId":"e473274d-29a7-5987-82fd-b448231ae0ba","sourceKey":"bank:BUA205:OVR-031","payload":{"prompt":"The University of Michigan leadership studies classified leaders as either:","options":["Transformational or transactional","Autocratic or democratic","Employee-centred or job-centred","Task-motivated or relationship-motivated on the LPC scale"],"correctOption":2,"section":"An Overview of Leadership","explanation":"The Michigan studies contrasted employee-centred leaders, who focus on people and their needs, with job-centred (production-centred) leaders, who focus on tasks and output. Option B reflects the Iowa studies by Kurt Lewin, and option A is a later contemporary distinction. Option D is Fiedler's contingency model."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 59, $official_bank_source${"itemId":"464ee378-aef5-58f0-8848-20ac8363b634","questionId":"18fb4b42-db9d-52be-a353-79e0e6db8dcf","sourceKey":"bank:BUA205:OVR-032","payload":{"prompt":"On the Blake and Mouton Managerial Grid, a manager rated 9,9 (high concern for people and high concern for production) practises:","options":["Impoverished management","Team management","Middle-of-the-road management","Country club management"],"correctOption":1,"section":"An Overview of Leadership","explanation":"The 9,9 position combines maximum concern for production with maximum concern for people and is called team management, usually presented as the ideal. Option D is 1,9 (people high, production low), option A is 1,1 (both low), and option C is 5,5 (moderate on both)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 60, $official_bank_source${"itemId":"2efc82f8-e5f3-5728-900a-bf4a3b187369","questionId":"2a3fddb4-8ea6-52b5-ab1b-3a66515fa31f","sourceKey":"bank:BUA205:OVR-033","payload":{"prompt":"A branch manager keeps his staff happy with relaxed rules, frequent parties and little pressure, but the branch rarely meets its targets. On the Managerial Grid, his style is best described as:","options":["Country club management (1,9)","Authority-compliance management (9,1)","Impoverished management (1,1)","Team management (9,9)"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Country club management (1,9) shows high concern for people but low concern for production, creating a comfortable atmosphere while output suffers. Option D is high on both, and option B is high on production with little concern for people. Option C shows little concern for either people or production, but this manager clearly cares about staff comfort."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 61, $official_bank_source${"itemId":"f25b8a7d-f950-513a-9cd4-fb2162982cef","questionId":"951989a5-f206-56bc-8034-15d5e87159e2","sourceKey":"bank:BUA205:OVR-034","payload":{"prompt":"Kurt Lewin's leadership studies at the University of Iowa identified which three leadership styles?","options":["Telling, selling and delegating","Directive, supportive and participative","Autocratic, democratic and laissez-faire","Transformational, transactional and servant"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Lewin's Iowa studies compared groups led in autocratic, democratic and laissez-faire ways, and these became the classic traditional styles. Option A lists styles from Hersey and Blanchard's situational model, and option B comes from House's path-goal theory. Option D mixes later contemporary approaches."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 62, $official_bank_source${"itemId":"1839c2fd-4350-52a8-8a42-89943f415013","questionId":"1a7a4730-128a-56c0-b14c-1bce339fcf03","sourceKey":"bank:BUA205:OVR-035","payload":{"prompt":"In Fiedler's contingency model, the Least Preferred Co-worker (LPC) scale is used to determine:","options":["Whether a leader is task-oriented or relationship-oriented","Which reward a follower prefers","How much position power the leader holds","How mature or ready the followers are"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Fiedler used the LPC scale to identify a leader's basic style: a leader who describes their least preferred co-worker harshly is task-oriented, while one who describes them favourably is relationship-oriented. Option D is the focus of Hersey and Blanchard's model, and option C is one of Fiedler's situational factors, not what the LPC measures. Option B relates to transactional exchange."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 63, $official_bank_source${"itemId":"e627321b-abf1-5a63-a955-33ab9d70fa86","questionId":"f342bcba-3dd3-5f4d-b1d8-1e744ac03d65","sourceKey":"bank:BUA205:OVR-036","payload":{"prompt":"Which of the following is NOT one of the three factors Fiedler used to judge how favourable a situation is for a leader?","options":["Leader-member relations","Position power","Follower maturity or readiness","Task structure"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Fiedler judged situational favourableness by leader-member relations, task structure and position power. Follower maturity or readiness belongs to Hersey and Blanchard's situational leadership model, not Fiedler's. Options A, D and B are Fiedler's three factors."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 64, $official_bank_source${"itemId":"54ad7c21-601d-5821-8393-c26eb31dc9a4","questionId":"d3ffe182-f2af-5993-91ee-cef86936bbf8","sourceKey":"bank:BUA205:OVR-037","payload":{"prompt":"Because Fiedler assumed that a leader's style is relatively fixed, his model suggests that organisations should:","options":["Train every leader to switch styles daily","Allow followers to choose their leader's style","Ignore the situation and select leaders by traits","Match leaders to suitable situations or change the situation"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Since Fiedler believed leaders cannot easily change their basic style, the practical advice is to place leaders in situations that suit them, or to change the situation to fit the leader. Option A reflects situational models such as Hersey and Blanchard's, which assume flexibility. Option C returns to trait thinking, and option B is not part of the model."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 65, $official_bank_source${"itemId":"4b15e6ee-ea5f-5537-921a-958331f0fcf9","questionId":"1ddb0531-b678-59d0-9367-0446a7becda4","sourceKey":"bank:BUA205:OVR-038","payload":{"prompt":"A fresh graduate trainee in a Port Harcourt oil-services firm is unable to perform a new technical task and is unsure of himself. Under Hersey and Blanchard's situational model, which style should his supervisor use?","options":["Delegating","Telling","Participating","Selling"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Followers with low readiness, who lack both ability and confidence, need the telling style: clear, specific instructions and close supervision. Option D suits followers who are willing but still lack ability. Option C suits able but unsure followers, and option A suits followers who are both able and willing."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 66, $official_bank_source${"itemId":"d844d4b0-e811-56bb-add0-d054077a2464","questionId":"b0c046e6-2e28-5e9b-82bb-4f749a619959","sourceKey":"bank:BUA205:OVR-039","payload":{"prompt":"A senior accountant is highly skilled, confident and keen to take ownership of the month-end close. Under Hersey and Blanchard's situational model, the most suitable style is:","options":["Telling","Selling","Delegating","Directing with close supervision"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Followers with high readiness, who are both able and willing, respond best to delegating, where the leader hands over responsibility with little direction or support. Options A and D give heavy direction that would frustrate a capable follower. Option B still combines high direction with high support, which this accountant does not need."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 67, $official_bank_source${"itemId":"ecde4115-c3e5-5e2e-883c-46ad33f76912","questionId":"3b05b88d-4740-5658-a2b7-081595c7c0c5","sourceKey":"bank:BUA205:OVR-040","payload":{"prompt":"In Hersey and Blanchard's situational model, the 'selling' (coaching) style combines:","options":["Low task behaviour and high relationship behaviour","High task behaviour and high relationship behaviour","Low task behaviour and low relationship behaviour","High task behaviour and low relationship behaviour"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Selling keeps giving direction (high task) while also explaining decisions and offering support (high relationship). Option D is telling, option A is participating, and option C is delegating."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 68, $official_bank_source${"itemId":"307a95b8-157d-529d-9433-5b7d023453ba","questionId":"7e8a1357-b1bb-51cf-bd79-bea84fbc70d5","sourceKey":"bank:BUA205:OVR-041","payload":{"prompt":"Which of the following is a contingency theory of leadership?","options":["The Ohio State studies","The Great Man theory","The Managerial Grid","Fiedler's contingency model"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Fiedler's model is the classic contingency theory because it says effectiveness depends on matching the leader's style to the favourableness of the situation. Option B is a trait theory. Options A and C are behavioural approaches that describe what leaders do without making the situation central."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 69, $official_bank_source${"itemId":"c6a4c069-758f-5f16-b459-c36d0ed95841","questionId":"936f9f9c-43dc-5b70-97ea-6fa243886405","sourceKey":"bank:BUA205:OVR-042","payload":{"prompt":"Which of the following belongs to the behavioural approach to leadership?","options":["House's path-goal theory","The Great Man theory","Blake and Mouton's Managerial Grid","Fiedler's contingency model"],"correctOption":2,"section":"An Overview of Leadership","explanation":"The Managerial Grid describes leader behaviour in terms of concern for people and concern for production, which makes it a behavioural approach. Options D and A are contingency or situational theories because they tie effectiveness to the situation. Option B is a trait theory."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 70, $official_bank_source${"itemId":"3577243d-a665-5080-b095-47f994d0f1e3","questionId":"7246845f-d1da-5774-8fbf-6bf67b2b6f70","sourceKey":"bank:BUA205:OVR-043","payload":{"prompt":"The political scientist who, in 1978, first distinguished 'transforming' leadership from 'transactional' leadership was:","options":["Robert Kelley","Fred Fiedler","James MacGregor Burns","Robert Blake"],"correctOption":2,"section":"An Overview of Leadership","explanation":"James MacGregor Burns introduced the contrast between transforming and transactional leadership in his 1978 book Leadership, and Bernard Bass later developed it in 1985. Option B is linked to the contingency model, option A to the followership model, and option D to the Managerial Grid."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 71, $official_bank_source${"itemId":"8e0e66ab-7e73-5da8-9e2c-299e6a0b766a","questionId":"8ff61772-2b6d-56b7-8883-391f8355aec6","sourceKey":"bank:BUA205:OVR-044","payload":{"prompt":"A factory supervisor tells workers that anyone who misses the day's quota will be issued a query and may lose part of their N80,000 monthly allowance. Which base of power is the supervisor relying on?","options":["Reward power","Referent power","Coercive power","Expert power"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Coercive power comes from the ability to punish or impose penalties, such as queries and pay deductions. Option B comes from followers' admiration of the leader, and option D from the leader's knowledge or skill. Option A is the ability to give benefits, which is the opposite of a threatened deduction."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 72, $official_bank_source${"itemId":"2cb6639a-469c-5bfe-b5eb-1552910ea2cd","questionId":"467514ee-7412-5dc5-9978-4e0c997aea93","sourceKey":"bank:BUA205:OVR-045","payload":{"prompt":"In Fiedler's model, relationship-oriented leaders tend to perform best when the situation is:","options":["Very unfavourable","Either very favourable or very unfavourable","Very favourable","Moderately favourable"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Fiedler found that relationship-oriented leaders do best in situations of moderate favourableness, while task-oriented leaders do best when the situation is either very favourable or very unfavourable. Options C, A and B describe where task-oriented leaders do best."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 73, $official_bank_source${"itemId":"aea6d6b3-65bf-5aba-91ae-706acaa319ef","questionId":"07056a80-9d45-506d-aa15-e6194f77f6f3","sourceKey":"bank:BUA205:NB-001","payload":{"prompt":"The view that leaders are born, not made, is known as the:","options":["Contingency hypothesis","Path-goal hypothesis","Social learning hypothesis","Great Man Hypothesis"],"correctOption":3,"section":"An Overview of Leadership","explanation":"The Great Man Hypothesis holds that people are born with the qualities that make them leaders, and it is the foundation of the trait approach to leadership. Options A and B tie a leader's effectiveness to the situation and to clearing paths to goals, while Option C suggests behaviour is learned by watching others, so none of them claims leaders are simply born."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 74, $official_bank_source${"itemId":"ef57945c-3aaa-557c-b6c3-90bfc57d0b86","questionId":"91dc64ba-c3d9-50dd-9ea0-5ccd6b3cf661","sourceKey":"bank:BUA205:NB-002","payload":{"prompt":"Under trait theory, height, strength, vigour and appearance are grouped as:","options":["Intelligence traits","Physical traits","Task-related abilities","Personality traits"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Height, strength, vigour and appearance are bodily features, so trait theory groups them as physical traits. Option D covers things like interpersonal skills and adaptiveness, Option A covers the ability to comprehend, plan and think, and Option C covers initiative and administrative ability."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 75, $official_bank_source${"itemId":"149d82f9-c1d1-5241-b67b-9c83e1b67079","questionId":"4f7ed091-ff7c-56da-9b18-d1926d7b3096","sourceKey":"bank:BUA205:NB-003","payload":{"prompt":"In trait theory, the ability to comprehend, conceptualise, plan and think belongs to which group of traits?","options":["Physical traits","Intelligence traits","Personality traits","Task-related abilities"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Comprehending, conceptualising, planning and thinking are mental capacities, which trait theory classes as intelligence traits. Option A refers to features such as height and vigour, Option D refers to initiative and administrative ability, and Option C refers to qualities such as interpersonal skills and aggressiveness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 76, $official_bank_source${"itemId":"79b0ca5f-7608-58a2-af38-3e3369cae089","questionId":"d5a4217a-1234-5f80-bc26-9b216ae1bda9","sourceKey":"bank:BUA205:NB-004","payload":{"prompt":"Initiative and administrative ability are classified in trait theory as:","options":["Personality traits","Intelligence traits","Task-related abilities","Physical traits"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Initiative and administrative ability relate to getting a job started and running it well, so they are task-related abilities. Option B is about comprehending and planning, Option A is about interpersonal style and temperament, and Option D refers to bodily features like height and strength."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 77, $official_bank_source${"itemId":"d551178c-3018-55ee-9194-303f9f56b56d","questionId":"fcdce817-75b5-5bc0-abd8-5068dbfa11ee","sourceKey":"bank:BUA205:NB-005","payload":{"prompt":"Interpersonal skills, aggressiveness and adaptiveness are examples of which group of leadership traits?","options":["Task-related abilities","Physical traits","Personality traits","Intelligence traits"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Interpersonal skills, aggressiveness and adaptiveness describe a person's temperament and way of relating to others, so trait theory lists them as personality traits. Option A covers initiative and administrative ability, Option D covers the ability to think and plan, and Option B covers features such as height and appearance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 78, $official_bank_source${"itemId":"0f28bccd-cfad-545e-b140-478b9392321c","questionId":"5aa88710-3c03-5e3f-afcc-930f5eaa0b75","sourceKey":"bank:BUA205:NB-006","payload":{"prompt":"Which of the following is NOT one of the groups of traits identified by trait theory?","options":["Social-class traits such as family name and inheritance","Task-related abilities such as initiative","Intelligence traits such as the ability to plan and think","Physical traits such as height and vigour"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Trait theory groups leadership qualities into physical traits, intelligence traits, task-related abilities and personality traits, and social class is not one of these groups. Options D, C and B each name a real trait group with a correct example."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 79, $official_bank_source${"itemId":"6d4a64f6-23a0-59bf-b41e-fbdbf9722116","questionId":"1b3b0af5-91bc-535c-a8d8-c6767dec22d8","sourceKey":"bank:BUA205:NB-007","payload":{"prompt":"Which pairing of a trait and its trait group is CORRECT?","options":["Aggressiveness - task-related ability","Ability to plan - physical trait","Vigour - intelligence trait","Initiative - task-related ability"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Initiative sits with administrative ability under task-related abilities, so this pairing is correct. Option C is wrong because vigour is a physical trait, Option B is wrong because planning is an intelligence trait, and Option A is wrong because aggressiveness is a personality trait."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 80, $official_bank_source${"itemId":"ca650445-e9e1-5e90-b20e-a047552cda32","questionId":"e7e01197-f0de-5335-ad5d-488e3472b417","sourceKey":"bank:BUA205:NB-008","payload":{"prompt":"A managing director led a Lagos distribution firm very well during stable years, but with exactly the same personal qualities he struggled badly when a sudden currency crisis hit the firm. Which limitation of trait theory does this case illustrate?","options":["It provides no basis for comparing the traits","It ignores situational factors","It focuses too much on followers' needs","It assumes leadership is learned through training"],"correctOption":1,"section":"An Overview of Leadership","explanation":"The leader's traits did not change, yet his success did, because the situation changed; trait theory is criticised for ignoring such situational factors. Option A is the other limitation of trait theory, but it concerns measuring one leader's traits against another's, which is not the issue here. Options D and C are not features of trait theory at all, since it holds that leaders are born and it centres on the leader rather than followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 81, $official_bank_source${"itemId":"3cb0e3b1-ba31-5c32-9871-deea962a0545","questionId":"192a4399-2a7f-5caa-b58b-51966cced5ac","sourceKey":"bank:BUA205:NB-009","payload":{"prompt":"Two consultants assess the same pair of managers for 'vigour' and 'initiative' but cannot agree on any yardstick for saying that one manager has more of a trait than the other. Which limitation of trait theory does this reflect?","options":["It ignores situational factors","It treats leadership style as fixed by the organisation's policies","It relies on rewards and punishments to explain leadership","It provides no basis for comparing the traits"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Trait theory lists qualities leaders should have but offers no basis for comparing those traits between people, which is exactly the consultants' problem. Option A is a real limitation too, but it is about the setting in which a leader works, not about measuring traits. Option C describes transactional ideas and Option B describes bureaucratic leadership, neither of which is a criticism of trait theory."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 82, $official_bank_source${"itemId":"ad22aba6-8bd3-580c-b2db-1053148f7adb","questionId":"8b25b72a-6349-5e69-99f3-0fa1e5a1feab","sourceKey":"bank:BUA205:NB-010","payload":{"prompt":"Which of the following is NOT a limitation of trait theory?","options":["It ignores situational factors","It has not produced an agreed list of leadership traits","It assumes anyone can become a leader through training","It provides no basis for comparing the traits"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Trait theory rests on the Great Man Hypothesis that leaders are born, not made, so it does not claim that anyone can be trained into leadership; that statement is the opposite of the theory, not a limitation of it. Options A, D and B are genuine weaknesses: the theory overlooks the situation, offers no yardstick for comparing traits, and has never settled on one agreed list."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 83, $official_bank_source${"itemId":"64f1bf8c-271f-58b9-829f-f9dddb17c632","questionId":"55f7e230-c024-526e-a48e-d6c14070ccdc","sourceKey":"bank:BUA205:NB-011","payload":{"prompt":"A leader's ability to influence others that comes from personal sources such as intelligence, wealth or even physical beauty is best described as:","options":["Authority","Power","Accountability","Delegation"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Power is the capacity to influence others, and it can come from personal attributes such as intelligence, wealth or even beauty. Option A is different because it is the right to command, conferred by culture, society or an organisation. Option D is passing tasks to others and Option C is being answerable for one's actions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 84, $official_bank_source${"itemId":"4ad39ff4-4cb0-5c3b-ab41-6afebb2f3858","questionId":"c9b2fb22-909c-548a-8b0e-193e96e17a4f","sourceKey":"bank:BUA205:NB-012","payload":{"prompt":"In leadership, authority is best defined as:","options":["The right to command","The freedom of subordinates to set their own goals","The ability to influence others through wealth or beauty","The duty to report to shareholders on performance"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Authority is the right to command, and it is conferred on a person by culture, society or an organisation. Option C describes where power comes from rather than authority, Option D describes accountability, and Option B describes the autonomy given under laissez-faire leadership."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 85, $official_bank_source${"itemId":"a6d6a094-8424-5143-9bc9-db5b6a6087fa","questionId":"bb9d1fed-620f-5dc5-a02e-217e8b65c0e9","sourceKey":"bank:BUA205:NB-013","payload":{"prompt":"Within a company, formal authority is conferred on leaders through:","options":["The board of directors","The company's customers","The employees' trade union","The external auditors"],"correctOption":0,"section":"An Overview of Leadership","explanation":"In an organisation, the right to command flows from the board of directors, which confers authority on executives and managers. Option C represents workers' interests, Option B buys the firm's products and Option D examines its financial statements, but none of them grants managers the right to command."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 86, $official_bank_source${"itemId":"231f5451-4a19-5704-bc5e-2dbab80687d5","questionId":"9f592954-8af4-5a33-935c-2f52c52acb95","sourceKey":"bank:BUA205:NB-014","payload":{"prompt":"Which of the following is NOT a quality that authority should have?","options":["It should be consistent with individual belief and organisational purpose","It should be clear","It should be known only to the leader and kept from subordinates","It should be feasible and capable of being carried out"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Authority must be clear, feasible, consistent with individual belief and organisational purpose, and capable of being carried out; authority that subordinates cannot see is the opposite of clear. Options B, D and A are all qualities sound authority should have."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 87, $official_bank_source${"itemId":"6c2d062e-3c57-5b8d-a64a-783e389d04ed","questionId":"a7646556-a806-556a-939c-b42dc71ab86c","sourceKey":"bank:BUA205:NB-015","payload":{"prompt":"A new branch manager in Ibadan is told by head office to 'handle staff matters as necessary', but nobody explains which decisions she may take on leave, discipline or hiring. Which quality of authority is missing?","options":["Consistency with organisational purpose","Clarity","Consistency with individual belief","Feasibility"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Authority must be clear, so the holder knows exactly what she is allowed to decide; a vague instruction with no stated limits fails this test. Nothing suggests the authority is impossible to exercise, as Option D would mean, or that it conflicts with the firm's purpose or her personal beliefs, as Options A and C would mean."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 88, $official_bank_source${"itemId":"1b1add1c-1969-5b2a-9211-36961a935e2d","questionId":"7805879f-a459-5600-89ee-d538535d652a","sourceKey":"bank:BUA205:NB-016","payload":{"prompt":"Which statement correctly distinguishes power from authority?","options":["Power and authority mean exactly the same thing and can be used interchangeably","Power is the right to command conferred by the board, while authority arises from personal beauty or wealth","Authority comes only from personal wealth, while power comes only from written job descriptions","Authority is the right to command conferred by culture, society or an organisation, while power can arise from personal sources such as intelligence or wealth"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Authority is a right to command that is conferred, for example by an organisation through its board, whereas power is the ability to influence and can come from personal attributes such as intelligence, wealth or beauty. Option B swaps the two ideas, Option A wrongly treats them as identical, and Option C gets the origin of each one wrong."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 89, $official_bank_source${"itemId":"6da8b5d6-4dc9-50a2-a10b-6e26cc42de09","questionId":"231f988a-9801-5a1a-b770-ae2d073d993e","sourceKey":"bank:BUA205:NB-017","payload":{"prompt":"Under the behavioural theory of leadership, which of the following describes an autocratic leader?","options":["Sets no goals and lets things drift","Puts followers' needs and growth first","Leads by coercion and acts as a fault-finder rather than a coach","Trusts subordinates and expects their feedback"],"correctOption":2,"section":"An Overview of Leadership","explanation":"The autocratic leader allows no subordinate participation, leads by coercion and looks for faults instead of coaching people. Option D describes the democratic leader, Option A describes the laissez-faire leader, and Option B describes servant leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 90, $official_bank_source${"itemId":"2c6ccf45-df8d-54b4-8604-3b2bdf55e415","questionId":"d23d9e8c-21dd-56c8-b252-3463ec91be0a","sourceKey":"bank:BUA205:NB-018","payload":{"prompt":"Which pairing of leader type and communication pattern is CORRECT?","options":["Autocratic leader - two-way communication; democratic leader - one-way communication","Autocratic and democratic leaders both use only one-way communication","Laissez-faire leader - one-way communication; democratic leader - no communication","Autocratic leader - one-way communication; democratic leader - two-way communication"],"correctOption":3,"section":"An Overview of Leadership","explanation":"The autocratic leader passes instructions down with one-way communication, while the democratic leader uses two-way communication and expects feedback from subordinates. Option A reverses the two styles, Option B ignores the feedback the democratic leader seeks, and Option C misdescribes both styles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 91, $official_bank_source${"itemId":"df9b464e-241e-530e-95de-5422a15ca0e9","questionId":"4930e82c-2dd7-51f0-ad11-edd01c0f349d","sourceKey":"bank:BUA205:NB-019","payload":{"prompt":"The main merit of the autocratic leadership style is that:","options":["Creativity and personal initiative are boosted","Workers feel recognised and motivated","Subordinates take part in every decision","Things get done quickly"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Because the autocratic leader decides alone without waiting for input, things get done quickly. Option B is the merit of democratic leadership, Option A is the merit of laissez-faire leadership, and Option C is the opposite of autocratic leadership, which allows no subordinate participation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 92, $official_bank_source${"itemId":"44655155-2e6e-52c9-9083-7daf6b6ab2a8","questionId":"af287b72-db28-52b5-bc37-0d087db1a6ef","sourceKey":"bank:BUA205:NB-020","payload":{"prompt":"At a Kano packaging factory, the manager decides everything alone, gives orders without explanation and publicly criticises any mistake. Orders are executed fast, but staff are increasingly unhappy and withdrawn. Which drawback of this leadership style is shown?","options":["It leads to slow decision-making","It hurts workers' morale","It encourages too much entrepreneurial freedom","It leaves the group without direction"],"correctOption":1,"section":"An Overview of Leadership","explanation":"This is autocratic leadership, whose demerit is that it hurts workers' morale even though work gets done quickly. Option A is the demerit of democratic leadership, while Options D and C relate to laissez-faire leadership, where the leader is absent and gives no direction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 93, $official_bank_source${"itemId":"bbc6b7fc-0fc2-56be-8b11-d1e8fc7ab7aa","questionId":"09df7b73-157d-53a9-83c3-0b26cd2fd83f","sourceKey":"bank:BUA205:NB-021","payload":{"prompt":"A major demerit of the democratic leadership style is:","options":["Low worker morale","Leadership by coercion","Absence of direction from the leader","Slow decision-making"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Democratic leaders involve subordinates and seek their feedback before deciding, which takes time and makes decision-making slow. Options A and C are demerits of the autocratic and laissez-faire styles respectively, and Option B is a feature of the autocratic leader."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 94, $official_bank_source${"itemId":"bf8f465a-ad93-5d6e-8344-afeac614a444","questionId":"8098ec62-3931-5198-b8d7-505776b6e0dc","sourceKey":"bank:BUA205:NB-022","payload":{"prompt":"Which of the following is a merit of the laissez-faire leadership style?","options":["It ensures strict compliance with policies","It gets things done quickly through firm control","It provides close direction at every stage","It boosts creativity and personal initiative"],"correctOption":3,"section":"An Overview of Leadership","explanation":"Because the laissez-faire leader sets no directives and lets individuals think and decide for themselves, the style boosts creativity, personal initiative and an entrepreneurial mindset. Option B is the merit of autocratic leadership, Option C is the opposite of a style in which the leader is largely absent, and Option A describes bureaucratic leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 95, $official_bank_source${"itemId":"b4c1dda6-222e-5693-81cb-3e75e018cb7c","questionId":"9bc3a564-b814-5c54-b20a-f7aa5d7f4efc","sourceKey":"bank:BUA205:NB-023","payload":{"prompt":"At a start-up in Yaba, the founder rarely shows up, sets no targets and lets each team do as it likes. Some new ideas emerge, but projects wander off course and deadlines are missed. Which demerit of laissez-faire leadership is shown?","options":["Decisions are slow because everyone must be consulted","Rigid rules block every new idea","The leader is not there to give direction, so the group easily drifts","Workers' morale is hurt by coercion"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Laissez-faire leaders are often absent and give no direction, so the group easily drifts, which is exactly what is happening here. Option A is the demerit of democratic leadership, Option D is the demerit of autocratic leadership, and Option B describes an over-bureaucratic setting rather than one with no rules."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 96, $official_bank_source${"itemId":"2b28b9d8-b2e2-5cb3-8767-f14450e7bf2e","questionId":"fa278c82-9c93-560f-b0ff-2a6faf3b1125","sourceKey":"bank:BUA205:NB-024","payload":{"prompt":"Which pairing of leadership style and its demerit is CORRECT?","options":["Democratic - slow decision-making","Laissez-faire - morale hurt by coercion","Autocratic - easy for the group to drift","Autocratic - slow decision-making"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Democratic leadership involves subordinates in decisions, so its demerit is slow decision-making. Option C is wrong because drifting is a laissez-faire problem, Option B is wrong because coercion belongs to the autocratic style, and Option D is wrong because autocratic leadership gets things done quickly."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 97, $official_bank_source${"itemId":"073a1774-91c5-5bf7-b663-21201a5e891d","questionId":"0f524f7c-c6df-5feb-aedb-85bf819b4ab3","sourceKey":"bank:BUA205:NB-025","payload":{"prompt":"Which of the following is NOT a quality of an effective leader?","options":["Keeping away from subordinates to protect one's authority","Having a vision","Possessing interpersonal skill","Being decisive"],"correctOption":0,"section":"An Overview of Leadership","explanation":"Effective leaders are decisive, have a vision, are empathetic with good conceptual skills, and have interpersonal skill, all of which involve engaging with people rather than avoiding them. Options D, B and C are each listed qualities of an effective leader."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 98, $official_bank_source${"itemId":"34f8ca27-0a37-5c6b-877a-26397d666ffb","questionId":"15aee6b9-50ac-56d3-83ea-c7719e3a51d0","sourceKey":"bank:BUA205:NB-026","payload":{"prompt":"Faced with two competing proposals and a tight deadline, the head of a Lagos logistics firm weighs the facts and makes a firm choice the same afternoon instead of postponing. Which quality of an effective leader is she showing?","options":["Physical vigour","Decisiveness","Interpersonal skill","Empathy"],"correctOption":1,"section":"An Overview of Leadership","explanation":"Making a firm, timely choice between alternatives rather than putting it off is decisiveness, which is a key quality of an effective leader. Option D is about understanding others' feelings and Option C is about relating well with people, while Option A is a physical trait, and none of these describes making the decision itself."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 99, $official_bank_source${"itemId":"a76d5c29-ebe3-56b3-a892-ec372c541037","questionId":"7a8e85ed-0bb0-5101-8b9f-8bd93734e531","sourceKey":"bank:BUA205:NB-027","payload":{"prompt":"A mental picture of what someone aims to achieve within a time frame, given the constraints they face, is called a:","options":["Vision","Policy","Procedure","Budget"],"correctOption":0,"section":"An Overview of Leadership","explanation":"A vision is the mental picture of the future a person or organisation aims to reach within a time frame, given its constraints, and goals and objectives then make it more concrete. Options B and C are guidelines and step-by-step methods for doing things, and Option D is a financial plan, so none of them is the broad picture of what is to be achieved."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 100, $official_bank_source${"itemId":"f72e759b-3d6c-5e71-a47c-a302ab757d6d","questionId":"0cbfa0be-a80c-53ae-b16e-2493cfa94ac8","sourceKey":"bank:BUA205:NB-028","payload":{"prompt":"Which option arranges vision, goal and objective from the broadest to the most concrete?","options":["Vision, objective, goal","Goal, vision, objective","Vision, goal, objective","Objective, goal, vision"],"correctOption":2,"section":"An Overview of Leadership","explanation":"A vision is the broad mental picture, a goal narrows it down, and an objective is more concrete than a goal. For example, quality education is the vision, university education is the goal, and a four-year course is the objective. Option D reverses the order, while Options B and A put the middle and last items in the wrong places."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 101, $official_bank_source${"itemId":"e002f8ab-3b2d-5552-9a65-558edcc50b22","questionId":"ad147e5e-bcc2-5058-885b-142a9b67129d","sourceKey":"bank:BUA205:NB-029","payload":{"prompt":"Tunde's aim in life is a quality education. To achieve it, he decides to obtain a university education, and he enrols for a four-year degree course. In this example, the four-year degree course is his:","options":["Vision","Mission","Objective","Goal"],"correctOption":2,"section":"An Overview of Leadership","explanation":"The four-year course is the most concrete, specific target, so it is the objective. Option A is the broad aim of a quality education and Option D is the university education that narrows it down. Option B is not one of the three levels in this example."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 102, $official_bank_source${"itemId":"5f5584b5-c47b-58b9-97b6-007ed7e08d7d","questionId":"1bdedafd-fced-5bf6-b773-4251fc15b2f5","sourceKey":"bank:BUA205:NB-030","payload":{"prompt":"Which of the following is a role of a leader?","options":["Bringing people together","Leaving subordinates to settle every conflict on their own","Postponing decisions until everyone agrees","Keeping key information away from followers"],"correctOption":0,"section":"An Overview of Leadership","explanation":"A leader is expected to be firm and decisive in decisions and to bring people together towards the group's goal. Options B and D would divide the group rather than unite it, and Option C is the opposite of being firm and decisive."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 103, $official_bank_source${"itemId":"7982019c-4aad-5a04-8c50-137fbed545aa","questionId":"3610c305-ba1a-54d1-82a1-786748b8a6e5","sourceKey":"bank:BUA205:NB-031","payload":{"prompt":"The sales and finance departments of an Abuja firm have been feuding for months. The new MD meets both teams, settles their differences and gets them working on a joint plan. Which role of a leader is the MD performing?","options":["Enforcing rules as a compliance officer","Exercising physical vigour","Bringing people together","Being firm and decisive in decisions"],"correctOption":2,"section":"An Overview of Leadership","explanation":"Uniting feuding groups and getting them to work towards a shared plan is the leader's role of bringing people together. Option D is the other role of a leader, but the case is about reconciling people rather than making a firm choice, Option B is a physical trait, and Option A describes bureaucratic leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 104, $official_bank_source${"itemId":"f922df08-c770-5442-b4ad-90af253859c0","questionId":"27768fb7-3ce2-5b95-a35a-3745c6db8f48","sourceKey":"bank:BUA205:PQ-029-b","payload":{"prompt":"Which of the following is NOT one of the four dimensions of transformational leadership?","options":["Intellectual stimulation","Idealised influence (charisma)","Individualised consideration","Contingent reward"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Contingent reward, where rewards or sanctions follow whether targets are met, is an element of transactional leadership. Idealised influence (B), intellectual stimulation (A) and individualised consideration (C), together with inspirational motivation, are the four dimensions of transformational leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 105, $official_bank_source${"itemId":"b6a0f2dc-ecb3-534d-a46a-1cdf3c16afd8","questionId":"0a715db1-f054-5977-9b94-1f1ae41349f9","sourceKey":"bank:BUA205:PQ-041-b","payload":{"prompt":"Laissez-faire leadership, in which the leader is hands-off and allows group members to make decisions, is also known as ____ leadership.","options":["Participative","Delegative","Bureaucratic","Authoritarian"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire, from the French for 'leave it alone', is also called delegative leadership because decision-making is handed over to the group. Participative (A) is another name for the democratic style, authoritarian (D) is the autocratic style, and bureaucratic leadership (C) follows rules and procedures strictly."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 106, $official_bank_source${"itemId":"285c5aac-f07a-57c6-9389-02383449942f","questionId":"7a3660e1-2363-537b-90e9-a15fbb9ba3d7","sourceKey":"bank:BUA205:PQ-060-b","payload":{"prompt":"Which of the following is an element of transactional leadership?","options":["Individualised consideration","Intellectual stimulation","Management by exception","Inspirational motivation"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Transactional leadership is made up of contingent reward and management by exception (active and passive), where the leader steps in to correct deviations from standards. Intellectual stimulation (B), inspirational motivation (D) and individualised consideration (A) are all dimensions of transformational leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 107, $official_bank_source${"itemId":"4b1ad9b2-8b02-5161-a173-a686e4ed5d77","questionId":"4f42ea57-230a-5032-b198-3f2fee3d771f","sourceKey":"bank:BUA205:PQ-065","payload":{"prompt":"A leadership approach that links performance directly to rewards exemplifies ____","options":["Participative leadership","Servant leadership","Transformational leadership","Transactional leadership"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Linking performance directly to rewards is the core of transactional leadership, where the leader exchanges rewards for results. Participative leadership (A) shares decisions, servant leadership (B) serves followers' needs, and transformational leadership (C) inspires through vision and values."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 108, $official_bank_source${"itemId":"70478c11-8bcb-51b8-914a-80b96940226b","questionId":"30381453-73f6-53b9-bc21-20c628f811f3","sourceKey":"bank:BUA205:PQ-092-b","payload":{"prompt":"Which of the following is NOT one of the three main elements of transactional leadership?","options":["Intellectual stimulation","Management by exception (active)","Management by exception (passive)","Contingent reward"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Intellectual stimulation belongs to transformational leadership, where the leader encourages followers to question old ways and find new solutions. Transactional leadership is made up of contingent reward, active management by exception and passive management by exception, so Option D (contingent reward), like the other two remaining options, is one of them."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 109, $official_bank_source${"itemId":"3af726cb-fdcc-51db-b623-c59f4986e098","questionId":"ee3865bd-1dff-59ca-8982-24676239dd2a","sourceKey":"bank:BUA205:PQ-104-b","payload":{"prompt":"Self-awareness, relational transparency, balanced processing and a strong moral perspective are the components of which leadership approach?","options":["Transactional leadership","Servant leadership","Laissez-faire leadership","Authentic leadership"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Authentic leadership is built on knowing oneself, being open in relationships, weighing information fairly and acting on firm moral values. Option B (servant leadership) is close because it is also ethical, but it centres on putting followers' needs first; Option A (transactional leadership) and Option C (laissez-faire leadership) are about rewards and hands-off direction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 110, $official_bank_source${"itemId":"8d8e3511-5dbc-50ca-8531-f0dee93f5600","questionId":"e4640126-f180-538b-adc5-81a1f361bafd","sourceKey":"bank:BUA205:PQ-133-b","payload":{"prompt":"Laissez-faire leadership is also known as which of the following?","options":["Participative leadership","Authoritarian leadership","Bureaucratic leadership","Delegative leadership"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire leadership is also called delegative leadership because the leader hands decisions over to group members and gives them wide freedom. Option A (participative leadership) is another name for democratic leadership, where the leader still guides and has the final say, while Option B (authoritarian leadership) and Option C (bureaucratic leadership) keep tight control."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 111, $official_bank_source${"itemId":"02b1d6b3-545c-5bce-8b7b-bfc5a400d690","questionId":"4ae5e7c0-c35e-5e68-8144-b7bcc6cee419","sourceKey":"bank:BUA205:PQ-177","payload":{"prompt":"Leadership that focuses on engaging followers and building shared commitment to a collective vision is:","options":["Bureaucratic leadership","Autocratic leadership","Transactional leadership","Transformational leadership"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Transformational leaders inspire followers with a compelling vision, engage them emotionally and build commitment to shared goals, often motivating them to go beyond self-interest. Transactional leadership (option C) relies on rewards and sanctions, bureaucratic leadership (option A) on rules and procedures, and autocratic leadership (option B) on centralised control with little follower input."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 112, $official_bank_source${"itemId":"9875a2e1-675c-553a-95b9-7494e4ef0f22","questionId":"d1d0eb3f-2706-5787-947f-8322bcf57818","sourceKey":"bank:BUA205:PQ-186","payload":{"prompt":"A leader who primarily relies on rewards and punishments to motivate followers is practising which leadership style?","options":["Transactional leadership","Transformational leadership","Servant leadership","Laissez-faire leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Transactional leadership is based on an exchange: followers who meet targets are rewarded, and poor performance is sanctioned, through contingent reward and management by exception. Transformational leadership (option B) motivates through vision and inspiration, servant leadership (option C) through putting followers' needs first, and laissez-faire leadership (option D) involves very little intervention at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 113, $official_bank_source${"itemId":"c2e7cd3b-6233-5383-a963-296e62a18266","questionId":"63f48bce-b33d-5dc8-943d-94f2747efa9e","sourceKey":"bank:BUA205:PQ-187","payload":{"prompt":"Transformational leadership is BEST associated with which of the following?","options":["Inspiring followers to exceed their own self-interest for the good of the group","Maintaining the status quo through rule enforcement","Using coercive power to ensure compliance","Allowing followers to work independently without supervision"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Transformational leaders use charisma, inspirational motivation, intellectual stimulation and individual consideration to raise followers' commitment, so that people put the group's goals above narrow self-interest. Option B describes a rule-focused transactional or bureaucratic approach, option D describes laissez-faire leadership, and option C describes autocratic leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 114, $official_bank_source${"itemId":"74e3ad10-ed05-552b-8067-b3606fb27e30","questionId":"e7cc9a30-8620-5efc-a814-b0942ff2d0b8","sourceKey":"bank:BUA205:PQ-188","payload":{"prompt":"Traditional leadership styles include all of the following EXCEPT:","options":["Autocratic style","Laissez-faire style","Democratic (participative) style","Authentic leadership style"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"The traditional leadership styles are autocratic, democratic or participative, bureaucratic and laissez-faire. Authentic leadership, which stresses self-awareness, relational transparency and a strong moral perspective, is a more recent, values-based approach. Options A, C and B are all traditional styles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 115, $official_bank_source${"itemId":"04d12e24-c040-5c3e-9eb7-71754fe9f671","questionId":"1c18fa99-a3ac-584c-915c-ca9f938cbfcf","sourceKey":"bank:BUA205:PQ-189","payload":{"prompt":"Which moral philosophy holds that the rightness of an action is judged solely by its consequences?","options":["Consequentialism (Utilitarianism)","Divine command theory","Virtue ethics","Deontology"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Consequentialism, with utilitarianism as its best-known form, judges an action right if it produces the best outcomes, often summed up as the greatest good for the greatest number. Deontology (option D) judges actions by duties and rules regardless of outcomes, virtue ethics (option C) by the character of the person acting, and divine command theory (option B) by what God commands."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 116, $official_bank_source${"itemId":"7b4f74d0-dace-5889-8fec-f91b26ea5dab","questionId":"ddcc3fd1-ea36-56ec-b9c5-a2584726f715","sourceKey":"bank:BUA205:PQ-190","payload":{"prompt":"Servant leadership places the leader's primary obligation as:","options":["Maximising profit for shareholders","Centralising decision-making at the top management level","Serving the needs of followers and the community above self-interest","Enforcing organisational rules and procedures"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Servant leaders see themselves as facilitators who put the needs, growth and well-being of followers and the community first, which builds trust and empowers teams. Profit maximisation (option A) is a business objective, rule enforcement (option D) is typical of bureaucratic leadership, and centralised decision-making (option B) is typical of autocratic leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 117, $official_bank_source${"itemId":"4d3795e1-e1fa-5d7b-9646-803d3becd799","questionId":"4deb001c-9cd2-51e7-8e98-b355f0137b1e","sourceKey":"bank:BUA205:PQ-191","payload":{"prompt":"Deontological ethics, as applied to leadership, emphasises that leaders should:","options":["Rely on intuition when making ethical decisions","Follow situational norms and cultural expectations","Maximise the greatest good for the greatest number","Act based on duties and principles regardless of outcomes"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Deontology, associated with Immanuel Kant, holds that some actions are right or wrong in themselves, so a leader must keep to duties such as honesty and fairness even when breaking them would bring a better result. Option C describes utilitarianism, which judges by outcomes, and option B describes relativism, which deontology rejects."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 118, $official_bank_source${"itemId":"15449d11-d3ef-5b36-b6ac-919aaa07e5ce","questionId":"4a3b7ee3-a270-5a55-b430-d7540d9c7827","sourceKey":"bank:BUA205:PQ-192","payload":{"prompt":"In a laissez-faire leadership style, the leader primarily:","options":["Involves employees in every decision","Focuses on charismatic inspiration and visionary speeches","Gives followers maximum autonomy with minimal intervention","Makes all decisions unilaterally"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire, French for 'leave it alone', describes a hands-off leader who offers little direction and lets followers set goals, make decisions and solve problems on their own. It works best with highly skilled, self-motivated staff. Option D is autocratic, option A is democratic, and option B describes charismatic or transformational leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 119, $official_bank_source${"itemId":"b62ffd24-449d-5290-bb66-abe4d78188d7","questionId":"7bcf354e-bf44-5eda-b484-dc3b4541bf98","sourceKey":"bank:BUA205:PQ-193","payload":{"prompt":"Contemporary leadership approaches include all of the following EXCEPT:","options":["Adaptive leadership","Authentic leadership","Autocratic/Authoritarian leadership","Distributed leadership"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Autocratic leadership, where the leader keeps decision-making power and consults followers little or not at all, is one of the traditional styles rooted in the classical approach. Authentic, distributed and adaptive leadership (options B, D and A) are more recent approaches that stress values, shared leadership and responding to change."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 120, $official_bank_source${"itemId":"e13f4808-a81a-5e59-a2b3-e521116cdffd","questionId":"c43d9443-c6ef-546f-ad71-6d18e15f0b64","sourceKey":"bank:BUA205:PQ-207","payload":{"prompt":"Virtue ethics, as applied to leadership, holds that good leadership flows from:","options":["Compliance with legally mandated behavioural codes","Following specific rules and regulations","The character and moral virtues of the leader, such as courage, honesty and prudence","Achieving the best measurable outcome regardless of method"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Virtue ethics, rooted in Aristotle, focuses on the kind of person the leader is: good decisions come from a character built on virtues such as courage, integrity, humility and wisdom. Option B reflects rule-based (deontological) thinking, option D reflects consequentialism, and option A is legal compliance rather than moral character."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 121, $official_bank_source${"itemId":"59a6ef9f-dcb5-53c8-adcb-298dbf91f19d","questionId":"92eb7c68-2fd4-57cc-8166-c63a5b6b3ab9","sourceKey":"bank:BUA205:PQ-238-d","payload":{"prompt":"Under passive management-by-exception, an element of transactional leadership, the leader:","options":["Intervenes only when problems have become serious or mistakes occur","Inspires followers with a compelling vision of the future","Gives followers complete freedom to set their own goals","Continuously monitors each follower's performance to suggest improvements"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"A leader using passive management-by-exception waits for problems to arise and acts only when they become serious, which can harm the organisation. Option D describes active management-by-exception, where the leader monitors performance closely, option B describes transformational leadership, and option C describes laissez-faire leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 122, $official_bank_source${"itemId":"7de130fe-7e3c-5c03-97d5-99e50e5ddfcd","questionId":"af313eb4-5adf-53d8-8338-cc52b8a84b26","sourceKey":"bank:BUA205:PQ-238-f","payload":{"prompt":"Which leadership style is regarded as particularly important for driving institutional reform and national development initiatives?","options":["Transactional leadership","Transformational leadership","Bureaucratic leadership","Laissez-faire leadership"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Transformational leaders create a compelling vision, encourage new ways of working and build collective commitment to change, which is exactly what reform requires. Transactional (option A) and bureaucratic (option C) leadership suit routine, rule-based operations and may discourage innovation, while laissez-faire leadership (option D) gives too little direction to drive change."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 123, $official_bank_source${"itemId":"d53d2cda-1ea6-5a41-89fe-35efb1d8df35","questionId":"95476806-62be-52fe-a547-9a0082c7dee6","sourceKey":"bank:BUA205:APP-001","payload":{"prompt":"The concept of leadership as studied in management developed in the 20th century as an offshoot of:","options":["Scientific management principles","New Public Management","Open government principles","The social contract tradition"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Modern leadership study grew in the 20th century out of scientific management, which held that workers could be scientifically observed to improve their effectiveness and performance. Option D is a theory of the origin of government, and options C and B are much later governance and reform ideas."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 124, $official_bank_source${"itemId":"2d6e3739-6852-5e81-bdcf-0c56712059e1","questionId":"b3514f2c-895f-5b24-9be6-b92dbc0672d1","sourceKey":"bank:BUA205:APP-002","payload":{"prompt":"The patterns of thinking, feeling and behaviour that people in executive positions use to handle the affairs of employees and organisations are known as:","options":["Leadership style","Followership","Leadership philosophy","Corporate governance"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Leadership style is the way a leader influences followers toward a common goal, described as the leader's patterns of thinking, feeling and behaviour in handling people and organisations. Option C is the underlying set of beliefs and values that guides a leader, while option D is the system by which a company is directed and controlled. Option B is the role of followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 125, $official_bank_source${"itemId":"87214e74-833f-51b1-89ac-03684b8459e3","questionId":"f3eecfd1-6f2a-5ec3-9784-21ba063e5a08","sourceKey":"bank:BUA205:APP-003","payload":{"prompt":"Three issues are said to influence the leadership style a leader adopts. Which of the following is NOT one of them?","options":["The organisation's traditions, values and philosophy","The manager's individual characteristics","The company's daily share price on the stock exchange","The employees being supervised"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"The style a leader adopts is shaped by the manager's own characteristics (personality, knowledge, values, ethics, experience), the employees being supervised, and the organisation (its traditions, values and philosophy). A daily share price is not one of these influences. Options B, D and A are the three listed issues."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 126, $official_bank_source${"itemId":"9d0af771-955c-5af6-983d-4b7ca8c46c97","questionId":"1e041cf8-24a2-5620-bf9a-c71463e5c17e","sourceKey":"bank:BUA205:APP-004","payload":{"prompt":"Which of the following is a traditional leadership style?","options":["Bureaucratic leadership","Transformational leadership","Authentic leadership","Transactional leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"The traditional styles are democratic (participative), autocratic, bureaucratic and laissez-faire. Options B and D are contemporary styles, and option C is an approach rooted in moral philosophy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 127, $official_bank_source${"itemId":"bce64377-70b0-55be-bbf2-169f48bb2efc","questionId":"9ff0ed95-a479-52b5-80ba-3389bdba5a6b","sourceKey":"bank:BUA205:APP-005","payload":{"prompt":"Which leadership style appears in BOTH the list of traditional styles and the list of contemporary styles?","options":["Laissez-faire","Bureaucratic","Transformational","Democratic"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire is listed among the traditional styles (with democratic, autocratic and bureaucratic) and also among the most common contemporary styles (with transformational and transactional). Options B and D appear only in the traditional list, and option C appears only in the contemporary list."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 128, $official_bank_source${"itemId":"bf6c0e1c-0663-5df9-af76-54243a5faa78","questionId":"c425a9eb-78ae-52e4-b750-801835a46aaf","sourceKey":"bank:BUA205:APP-006","payload":{"prompt":"A leader acts like a coach who keeps subordinates informed and collects their input before deciding, but still has the final say. This describes:","options":["Laissez-faire leadership","Democratic leadership","Autocratic leadership","Bureaucratic leadership"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"In democratic (participative) leadership the leader is a coach who gathers information and views from subordinates but keeps the final say. Option A hands decisions over to the group, and option D decides strictly by policy. Option C decides alone with little or no input."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 129, $official_bank_source${"itemId":"5186bf47-f90f-53a2-82cc-0f0d4f5b42d5","questionId":"50c48319-9498-55a5-8087-fccd7d566447","sourceKey":"bank:BUA205:APP-007","payload":{"prompt":"Democratic leadership often yields high productivity over long periods mainly because:","options":["Employees are monitored closely and punished for errors","The leader makes every decision without consultation","Strict procedures leave no room for employee input","Employees value the trust they receive and respond with cooperation and commitment"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Under democratic leadership many employees appreciate being trusted and respond with cooperation, team spirit and high commitment, which sustains productivity. Option B describes autocratic leadership, option A sounds like management by exception with sanctions, and option C describes bureaucratic leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 130, $official_bank_source${"itemId":"b058f946-a63c-560a-a343-2f4af616871b","questionId":"f72eb6ea-9ca3-5518-a938-d47a35cf4ad5","sourceKey":"bank:BUA205:APP-008","payload":{"prompt":"The autocratic (authoritarian) leadership style is founded on which approach to leadership?","options":["The transformational approach","The classical approach","The participative approach","The servant approach"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Autocratic leadership is founded on the classical approach, in which the leader keeps as much power and decision-making authority as possible. Option C is the basis of democratic leadership. Options D and A are people-centred modern approaches that share power."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 131, $official_bank_source${"itemId":"b9f98352-7c4e-58a8-8087-92533f25e8e5","questionId":"ab94962b-9722-578a-9efa-c019123856c8","sourceKey":"bank:BUA205:APP-009","payload":{"prompt":"A manager insists that every activity follow the company's laid-down procedures and seeks express approval from top management for any problem not covered by policy. This manager is practising:","options":["Laissez-faire leadership","Bureaucratic leadership","Transformational leadership","Autocratic leadership"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"A bureaucratic leader sticks strictly to stated policy, acts almost like a compliance officer enforcing the rules, and refers anything outside policy upward for approval. Option D also centralises control, but on the leader's own judgement rather than written policy. Option A gives staff freedom, and option C inspires change."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 132, $official_bank_source${"itemId":"0c0a2dea-7150-5143-b27e-13779bb1f38f","questionId":"aa2a4355-cbfd-5531-a3da-cc5f3c9fab1a","sourceKey":"bank:BUA205:APP-010","payload":{"prompt":"Tellers at a commercial bank in Abuja handle about N40 million in cash daily and must follow fixed counting and reconciliation procedures. Which leadership style is most suitable for supervising them?","options":["Bureaucratic leadership","Laissez-faire leadership","Democratic leadership","Transformational leadership"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Bureaucratic leadership works well when staff perform routine tasks repeatedly, handle cash, or must follow a fixed set of procedures, all of which apply to bank tellers. Option B gives too much freedom for cash handling. Options D and C have strengths, but neither is the style matched to strict procedural compliance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 133, $official_bank_source${"itemId":"ea2dbf37-79bf-59c6-b963-364c533cdd6f","questionId":"a2a15062-be03-56b4-bbb3-918b63a23869","sourceKey":"bank:BUA205:APP-011","payload":{"prompt":"Bureaucratic leadership can be effective in all of the following situations EXCEPT when:","options":["Safety training is being conducted","Employees work with unsafe or delicate equipment","Staff perform routine tasks over and over","Staff must improvise creative solutions to new, non-routine problems"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Bureaucratic leadership fits routine work, unsafe or delicate equipment, safety training, cash handling and tasks needing set principles or processes. Creative improvisation on new problems needs flexibility, which strict rules discourage. Options B, A and C are all situations where the bureaucratic style is effective."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 134, $official_bank_source${"itemId":"55d6855d-59ba-5349-898d-ac53d7da97e7","questionId":"dd31e639-053b-5953-8ee3-c06c7ff39a41","sourceKey":"bank:BUA205:APP-012","payload":{"prompt":"Laissez-faire leadership can be effective when subordinates are:","options":["Highly skilled, motivated and able to work on their own","New to the job and unsure of procedures","Handling cash under strict procedures","Unwilling to take responsibility for decisions"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire works when subordinates are highly skilful, motivated and proficient enough to work independently. Option B describes followers who need direction, and option C calls for bureaucratic leadership. Option D would make a hands-off approach fail."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 135, $official_bank_source${"itemId":"bbc68258-b235-52c8-a488-626e3c6b31c0","questionId":"2880cadc-e13a-5d6a-ba81-7f76aa675dab","sourceKey":"bank:BUA205:APP-013","payload":{"prompt":"The French expression 'laissez-faire', as used in leadership, connotes:","options":["Lead by example","Follow the rules","Reward the best","Leave it alone"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire is a French expression meaning 'leave it alone', describing a leader who lets subordinates decide, set their own goals and regulate their own work. Options A, B and C describe role modelling, bureaucratic and transactional ideas respectively, not the meaning of the phrase."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 136, $official_bank_source${"itemId":"c776bfbf-6a40-5ec6-ab1e-214dc9b67bd1","questionId":"6b4329c5-d00c-5d72-9d1a-ae3bcfe1639b","sourceKey":"bank:BUA205:APP-014","payload":{"prompt":"Laissez-faire leadership is characterised by all of the following EXCEPT:","options":["Wide-ranging freedom for subordinates to make decisions","The leader providing the tools and resources required","Minimal guidance from the leader","Close supervision of every task by the leader"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Laissez-faire is marked by minimal guidance, wide freedom for subordinates, the leader providing tools and resources, and subordinates solving problems on their own. Close supervision of every task is the opposite. Options C, A and B are all features of the style."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 137, $official_bank_source${"itemId":"f6c2d4db-42fb-5f7a-a8fe-43257f400a43","questionId":"92fb0998-f106-574f-b58f-740cd9b1c801","sourceKey":"bank:BUA205:APP-015","payload":{"prompt":"Which statement about laissez-faire leaders in practice is correct?","options":["They make all decisions and simply announce them","They rely mainly on rewards and punishments to control work","They must never speak to subordinates once goals are set","Many remain open and accessible to subordinates for consultation and feedback"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Although laissez-faire is usually read as completely hands-off, many leaders who use it still stay open and available for consultation and feedback. Option C exaggerates the hands-off idea. Option A describes autocratic leadership, and option B describes transactional leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 138, $official_bank_source${"itemId":"4c3a6866-03c7-5ca9-8a88-85d374397528","questionId":"4845b4c4-850f-52c8-b7e7-5739e8b453d9","sourceKey":"bank:BUA205:APP-016","payload":{"prompt":"Transformational leadership has four distinctive dimensions. Which of the following is NOT one of them?","options":["Intellectual stimulation","Individualised consideration","Inspirational motivation","Contingent reward"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"The four dimensions of transformational leadership are charismatic leadership (idealised influence), intellectual stimulation, individualised consideration and inspirational motivation. Contingent reward is an element of transactional leadership. Options A, B and C are transformational dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 139, $official_bank_source${"itemId":"bfc8037e-441b-5862-9661-60f844367c13","questionId":"54756132-e58e-5163-b9ce-5c723b55f718","sourceKey":"bank:BUA205:APP-017","payload":{"prompt":"Which element is described as the most vital element of transformational leadership?","options":["Charisma (idealised influence)","Management by exception","Intellectual stimulation","Individualised consideration"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Charisma, or idealised influence, is singled out as the most vital element: the leader shapes followers through personality and the values they uphold, becoming a trusted role model. Options C and D are other transformational dimensions but not the most vital one. Option B belongs to transactional leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 140, $official_bank_source${"itemId":"bfc31208-13bf-5dd0-8c69-4f3cc02f7919","questionId":"1572db34-eb38-50df-a9d6-a3dfea16efa6","sourceKey":"bank:BUA205:APP-018","payload":{"prompt":"A product manager at a Yaba tech start-up encourages her team to question long-standing assumptions, reframe problems and try new ways of solving them. Which dimension of transformational leadership is this?","options":["Intellectual stimulation","Individualised consideration","Idealised influence","Inspirational motivation"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Intellectual stimulation is when the leader promotes followers' initiative by probing established conventions, reframing problems and re-examining difficulties. Option C is about being an admired role model, and option B is about attending to each person's needs. Option D is about inspiring optimism about the future."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 141, $official_bank_source${"itemId":"653db742-f84f-5851-9b85-096999b2c08e","questionId":"88aad62c-e657-5fb9-9d00-a3962a8f6ce1","sourceKey":"bank:BUA205:APP-019","payload":{"prompt":"A head of department meets each staff member separately, learns their career goals and gives each person tailored coaching and support. Which dimension of transformational leadership is this?","options":["Contingent reward","Inspirational motivation","Intellectual stimulation","Individualised consideration"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Individualised consideration means showing concern for each subordinate's needs and treating each one as an individual in a supportive climate. Option C is about challenging assumptions, and option B is about inspiring the group with optimism. Option A is a transactional exchange of rewards for performance."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 142, $official_bank_source${"itemId":"097f90ba-f235-5557-8bcf-0f4d77520553","questionId":"dbffa865-ab02-5438-995b-f1e0eda1c594","sourceKey":"bank:BUA205:APP-020","payload":{"prompt":"At a staff rally, the CEO speaks with optimism about the company's future goals, challenges everyone to hold high moral standards and explains clearly what each team must achieve. Which dimension of transformational leadership is this?","options":["Intellectual stimulation","Individualised consideration","Management by exception-active","Inspirational motivation"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Inspirational motivation is the leader expressing an engaging, inspiring disposition, encouraging high moral standards, expressing positivity about future objectives and being concrete about tasks. Option B works person by person rather than through group inspiration, and option A is about questioning assumptions. Option C is a transactional monitoring practice."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 143, $official_bank_source${"itemId":"c52b48dc-9c36-5dae-a76c-4e0378a9c9bb","questionId":"74255c8a-6db9-5790-9df4-2a7d73cf4612","sourceKey":"bank:BUA205:APP-021","payload":{"prompt":"A leader who becomes valued, appreciated and trusted because he behaves as a good role model for subordinates is displaying:","options":["Inspirational motivation","Management by exception-passive","Idealised influence","Contingent reward"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Idealised influence (charisma) describes a leader whose personality and values make him a role model who is valued, appreciated and trusted. Option A is about inspiring optimism and high standards. Options B and D are transactional practices."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 144, $official_bank_source${"itemId":"ad10a4e6-1c09-55ba-94cb-0bebced7c4be","questionId":"dacec0a1-3727-5951-801b-66bc856b0409","sourceKey":"bank:BUA205:APP-023","payload":{"prompt":"The idea of transactional leadership was later expanded in 1985 by:","options":["Bernard Bass","Fred Fiedler","Robert Kelley","Thomas Hobbes"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Bernard Bass expanded the transactional (and transformational) leadership framework in 1985. Option C is known for the followership model, option B for the contingency model, and option D for social contract theory."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 145, $official_bank_source${"itemId":"c7359cc2-594b-594a-a126-e54d66d68786","questionId":"fa82a182-e8c8-5c1a-b931-b094837e0b7c","sourceKey":"bank:BUA205:APP-024","payload":{"prompt":"A production supervisor checks each worker's output against standards throughout the day and corrects deviations before they become problems. Which transactional practice is this?","options":["Management by exception-active","Management by exception-passive","Contingent reward","Individualised consideration"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Active management by exception means the leader continuously monitors each follower's performance and makes corrections to keep work to standard. Option B waits until problems become serious before acting. Option C links rewards to meeting targets, and option D is a transformational dimension."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 146, $official_bank_source${"itemId":"7eadbe48-63b2-530c-be91-427bfd89461d","questionId":"eb4858b6-dbd3-57f9-af0c-856f689ddead","sourceKey":"bank:BUA205:APP-025","payload":{"prompt":"A branch manager ignores warning signs in his team's work and acts only when a customer complaint becomes so serious that head office gets involved. This practice is called:","options":["Contingent reward","Management by exception-passive","Inspirational motivation","Management by exception-active"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Under passive management by exception, leaders do not act until problems arise, and they treat issues seriously only once they become critical, which is why the practice is described as harmful. Option D monitors continuously and acts early. Option A is about rewards for meeting targets, and option C is a transformational behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 147, $official_bank_source${"itemId":"9d2074c8-7136-5629-ac79-b20632ae3c82","questionId":"6f62c70d-f5e5-5080-b6b2-66d277df6f28","sourceKey":"bank:BUA205:APP-026","payload":{"prompt":"In transactional leadership, contingent reward describes:","options":["Coaching each employee according to personal needs","The leader stepping in only when problems become critical","What employees must do to qualify for rewards, with sanctions when targets are missed","Rewards given to all staff regardless of performance"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Contingent reward links rewards (or punishment) to whether employees meet targets and makes clear what they must do to qualify for compensation. Option D is not contingent on anything. Option B is passive management by exception, and option A is individualised consideration."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 148, $official_bank_source${"itemId":"ec5cdf8b-5d53-5c80-b582-d38a75acdf34","questionId":"2e01855e-5ca4-5bd7-80e6-c38331159506","sourceKey":"bank:BUA205:APP-027","payload":{"prompt":"A foundational framework that sets out an individual's core beliefs, values and principles about leadership is called a:","options":["Leadership style","Code of corporate governance","Leadership philosophy","Followership model"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"A leadership philosophy is the framework of core beliefs, values and principles that acts as a compass for decisions, behaviour and interactions. Option A is the observable way a leader behaves and influences others. Option B governs how a company is directed and controlled, and option D classifies followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 149, $official_bank_source${"itemId":"bdd989b9-2788-5f24-a2db-43db256dc243","questionId":"38abcc6f-83e3-5c71-8450-a734f54dcfe5","sourceKey":"bank:BUA205:APP-028","payload":{"prompt":"A leadership philosophy consists of four elements. Which of the following is NOT one of them?","options":["Attitude","Guiding principles","Remuneration","Theory"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"The four elements of a leadership philosophy are theory, attitude, guiding principles and behaviour. Remuneration is about pay, not about a leader's beliefs. Options D, A and B are all elements."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 150, $official_bank_source${"itemId":"0219d3ae-16d6-5c46-9af8-6e1548b4a912","questionId":"d839bc7d-ec32-5591-b728-2c4db991ea17","sourceKey":"bank:BUA205:APP-029","payload":{"prompt":"A leadership philosophy is said to act as a ________ for leaders, guiding their decisions, behaviour and interactions.","options":["Shield","Ladder","Mirror","Compass"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"A leadership philosophy works like a compass: it points the leader in the right direction when making decisions, shaping behaviour and dealing with others. Options B, A and C suggest promotion, protection and reflection, which are not the image used for a guiding philosophy."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 151, $official_bank_source${"itemId":"6ec6e18d-97db-536a-8615-9d0d800197a3","questionId":"e3e05f6d-ed54-57f9-9310-f94d0e83d063","sourceKey":"bank:BUA205:APP-030","payload":{"prompt":"Which of the following is NOT one of the leadership approaches rooted in moral philosophy?","options":["Authentic leadership","Servant leadership","Virtuous leadership","Bureaucratic leadership"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"The leadership approaches rooted in moral philosophy are ethical, servant, authentic and virtuous leadership. Bureaucratic leadership is a traditional style based on following policy. Options B, A and C are all moral-philosophy approaches."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 152, $official_bank_source${"itemId":"b3f3c353-2a8d-5b7f-9d78-e37a2b29a7cf","questionId":"c30814d5-3293-557c-9f25-46832d1499ee","sourceKey":"bank:BUA205:APP-032","payload":{"prompt":"A leadership approach that emphasises character traits such as courage, integrity, humility, compassion and wisdom, guided by moral excellence, is:","options":["Transactional leadership","Bureaucratic leadership","Authentic leadership","Virtuous leadership"],"correctOption":3,"section":"Leadership Approaches and Practices","explanation":"Virtuous leadership focuses on the leader's character, especially courage, integrity, humility, compassion and wisdom, guided by moral excellence. Option C focuses on self-awareness and transparency rather than a set of virtues. Options A and B are about exchange and rules respectively."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 153, $official_bank_source${"itemId":"5e07f530-c40f-54c9-a62a-41ba3495bd01","questionId":"48e46562-b0a6-5b1f-8aa8-c0c55074fd4d","sourceKey":"bank:BUA205:APP-033","payload":{"prompt":"A leadership approach that focuses on respect, accountability, honesty, justice and service so that decisions benefit employees, customers and communities is:","options":["Autocratic leadership","Laissez-faire leadership","Ethical leadership","Management by exception"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Ethical leadership is built on respect, accountability, honesty, justice and service, making sure decisions benefit employees, customers and communities. Option B is about leaving decisions to followers. Option A centralises power, and option D is a transactional monitoring practice."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 154, $official_bank_source${"itemId":"69480ca9-84d7-513b-a2bd-2e75202d4201","questionId":"10dec8f6-825e-5fc3-b760-e62b2569f09e","sourceKey":"bank:BUA205:APP-034","payload":{"prompt":"Moral philosophy influences leadership by placing people at the centre, recognising their full humanity, aspirations and concerns, which leads to more engaged and loyal teams. This influence is called:","options":["Purpose-driven action","Trust and credibility","Human-centred approach","Decision-making"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"The human-centred approach puts people at the centre and recognises their full humanity, which produces more engaged and loyal teams. Option A links leadership to a larger purpose of doing what is right. Option B is about trust earned through ethical, transparent conduct, and option D is about having a framework for ethical choices."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 155, $official_bank_source${"itemId":"ffdf6c1f-c099-57be-811b-1411c690ea71","questionId":"63d52c1c-cf55-532d-b6c9-a8e133c4bc97","sourceKey":"bank:BUA205:APP-035","payload":{"prompt":"One way moral philosophy influences leadership decision-making is by providing a framework for making choices that align with:","options":["Whatever the majority demands at the moment","Ethical values rather than expediency","The leader's personal advantage","Short-term convenience rather than principle"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Moral philosophy gives leaders a framework such as fairness, justice and empathy, so their choices follow ethical values rather than what is merely expedient. Options D, C and A all describe the expediency that moral philosophy is meant to correct."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 156, $official_bank_source${"itemId":"ff936ccc-9268-5c5f-9d31-5d72242a7677","questionId":"dc032ce5-9c38-5ff0-bc25-6ce99b1cec2c","sourceKey":"bank:BUA205:APP-036","payload":{"prompt":"A moral leader who first reflects on the current situation, reconnects with her moral commitments, rethinks current approaches and reimagines what is possible is practising which moral leadership practice?","options":["Foster freedom","Start with a pause","Seek the truth","Act with courage"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"'Start with a pause' means reflecting on the situation, reconnecting with moral commitments, rethinking current approaches and reimagining what is possible. Option D is about standing up for principles despite risk, and option A is about building a culture of trust and responsibility. Option C is about rigorously finding the facts."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 157, $official_bank_source${"itemId":"a91aa78e-2b01-5633-ada7-8a5f8512bce0","questionId":"4f8611df-97cd-578c-add7-c0dfa0897882","sourceKey":"bank:BUA205:APP-037","payload":{"prompt":"The moral leadership practice in which leaders see other people not as means but as ends in themselves, and take time to learn their hopes and struggles, is:","options":["Start with a pause","See the humanity in everyone","Demonstrate humility","Uphold ethical standards"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"'See the humanity in everyone' means treating people as ends in themselves, building deep relationships and learning about their hopes, struggles and dreams. Option C is about admitting the limits of one's knowledge, and option D is about modelling integrity. Option A is about reflection before action."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 158, $official_bank_source${"itemId":"733c95cc-b2f2-5c9f-99aa-fe67c99be833","questionId":"ed3191c6-1115-5832-9a5d-5b4a4ffd4cda","sourceKey":"bank:BUA205:APP-038","payload":{"prompt":"After a costly decision fails, a managing director publicly acknowledges the limits of his knowledge and makes meaningful amends to those affected. Which moral leadership practice is he showing?","options":["Foster freedom","Demonstrate humility","Act with courage","See the humanity in everyone"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Demonstrating humility means being confident when it is warranted while acknowledging the limits of one's knowledge and making meaningful amends for mistakes. Option A is about building a culture of trust and informed risk-taking. Option C is about standing firm on principles, and option D is about treating people as ends in themselves."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 159, $official_bank_source${"itemId":"bfb8dd57-7079-53ba-b798-1e4147f6f64c","questionId":"719ec40b-d8c8-5a38-b510-214c0b7e7364","sourceKey":"bank:BUA205:APP-039","payload":{"prompt":"A procurement director refuses a N30 million 'gift' to approve a substandard supplier, even though rejecting it angers powerful board members. Which moral leadership practice does this best illustrate?","options":["Demonstrate humility","Act with courage","Start with a pause","Foster freedom"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Acting with courage means not sacrificing principles for short-term gain and taking the risk of standing up for what is right. Option C is about reflection, and option D is about a culture of trust and shared values. Option A is about admitting limits and mistakes, which is not the issue here."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 160, $official_bank_source${"itemId":"e8881bad-5f25-556e-a10f-d14bbda3c079","questionId":"836f2344-ed78-5832-a26a-f68d2b7a2a4f","sourceKey":"bank:BUA205:APP-040","payload":{"prompt":"Which moral leadership practice involves cultivating a culture of interdependence and responsibility, where people are guided by shared values and supported in taking informed risks?","options":["Foster freedom","Seek the truth","Uphold ethical standards","Demonstrate humility"],"correctOption":0,"section":"Leadership Approaches and Practices","explanation":"Fostering freedom means building a culture of interdependence and responsibility in which people extend trust, share values and are supported in taking informed risks. Option B is about rigorously finding the truth, option C is about modelling integrity, and option D is about admitting limits and mistakes."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 161, $official_bank_source${"itemId":"d0222f59-3bad-5390-a1f9-f2a276a49d16","questionId":"a1de029a-9a86-5c07-b56e-5c149deb9262","sourceKey":"bank:BUA205:APP-041","payload":{"prompt":"Under the moral leadership practice 'uphold ethical standards', situations that test a leader's ethical standards are viewed as:","options":["Exceptions where the rules may be relaxed","Constraints that slow the organisation down","Opportunities to reveal what the leader most values","Problems to be passed to the legal department"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Moral leaders treat ethical standards and the situations that test them as opportunities to show others, and themselves, what they most value, especially when doing right is difficult or unpopular. Option B is the view explicitly rejected. Options A and D are ways of avoiding the test rather than upholding standards."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 162, $official_bank_source${"itemId":"5afa8e31-956f-58cf-80ab-e7b575b74263","questionId":"a7cdf456-a7ea-52b7-99e8-e6ae63b678f3","sourceKey":"bank:BUA205:APP-042","payload":{"prompt":"Lagos is hit by sudden flash floods, and the state emergency agency must evacuate thousands of residents within hours. Which leadership style is most suited to this context?","options":["Laissez-faire leadership","Servant leadership","Authoritarian leadership","Democratic leadership"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Authoritarian leadership gives fast decisions and clear direction during emergencies, which is why emergency governance and crisis management are its best contexts. Option A would leave people without direction. Options D and B are valuable in normal times but tend to slow decisions because of consultation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 163, $official_bank_source${"itemId":"89d3413d-ed5e-5a7b-9d9a-d2a82eb7ef6a","questionId":"6cff3518-b5e2-5dcd-9076-e842cc4d162e","sourceKey":"bank:BUA205:APP-043","payload":{"prompt":"Bureaucratic systems, public administration and regulatory agencies are identified as the best governance contexts for which leadership style?","options":["Servant leadership","Democratic leadership","Transactional leadership","Transformational leadership"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Transactional leadership is structured and rule-based and ensures efficiency, compliance and accountability in routine operations, so it suits bureaucratic systems, public administration and regulatory agencies. Option D suits national reforms and organisational change. Option A suits public service, NGOs and community development, and option B suits democratic institutions and policy consultations."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 164, $official_bank_source${"itemId":"86578f15-8bf9-5447-9088-0a3f857dc1a7","questionId":"bca32986-4714-58cb-8b3e-4cad56f6004c","sourceKey":"bank:BUA205:APP-044","payload":{"prompt":"Which of the following is a limitation of transformational leadership in governance?","options":["Discouraging innovation through strict rules","Overdependence on a charismatic leader","Slower decisions due to wide consultation","Being perceived as weak in rigid hierarchies"],"correctOption":1,"section":"Leadership Approaches and Practices","explanation":"Transformational leadership risks overdependence on charismatic leaders, and its vision may overshadow practical implementation. Option C is a limitation of democratic leadership, option A of transactional leadership, and option D of servant leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 165, $official_bank_source${"itemId":"2e1ab884-d330-5d3e-bf44-16f163adc0d9","questionId":"8c9876c9-519a-5fbb-bae8-8eee8fce8fd3","sourceKey":"bank:BUA205:APP-045","payload":{"prompt":"Servant leadership may be limited in governance because it:","options":["Concentrates too much power in the leader","Ignores the welfare of followers","May be perceived as weak in highly hierarchical settings","Relies heavily on rewards and punishments"],"correctOption":2,"section":"Leadership Approaches and Practices","explanation":"Servant leadership can look weak in rigid, highly hierarchical settings, and consultation can slow its decisions. Option A is a risk of authoritarian leadership, and option D describes transactional leadership. Option B is the opposite of servant leadership, which prioritises followers' welfare."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 166, $official_bank_source${"itemId":"24589177-62f8-545c-9dd4-2d9ee87ed24b","questionId":"038041f6-60a5-58d1-877b-79967c7c8c6e","sourceKey":"bank:BUA205:PQ-047-b","payload":{"prompt":"In Robert Kelley's followership model, followers who are both actively engaged and independent, critical thinkers are called ____","options":["Conformist followers","Exemplary followers","Passive followers","Alienated followers"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Exemplary followers combine high engagement with independent thinking, so they support leaders while also questioning and contributing ideas. Conformist followers (A) are active but unquestioning, alienated followers (D) think critically but are disengaged, and passive followers (C) depend on the leader for direction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 167, $official_bank_source${"itemId":"da12fa9d-3c60-5011-b153-374987685dd8","questionId":"6f90d55a-c401-556d-942d-3c4164436c02","sourceKey":"bank:BUA205:PQ-164","payload":{"prompt":"In democratic governance, followership emphasises the duty of followers to ______ leadership actions.","options":["Glorify","Conceal","Personalise","Scrutinise"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Democratic followers are partners, not passive subjects: they question, monitor and give feedback on what leaders do, which keeps power in check and prevents abuse. Option A, glorifying leaders, reflects the uncritical loyalty found under authoritarian rule, and concealing or personalising leadership actions (options B and C) undermines accountability."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 168, $official_bank_source${"itemId":"1ff7fdb1-5762-5b2a-82b8-be1963db8dbe","questionId":"62516756-b96c-58be-b42a-bb8d9b10a861","sourceKey":"bank:BUA205:PQ-194","payload":{"prompt":"Civic society (civil society) is BEST described as:","options":["The legislative branch of the federal government","The formal sector of the economy regulated by the Central Bank","The military and law enforcement agencies of a state","The arena of voluntary associations and organisations outside government and business"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society is made up of voluntary, non-governmental organisations, such as NGOs, religious bodies, professional associations, labour unions and student groups, that operate between the state and the private sector to represent citizens' interests. Options C and A are parts of government itself, and option B describes the business sector."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 169, $official_bank_source${"itemId":"99c06f11-8366-5605-91eb-2ba0d27ccc9e","questionId":"0c218bd9-cfe7-52a7-9126-901fc0ffe9ea","sourceKey":"bank:BUA205:PQ-195","payload":{"prompt":"Active citizenship in the context of governance refers to:","options":["Holding elected office at any level of government","The act of paying taxes to the federal government","Citizens participating meaningfully in governance, policy-making and community affairs","Passive compliance with government directives"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Active citizenship means engaging in civic life by voting, joining public consultations, advocating on issues, monitoring officials and contributing to community development. Passive compliance (option D) is the opposite, holding office (option A) is only one narrow form of participation, and paying taxes (option B) is a civic duty but not, by itself, active engagement."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 170, $official_bank_source${"itemId":"c84a5b66-6c53-5d90-8c17-e4c61054cca7","questionId":"b10f5c72-5e73-5741-9f74-cfae1d2063b6","sourceKey":"bank:BUA205:PQ-196","payload":{"prompt":"Effective followership contributes to organisational success because:","options":["Followers create checks and balances on government expenditure","Followers reduce the workload of leadership and management","Competent followers co-create outcomes and provide critical feedback that leaders need","Followers simply execute orders without contributing ideas"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Modern views treat followers as partners in the leadership process: they think independently, contribute ideas and give honest feedback, which improves decisions and results. Option D describes passive followership, which weakens organisations, and option B is at most a side effect, while option A concerns public finance rather than organisational followership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 171, $official_bank_source${"itemId":"6248c073-b25e-5720-b731-73d42dbb0523","questionId":"3faedcd7-4a47-57df-99ce-e7513e383848","sourceKey":"bank:BUA205:PQ-197","payload":{"prompt":"Which of the following BEST links citizenship to good governance?","options":["An informed and engaged citizenry holds leaders accountable and promotes transparent governance","Citizens only influence governance during election periods","Citizenship roles are limited to tax compliance and military service","Governance is solely the responsibility of elected politicians"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizens strengthen governance when they know their rights, follow public affairs and use voting, advocacy and monitoring to hold leaders to account. Option B is too narrow because citizens can influence governance continuously, not only at elections, and options D and C ignore the active role citizens play."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 172, $official_bank_source${"itemId":"1fca2019-1bda-50a6-a85d-62cf9b3a0b1e","questionId":"731ab1c0-fbe4-5669-b303-9bd5ff55ea92","sourceKey":"bank:BUA205:PQ-198","payload":{"prompt":"Robert Kelley's typology of followers classifies the MOST effective followers as:","options":["Star/exemplary followers who are both independent thinkers and actively engaged","Conformist followers who simply comply without question","Alienated followers who think independently but do not participate","Passive and dependent followers who defer all decisions to leaders"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Kelley classified followers by two dimensions, independent critical thinking and active engagement, and exemplary followers score high on both. Alienated followers (option C) think critically but are disengaged, conformist followers (option B) are active but unquestioning, and passive followers (option D) are low on both dimensions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 173, $official_bank_source${"itemId":"83e0a28b-c872-5692-9b83-bd242f3ab156","questionId":"0409e8e5-ab6d-56fe-9677-a627c3ecf590","sourceKey":"bank:BUA205:PQ-199","payload":{"prompt":"Citizenship education in Nigeria's governance discourse is important because it:","options":["Equips individuals with knowledge of rights, responsibilities and civic participation skills","Teaches citizens to obey government without question","Prepares students for civil service examinations only","Restricts political participation to the educated elite"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizenship education helps people understand their rights, such as voting and free expression, and their duties, such as obeying laws and holding leaders accountable, and it builds the skills needed to take part in civic life. Option B describes blind obedience, which weakens accountability, and options C and D are far too narrow or exclusionary."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 174, $official_bank_source${"itemId":"b53d3f5f-b27e-5678-9b1e-8388dd363a6a","questionId":"701d6a77-f125-5a23-9e4a-4de4fccd80c0","sourceKey":"bank:BUA205:PQ-200","payload":{"prompt":"The relationship between leadership and followership is best described as:","options":["A purely contractual employer-employee arrangement","A dynamic, reciprocal relationship where each role influences and depends on the other","An adversarial relationship driven by competing interests","A hierarchical relationship where followers have no influence on leaders"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Leadership is relational: leaders influence followers, but followers also shape leaders through their support, feedback and willingness to challenge wrong actions, so each depends on the other. Option D ignores followers' influence, option A reduces the relationship to a contract, and option C wrongly assumes the two sides are natural opponents."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 175, $official_bank_source${"itemId":"855cd21e-cb0d-5f9b-9fdd-69b5a0997b85","questionId":"3b985aab-7ce0-5da2-b3c5-66c91b852c8a","sourceKey":"bank:BUA205:PQ-237","payload":{"prompt":"The statement 'Good leaders must first be good followers' reflects the view that leadership development:","options":["Assumes that followers are less important than leaders in any organisation","Is irrelevant in modern organisational contexts","Focuses entirely on technical management skills","Requires understanding the perspective, needs and challenges of followers before assuming leadership roles"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Serving as a follower teaches future leaders what followers need, how decisions feel from below and how to support and challenge leaders constructively, which makes them better leaders later. Options B and C ignore the human side of leadership, and option A contradicts the idea that leadership and followership depend on each other."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 176, $official_bank_source${"itemId":"22d44bf0-72e4-53de-bd72-b13392b7f842","questionId":"118e0884-6439-55c8-a228-875e4dba2a60","sourceKey":"bank:BUA205:PQ-239-f","payload":{"prompt":"Which of the following is a function civil society performs in promoting accountable governance?","options":["Commanding the armed forces","Enacting laws for the country","Collecting taxes on behalf of government","Election monitoring and advocacy on public issues"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society organisations promote accountability by monitoring elections, advocating on policy, educating citizens about their rights, protecting human rights and exposing corruption. Making laws (option B), collecting taxes (option C) and commanding the military (option A) are functions of the state, not of civil society."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 177, $official_bank_source${"itemId":"1d964d90-1996-5ab9-8454-e70372655585","questionId":"30d84c45-eb73-54d3-ada9-8a7a0bc592ed","sourceKey":"bank:BUA205:FOL-001","payload":{"prompt":"The active role individuals play in supporting, influencing and sometimes challenging leaders to achieve shared objectives is called:","options":["Followership","Civil society","Governance","Citizenship"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Followership is the active role people play in supporting, influencing and, when necessary, challenging leaders toward shared objectives. Option D is legal membership of a country with rights and duties. Option B is the set of voluntary non-governmental organisations, and option C is the system through which authority is exercised."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 178, $official_bank_source${"itemId":"b5788267-254c-587e-a090-8603f07599dc","questionId":"80c00d6e-387a-5076-8660-d8113ae6c907","sourceKey":"bank:BUA205:FOL-002","payload":{"prompt":"How does the modern view of followers differ from the traditional view?","options":["Followers matter only when leaders are absent","Followers have no influence on the leader's decisions","Followers are partners in the leadership process, not passive recipients of instructions","Followers are expected to obey without question"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Modern leadership theory treats followers as partners in the leadership process rather than passive people who simply receive instructions. Options D, B and A all reflect the older, passive view that the modern view rejects."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 179, $official_bank_source${"itemId":"715caeaa-4e0a-5720-b3c1-3a15a1b3f3ba","questionId":"b0aef3a7-a720-5f94-a52f-53480cac5c82","sourceKey":"bank:BUA205:FOL-003","payload":{"prompt":"Followership, as a concept, emphasises:","options":["Passivity, dependence and routine compliance","Competition, secrecy and personal gain","Obedience, silence and loyalty to the leader","Collaboration, critical thinking and ethical responsibility"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Followership emphasises collaboration, critical thinking and ethical responsibility, so good followers question unethical behaviour and contribute ideas. Options C and A describe passive or conformist following, and option B describes behaviour that undermines governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 180, $official_bank_source${"itemId":"26d473bd-9827-57c6-a048-e3377dc500c7","questionId":"071afaa7-84a6-5218-aa26-e8486f2525fd","sourceKey":"bank:BUA205:FOL-004","payload":{"prompt":"Robert Kelley's followership model classifies followers on the basis of which two dimensions?","options":["Independent thinking and level of engagement","Task structure and position power","Concern for people and concern for production","Ability and willingness to perform a task"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Kelley classified followers by how independently and critically they think and how actively engaged they are. Option B lists Fiedler's situational factors, and option C is the Managerial Grid. Option D is the basis of follower readiness in Hersey and Blanchard's model."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 181, $official_bank_source${"itemId":"b9b936da-7cb0-5075-aec6-6e851121f0b9","questionId":"2556b55f-e949-58b8-beaf-a585d3e28c81","sourceKey":"bank:BUA205:FOL-005","payload":{"prompt":"An accounts officer at a federal agency works diligently, but when asked to process a N15 million payment without proper documents, she raises reasoned objections and proposes the correct procedure. In Kelley's model she is best described as:","options":["An exemplary follower","A passive follower","A conformist follower","An alienated follower"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Exemplary followers are both active and independent thinkers: they work hard and also challenge what is wrong, offering constructive alternatives. Option C is active but would process the payment without questioning. Option D is critical but disengaged, and option B simply waits for direction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 182, $official_bank_source${"itemId":"8cbe9394-8514-5ddf-9e1c-49d9c47a0cf7","questionId":"19451972-a7e3-5991-83d4-fc989e3f6ca6","sourceKey":"bank:BUA205:FOL-006","payload":{"prompt":"A staff member eagerly carries out every instruction from his manager, works long hours, but never questions any directive, even doubtful ones. In Kelley's model he is:","options":["An alienated follower","A pragmatic follower","A conformist follower","An exemplary follower"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Conformist followers are active but unquestioning: highly engaged yet lacking independent critical thinking. Option D would also question doubtful directives. Option A thinks critically but is disengaged, and option B shifts behaviour to suit the situation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 183, $official_bank_source${"itemId":"eb5839e5-fec7-5a59-9529-0bce3a45f64d","questionId":"33ed9d9e-6ace-5af7-bb4d-4b3f9913096f","sourceKey":"bank:BUA205:FOL-007","payload":{"prompt":"A clerk in a ministry does only what she is told, never takes initiative and always waits for her supervisor to tell her what to do next. In Kelley's model she is:","options":["A conformist follower","An exemplary follower","A pragmatic follower","A passive follower"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Passive followers depend on leaders for direction and show neither initiative nor independent thinking. Option A is enthusiastically active, even if unquestioning. Option C adapts to whatever the situation rewards, and option B is active and independent."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 184, $official_bank_source${"itemId":"e803faba-33b6-5fdb-b4cf-765afedd75a5","questionId":"220a260a-dfdf-54ba-b8f2-f6b60f6c8190","sourceKey":"bank:BUA205:FOL-008","payload":{"prompt":"A senior officer in a state ministry constantly criticises management decisions in private conversations but refuses to join committees or contribute to solving the problems he complains about. In Kelley's model he is:","options":["A conformist follower","A passive follower","An alienated follower","An exemplary follower"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Alienated followers think critically and independently but are disengaged, so their criticism is not turned into contribution. Option D would combine the criticism with active involvement. Option A is engaged but uncritical, and option B is neither critical nor engaged."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 185, $official_bank_source${"itemId":"20ca1300-bbd4-52a4-952a-81249eba0c56","questionId":"aa8f2fb5-eb55-5555-a86d-e3b671728436","sourceKey":"bank:BUA205:FOL-009","payload":{"prompt":"A union officer supports management when it seems safe, criticises it when the mood among members changes, and generally adjusts her stance to whatever the situation rewards. In Kelley's model she is:","options":["An alienated follower","A pragmatic follower","A conformist follower","An exemplary follower"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Pragmatic followers are flexible and situational, shifting their behaviour to suit circumstances rather than holding a consistent stance. Option D is consistently active and independent. Option A is consistently critical and disengaged, and option C is consistently active and unquestioning."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 186, $official_bank_source${"itemId":"c0d81018-0bd5-5bc2-b2eb-d1142e6023aa","questionId":"07f091f4-b5c6-59b2-a573-0978d1d013a5","sourceKey":"bank:BUA205:FOL-010","payload":{"prompt":"In Kelley's followership model, alienated followers are best described as:","options":["Active and independent thinkers","Critical but disengaged","Dependent on leaders for direction","Active but unquestioning"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Alienated followers think critically but are disengaged from the work and from the leader. Option D describes conformist followers, option A exemplary followers, and option C passive followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 187, $official_bank_source${"itemId":"a79fbaaa-b086-5a36-92ca-5e35b2679826","questionId":"355b582d-f4a2-5d97-b81b-9c6fdc024c39","sourceKey":"bank:BUA205:FOL-011","payload":{"prompt":"Which of the following is NOT one of the follower types in Robert Kelley's model?","options":["Conformist followers","Charismatic followers","Alienated followers","Pragmatic followers"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Kelley's five follower types are exemplary, conformist, passive, alienated and pragmatic. 'Charismatic' describes a kind of leader, not a follower type in Kelley's model. Options D, A and C are all among Kelley's types."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 188, $official_bank_source${"itemId":"1f3e1afc-0b72-5493-af69-47ff41e97228","questionId":"4e103caa-af91-560d-af57-6d637b75bf67","sourceKey":"bank:BUA205:FOL-012","payload":{"prompt":"Which of the following is NOT an importance of followership in governance?","options":["Supporting policy implementation","Strengthening accountability mechanisms","Preventing authoritarian leadership and leadership abuse","Guaranteeing that leaders never make mistakes"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Good followership prevents authoritarian leadership and abuse, encourages democratic participation, improves institutional performance, strengthens accountability, supports policy implementation and encourages stability. It cannot guarantee leaders will never err. Options C, B and A are all genuine importances."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 189, $official_bank_source${"itemId":"342b3882-d123-5f10-935a-93aa652a206c","questionId":"88d89ec3-d4fe-5ce7-8bfd-dbea5683fcf6","sourceKey":"bank:BUA205:FOL-013","payload":{"prompt":"Which of the following is NOT a characteristic of effective followers?","options":["Commitment to institutional values","Courage to question unethical practices","Unquestioning loyalty to every instruction","Critical thinking"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Effective followers show critical thinking, responsibility, ethical awareness, courage to question unethical practices, teamwork and commitment to institutional values. Unquestioning loyalty is the mark of a conformist follower, not an effective one. Options D, B and A are all listed characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 190, $official_bank_source${"itemId":"55d3128b-a072-5fba-bffc-f9719163df8c","questionId":"66012927-d195-58fc-846c-66a4501f2892","sourceKey":"bank:BUA205:FOL-014","payload":{"prompt":"In governance, active followership mainly helps to:","options":["Maintain accountability and prevent misuse of power","Concentrate authority in the leader","Replace the role of public institutions","Reduce the need for elections"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Active followers question, give feedback and refuse to go along with wrongdoing, which helps keep leaders accountable and prevents misuse of power so institutions work properly. Options D, B and C would weaken rather than strengthen governance."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 191, $official_bank_source${"itemId":"f5f4705e-03da-5fee-92a2-7c7916944087","questionId":"43b5ed37-06fd-5d34-8b75-9e035f7ffe72","sourceKey":"bank:BUA205:FOL-015","payload":{"prompt":"In democratic societies, citizens are said to play dual roles. What are these roles?","options":["Followers of leaders and active participants in governance through civic engagement","Taxpayers and government employees","Voters and political party officials","Consumers of services and owners of businesses"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizens in a democracy are followers of their leaders and, at the same time, active participants in governance through civic engagement. Options B, C and D describe roles that only some citizens hold and are not the two general roles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 192, $official_bank_source${"itemId":"272124e6-d1f1-58f8-8581-7ce3d27b7821","questionId":"3a062b95-5f84-5cc9-a7a3-cae137f0c203","sourceKey":"bank:BUA205:FOL-016","payload":{"prompt":"Effective governance is said to depend on the interaction among which groups?","options":["Leaders, followers, citizens and civic institutions","Leaders and the armed forces only","The president and the National Assembly only","Political parties and foreign donors only"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Leadership alone does not decide governance outcomes; effective governance depends on how leaders, followers, citizens and civic institutions interact. Options B, D and C each name only a narrow set of actors."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 193, $official_bank_source${"itemId":"c8a63b98-9af9-5d59-a57e-d8cc0165cacd","questionId":"e4816542-fee1-5222-830b-08616374c010","sourceKey":"bank:BUA205:FOL-017","payload":{"prompt":"An individual's legal membership in a country, involving rights, duties and participation in governance and development, is called:","options":["Followership","Democratic participation","Citizenship","Civil society"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizenship is legal membership in a country that comes with rights, duties and participation in governance and development. Option A is the active role of followers toward leaders. Option D refers to voluntary non-governmental organisations, and option B is one form of citizen activity."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 194, $official_bank_source${"itemId":"6c64c6b3-953e-5482-8f15-d18721710a70","questionId":"b6caa319-736d-5b7d-96b5-eee65d9febbe","sourceKey":"bank:BUA205:FOL-018","payload":{"prompt":"Which of the following is a RESPONSIBILITY of citizens rather than a right?","options":["Right to education","Access to justice","Paying taxes","Freedom of speech and association"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizens' responsibilities include obeying laws, paying taxes, voting responsibly, participating in community activities, promoting social harmony and holding leaders accountable. Options D, B and A are rights that citizens enjoy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 195, $official_bank_source${"itemId":"edfdcdf7-cf97-5c1f-a03d-a309f0f5f890","questionId":"dc974adf-6168-5a86-8cee-aec4dcda205a","sourceKey":"bank:BUA205:FOL-019","payload":{"prompt":"Which of the following is a RIGHT of citizens rather than a responsibility?","options":["Obeying laws","Equal protection under the law","Promoting social harmony","Participating in community activities"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Equal protection under the law is one of the rights of citizens, alongside the right to vote, freedom of speech and association, access to justice and the right to education. Options A, C and D are responsibilities citizens owe to society."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 196, $official_bank_source${"itemId":"2e9ae04b-6e18-570b-ba12-effdbd74f070","questionId":"643729d9-0deb-5381-a433-7f44f41a7300","sourceKey":"bank:BUA205:FOL-020","payload":{"prompt":"'Holding leaders accountable' is classified as:","options":["A function of the executive arm only","A characteristic of passive followers","A responsibility of citizens","A right reserved for elected officials"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Holding leaders accountable is listed among the responsibilities of citizens, together with obeying laws, paying taxes and voting responsibly. Options D and A wrongly limit it to officials. Option B is wrong because passive followers depend on leaders and do not hold them to account."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 197, $official_bank_source${"itemId":"5c6a9fc8-b2b2-5c6e-9823-3ded8940d7f0","questionId":"ac3b11a6-436b-5b2b-abfd-15f2cf12ff1a","sourceKey":"bank:BUA205:FOL-021","payload":{"prompt":"Civil society is described as operating in the space between:","options":["The judiciary and the legislature","Federal and state governments","Employers and their shareholders","The state and the private sector"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society is made up of voluntary, non-governmental organisations that operate between the state and the private sector, representing citizens' interests and promoting accountability. Options A and B are both inside the state, and option C is within the private sector."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 198, $official_bank_source${"itemId":"83d205ee-1b9b-51a9-9d01-0b5341a0fca5","questionId":"8b4dd490-88df-57cb-99aa-43717c37d860","sourceKey":"bank:BUA205:FOL-022","payload":{"prompt":"Which of the following is NOT an example of a civil society organisation?","options":["A labour union","A federal ministry","A religious body","A professional association"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society consists of voluntary, non-governmental bodies such as NGOs, religious bodies, professional associations, labour unions, student organisations and media institutions. A federal ministry is part of government, so it is not civil society. Options A, D and C are all listed examples."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 199, $official_bank_source${"itemId":"59a77ee4-aea3-5494-8e65-ea530cc2fc1e","questionId":"87ea1a64-3884-5255-994e-dce6fee05a33","sourceKey":"bank:BUA205:FOL-023","payload":{"prompt":"A coalition of NGOs deploys trained observers to polling units across several states during a governorship election and publishes a report on irregularities. Which function of civil society is this?","options":["Human rights protection","Community development","Election monitoring","Civic education"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Sending observers to polling units and reporting irregularities is election monitoring, one of the functions of civil society. Option B is about improving local facilities and livelihoods, and option D is about teaching citizens their rights and duties. Option A is a related function but is not what this activity is mainly about."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 200, $official_bank_source${"itemId":"49debdef-36f6-536c-87c2-5f37a620a952","questionId":"c651ba10-4b66-56f9-9f03-5d8396333476","sourceKey":"bank:BUA205:FOL-024","payload":{"prompt":"An NGO runs a weekly radio programme in Hausa and Yoruba that teaches listeners their constitutional rights and civic duties. Which function of civil society is this?","options":["Civic education","Election monitoring","Community development","Advocacy and policy influence"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Teaching citizens their rights and duties is civic education. Option B is observing elections, and option D is lobbying to shape policy. Option C is about local projects and livelihoods."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 201, $official_bank_source${"itemId":"35459280-5910-5576-93b8-1c74f69256f5","questionId":"915fa512-61b3-5ca7-8071-b45d8d0c5fd7","sourceKey":"bank:BUA205:FOL-025","payload":{"prompt":"Which of the following is NOT a function of civil society?","options":["Enacting laws for the country","Advocacy and policy influence","Public accountability promotion","Human rights protection"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Civil society functions include advocacy and policy influence, civic education, election monitoring, human rights protection, promoting public accountability and community development. Enacting laws is the job of the legislature, which is part of the state. Options B, C and D are all civil society functions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 202, $official_bank_source${"itemId":"d31702c2-33f0-5ed9-92c3-0a936d621f24","questionId":"4a51180e-9418-50de-8fa5-d5993f9203e8","sourceKey":"bank:BUA205:FOL-026","payload":{"prompt":"The systems and processes through which authority is exercised and decisions are made in public or organisational institutions are called:","options":["Citizenship","Civic education","Followership","Governance"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Governance refers to the systems and processes through which authority is exercised and decisions are made in public or organisational institutions. Option A is membership of a state, option C is the role of followers, and option B is a function of civil society."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 203, $official_bank_source${"itemId":"871e3b28-1b49-59b8-ae31-b9303db5e781","questionId":"8b7d23a0-5f98-5b14-99f4-1f729e806e5c","sourceKey":"bank:BUA205:FOL-027","payload":{"prompt":"Which statement about governance is correct?","options":["Governance concerns only how elections are conducted","Governance extends beyond government to private organisations, civil society and community groups","Governance applies only to the federal government","Governance is the same thing as the civil service"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Governance extends beyond government and includes public institutions, private organisations, civil society actors and community groups. Options C, A and D each narrow governance to one part of the public sector."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 204, $official_bank_source${"itemId":"a31cde8a-5bd0-5a74-9ab9-70e2be288ae0","questionId":"b7d60913-fb84-57de-a16d-25e78d2f8228","sourceKey":"bank:BUA205:FOL-028","payload":{"prompt":"Residents of a community in Enugu track the N120 million constituency project allocated to their area, visit the site monthly and publish photos showing that the project has stalled. Which role of citizens in governance is this?","options":["Public consultations and policy discussions","Voting and electoral participation","Paying taxes","Monitoring public officials"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Tracking projects and checking whether officials deliver what was promised is monitoring public officials, one of the roles of citizens in governance. Option B is about elections, and option A is about giving views before a policy is made. Option C is a responsibility of citizens, but it does not describe what these residents are doing."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 205, $official_bank_source${"itemId":"f5dd65ef-b25a-5097-895a-c55831745263","questionId":"ad4d4f74-98f6-5a41-bb5a-bdb2123d95ca","sourceKey":"bank:BUA205:FOL-029","payload":{"prompt":"Which of the following is NOT a role of followership in governance?","options":["Concealing leaders' misconduct to protect the institution","Resisting corruption","Providing feedback on public policies","Supporting ethical leaders"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Followers contribute to governance by supporting ethical leaders, resisting corruption, participating in decisions, giving feedback on policies and upholding institutional standards. Concealing misconduct undermines those standards. Options D, B and C are all genuine roles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 206, $official_bank_source${"itemId":"8b5ba6d2-0726-5e7c-8ba2-5abeddcd782e","questionId":"eeb6ee4b-b924-5e5b-8c33-943b49111a75","sourceKey":"bank:BUA205:FOL-030","payload":{"prompt":"Weak governance often results from all of the following EXCEPT:","options":["Weak institutional structures","Civic apathy","Passive followership","An active civil society"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Weak governance often results from passive followership, civic apathy, lack of accountability mechanisms and weak institutional structures. An active civil society promotes accountability and transparency, so it strengthens governance. Options C, B and A are causes of weak governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 207, $official_bank_source${"itemId":"7a62eb57-b2ca-59d3-b8f9-6fd890a81f55","questionId":"e9cfa9e5-bad5-50f8-8e04-fd87fef31f2f","sourceKey":"bank:BUA205:FOL-031","payload":{"prompt":"Which of the following is one of the conditions under which effective governance occurs?","options":["Citizens leave all decisions to elected leaders","Civil society avoids commenting on government","Leaders keep decision-making away from followers","Followers actively engage and provide constructive feedback"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Effective governance occurs when leaders act ethically, followers actively engage and give constructive feedback, citizens take part in democratic processes, and civil society promotes accountability and transparency. Options A, B and C describe the passivity and secrecy linked to weak governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 208, $official_bank_source${"itemId":"3096b6e4-8d5f-5ee5-a9e4-97dac50b4542","questionId":"d91798ab-cd82-54d1-a598-641913d11dee","sourceKey":"bank:BUA205:FOL-032","payload":{"prompt":"In the Nigerian context, low voter turnout mainly:","options":["Improves the quality of public services","Strengthens the mandate of elected leaders","Reduces leadership accountability and governance legitimacy","Increases citizens' influence on policy"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"When few people vote, leaders are less accountable to the public and their mandate carries less legitimacy. Options B, A and D suggest benefits that do not follow from low turnout."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 209, $official_bank_source${"itemId":"695250ad-d12e-5e16-9647-becb48565387","questionId":"9c28e583-f723-5d9b-af44-1d4fa30951d6","sourceKey":"bank:BUA205:FOL-033","payload":{"prompt":"A newspaper's investigative team uncovers how N2.3 billion meant for rural clinics was diverted, and a civil society campaign follows to demand prosecution. This best illustrates which practical channel in Nigerian governance?","options":["Community development associations","Electoral participation","Student governance","Media and civic advocacy"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Investigative journalism and civil society campaigns help expose corruption and promote transparency, which is what the media and civic advocacy channel describes. Option C concerns university administration, and option A concerns grassroots collective action. Option B concerns voting."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 210, $official_bank_source${"itemId":"48cacec0-caad-502a-a40e-b5dff1ca28ed","questionId":"0f59b458-d390-52ff-9f54-cc3e47f85e0c","sourceKey":"bank:BUA205:FOL-034","payload":{"prompt":"Residents of an estate in Abeokuta contribute N5,000 per household to repair a failed culvert and agree on a work plan at their monthly meeting. This is an example of governance through:","options":["Community development associations","Electoral participation","Media and civic advocacy","Student governance"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Community development associations let local communities contribute to governance through collective action and grassroots initiatives, such as pooling funds for local repairs. Option C involves journalism and campaigns. Option B is about voting, and option D is about university administration."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 211, $official_bank_source${"itemId":"2311c43a-acfb-569e-9d00-6d0dc3b52c17","questionId":"4b5cab8e-e0d1-59f2-99e9-6a1e38f1493e","sourceKey":"bank:BUA205:FOL-035","payload":{"prompt":"Young Nigerians are said to influence governance mainly through:","options":["Activism, policy advocacy and community development initiatives","Running government ministries directly","Holding all key political offices","Controlling the electoral commission"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Young people influence governance through activism, policy advocacy and community development initiatives. Options C, D and B describe formal state power that young people as a group do not hold."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 212, $official_bank_source${"itemId":"bcc5d39f-51a9-52e8-affd-f7682e473998","questionId":"ca084c02-25e2-54ad-a1a1-0a509a5e5e40","sourceKey":"bank:BUA205:FOL-036","payload":{"prompt":"Which of the following is NOT an accountability mechanism?","options":["Institutional checks and balances","Performance monitoring","Legal oversight","Unrestricted personal discretion for officials"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Accountability mechanisms include performance monitoring, legal oversight, public reporting and institutional checks and balances, all of which make officials answer for their actions. Unrestricted discretion removes those checks. Options B, C and A are listed mechanisms."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 213, $official_bank_source${"itemId":"bf5ed382-9871-5013-94c5-fd7eb8d982b0","questionId":"4871faec-6428-59a8-afd0-fb466fce4ba1","sourceKey":"bank:BUA205:FOL-037","payload":{"prompt":"Without transparency, governance systems become vulnerable to:","options":["Too much public trust","Secrecy, inefficiency and abuse of power","Over-monitoring of leaders","Excessive citizen participation"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Transparency builds trust, reduces corruption, encourages participation and allows monitoring of leaders; without it, governance becomes vulnerable to secrecy, inefficiency and abuse of power. Options D, A and C are things transparency produces, not risks of its absence."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 214, $official_bank_source${"itemId":"377a125a-2fc6-52c4-8e25-0d09071c2290","questionId":"431158d6-047b-57b7-a112-fd3b67f7f75e","sourceKey":"bank:BUA205:FOL-038","payload":{"prompt":"Transparency in governance promotes all of the following EXCEPT:","options":["Public participation","Greater opportunities for corruption","Effective monitoring of leadership actions","Trust in institutions"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Transparency promotes trust in institutions, reduced corruption, public participation and effective monitoring of leaders. More opportunities for corruption come from a lack of transparency. Options D, A and C are listed benefits."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 215, $official_bank_source${"itemId":"7d4519e5-9db1-5d97-9240-80b9f466fd9e","questionId":"ff90ff97-830b-58c7-9b76-0e5346dbf012","sourceKey":"bank:BUA205:FOL-039","payload":{"prompt":"Which of the following is NOT a form of democratic participation?","options":["Public consultations","Offering officials money to secure a contract","Advocacy and policy dialogue","Civic activism"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Democratic participation includes voting, public consultations, civic activism, community engagement, and advocacy and policy dialogue. Offering money to officials for contracts is bribery, which corrupts governance. Options A, D and C are listed forms."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 216, $official_bank_source${"itemId":"9a9a09c7-3da4-5ff6-af0e-7da745e585c4","questionId":"8ee04aa9-c0a6-5b77-9434-95e24d83fb6e","sourceKey":"bank:BUA205:FOL-040","payload":{"prompt":"Active democratic participation strengthens governance mainly by:","options":["Ensuring that leaders never face criticism","Transferring all decisions to civil society","Keeping leaders responsive to citizens' needs and policies in line with public interests","Removing the need for laws and institutions"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"When citizens participate actively, leaders remain responsive to their needs and policies reflect public interests. Options D and B misstate the role of participation, and option A is the opposite of what active participation produces."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 217, $official_bank_source${"itemId":"d93a2bbb-384c-526c-8fe7-a42a65779bf9","questionId":"79f71a9b-c895-59f0-8a12-526922a35d04","sourceKey":"bank:BUA205:FOL-041","payload":{"prompt":"Citizenship is said to include three elements. Which option lists them correctly?","options":["Ownership of land, payment of levies, and military service","Legal membership in a country, political participation, and social responsibilities toward community development","Membership of an NGO, a labour union, and a religious body","Party membership, government employment, and tax exemption"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Citizenship includes legal membership in a country, political participation such as voting and advocacy, and social responsibilities toward community development. Option D lists things only some citizens have, and option A mixes property and duties that do not define citizenship. Option C lists civil society bodies, which are a separate idea."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 218, $official_bank_source${"itemId":"2f6115f7-9f81-5f15-8d67-c55474b82b49","questionId":"7684559d-5715-52a1-99aa-2572f34ce9ae","sourceKey":"bank:BUA205:FOL-042","payload":{"prompt":"Staff of a state agency notice their director diverting N60 million in project funds, but all of them stay silent and keep waiting for instructions. What is the most likely governance consequence of this passive followership?","options":["It allows misuse of power to continue and weakens governance","It strengthens accountability within the agency","It shows the exemplary followership that governance needs","It improves the agency's institutional performance"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Passive followership and civic apathy are listed causes of weak governance, because when followers do not question wrongdoing, misuse of power goes unchecked. Options B and D are what active followership produces. Option C is wrong because exemplary followers are active, independent thinkers who would challenge the diversion."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 219, $official_bank_source${"itemId":"2cd3ba70-bb93-58ec-b100-06e0cbf616ca","questionId":"4cecd99b-ab19-52ca-98f5-3c9e51b2a3f3","sourceKey":"bank:BUA205:FOL-043","payload":{"prompt":"The quality of governance in a society is said to reflect mainly:","options":["The number of laws passed each year","The size of the country's population","The personal ability of the head of government alone","The collective actions of leaders and followers within that society"],"correctOption":3,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Because leadership and followership are complementary, governance quality reflects what leaders and followers do together, supported by engaged citizens and strong civil society. Option C is rejected because leadership alone does not determine governance outcomes. Options B and A are not what decides how well a society is governed."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 220, $official_bank_source${"itemId":"344aa04b-1103-5219-8eb8-a68b06279fc6","questionId":"8e4e59f0-3643-521f-b64e-b243436b99d9","sourceKey":"bank:BUA205:FOL-044","payload":{"prompt":"The Nigeria Labour Congress (NLC), which represents workers' interests and campaigns on wage and policy issues, is an example of:","options":["A private profit-making company","A civil society organisation","A public sector entity","An arm of the legislature"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Labour unions are voluntary, non-governmental bodies that represent citizens' interests, which makes them part of civil society. Option C would make it part of government, and option A would make it a business run for profit. Option D is part of the state."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 221, $official_bank_source${"itemId":"dae9401e-0b2e-5a3b-91c6-20f20dc4f5ce","questionId":"aed3ef09-48d5-554a-be95-fceb350e8726","sourceKey":"bank:BUA205:FOL-045","payload":{"prompt":"A student union president at a Nigerian university consults students before negotiating hostel fees with management, while students give honest feedback and comply with agreed rules. This best illustrates:","options":["Alienated followership among students","Laissez-faire leadership by management","Responsible student leadership and followership promoting effective university administration","Political interference in university affairs"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Responsible student leadership and followership help university administration work well, which is what consultation, honest feedback and compliance with agreed rules show. Option D would involve outside partisan pressure. Option A would mean students were critical but disengaged, and option B does not describe management's role here."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 222, $official_bank_source${"itemId":"0dbabb3f-d965-5862-a047-41f6d5bfdc55","questionId":"c2ba765b-f753-5e2f-8015-7c2505fe0998","sourceKey":"bank:BUA205:NB-032","payload":{"prompt":"The choice of leadership style depends on which set of factors?","options":["The leader's age, salary, job title and office size","The number of departments, buildings, vehicles and branches","The environment, the leader, the followers and the objective or goal","The organisation's founding date, logo, motto and colours"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Leadership style depends on the environment, the leader, the followers and the objective or goal being pursued, so a style that suits one combination may fail in another. Options A, B and D list personal perks or physical and symbolic features of the organisation that do not determine how a leader should lead."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 223, $official_bank_source${"itemId":"6c10e0da-480b-5b76-9a62-7c32ff335267","questionId":"719d1336-5403-56da-884d-ed3fd31bf893","sourceKey":"bank:BUA205:NB-033","payload":{"prompt":"Which of the following is NOT one of the factors on which leadership style depends?","options":["The followers","The leader's ethnic origin","The objective or goal","The environment"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Leadership style depends on the environment, the leader, the followers and the objective or goal; a leader's ethnic origin does not decide which style suits a situation. Options D, A and C are all among the factors that shape leadership style."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 224, $official_bank_source${"itemId":"e3446f14-d23b-5726-be3a-03c6c8417de2","questionId":"a6576e8f-758e-5c46-9492-ec7b1cfb181d","sourceKey":"bank:BUA205:NB-034","payload":{"prompt":"A production manager gives close, step-by-step instructions to newly hired, untrained interns, but lets her experienced senior engineers decide how to do their own work. Her goals and workplace are the same for both groups. Which factor is shaping her choice of style?","options":["The objective or goal","The environment","The followers","The leader's own traits"],"correctOption":2,"section":"Leadership, Followership, Citizenship and Governance","explanation":"She adjusts her style to suit the people she is leading: inexperienced interns need direction while skilled engineers can be trusted with freedom, so the followers are the deciding factor. The case states that Options B and A are the same for both groups, and Option D cannot explain the difference because she is the same leader in both cases."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 225, $official_bank_source${"itemId":"661c75bb-653a-5f3d-b15f-8bd6a850891f","questionId":"538620eb-bf40-5132-8e59-0c918e39221b","sourceKey":"bank:BUA205:NB-035","payload":{"prompt":"A clerk in a state ministry is offered N2 million to move a contractor's file to the top of the pile, and she refuses. Which role of followership in governance is she performing?","options":["Resisting corruption","Giving feedback on public policies","Supporting ethical leaders","Participating in decision-making"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Refusing a bribe is a direct act of resisting corruption, one of the five roles of followership in governance. Options D and B involve contributing to decisions and commenting on policies, and Option C involves backing leaders who act ethically, none of which is what the clerk did."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 226, $official_bank_source${"itemId":"68570f98-522f-5a11-a004-7c7e2ae9739a","questionId":"884d62ef-935b-5b02-b719-c5acee00707d","sourceKey":"bank:BUA205:NB-036","payload":{"prompt":"Before a university finalises a new hostel allocation policy, students fill an online survey stating what works and what does not in the draft. Which role of followership in governance does this show?","options":["Giving feedback on public policies","Upholding institutional standards","Resisting corruption","Supporting ethical leaders"],"correctOption":0,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Commenting on a draft policy so that leaders can improve it is giving feedback on policies, one of the roles of followership in governance. Nothing in the case involves refusing corrupt practices (Option C), protecting the institution's rules (Option B) or backing a particular leader's conduct (Option D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 227, $official_bank_source${"itemId":"1c093969-e1f4-54ef-af7a-cfb919f0995f","questionId":"c6878c17-a39d-5702-9dc5-a1cc8a20228b","sourceKey":"bank:BUA205:NB-037","payload":{"prompt":"Which list correctly states the roles of followership in governance?","options":["Preventing authoritarian leadership, encouraging stability, strengthening accountability, enhancing institutional performance and supporting policy implementation","Supporting ethical leaders, participating in decision-making, upholding institutional standards, resisting corruption and giving feedback on public policies","Voting responsibly, obeying laws, paying taxes, promoting social harmony and holding leaders accountable","Advocacy and policy influence, human-rights protection, civic education, election monitoring and community development"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"The five roles of followership in governance are supporting ethical leaders, participating in decision-making, upholding institutional standards, resisting corruption and giving feedback on public policies. Option C lists responsibilities of citizens, Option D lists functions of civil society, and Option A lists reasons why followers are important in governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 228, $official_bank_source${"itemId":"80202aa4-aaf9-5931-b5f7-3e9dc9c87647","questionId":"03a494b6-f545-56bb-9625-dd064af2ffa1","sourceKey":"bank:BUA205:NB-038","payload":{"prompt":"Members of a local government staff association sit on the committee that decides the council's new staff welfare scheme and help shape its final terms. Which role of followership in governance is this?","options":["Upholding institutional standards","Participating in decision-making","Supporting ethical leaders","Resisting corruption"],"correctOption":1,"section":"Leadership, Followership, Citizenship and Governance","explanation":"Sitting on the committee that shapes a decision is participating in decision-making, one of the roles of followership in governance. Option D would involve refusing or exposing corrupt practices, Option A would involve protecting the institution's rules and values, and Option C would involve backing leaders who act with integrity."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 229, $official_bank_source${"itemId":"cd4845f8-eeaf-5bb3-ad14-433defb4be93","questionId":"0f262eb8-f49e-5210-a215-6ed1e7ce1543","sourceKey":"bank:BUA205:PQ-201","payload":{"prompt":"The social contract theory, as propounded by Rousseau, holds that government legitimacy derives from:","options":["Military strength and territorial control","Economic dominance and wealth accumulation","Divine right and hereditary privilege","The consent and agreement of the governed"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Rousseau argued that legitimate authority comes only from an agreement among the people, who together form a sovereign body guided by the general will. Divine right (option C) is the older justification that social contract thinkers rejected, and force or wealth (options A and B) may give power but not legitimacy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 230, $official_bank_source${"itemId":"225b5f2e-2b4e-58c7-9eb0-e1e36a4ccc32","questionId":"f8712e26-a914-55b4-8d14-88ec6e1cf001","sourceKey":"bank:BUA205:PQ-202","payload":{"prompt":"Thomas Hobbes' view of the social contract differed from Locke's primarily in that Hobbes believed:","options":["A powerful sovereign was necessary to prevent the brutish state of nature","People should retain natural rights even after forming a government","Property rights are the foundation of all political obligations","The general will always reflects individual interests"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Hobbes saw life without government as a war of all against all, so he argued that people should surrender their freedom to a strong, absolute sovereign in exchange for peace and security. Option B is Locke's position, option C also reflects Locke's emphasis on property, and option D uses Rousseau's idea of the general will."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 231, $official_bank_source${"itemId":"695232f3-e331-57c7-bf26-8f8a912673d8","questionId":"2712a4fc-136c-5612-843c-d0f1a44dd4a3","sourceKey":"bank:BUA205:PQ-203","payload":{"prompt":"Corporate governance ethics in the private sector primarily ensures that:","options":["Organisations act with integrity, transparency and accountability to all stakeholders","Companies maximise profits irrespective of ethical constraints","Government directives replace internal corporate codes of conduct","Only legal compliance is required without voluntary ethical standards"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Ethical corporate governance means a company is directed and controlled in a way that is honest, open and accountable to shareholders, employees, customers, suppliers, regulators and the community. Option B ignores ethics altogether, option D treats ethics as mere legal compliance, and option C wrongly suggests companies need no internal codes of their own."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 232, $official_bank_source${"itemId":"d0ff07c3-a2e5-5465-822e-c42615ede7aa","questionId":"37f932e4-5bf3-5bc2-aa73-89010f5b700f","sourceKey":"bank:BUA205:PQ-204","payload":{"prompt":"Ethical considerations in the public sector differ from those in the private sector primarily because:","options":["Public sector actors are stewards of public resources and owe accountability to all citizens","Profit motive is the primary ethical consideration in the public sector","Private sector ethics are more stringent than public sector requirements","Public officials are not bound by any code of conduct"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Public officials hold power and funds in trust for the whole population, so their central ethical duties are to avoid abusing office for personal gain and to act in the public interest. Option D is false because public officers have codes of conduct, option B describes the private sector, and option C has no general basis."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 233, $official_bank_source${"itemId":"981c6946-abbb-5d54-b3c8-475d1a848f12","questionId":"ce8f43a7-3767-5226-a63e-f49f6d20b117","sourceKey":"bank:BUA205:PQ-205","payload":{"prompt":"Which of the following BEST represents a breach of the social contract by a government?","options":["Passing laws to regulate taxation","Holding regular free and fair elections","Systematically denying citizens access to basic rights and public services","Establishing an independent judiciary"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Under the social contract, citizens accept the authority of government in return for protection of their rights and provision of basic services, so a government that systematically denies these fails its side of the bargain. Taxation laws (option A) are part of the normal contract, and free elections and an independent judiciary (options B and D) are signs that the contract is being kept."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 234, $official_bank_source${"itemId":"9b50ed3e-504c-5eeb-b108-914842877680","questionId":"99bd221f-9354-5269-9939-d0222cfc1ed1","sourceKey":"bank:BUA205:PQ-206","payload":{"prompt":"The concept of Corporate Social Responsibility (CSR) reflects which view of business responsibility?","options":["Pure profit maximisation without external obligations","Strict compliance with government tax codes only","A stakeholder-oriented approach where business has responsibilities beyond profit","Avoidance of all business activities that carry risk"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"CSR holds that a business owes duties not only to its owners but also to employees, customers, communities and the environment, so it should act responsibly beyond simply making profit. Option A is the narrow shareholder view that CSR challenges, option B reduces responsibility to tax compliance, and option D has nothing to do with CSR."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 235, $official_bank_source${"itemId":"25af6031-a3fe-57eb-a377-c0dc97561ae0","questionId":"2741f0e3-484c-5952-9d13-a348c7dfe494","sourceKey":"bank:BUA205:PQ-239-a","payload":{"prompt":"Which social contract theorist argued that people keep natural rights to life, liberty and property, and may resist a government that violates them?","options":["John Locke","Niccolo Machiavelli","Jean-Jacques Rousseau","Thomas Hobbes"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"John Locke held that government is created by consent to protect natural rights, so a government that violates life, liberty and property breaks the contract and may be resisted or replaced. Hobbes (option D) favoured an absolute sovereign that subjects should not resist, Rousseau (option C) built his theory on the general will, and Machiavelli (option B) was not a social contract theorist."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 236, $official_bank_source${"itemId":"80f6583d-40eb-5c45-8d8d-f632b738acd6","questionId":"90a3e775-5b5e-5b28-bea4-e66e1bfcc8ee","sourceKey":"bank:BUA205:PQ-239-b","payload":{"prompt":"Thomas Hobbes described human life in the state of nature, without government, as:","options":["Ordered by the divine right of kings","Solitary, poor, nasty, brutish and short","Peaceful but lacking an impartial judge to settle disputes","Free and equal, until corrupted by society and private property"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Hobbes believed that without a common power to keep order, people would live in a war of all against all, making life solitary, poor, nasty, brutish and short, which is why he argued for a strong sovereign. Option C is closer to Locke's milder view of the state of nature, option D reflects Rousseau, and option A is the older theory social contract thinkers rejected."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 237, $official_bank_source${"itemId":"aca27f3e-cf5f-53a0-9b8a-b9f93308b055","questionId":"10df97c6-767e-5dda-987c-07f2ca30d9a9","sourceKey":"bank:BUA205:PQ-239-c","payload":{"prompt":"In Rousseau's version of the social contract, legitimate laws must reflect the:","options":["Interests of property owners","Will of the strongest","General will","Divine will of the monarch"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Rousseau argued that people unite into a sovereign community and that laws are legitimate only when they express the general will, meaning the common good of all citizens. The will of the strongest (option B) is force, not legitimacy, divine will (option D) is the divine right theory, and the interests of property owners (option A) would favour one class over the community."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 238, $official_bank_source${"itemId":"55c40c64-0146-542a-b261-7c324c6eb4e8","questionId":"19591552-2f28-5d1c-9901-624b933ffd9d","sourceKey":"bank:BUA205:PQ-239-d","payload":{"prompt":"A social contract is best described as:","options":["An agreement in which people give up certain freedoms and accept a central authority in order to protect their other rights","A constitution imposed on citizens by a military government","A trade agreement between two or more countries","A written employment contract between a government and its civil servants"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"The social contract is an implicit agreement among members of a society to cooperate, accepting laws and authority in return for protection and social benefits; it explains why governments have the right to rule. Options D and C are ordinary legal contracts, and an imposed military constitution (option B) lacks the consent that the social contract depends on."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 239, $official_bank_source${"itemId":"e16e64ca-991e-54f5-bc6c-6c1c56559c78","questionId":"eacd5290-ed94-5609-b7b9-ce9f46ea129c","sourceKey":"bank:BUA205:PQ-239-e","payload":{"prompt":"Which of the following ethical issues is specific to the public sector rather than the private sector?","options":["Price-fixing that harms consumers and stifles competition","Using public office for private gain, such as diverting public funds","Misleading shareholders through fraudulent company accounts","Exploiting workers in a company's supply chain"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Public sector ethics centre on abuse of entrusted public authority, such as embezzling public funds, taking kickbacks on government contracts and failing to act in the public interest. Price-fixing (option A), labour exploitation in supply chains (option D) and misleading shareholders (option C) are typical private sector ethical issues arising from profit pressure."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 240, $official_bank_source${"itemId":"e4bdc795-ff6c-5d58-a487-9a5dd09d2575","questionId":"d4acb1d1-b31e-5f98-b9d4-e139fda989d1","sourceKey":"bank:BUA205:SCE-001","payload":{"prompt":"When a group of people agree to give up certain rights and accept a central authority in order to protect their other rights, this arrangement is called:","options":["Corporate governance","A social contract","Laissez-faire","A conflict of interest"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"A social contract is an agreement in which people give up certain rights and accept a central authority so that their other rights are protected. Option D is an ethical problem where personal interests clash with duty, and option A is the system by which a company is directed and controlled. Option C is a hands-off leadership style."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 241, $official_bank_source${"itemId":"14300110-662c-5c42-a116-1478722850ba","questionId":"bd2745cb-d1ee-5fe3-b22b-27b4f9d67de7","sourceKey":"bank:BUA205:SCE-002","payload":{"prompt":"Which statement correctly describes the relationship between government and the social contract?","options":["The social contract is a written document signed by every citizen","Government and the social contract mean exactly the same thing","The social contract is what allows any government to work, but the two are different things","A government can only exist where there is no social contract"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"The social contract is the underlying agreement that allows any government to work, but it is not the same thing as the government itself. Option B ignores that distinction. Option A is wrong because the contract is implicit, not a signed document, and option D reverses the relationship."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 242, $official_bank_source${"itemId":"0b95a1be-1aae-5538-844a-d4bd40e0b4c9","questionId":"8b4f88dd-13a8-538a-b328-0f13d79b040c","sourceKey":"bank:BUA205:SCE-003","payload":{"prompt":"The social contract is best described as which kind of agreement among members of a society?","options":["A trade agreement between two countries","An implicit agreement to cooperate for social benefits","An employment contract between workers and the state","A written contract enforced by the courts"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"The social contract is an implicit, unwritten agreement among members of society to cooperate for social benefits, such as giving up some individual freedom in exchange for state protection. Option D describes a formal legal contract. Options A and C describe specific agreements that are not the social contract."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 243, $official_bank_source${"itemId":"8dcf4902-84b8-5b0e-be2a-08e099030737","questionId":"cbdc45ba-d759-5813-bb83-b070eb550c54","sourceKey":"bank:BUA205:SCE-004","payload":{"prompt":"Which of the following is the typical trade-off at the heart of the social contract?","options":["Surrendering property in exchange for voting rights","Giving up all rights in exchange for wealth","Paying bribes in exchange for public services","Sacrificing some individual freedom in exchange for state protection"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"The classic social contract trade-off is giving up some individual freedom in return for protection by the state. Option B exaggerates the bargain. Option C describes corruption, and option A is not the exchange the social contract describes."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 244, $official_bank_source${"itemId":"2fecaad2-3807-5304-b8f7-07f315d325d0","questionId":"07254979-b7ca-5b53-a6bf-7e1447e6f5d0","sourceKey":"bank:BUA205:SCE-005","payload":{"prompt":"Theories of the social contract became popular during which period?","options":["The 21st century","The 10th and 11th centuries","The 16th, 17th and 18th centuries","The 19th and 20th centuries only"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Social contract theories became popular in the 16th, 17th and 18th centuries through thinkers such as Thomas Hobbes, John Locke and Jean-Jacques Rousseau. Options B, D and A give the wrong period."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 245, $official_bank_source${"itemId":"545a5a9b-bb6e-5993-8b3f-c4960125eea9","questionId":"d999823f-074f-5a50-ad44-b231fdcb9549","sourceKey":"bank:BUA205:SCE-006","payload":{"prompt":"Social contract theories were developed mainly as a means of explaining:","options":["Why followers should never question leaders","The origin of government and the obligations of subjects","How leaders should choose a leadership style","How firms should calculate profit"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Hobbes, Locke and Rousseau used the social contract to explain where government comes from and what obligations subjects have toward it. Option D is an accounting question, and option C is a leadership-style question. Option A is not what the theories argue."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 246, $official_bank_source${"itemId":"6af27a7c-41fa-56ba-87c4-05cbf118c973","questionId":"056a4f82-8b3d-5642-80c9-5223c211bbf1","sourceKey":"bank:BUA205:SCE-007","payload":{"prompt":"According to social contract theory, people live together in society in accordance with:","options":["Market forces of demand and supply alone","The commands of whoever is strongest at any moment","An agreement that establishes moral and political rules of behaviour","Religious rules handed down by a single church"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Social contract theory holds that people live together in line with an agreement that sets moral and political rules of behaviour. Option B describes rule by force, the kind of insecure condition the contract is meant to escape. Options A and D name other forces that are not the basis of the theory."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 247, $official_bank_source${"itemId":"5a0ac74c-8597-5b3d-80cd-4dd417c1feb0","questionId":"a1ce2cf3-fb20-5c45-895f-81b793f24078","sourceKey":"bank:BUA205:SCE-008","payload":{"prompt":"Which of the following thinkers is NOT one of the classical social contract theorists?","options":["Jean-Jacques Rousseau","Thomas Hobbes","Karl Marx","John Locke"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Thomas Hobbes, John Locke and Jean-Jacques Rousseau are the classical social contract theorists of the 17th and 18th centuries. Karl Marx was a 19th-century thinker known for his critique of capitalism, not for social contract theory. Options B, D and A are all social contract theorists."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 248, $official_bank_source${"itemId":"c9ec14f1-2a63-551f-a9ff-d0000aec656d","questionId":"3f56bc65-7a87-5478-bcdc-5d4efe01e044","sourceKey":"bank:BUA205:SCE-009","payload":{"prompt":"Which social contract theorist described life in the state of nature, without government, as 'solitary, poor, nasty, brutish and short'?","options":["Jean-Jacques Rousseau","John Locke","Robert Kelley","Thomas Hobbes"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Thomas Hobbes described the state of nature as a war of all against all in which life is 'solitary, poor, nasty, brutish and short', which is why he thought people needed a strong sovereign. Option B saw the state of nature as governed by natural law and reason, and option A saw natural man as relatively free and peaceful. Option C is a followership scholar."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 249, $official_bank_source${"itemId":"d40707c3-7168-568e-a785-7dcd03c087f8","questionId":"7c2c42bd-9458-523c-b31a-e707c846c534","sourceKey":"bank:BUA205:SCE-010","payload":{"prompt":"Thomas Hobbes set out his social contract theory in which work?","options":["The Power of Followership","Two Treatises of Government","Leviathan","The Social Contract"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Hobbes presented his social contract theory in Leviathan (1651). Option B is by John Locke, and option D is by Jean-Jacques Rousseau. Option A is Robert Kelley's book on followership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 250, $official_bank_source${"itemId":"a458a767-70fc-5f55-9ded-a350bc9f46d6","questionId":"0976aec1-6f9e-5c57-840b-4d254bc683a0","sourceKey":"bank:BUA205:SCE-011","payload":{"prompt":"In Hobbes' version of the social contract, people surrender their rights mainly to:","options":["Voluntary civil society organisations","A general will that is expressed by the whole community","A limited government that must protect property or be replaced","A strong, absolute sovereign that guarantees peace and security"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Hobbes believed that, to escape the violent state of nature, people hand their rights to a powerful, absolute sovereign that keeps order and security. Option B reflects Rousseau's idea of the general will, and option C reflects Locke's limited government. Option A is a modern governance idea, not Hobbes' sovereign."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 251, $official_bank_source${"itemId":"8e86df94-4639-57e1-9195-d6e4e3d7ab41","questionId":"26f8e865-b0e3-51d3-9449-96f3a528ab81","sourceKey":"bank:BUA205:SCE-012","payload":{"prompt":"John Locke held that people possess natural rights which government exists to protect. These rights are:","options":["Food, shelter and clothing","Voting, jury service and taxation","Life, liberty and property","Wealth, power and status"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Locke argued that people have natural rights to life, liberty and property, and that the purpose of government is to protect them. Option D lists social advantages, and option A lists basic needs. Option B lists civic duties and processes, not Locke's natural rights."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 252, $official_bank_source${"itemId":"2bdf73b6-c25a-51b3-b1dc-b5f3e8564839","questionId":"bdbed978-e1e0-588b-a93b-eb94fc588cff","sourceKey":"bank:BUA205:SCE-013","payload":{"prompt":"According to John Locke, if a government violates the natural rights it was created to protect, the people:","options":["Have the right to resist and replace that government","Should return to the state of nature permanently","Must transfer their rights to a foreign power","Must obey it absolutely to avoid returning to chaos"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Locke's government is limited and rests on the consent of the governed, so if it breaks its trust by violating natural rights, the people may resist and replace it. Option D is closer to Hobbes' view of an absolute sovereign. Options B and C are not part of Locke's argument."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 253, $official_bank_source${"itemId":"40af54d5-52b7-5f6b-b238-4e51f8ec3a11","questionId":"3858a1f2-a4fc-5ff9-bfcc-715197d773aa","sourceKey":"bank:BUA205:SCE-014","payload":{"prompt":"Which social contract theorist is associated with the idea of the 'general will' as the basis of legitimate authority?","options":["Jean-Jacques Rousseau","Bernard Bass","John Locke","Thomas Hobbes"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Rousseau argued that legitimate authority comes from the general will of the people as a whole, so sovereignty belongs to the people. Option D favoured an absolute sovereign, and option C stressed natural rights and limited government. Option B is a leadership scholar."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 254, $official_bank_source${"itemId":"b9cbf333-2316-54a9-a7fd-62e5e3cd017e","questionId":"ae27b93d-95c1-5b08-99dc-8cc122fef44b","sourceKey":"bank:BUA205:SCE-015","payload":{"prompt":"The famous opening line 'Man is born free, and everywhere he is in chains' comes from which thinker?","options":["Jean-Jacques Rousseau","John Locke","Thomas Hobbes","James MacGregor Burns"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"This line opens Rousseau's The Social Contract (1762), where he asks how political authority can be legitimate. Option C is known for the 'nasty, brutish and short' description of the state of nature. Option B is known for natural rights to life, liberty and property, and option D is a leadership scholar."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 255, $official_bank_source${"itemId":"c5cc9ec3-7bee-5b0d-a177-da76ffa2de21","questionId":"bc64e74a-026c-5fa7-8dba-d9bebb6f1cee","sourceKey":"bank:BUA205:SCE-016","payload":{"prompt":"Which statement correctly contrasts Hobbes and Rousseau?","options":["Hobbes placed sovereignty in the people; Rousseau favoured an absolute monarch","Both argued that property is the only natural right","Both argued that people should have no government at all","Hobbes favoured an absolute sovereign; Rousseau placed sovereignty in the general will of the people"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Hobbes thought only an absolute sovereign could prevent the chaos of the state of nature, while Rousseau located sovereignty in the people through the general will. Option A swaps their positions. Option C is wrong because both justified government, and option B misstates both thinkers, since property was one of Locke's three natural rights."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 256, $official_bank_source${"itemId":"9d9f62e2-ecf7-59a0-b82e-20853b5c7caa","questionId":"197f315a-abdb-596b-8426-24d4cffc034a","sourceKey":"bank:BUA205:SCE-017","payload":{"prompt":"How did John Locke's view of the state of nature differ from that of Thomas Hobbes?","options":["Both saw it as the ideal condition to return to","Both saw it as perfectly safe and orderly","Locke saw it as a war of all against all; Hobbes saw it as peaceful","Locke saw it as governed by natural law and reason, though insecure; Hobbes saw it as a war of all against all"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"For Locke, the state of nature was governed by natural law and reason, but people formed governments to protect their rights more securely. For Hobbes it was a violent war of all against all. Option C reverses the two. Options B and A misstate both, since neither saw the state of nature as something to keep."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 257, $official_bank_source${"itemId":"8f6f70ba-5a62-5aae-9a40-4b3f6e5c4704","questionId":"d6123b2a-b57b-5987-ab76-85bab533da75","sourceKey":"bank:BUA205:SCE-018","payload":{"prompt":"During violent unrest, a state government imposes a dusk-to-dawn curfew, and residents accept a temporary limit on their movement so that lives and property are protected. This best illustrates:","options":["Management by exception-passive","A conflict of interest on the part of the governor","Laissez-faire leadership by the state government","The social contract, in which citizens give up some freedom for state protection"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Accepting a temporary limit on freedom in return for protection is the social contract at work, and emergency measures that override freedoms are listed among its examples. Option C would mean the government stepping back, not acting. Option B requires a personal interest clashing with public duty, and option A is a transactional leadership practice."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 258, $official_bank_source${"itemId":"c65de846-61ed-59ee-a173-7844070d9ce1","questionId":"18c4bf17-64ff-5b3a-baf1-94787c071724","sourceKey":"bank:BUA205:SCE-019","payload":{"prompt":"Which of the following examples of the social contract is a civic DUTY rather than a right?","options":["Jury duty","Right to a fair trial","Right to privacy","Freedom of religion"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Jury duty is an obligation citizens owe under the social contract, along with paying taxes, census participation and other civic duties. Options B, D and C are rights that the social contract protects for citizens."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 259, $official_bank_source${"itemId":"0ff6f108-18da-52d1-b577-a8a7ba604915","questionId":"97209a7f-7946-51ff-a8cf-5fbe9ca2bf68","sourceKey":"bank:BUA205:SCE-020","payload":{"prompt":"Every year, a Lagos trader pays N250,000 in taxes, and in return expects the state to provide security, roads and courts. This exchange is best explained by:","options":["Kelley's followership model","The Managerial Grid","The social contract","The agency relationship in a company"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Paying taxes and accepting government authority in return for protection and public services is a classic example of the social contract. Option D describes managers acting on behalf of owners in a business. Options B and A are leadership and followership models."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 260, $official_bank_source${"itemId":"863fda18-db90-50cf-87da-1681cf17fdc6","questionId":"d4a26938-ef56-581a-970c-db8147ef68ed","sourceKey":"bank:BUA205:SCE-021","payload":{"prompt":"Requirements such as registering births and obtaining government identification are listed under the social contract as:","options":["International agreements","Administrative requirements","Freedoms of expression","Economic rights"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Registering births and obtaining government identification are administrative requirements that citizens accept as part of the social contract. Option D concerns rights to work and earn, and option C concerns speech. Option A concerns agreements between states."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 261, $official_bank_source${"itemId":"32695472-7759-59b8-9341-4d4c1af395cc","questionId":"fba6296c-b6a0-55aa-850c-c120d65ae011","sourceKey":"bank:BUA205:SCE-022","payload":{"prompt":"Corporate social responsibility, consumer protection and environmental protection appear among examples of the social contract. This suggests that the social contract:","options":["Has nothing to do with economic life","Applies only to elected politicians","Replaces the need for laws and regulations","Also shapes what society expects of businesses, not only of governments"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Including CSR, consumer protection and environmental protection shows that the social contract also covers society's expectations of businesses. Options B and A wrongly narrow the idea. Option C is wrong because laws and regulations are themselves listed as examples of the social contract."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 262, $official_bank_source${"itemId":"50e6fa34-82c9-5e53-967e-619c3be42464","questionId":"757e215b-0f63-5b38-ae54-22e7cf080980","sourceKey":"bank:BUA205:SCE-023","payload":{"prompt":"Ethical issues in the public sector centre mainly on:","options":["Price-fixing and anti-competitive behaviour among firms","Pressure to maximise shareholder profits","Exploitation of labour in global supply chains","Abuse of authority for personal gain, conflicts of interest, corruption and failure to act in the public interest"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Public sector ethical issues centre on abuse of authority for personal gain, conflicts of interest, corruption and failure to act in the public interest. Options A, B and C are ethical issues mainly associated with the profit-driven private sector."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 263, $official_bank_source${"itemId":"956b1c46-2285-51dd-87d0-405c29b10cda","questionId":"dc458f62-5fa1-55f3-91a6-5566b9aaf249","sourceKey":"bank:BUA205:SCE-024","payload":{"prompt":"Bribery, nepotism, mismanagement of public funds and weak accountability in the public sector mainly:","options":["Increase transparency","Strengthen merit-based administration","Improve service delivery","Erode public trust"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"These common public sector ethical failures erode public trust in government. Options C, B and A are outcomes of ethical, accountable administration, which these failures undermine."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 264, $official_bank_source${"itemId":"9fa7632b-ce75-5efb-bb0f-881f46cd2459","questionId":"b86412fc-afe8-500b-b0db-419644d5beaa","sourceKey":"bank:BUA205:SCE-025","payload":{"prompt":"A local government works officer tells a contractor that a N20 million drainage contract will only be approved if the contractor pays him 10 percent in cash. Which public sector ethical issue is this?","options":["Corruption and bribery","Low integrity and work ethic","Ethical dilemma in decision-making","Data privacy violation"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Demanding a kickback to approve a contract is using public office for private gain, which is corruption and bribery. Option D concerns mishandling confidential information, and option B concerns absenteeism and laziness. Option C involves a genuine clash of values, not plain extortion."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 265, $official_bank_source${"itemId":"4b2e2df0-b574-51cb-94b8-09c2984cfcdb","questionId":"362042ff-1c70-5c88-be4d-88ffd935b692","sourceKey":"bank:BUA205:SCE-026","payload":{"prompt":"A state commissioner for lands approves a large land allocation to a company in which he secretly holds shares. Which ethical issue does this primarily illustrate?","options":["Low integrity and work ethic","Conflict of interest","Misuse of power through harassment","Data privacy violation"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"A conflict of interest arises when public officials make decisions that benefit themselves, their family or associates rather than the public, as when the commissioner favours a company he owns shares in. Option D involves confidential information, and option A involves absenteeism and laziness. Option C involves intimidating or harassing people."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 266, $official_bank_source${"itemId":"b1d0a6fe-36f3-512e-9f2e-fcdeef025f53","questionId":"da9061c1-e16c-50dd-a4ef-a91e77c243fa","sourceKey":"bank:BUA205:SCE-027","payload":{"prompt":"A director in a federal parastatal promotes his niece to a senior post over three better-qualified officers, purely because she is family. Which public sector ethical issue is this?","options":["Low integrity and work ethic","Data privacy violation","Nepotism and favouritism","Anti-competitive behaviour"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Nepotism and favouritism means hiring, promoting or awarding contracts to friends or family because of the relationship rather than merit. Option B concerns confidential information, and option A concerns absenteeism and laziness. Option D is a private-sector market issue such as price-fixing."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 267, $official_bank_source${"itemId":"ec13951c-7783-55ef-b0f3-7aff32da5bc1","questionId":"59af7dd6-e2d8-5861-a363-28572c5f12dd","sourceKey":"bank:BUA205:SCE-028","payload":{"prompt":"A senior officer repeatedly intimidates and threatens a junior colleague who refused to falsify a report. Which public sector ethical issue is this?","options":["Nepotism and favouritism","Data privacy violation","Misuse of power or authority","Low integrity and work ethic"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Misuse of power or authority covers intimidating, harassing or discriminating against others by using one's position. Option A involves favouring relatives or friends. Option B involves confidential information, and option D involves absenteeism and laziness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 268, $official_bank_source${"itemId":"7e785ea6-448d-5284-a6d7-459875e784e6","questionId":"b7d3bca4-ad56-5328-b87a-6e05b33c83e1","sourceKey":"bank:BUA205:SCE-029","payload":{"prompt":"Staff at a government registry access citizens' personal records without authorisation and share some of them on social media. Which public sector ethical issue is this?","options":["Data privacy violation","Conflict of interest","Nepotism and favouritism","Low integrity and work ethic"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Improper handling of, or unauthorised access to, confidential citizen or government information is a data privacy violation. Option C involves favouring relatives or friends. Option D involves absenteeism and laziness, and option B involves decisions that benefit the official personally."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 269, $official_bank_source${"itemId":"8cc648b0-5f71-5fa7-a28e-d455052368e5","questionId":"dbbe4bf7-00e8-52af-8814-2ee8cb305370","sourceKey":"bank:BUA205:SCE-030","payload":{"prompt":"Officers at a ministry routinely sign the attendance register at 8 a.m. and then leave to run private businesses, returning only to sign out. Which public sector ethical issue is this?","options":["Low integrity and work ethic","Data privacy violation","Conflict of interest","Nepotism and favouritism"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Low integrity and work ethic covers absenteeism, laziness and a lack of dedication to public service, which is what these officers show. Option B involves confidential information, and option C involves official decisions that benefit the decision-maker. Option D involves favouring relatives or friends."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 270, $official_bank_source${"itemId":"322a2185-abf9-51a1-b5c2-bf701723f9a2","questionId":"d688e2f1-92a3-5b4f-b97c-32a047e3319d","sourceKey":"bank:BUA205:SCE-031","payload":{"prompt":"A public official must choose between her personal values, pressure from politicians and her professional responsibilities, and the conflict leads to poor administrative judgement. This is described as:","options":["Nepotism and favouritism","Low integrity and work ethic","A data privacy violation","An ethical dilemma in decision-making"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"An ethical dilemma in decision-making is having to choose between personal values, political pressure and professional responsibilities, which often leads to poor administrative judgement. Option A is favouring relatives or friends, and option C is mishandling confidential information. Option B is absenteeism and laziness."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 271, $official_bank_source${"itemId":"2dd3cfe4-a63c-5eaf-aa21-c1be5a139b37","questionId":"15599dc8-3171-5485-8a5f-b37de2366fde","sourceKey":"bank:BUA205:SCE-032","payload":{"prompt":"Concealing information, making fraudulent reports or avoiding scrutiny in a public agency is classified as:","options":["Misuse of power through harassment","Nepotism and favouritism","Lack of accountability and transparency","Ethical dilemma in decision-making"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Concealing information, filing fraudulent reports and avoiding scrutiny are forms of lack of accountability and transparency, which hinders public trust. Option D is a genuine clash of values, and option B is favouring relatives or friends. Option A is intimidating or harassing people."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 272, $official_bank_source${"itemId":"b349be16-8dcb-5851-a71b-65e3f4824c7e","questionId":"59339c75-3bd5-5f6e-a88e-76391a3a76ed","sourceKey":"bank:BUA205:SCE-033","payload":{"prompt":"Addressing ethical challenges in the public sector requires all of the following EXCEPT:","options":["Strong anti-corruption laws","Restricting citizens' access to public information","Merit-based administration","Whistleblower protection"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Public sector ethical problems are tackled with strong anti-corruption laws, whistleblower protection, improved transparency and merit-based administration. Restricting access to information reduces transparency and makes things worse. Options A, D and C are all recommended remedies."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 273, $official_bank_source${"itemId":"41789ac3-97c4-5627-95b6-5e30f3bb7e5d","questionId":"d85a6200-8b1c-56cb-893c-13ebe084ef9b","sourceKey":"bank:BUA205:SCE-034","payload":{"prompt":"A ministry wants to stop the practice of awarding posts to relatives of senior officials. Which remedy most directly addresses this problem?","options":["Larger budgets for the ministry","A focus on merit-based administration","Stricter rules against price-fixing","Data encryption of citizens' records"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Nepotism means appointing people because of relationships rather than merit, so a focus on merit-based administration attacks it directly. Option D addresses data privacy, and option C addresses anti-competitive private-sector behaviour. Option A does not deal with how posts are filled."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 274, $official_bank_source${"itemId":"317e17df-d54f-5724-a9c2-673939e7b66b","questionId":"4e01b33e-e7c7-5f6f-b18c-465d12deb21f","sourceKey":"bank:BUA205:SCE-035","payload":{"prompt":"Whistleblower protection helps address public sector ethical problems mainly by:","options":["Encouraging insiders to report wrongdoing without fear of reprisal","Guaranteeing jobs for relatives of senior staff","Keeping corruption cases out of the media","Allowing officials to avoid public scrutiny"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Protecting whistleblowers makes it safer for insiders to expose corruption and misconduct, which strengthens accountability. Options D and C reduce transparency, and option B describes nepotism."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 275, $official_bank_source${"itemId":"5cb78c43-3d1a-5f0b-ab86-d736e221da36","questionId":"7b8b3908-d4e9-58f1-b3f7-4c2b788dba6a","sourceKey":"bank:BUA205:SCE-036","payload":{"prompt":"Ethical issues in the private sector primarily arise from:","options":["Bureaucratic multi-level approvals","The obligation to serve the general public welfare","Profit-driven decision-making","Political pressure from elected officials"],"correctOption":2,"section":"Social Contract and Ethics","explanation":"Private sector ethical problems mostly come from profit-driven decision-making, which can lead to conflicts of interest, discrimination, harassment and environmental harm. Options A and D are more typical of public sector settings. Option B is the main objective of public enterprises, not the cause of private sector problems."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 276, $official_bank_source${"itemId":"3c02ac3f-8c4a-5b63-8f90-1364e12c3346","questionId":"0746c035-9674-5b99-93ad-3b94e7893add","sourceKey":"bank:BUA205:SCE-037","payload":{"prompt":"Three cement manufacturers secretly agree to sell a bag at not less than N9,500 so that none of them undercuts the others. Which private sector ethical issue is this?","options":["Data privacy and security breach","Anti-competitive behaviour","Environmental and social responsibility failure","Workplace harassment and discrimination"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Price-fixing is an anti-competitive practice that harms consumers and stifles fair competition. Option D concerns mistreating employees, and option A concerns mishandling customer information. Option C concerns environmental harm and unfair labour practices."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 277, $official_bank_source${"itemId":"43eda824-da57-5824-a143-9e287bb9f5dc","questionId":"9875e08c-6d26-572f-9890-2c3adf0ff317","sourceKey":"bank:BUA205:SCE-038","payload":{"prompt":"To meet investors' expectations, the finance team of a listed company records N800 million of sales that never took place. Which private sector ethical issue is this?","options":["Financial integrity and fraud","Anti-competitive behaviour","Data privacy and security","Workplace harassment and discrimination"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Recording fictitious sales is dishonest financial reporting, which falls under financial integrity and fraud. Option B concerns practices such as price-fixing. Option D concerns mistreating staff, and option C concerns protecting customer information."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 278, $official_bank_source${"itemId":"be4f163d-3bd5-533e-a0ad-4c618c7f8c80","questionId":"1fe6797a-d4c8-5114-836a-eeeeb1512f43","sourceKey":"bank:BUA205:SCE-039","payload":{"prompt":"A food processing company dumps untreated waste into a river used by nearby villages and buys raw materials from suppliers known to use child labour. Which private sector ethical issue is this?","options":["Environmental and social responsibility failure","Financial integrity and fraud","Anti-competitive behaviour","Data privacy and security"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Neglecting environmental impacts and failing to ensure safe, fair labour practices across the supply chain are environmental and social responsibility failures. Option C concerns practices such as price-fixing. Option B concerns dishonest reporting, and option D concerns customer information."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 279, $official_bank_source${"itemId":"c4b5c556-f921-595a-8d5b-022792ac5db2","questionId":"3d1848e2-44f6-5ed4-a90a-3297d0916663","sourceKey":"bank:BUA205:SCE-040","payload":{"prompt":"A private company repeatedly passes over a well-qualified employee for promotion because of her religion. Which private sector ethical issue is this?","options":["Workplace harassment and discrimination","Financial integrity and fraud","Anti-competitive behaviour","Environmental and social responsibility"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Mistreating employees because of race, gender or religion is workplace harassment and discrimination, which creates toxic environments and violates employee rights. Option C concerns market practices like price-fixing. Option B concerns dishonest reporting, and option D concerns environmental harm and supply-chain labour."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 280, $official_bank_source${"itemId":"2f7d4058-c11f-558b-9248-af3ddb678eeb","questionId":"7cce0046-5b1f-5dcf-89de-4b0fa4c8b0b2","sourceKey":"bank:BUA205:SCE-041","payload":{"prompt":"A fintech app stores customers' card details and BVNs with weak protection, and hackers steal the records of thousands of users. Which private sector ethical issue does this illustrate?","options":["Anti-competitive behaviour","Data privacy and security","Workplace harassment and discrimination","Conflicts of interest"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Misusing, or failing to adequately protect, consumers' personal and financial information is a data privacy and security issue that breaches customer trust. Option A concerns practices such as price-fixing. Option C concerns mistreating staff, and option D concerns personal interests compromising professional judgement."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 281, $official_bank_source${"itemId":"347e5e90-0eb2-538b-915c-66300e46b674","questionId":"81fdd6c2-4f1f-5282-8021-746d31691a32","sourceKey":"bank:BUA205:SCE-042","payload":{"prompt":"Ethical issues in the private sector are said to often stem from:","options":["Multiple levels of bureaucratic approval","Intense pressure for performance, leading to unethical shortcuts","Excessive public disclosure requirements","Too much consultation with employees"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Private sector ethical problems often come from intense pressure to perform, which tempts people into unethical shortcuts that risk legal consequences and reputational damage. Options C, D and A are not given as the root of these problems."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 282, $official_bank_source${"itemId":"cad102e3-7015-5d2f-9749-66dc7b82c314","questionId":"2405b234-6967-542a-9f0a-e767f0dc9848","sourceKey":"bank:BUA205:SCE-043","payload":{"prompt":"Which of the following ethical issues appears among BOTH the public sector issues and the private sector issues?","options":["Neglect of environmental impacts in the supply chain","Anti-competitive behaviour such as price-fixing","Absenteeism and low dedication to public service","Conflicts of interest"],"correctOption":3,"section":"Social Contract and Ethics","explanation":"Conflicts of interest appear in both lists: in the public sector as officials benefiting themselves or associates, and in the private sector as personal interests such as nepotism compromising professional judgement. Options B and A are listed only for the private sector, and option C only for the public sector."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 283, $official_bank_source${"itemId":"7559a0cf-03b3-51c7-9278-03b0479624d7","questionId":"832a95bb-3e61-524c-b662-fdd3490800cb","sourceKey":"bank:BUA205:SCE-044","payload":{"prompt":"John Locke presented his theory of government by consent and natural rights in which work?","options":["The Social Contract","Two Treatises of Government","Leviathan","Leadership"],"correctOption":1,"section":"Social Contract and Ethics","explanation":"Locke set out his ideas on natural rights and government by consent in Two Treatises of Government. Option C is Thomas Hobbes' work, and option A is Jean-Jacques Rousseau's. Option D is James MacGregor Burns' 1978 book on transforming and transactional leadership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 284, $official_bank_source${"itemId":"58770ee3-764b-5236-832e-e141888ca06b","questionId":"3315b2fa-2cb4-5c0e-9e94-0183f918ef46","sourceKey":"bank:BUA205:SCE-045","payload":{"prompt":"Corruption and bribery in the public sector include all of the following EXCEPT:","options":["Taking approved annual leave","Stealing public funds","Accepting kickbacks","Manipulating contracts"],"correctOption":0,"section":"Social Contract and Ethics","explanation":"Corruption and bribery means using public office for private gain, including accepting kickbacks, stealing public funds and manipulating contracts. Taking approved annual leave is a normal entitlement, not an ethical breach. Options C, B and D are all listed forms of corruption."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 285, $official_bank_source${"itemId":"07dc52e7-9ea8-51b0-94de-18991ffb1108","questionId":"33ef15d9-9883-5e62-8c5a-6c9e014038bf","sourceKey":"bank:BUA205:PQ-208","payload":{"prompt":"A stakeholder in public governance is BEST defined as:","options":["International organisations that fund national development","Elected politicians and appointed public officials only","Only shareholders of listed public companies","Any individual, group or organisation that can affect or is affected by government decisions and policies"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"A stakeholder is anyone who can influence, or is influenced by, a decision, which in public governance includes citizens, communities, businesses, civil society, public servants and development partners. Options C, B and A each pick out only one group and leave out most of the people affected by public policy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 286, $official_bank_source${"itemId":"f0a253e8-7041-51e5-8e8c-a5cce1db0262","questionId":"2a7465ef-7bf0-5e22-9b7d-8090d5461d40","sourceKey":"bank:BUA205:PQ-209","payload":{"prompt":"Effective stakeholder engagement in governance requires:","options":["Limiting public participation to technical experts","Inclusive, transparent and meaningful participation of all relevant parties in decision-making","Informing stakeholders only after major decisions have been made","Prioritising media engagement over community involvement"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Good engagement brings affected groups into the process early, shares information openly and gives their views real weight in the final decision. Option C is tempting because informing people is part of engagement, but telling them only after decisions are made is announcement, not engagement, and options A and D exclude many of those affected."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 287, $official_bank_source${"itemId":"3a4e09e9-c2e7-58c3-9710-d0a1af1ee5df","questionId":"892ee4ce-bef7-5f6d-80e6-6905e5fd4f23","sourceKey":"bank:BUA205:PQ-210","payload":{"prompt":"Crisis communication management in the public sector is critical because:","options":["Silence during a crisis protects government from legal liability","Only international media coverage determines crisis management success","Crisis management is exclusively a function of the military command","Timely, accurate and empathetic communication maintains public trust and enables effective crisis response"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"During a crisis people need quick, correct and caring information to stay safe and cooperate with authorities, and good communication protects the credibility of government. Silence (option A) usually breeds rumours and distrust, while options B and C wrongly narrow crisis management to the media or the military."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 288, $official_bank_source${"itemId":"a6ec851b-9f27-53f4-8ec6-6a118a025981","questionId":"1c21f4a2-b0a8-5a2e-a7cc-d65cf7f06f61","sourceKey":"bank:BUA205:PQ-211","payload":{"prompt":"Which of the following is the FIRST stage in a typical crisis management cycle?","options":["Post-crisis evaluation and recovery","Crisis prevention and preparedness (pre-crisis)","Crisis response","Crisis communication"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Crisis management begins before anything goes wrong, with identifying risks, preventing what can be prevented and preparing plans, teams and supplies. Response (option C) follows once a crisis occurs, recovery and evaluation (option A) come last, and communication (option D) runs through every stage rather than being the first one."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 289, $official_bank_source${"itemId":"5939d170-2e47-59d8-ab99-b0656248e376","questionId":"b01dbf7e-6241-5b9c-8a5a-7fb3219123eb","sourceKey":"bank:BUA205:PQ-212","payload":{"prompt":"In stakeholder theory, stakeholders are typically prioritised based on their:","options":["Financial contribution to the organisation or government","Geographic proximity to government offices","Power, legitimacy and urgency of their claims","Media visibility and public relations capacity"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Mitchell, Agle and Wood's stakeholder salience model says managers pay most attention to stakeholders who have power to influence the organisation, a legitimate claim and an urgent demand. Financial contribution (option A) and media visibility (option D) may give some power, but they are only parts of one attribute, and location (option B) is not a criterion at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 290, $official_bank_source${"itemId":"4b9e3ab1-209c-5fde-a784-2e67a05308ae","questionId":"02ff5cce-fa35-54e3-a926-6abd21a85aae","sourceKey":"bank:BUA205:PQ-213","payload":{"prompt":"A government's failure to communicate effectively during a national security crisis is likely to result in:","options":["A reduction in the spread of misinformation","Public panic, spread of misinformation and erosion of institutional credibility","Improved operational security for government agencies","Enhanced public trust and voluntary cooperation"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"When government is silent or unclear in a crisis, rumours fill the gap, people panic and citizens lose confidence in the institutions meant to protect them. Options D and A describe the results of good communication, not poor communication, and option C confuses careful handling of sensitive details with failing to communicate at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 291, $official_bank_source${"itemId":"fd39f8b4-9e20-565a-be95-404074700a67","questionId":"324b839c-3089-576f-b1bc-de2358433b3f","sourceKey":"bank:BUA205:PQ-240-a","payload":{"prompt":"In the Mitchell, Agle and Wood (1997) stakeholder salience model, a stakeholder who possesses power, legitimacy and urgency is classified as a:","options":["Discretionary stakeholder","Dependent stakeholder","Definitive stakeholder","Dormant stakeholder"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"The salience model says that the more of the three attributes a stakeholder has, the more attention it deserves, and a stakeholder with all three is definitive and needs immediate priority. A dormant stakeholder (option D) has only power, a discretionary stakeholder (option A) has only legitimacy, and a dependent stakeholder (option B) has legitimacy and urgency but lacks power."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 292, $official_bank_source${"itemId":"a2b69bf1-880a-535b-8103-565f69d2b134","questionId":"1ae08d38-ea82-5c7c-922a-f468e52079f9","sourceKey":"bank:BUA205:PQ-240-b","payload":{"prompt":"In the stakeholder salience model, 'urgency' refers to:","options":["The degree to which a stakeholder's claim is time-sensitive and critical, calling for immediate attention","The number of people a stakeholder group represents","The extent to which a stakeholder's claim is seen as proper or appropriate","The ability of a stakeholder to impose its will on the organisation"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Urgency captures how pressing a claim is: whether delay would be unacceptable and whether the matter is important to the stakeholder. Option D describes power and option C describes legitimacy, the model's other two attributes, while group size (option B) is not one of the attributes at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 293, $official_bank_source${"itemId":"51438d9b-6a10-52dc-bcb6-a0382b99230d","questionId":"708f4956-4f9b-507c-9c37-bc2e3b582261","sourceKey":"bank:BUA205:PQ-240-c","payload":{"prompt":"Stakeholder engagement in public governance is best defined as:","options":["Publicising government programmes through the media","The process by which government involves those who affect or are affected by its decisions in shaping and implementing them","Consulting only senior government officials before making decisions","Announcing policies to the public after they have been finalised"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Stakeholder engagement means bringing citizens, communities, businesses and civil society into policy processes early and genuinely, so their views influence what is decided and how it is carried out. Announcing finished policies (option D) or publicity (option A) is one-way communication, and consulting only officials (option C) leaves out the people affected."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 294, $official_bank_source${"itemId":"6550c6d0-c6dc-5c11-9b90-3f91673bca14","questionId":"97445a51-609b-59dc-9f7b-51022d931f54","sourceKey":"bank:BUA205:PQ-240-d","payload":{"prompt":"Which of the following is a widely accepted principle of effective crisis communication?","options":["Let different agencies release different messages","Say nothing until every fact is fully confirmed","Communicate early, accurately and consistently, and show empathy","Deny the crisis to avoid causing panic"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Effective crisis communication means being first with information, being right, being credible by speaking consistently, and showing empathy for those affected. Waiting for every fact (option B) leaves a gap that rumours fill, mixed messages (option A) destroy credibility, and denial (option D) usually backfires once the truth emerges."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 295, $official_bank_source${"itemId":"88386c82-6efd-56a9-99e3-b0ab10ec1bc4","questionId":"c213c483-6feb-5e4b-9ea3-ce2d8311cca3","sourceKey":"bank:BUA205:PQ-240-e","payload":{"prompt":"A likely consequence of poor stakeholder engagement in public policy implementation is:","options":["Faster and smoother implementation","Higher public trust in government","Stronger public ownership of the policy","Resistance, low compliance and conflict over the policy"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"When people affected by a policy are not consulted, they often feel excluded, misunderstand the policy or see it as unfair, so they resist it, fail to comply or protest. Public ownership, smooth implementation and trust (options C, A and B) are the benefits of good engagement, not consequences of poor engagement."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 296, $official_bank_source${"itemId":"2d30543b-b583-5e26-bc74-bce421134da9","questionId":"e2f6f694-1be9-5991-88e1-f06818a5fb5a","sourceKey":"bank:BUA205:STK-001","payload":{"prompt":"Any group or individual who can affect, or is affected by, the achievement of an organisation's objectives is called a ____.","options":["Shareholder","Stakeholder","Principal","Regulator"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"A stakeholder is anyone who can affect or is affected by what an organisation does, which makes the idea much wider than ownership. Option A is narrower: a shareholder is only an owner who has invested capital. Options C and D describe particular roles that some stakeholders play, not the general term."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 297, $official_bank_source${"itemId":"38862fd7-c9c4-56b3-98ae-8f1d74618c54","questionId":"ae8e15c3-dea6-50b4-969e-5151a42b7ec0","sourceKey":"bank:BUA205:STK-002","payload":{"prompt":"Which statement BEST distinguishes stakeholder theory from the shareholder-primacy view of the firm?","options":["Stakeholder theory says managers should weigh the interests of all affected groups, not only the owners' returns","Stakeholder theory says profits should be ignored completely in favour of social goals","Stakeholder theory says only shareholders and directors have legitimate claims on the firm","Stakeholder theory says government should own every firm that affects the public"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Stakeholder theory holds that a firm owes attention to employees, customers, suppliers, communities and others, not just to shareholders' returns. Option C actually describes shareholder primacy. Option B goes too far, because the theory balances profit with other interests rather than ignoring it, and Option D confuses the theory with state ownership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 298, $official_bank_source${"itemId":"6448e747-e245-5d09-a240-2a8bb55b81a3","questionId":"84d0b96c-8bd7-5f57-a877-6b1e89e5b9af","sourceKey":"bank:BUA205:STK-003","payload":{"prompt":"A manager who argues that 'the main responsibility of a business is to maximise returns to its owners within the law' is expressing the ____.","options":["Stakeholder view","Social contract view","Servant leadership view","Shareholder-primacy view"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Putting owners' returns first, subject only to the law, is the shareholder-primacy position. Option A is the opposite view, which asks managers to balance many groups' interests. Options B and C come from political philosophy and leadership respectively and say nothing specific about whose returns come first."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 299, $official_bank_source${"itemId":"3c217513-e823-51fb-a017-4c691ebfdc5c","questionId":"5dd37112-d11b-528c-8f3e-30d1e669009c","sourceKey":"bank:BUA205:STK-004","payload":{"prompt":"Which of the following statements about shareholders and stakeholders is correct?","options":["Every stakeholder is a shareholder, but not every shareholder is a stakeholder","Shareholders and stakeholders are exactly the same group of people","Shareholders are never counted among a firm's stakeholders","Every shareholder is a stakeholder, but not every stakeholder is a shareholder"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Shareholders are one group of stakeholders, alongside employees, customers, suppliers, regulators and the community. Option A reverses the relationship, Option B ignores all the non-owner groups, and Option C wrongly removes owners from the stakeholder list."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 300, $official_bank_source${"itemId":"8041ef05-db01-5fc8-a23b-b1a307d77526","questionId":"6bd08556-8b7b-5fea-80fc-9441fd08c31d","sourceKey":"bank:BUA205:STK-005","payload":{"prompt":"In the context of corporate governance, the board of directors is BEST described as ____.","options":["the executives who run the company's day-to-day operations","the government bodies that enforce laws on corporate governance","a group elected by shareholders to represent their interests and oversee management","the workforce that carries out the company's operations"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"The board is elected by shareholders to represent them and to oversee management. Option A describes management, Option B describes regulators, and Option D describes employees, each of which is a separate stakeholder group."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 301, $official_bank_source${"itemId":"aaf628a9-1e6d-5d90-aa4b-c13fc39cad46","questionId":"f7bb7b3c-8589-5585-9e18-80d9065484ad","sourceKey":"bank:BUA205:STK-006","payload":{"prompt":"In corporate governance, the government bodies that enforce laws and regulations related to how companies are governed are referred to as ____.","options":["Suppliers and partners","Management","Regulators","Board of directors"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Regulators are the public bodies that enforce governance laws and rules on companies. Option A provides goods, services or other resources, Option B runs daily operations, and Option D oversees management on behalf of shareholders."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 302, $official_bank_source${"itemId":"4de0aeb4-6804-5b1a-b7fe-703a7a94f545","questionId":"c01c25ba-e6ed-517e-805c-4e80b1ec2761","sourceKey":"bank:BUA205:STK-007","payload":{"prompt":"Kwara Cement Ltd buys limestone, bags and diesel from several Nigerian firms under long-term contracts. In stakeholder terms, these firms are the company's ____.","options":["Regulators","Customers","Shareholders","Suppliers and partners"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Firms that provide a company with goods, services or other resources are its suppliers and partners. Option A would be government enforcement bodies, Option B would be buyers of the cement, and Option C would be the owners who invested capital."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 303, $official_bank_source${"itemId":"9b2a9a0b-4f0b-53a3-a154-999f4441babd","questionId":"dbe04dab-d33c-5ac7-a190-3d9afc9df9d9","sourceKey":"bank:BUA205:STK-008","payload":{"prompt":"Primary stakeholders of an organisation are BEST described as those who ____.","options":["have a direct, formal stake in the organisation and are essential to its survival, such as employees, customers and owners","only comment on the organisation from outside, such as the media and pressure groups","have no interest in the organisation but hold great power over it","are always government agencies that license the organisation"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Primary stakeholders have a direct, ongoing relationship with the organisation, and it could not continue without them; employees, customers, owners and suppliers are typical examples. Option B describes secondary stakeholders, who influence the organisation indirectly. Options C and D are not definitions of primary stakeholders at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 304, $official_bank_source${"itemId":"cef1b7d7-b8ec-57d2-a931-dcc345c98df4","questionId":"a0e2cc3b-d867-5847-afb9-032c19478188","sourceKey":"bank:BUA205:STK-009","payload":{"prompt":"An environmental NGO in Port Harcourt campaigns against an oil company's gas flaring but has no contract or ownership link with the company. The NGO is BEST classified as a ____ stakeholder.","options":["primary","secondary","internal","definitive"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Secondary stakeholders influence or are affected by an organisation without a direct transactional or ownership link, and campaign groups and the media are classic examples. Option A would require a direct stake such as employment, ownership or a contract, and Option C would mean being inside the organisation. Option D is a salience label for a group that holds power, legitimacy and urgency together, which the stem does not establish."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 305, $official_bank_source${"itemId":"a8937d38-c929-55b3-86a2-9809b3d9cfc2","questionId":"d5da1d31-06aa-57d1-839e-3d8e2816fc31","sourceKey":"bank:BUA205:STK-010","payload":{"prompt":"Which of the following is an INTERNAL stakeholder of a commercial bank in Lagos?","options":["The bank's employees","The Central Bank of Nigeria","The bank's depositors","The host community"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Internal stakeholders are people within the organisation, such as employees and managers. Option B is an external regulator, Option C is a group of external customers, and Option D is an external community group."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 306, $official_bank_source${"itemId":"8dd70819-953b-570a-a9e7-7fff8316c009","questionId":"b920523f-5886-56ea-ba22-e94bb36c69d7","sourceKey":"bank:BUA205:STK-011","payload":{"prompt":"The process of identifying an organisation's stakeholders and positioning them according to attributes such as power and interest, in order to plan how to engage each group, is known as ____.","options":["Crisis auditing","Benchmarking","Succession planning","Stakeholder mapping"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Stakeholder mapping identifies who the stakeholders are and places them on a chart, such as a power/interest grid, so that engagement can be planned. Option A reviews crisis readiness, Option B compares performance against others, and Option C prepares future leaders."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 307, $official_bank_source${"itemId":"a8218da5-d5af-5eb6-804e-628009275223","questionId":"d0923d71-a158-5656-ace1-4118c463362c","sourceKey":"bank:BUA205:STK-012","payload":{"prompt":"When carrying out a stakeholder analysis for a new policy, which task should normally come FIRST?","options":["Deciding how often to send newsletters to each group","Identifying all the groups that can affect or be affected by the policy","Evaluating how satisfied each group was with the engagement","Choosing a spokesperson for media briefings"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Stakeholders must be identified before they can be analysed, prioritised or engaged. Option A is a later planning task that depends on knowing who the groups are. Option C is an evaluation step at the end, and Option D is a communication detail."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 308, $official_bank_source${"itemId":"2dc5f429-3303-5561-9517-f916c40d139b","questionId":"50bc2542-5064-519e-994d-2047b9db80c9","sourceKey":"bank:BUA205:STK-013","payload":{"prompt":"The two dimensions used in the classic power/interest grid for stakeholder mapping are ____.","options":["power and urgency","power and interest","legitimacy and urgency","age and location"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"The power/interest grid plots how much influence a stakeholder has against how much they care about the issue. Options A and C mix in attributes from the separate salience model, which uses power, legitimacy and urgency. Option D is demographic data, not a mapping dimension."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 309, $official_bank_source${"itemId":"865094d1-2138-5e72-8b26-16f007b3ce15","questionId":"e37c3352-839b-5c06-8023-7c8c4854c458","sourceKey":"bank:BUA205:STK-014","payload":{"prompt":"On a power/interest grid, stakeholders with HIGH power and HIGH interest should generally be ____.","options":["kept satisfied","kept informed","monitored with minimum effort","managed closely (fully engaged as key players)"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Groups that are both powerful and very interested are key players, so they need close, active engagement. Option A is the usual approach for high-power, low-interest groups, Option B suits low-power, high-interest groups, and Option C suits groups low on both."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 310, $official_bank_source${"itemId":"498ceeca-9dc7-58d7-a4b7-fab74215677c","questionId":"0a772a20-08ae-5fd7-ac5a-efb45c901ea1","sourceKey":"bank:BUA205:STK-015","payload":{"prompt":"On a power/interest grid, stakeholders with HIGH power but LOW interest should generally be ____.","options":["managed closely","kept satisfied","kept informed","ignored entirely"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Powerful groups with little interest should be kept satisfied so that they do not become opponents, without overloading them with detail. Option A is for groups with both high power and high interest, and Option C is for interested groups with little power. Option D is wrong because no mapped stakeholder is simply ignored, especially a powerful one."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 311, $official_bank_source${"itemId":"63a7392b-68c8-531b-b2b8-b7ca22c64dc5","questionId":"091788ea-8745-579f-ba45-2c48cb8584f0","sourceKey":"bank:BUA205:STK-016","payload":{"prompt":"On a power/interest grid, stakeholders with LOW power but HIGH interest should generally be ____.","options":["kept satisfied","managed closely","kept informed","monitored with minimum effort"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Groups that care a lot but have little influence should be kept informed through regular, adequate communication, and they can be useful allies. Option A fits powerful but uninterested groups, Option B fits key players, and Option D fits groups low on both power and interest."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 312, $official_bank_source${"itemId":"a283e14f-a7d0-58d6-9d30-bd7acef86693","questionId":"f74ba8f3-5786-5e9d-95a9-e7c6cfb406ff","sourceKey":"bank:BUA205:STK-017","payload":{"prompt":"On a power/interest grid, stakeholders with LOW power and LOW interest should generally be ____.","options":["monitored with minimum effort","managed closely","kept satisfied","kept informed"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Groups low on both power and interest need only light monitoring in case their position changes. Options B, C and D are the strategies for the other three quadrants and would spend too much effort on this group."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 313, $official_bank_source${"itemId":"d0ec354e-778c-55d2-95a1-fb491391c7e9","questionId":"e93cf854-c9a9-503e-9c82-8c7d47af366e","sourceKey":"bank:BUA205:STK-018","payload":{"prompt":"Lagos State plans a new bus rapid transit corridor. The traders' association along the route is very worried about the project but has little influence over the final decision. Using a power/interest grid, the BEST approach to this association is to ____.","options":["keep them satisfied","keep them informed","manage them closely as key players","monitor them with minimum effort"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"High interest with low power places the traders in the 'keep informed' quadrant, so they should get regular, clear information about the project. Option A is for powerful groups with low interest, and Option C is for groups with both high power and high interest. Option D would ignore how much the traders care about the project."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 314, $official_bank_source${"itemId":"711d0e8b-550c-51e0-84ec-a47f54bdcbf7","questionId":"2d85ceec-7219-5686-a5c8-ef429c3ebc9d","sourceKey":"bank:BUA205:STK-019","payload":{"prompt":"A federal ministry must approve funding for a state road project but pays little attention to its details. On a power/interest grid, the project team should treat the ministry as a group to ____.","options":["keep informed","keep satisfied","monitor with minimum effort","exclude from all communication"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"The ministry has high power, since it controls the funds, but low interest, so it falls in the 'keep satisfied' quadrant. Option A is for interested groups with little power. Options C and D risk upsetting a group that could stop the project."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 315, $official_bank_source${"itemId":"49538cdc-e2f4-5864-b768-a2b44440eaba","questionId":"4a2abb6d-ea11-5ab8-98a4-74eb943041ab","sourceKey":"bank:BUA205:STK-020","payload":{"prompt":"A key risk of neglecting a 'keep satisfied' stakeholder (high power, low interest) is that ____.","options":["the stakeholder will automatically lose all its power","the stakeholder may become interested and use its power to block the organisation's plans","the stakeholder will become a low-interest, low-power group","the stakeholder will become a supplier of the organisation"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Powerful stakeholders can quickly become interested if they feel ignored, and they then move into the key-player quadrant with the ability to block decisions. Option A is wrong because neglect does not reduce a group's power. Options C and D do not follow from neglect at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 316, $official_bank_source${"itemId":"2ba2dbfb-4015-5f5f-ad23-f00be538fa07","questionId":"8304d975-8997-5a08-aef6-6d9520e59416","sourceKey":"bank:BUA205:STK-021","payload":{"prompt":"In stakeholder salience analysis, the degree to which a stakeholder's claim calls for immediate attention is called ____.","options":["Legitimacy","Power","Interest","Urgency"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Urgency describes how time-sensitive or pressing a claim is. Option A is whether the claim is seen as proper or appropriate, and Option B is the ability to impose one's will on the organisation. Option C belongs to the separate power/interest grid, not the salience model."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 317, $official_bank_source${"itemId":"7e6c6f33-7ba4-5e0a-a1e5-7c7ce814d65c","questionId":"f75d15cf-2e0a-5c98-b074-7c4f8e5b2961","sourceKey":"bank:BUA205:STK-022","payload":{"prompt":"In stakeholder salience analysis, the general perception that a stakeholder's claim or actions are desirable, proper or appropriate is called ____.","options":["Urgency","Legitimacy","Power","Proximity"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Legitimacy is the attribute of a claim that is socially accepted as proper or appropriate. Option A is about how pressing the claim is, and Option C is about the stakeholder's ability to influence outcomes. Option D is not one of the three salience attributes."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 318, $official_bank_source${"itemId":"a3b73765-35ff-5c37-9aea-be9e86f39b18","questionId":"1271b2a4-5070-5316-a397-a71d6a5a7527","sourceKey":"bank:BUA205:STK-023","payload":{"prompt":"In stakeholder salience analysis, a stakeholder that possesses power, legitimacy AND urgency at the same time is called a ____ stakeholder.","options":["definitive","dormant","dependent","demanding"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Holding all three attributes makes a stakeholder definitive, and managers must give such a group immediate priority. Option B has power only, Option C has legitimacy and urgency but lacks power, and Option D has urgency only."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 319, $official_bank_source${"itemId":"aa281568-e7e7-5ed3-b575-70b4e8f0eff1","questionId":"7cea3584-e954-57e4-8b96-59f1a2c2159a","sourceKey":"bank:BUA205:STK-024","payload":{"prompt":"After a flood, residents of a riverside community in Kogi State have a legitimate and urgent claim for relief, but they have little power to force the state agency to act. In stakeholder salience terms, they are BEST described as ____ stakeholders.","options":["definitive","dependent","dormant","dominant"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"A dependent stakeholder has legitimacy and urgency but lacks power, so it relies on others to advocate for it. Option A would require power as well, Option C has power only, and Option D combines power and legitimacy without urgency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 320, $official_bank_source${"itemId":"84216c25-facb-599f-a4cc-78e7bff2c46c","questionId":"c9cf37e2-2e38-5fdf-b0d7-26fcd9df2fe8","sourceKey":"bank:BUA205:STK-025","payload":{"prompt":"A large trade union has the power to call a strike against a government agency, but at present it has no claim pending and no urgent issue. In stakeholder salience terms, the union is currently a ____ stakeholder.","options":["definitive","dependent","demanding","dormant"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"A dormant stakeholder has power but, for now, neither a legitimate claim nor an urgent one, so it could become important quickly if an issue arises. Option A would need all three attributes. Option B has legitimacy and urgency without power, and Option C has only urgency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 321, $official_bank_source${"itemId":"b69f809f-6691-5625-8b89-e2fc6e5ec378","questionId":"160c30ad-0c67-5d09-9866-ef1736f28d8d","sourceKey":"bank:BUA205:STK-026","payload":{"prompt":"Which pairing of stakeholder theory perspectives is correct?","options":["Instrumental: firms have a moral duty to consider stakeholders; Normative: attending to stakeholders improves profit","Instrumental: describes how firms actually behave; Normative: predicts share prices","Instrumental: attending to stakeholders helps the firm perform better; Normative: firms have a moral duty to consider stakeholders","Instrumental: applies only to government; Normative: applies only to private firms"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"The instrumental view treats stakeholder management as a means to better performance, while the normative view says stakeholders deserve consideration for moral reasons. Option A swaps the two. Option B confuses the instrumental view with the descriptive one, and Option D invents a public/private split."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 322, $official_bank_source${"itemId":"53e40870-f20c-52fc-a6e6-3431827ed809","questionId":"bfc5029b-e44e-56cb-96d5-c98206ee353a","sourceKey":"bank:BUA205:STK-027","payload":{"prompt":"The use of stakeholder theory simply to explain how organisations actually behave towards their stakeholders, without judging whether that behaviour is right, is called the ____ perspective.","options":["descriptive","normative","instrumental","transactional"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"The descriptive perspective reports what organisations really do in dealing with stakeholders. Option B prescribes what they ought to do on moral grounds, and Option C links stakeholder management to performance. Option D is a leadership style, not a stakeholder perspective."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 323, $official_bank_source${"itemId":"953c3369-fdcd-5db2-8dab-15d1ed666ada","questionId":"cb460224-37fe-5504-92d7-c626d78b1bff","sourceKey":"bank:BUA205:STK-029","payload":{"prompt":"On a spectrum of public participation running from least to most public influence, which level is the LOWEST?","options":["Inform","Consult","Collaborate","Empower"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Informing is one-way communication that gives people balanced information but no say in the decision, so it sits at the bottom of the spectrum. Option B at least collects feedback. Options C and D give the public progressively more influence, and empowering places the final decision in public hands."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 324, $official_bank_source${"itemId":"544cb8a2-31d2-5beb-9884-13985b83ccf8","questionId":"72f9e4e3-75fe-547e-a03b-b9ab1d772ff8","sourceKey":"bank:BUA205:STK-030","payload":{"prompt":"On a spectrum of public participation, the level at which final decision-making is placed in the hands of the public is called ____.","options":["Inform","Empower","Consult","Involve"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Empowering is the highest level of participation because the public itself makes the final decision, as in a binding referendum or citizen budget vote. Option A only shares information, Option C seeks feedback, and Option D works with the public throughout while the authority still decides."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 325, $official_bank_source${"itemId":"82bdeda6-d0f4-5207-b1c8-da4e84822a63","questionId":"4ef5db46-5416-59f5-93e5-2e526d842699","sourceKey":"bank:BUA205:STK-031","payload":{"prompt":"A local government council in Ogun State publishes its draft budget and holds town-hall meetings to collect residents' comments before councillors finalise it. This level of participation is BEST described as ____.","options":["Inform","Empower","Consult","Delegate authority to residents"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Consulting means obtaining public feedback on proposals while the authority keeps the final decision, which is what the council is doing. Option A would only publish the budget without seeking views. Options B and D would hand the final decision to residents, which the stem does not describe."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 326, $official_bank_source${"itemId":"e6632251-9eeb-5ba7-bdf5-810fd8f16769","questionId":"66ced384-488d-539b-9216-c2fcd719997e","sourceKey":"bank:BUA205:STK-032","payload":{"prompt":"Which of the following is NOT a realistic benefit of effective stakeholder engagement in public governance?","options":["It increases the legitimacy of decisions","It improves the quality of information used in decisions","It builds public ownership of policies and reduces conflict","It guarantees that every stakeholder gets exactly what it wants"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Engagement helps balance interests, but no process can give every group exactly what it wants, because interests often conflict. Options A, B and C are genuine benefits: engaged groups see decisions as more legitimate, add local knowledge, and are more likely to support the policies that result."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 327, $official_bank_source${"itemId":"77e9918e-b9e2-55f5-a79d-8f08a7a7c9c0","questionId":"0354bf46-ec8f-59ff-9c2e-c9e2363d68f3","sourceKey":"bank:BUA205:STK-033","payload":{"prompt":"Before relocating a motor park in Ibadan, the state government holds sessions only with transport union leaders, leaving out traders, commuters and persons with disabilities. Which principle of good stakeholder engagement is MOST clearly breached?","options":["Inclusiveness","Urgency","Confidentiality","Hierarchy"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Inclusive engagement reaches all affected groups, especially vulnerable ones, rather than only the loudest or most organised. Option B is a salience attribute, not an engagement principle. Options C and D would make the process even narrower."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 328, $official_bank_source${"itemId":"0c6e611b-b21e-596b-a1f7-ba28d40028ba","questionId":"f0cbe61b-a721-5c05-9e1e-6a5b5ed3c98d","sourceKey":"bank:BUA205:STK-034","payload":{"prompt":"Corporate governance, in its simplest sense, refers to ____.","options":["the rules, practices and processes by which a company is directed and controlled","the day-to-day selling and marketing activities of a company","the process of setting the prices of a company's products","the government's power to tax company profits"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Corporate governance is the system of rules, practices and processes through which a company is directed and controlled, balancing the interests of its many stakeholders. Option B describes operations, not governance. Option C is a pricing decision, and Option D is fiscal policy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 329, $official_bank_source${"itemId":"3b438339-7b32-5f0d-a28e-46d7ac6f4bf7","questionId":"0a2ef2f9-1d97-57da-93e4-b1e01e449235","sourceKey":"bank:BUA205:STK-035","payload":{"prompt":"An unexpected event that threatens an organisation's operations, reputation or stakeholders, and forces decisions under time pressure and uncertainty, is called a ____.","options":["Crisis","Routine incident","Strategic plan","Budget variance"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"A crisis combines threat, surprise, uncertainty and time pressure. Option B is handled by normal procedures without serious threat. Option C is a planned document, and Option D is an ordinary accounting difference."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 330, $official_bank_source${"itemId":"0a71f8dc-d071-530b-b153-1906c534469d","questionId":"d371f403-1e3d-5e21-b259-1ad804cd752a","sourceKey":"bank:BUA205:STK-036","payload":{"prompt":"Which of the following is NOT a typical characteristic of a crisis?","options":["It poses a serious threat","It creates uncertainty","It is routine and fully predictable","It leaves little time for decisions"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Crises are marked by serious threat, uncertainty and urgency, which is why ordinary routines are not enough. A routine, fully predictable event is handled by normal procedures, so it is not a crisis. Options A, B and D are all standard features of a crisis."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 331, $official_bank_source${"itemId":"763954ab-623e-5ee0-9eee-2912e88a2db1","questionId":"c316f2d3-8ae6-51a5-9656-d808b0ef0643","sourceKey":"bank:BUA205:STK-037","payload":{"prompt":"Which of the following activities belongs to the PRE-CRISIS stage of crisis management?","options":["Preparing a crisis communication plan and training spokespersons","Issuing a holding statement after an explosion","Reviewing lessons learned after the crisis has ended","Rebuilding the organisation's reputation after a scandal"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"The pre-crisis stage covers prevention and preparation, such as scanning for warning signs, writing plans and training spokespersons. Option B is a response activity during the crisis. Options C and D belong to the post-crisis stage of recovery and learning."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 332, $official_bank_source${"itemId":"ca4bbd48-588e-5a27-967e-7bf12ed9b241","questionId":"18c2a206-f88c-5d4d-856a-39fdad66adb4","sourceKey":"bank:BUA205:STK-038","payload":{"prompt":"Which of the following activities belongs to the POST-CRISIS stage of crisis management?","options":["Scanning the environment for early warning signs","Drafting pre-approved message templates","Evaluating how the crisis was handled and updating the crisis plan","Announcing the first facts of an incident to the media"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"After the crisis, the organisation evaluates its response, learns lessons, continues follow-up communication and updates its plan. Options A and B are preparation activities in the pre-crisis stage. Option D happens during the crisis response itself."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 333, $official_bank_source${"itemId":"7fca0b95-4438-571c-a8a4-7c64b6d88b65","questionId":"f6eeeed9-b5e5-5fd7-9c64-8accf000fddf","sourceKey":"bank:BUA205:STK-039","payload":{"prompt":"The collection, processing and sharing of information needed to deal with a crisis situation, with affected stakeholders and the public, is known as ____.","options":["Crisis communication","Issue advertising","Public relations budgeting","Stakeholder salience"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Crisis communication is the gathering and sharing of information during a crisis, both inside the organisation and with external stakeholders. Option B is paid messaging on policy issues. Option C is a financial planning task, and Option D is about how important stakeholders are."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 334, $official_bank_source${"itemId":"24effe32-c413-57d3-a2ea-cae1c033bcc2","questionId":"4bef10dc-2ada-505b-b467-fbb2141e1806","sourceKey":"bank:BUA205:STK-040","payload":{"prompt":"A short statement released very quickly after a crisis breaks, which acknowledges the incident, expresses concern and promises further updates before all facts are known, is called a ____.","options":["Press embargo","Annual report","Gag order","Holding statement"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"A holding statement lets the organisation speak first and show concern while it gathers the facts. Option A delays publication of information, and Option B is a yearly performance document. Option C stops people from speaking, which is the opposite of early communication."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 335, $official_bank_source${"itemId":"ae59769c-941b-517e-bd04-e0ffb4c10b3b","questionId":"940e1028-c7ec-59e5-afb7-49cd0894c830","sourceKey":"bank:BUA205:STK-041","payload":{"prompt":"Which of the following is NOT generally regarded as good practice in crisis communication?","options":["Communicating early, even if only to say what is known so far","Making sure information released is accurate","Showing empathy for those affected","Responding to media questions with 'no comment' until the crisis is over"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Saying 'no comment' is usually read as hiding something, and it leaves a gap that rumour and speculation fill. Options A, B and C reflect widely accepted principles: be first, be right, be credible and show empathy."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 336, $official_bank_source${"itemId":"0da02195-55c0-5cd8-add5-428f8a9cc170","questionId":"96ba9193-34d1-5f5a-91b8-6091bfa03883","sourceKey":"bank:BUA205:STK-042","payload":{"prompt":"During a cholera outbreak in Bauchi, three state officials give journalists three different death tolls on the same day. Which crisis communication practice would MOST directly have prevented this?","options":["Releasing no figures at all until the outbreak ends","Using a single designated spokesperson and coordinated, verified messages","Allowing every official to brief the press independently","Communicating only through rumour on social media"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"A designated spokesperson working from verified, coordinated figures keeps messages consistent and credible. Option A creates an information vacuum that rumours fill, and Option C is what caused the confusion in the first place. Option D would make the misinformation worse."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 337, $official_bank_source${"itemId":"50282f02-cca1-563d-9ac8-715f889f0244","questionId":"3595ed09-4eec-552a-9497-3eb4bbedc0dd","sourceKey":"bank:BUA205:STK-043","payload":{"prompt":"A Lagos food company discovers that one batch of its yoghurt is contaminated. Which response BEST reflects sound crisis communication?","options":["Quietly withdraw the batch and say nothing to avoid bad publicity","Deny any problem until a customer falls sick","Promptly recall the batch and tell the public honestly what is known, what is being done and how to get refunds","Blame the retailers who stocked the product"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Fast, honest communication combined with corrective action protects consumers and preserves trust. Options A and B hide a safety risk, which is unethical and usually backfires when the truth comes out. Option D shifts blame instead of solving the problem."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 338, $official_bank_source${"itemId":"c11d32fb-e392-5c1b-9fd5-cf4f25fb4b4d","questionId":"94eaa1e7-4c82-55d6-907a-b27d2dc0fc66","sourceKey":"bank:BUA205:STK-044","payload":{"prompt":"During a crisis, a company publicly blames an outside party, such as a supplier, entirely for the problem. This crisis response strategy is called ____.","options":["Apology","Scapegoating","Corrective action","Bolstering"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Scapegoating is a denial-type strategy that puts the blame on some person or group outside the organisation. Option A accepts responsibility, and Option C fixes the problem and prevents it from happening again. Option D reminds stakeholders of the organisation's past good deeds."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 339, $official_bank_source${"itemId":"fd35c4dd-f6e5-5261-9983-d69e870a8082","questionId":"c911515b-5fd9-590a-a39b-ab9cef466de4","sourceKey":"bank:BUA205:STK-045","payload":{"prompt":"When an organisation is clearly at fault for a preventable crisis, which response is MOST likely to protect long-term trust?","options":["Denying that the crisis happened","Attacking those who reported the problem","Staying silent until public attention fades","Accepting responsibility, apologising and taking corrective action"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"When responsibility is clear, rebuilding strategies such as an apology, compensation and corrective action are the most credible way to restore trust. Options A and B are denial strategies that badly damage credibility once the facts are known. Option C leaves an information vacuum."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 340, $official_bank_source${"itemId":"fd892224-1637-5acf-9fb8-388eb5764be9","questionId":"a5650422-1574-5e28-a3ae-c683087501df","sourceKey":"bank:BUA205:STK-046","payload":{"prompt":"Why should an organisation inform its own employees early during a crisis?","options":["Employees are legally the only group that must be told","Employees have no role in how outsiders see the crisis","Employees act as informal spokespersons, and learning the facts first from the media damages morale and spreads confusion","Informing employees removes the need to inform the public"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Employees are a key internal stakeholder group. They talk to customers, family and the media, so they need accurate information early. Option A is false, and Option B ignores their influence. Option D is wrong because the public still has to be informed."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 341, $official_bank_source${"itemId":"12f24d57-fc8f-5a06-a5d4-c3fbe5918a7e","questionId":"e8310d57-e45c-50ba-b46b-2507bcf09d02","sourceKey":"bank:BUA205:STK-047","payload":{"prompt":"During a fuel scarcity, false messages claiming that all filling stations in Abuja will shut for a week spread rapidly on WhatsApp. The MOST appropriate action for the responsible agency is to ____.","options":["ignore social media because only newspapers matter","wait until the scarcity ends before saying anything","monitor social media and quickly correct the false claims with verified information through official channels","shut down all social media in the city"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Social media spreads rumours fast, so monitoring them and quickly correcting falsehoods with verified facts is central to modern crisis communication. Options A and B let the rumour grow. Option D is a heavy-handed restriction that harms public trust."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 342, $official_bank_source${"itemId":"3e6d57bb-8713-5a39-ab55-8d73e3b4afc8","questionId":"408e72cc-91ef-5c31-b3bb-37767d2fbc4c","sourceKey":"bank:BUA205:STK-048","payload":{"prompt":"Which of the following would NOT normally be part of a crisis management plan?","options":["A list of crisis team members and their roles","Up-to-date contact details for key stakeholders and media","A promise that the organisation will never face a crisis","Pre-approved message templates and procedures"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"A crisis plan prepares for crises that may happen; it cannot promise that none will occur. Options A, B and D are standard contents of a crisis plan: who does what, whom to contact, and ready-made messages and procedures."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 343, $official_bank_source${"itemId":"15055ca2-f548-54f4-b1f1-0d8ec8ea197b","questionId":"bb91d64a-8ab3-58b7-9687-256c64bbe318","sourceKey":"bank:BUA205:STK-049","payload":{"prompt":"A government agency sets up a toll-free hotline during a disease outbreak so that citizens can ask questions and report cases. This mainly reflects the crisis communication principle of ____.","options":["one-way propaganda","information secrecy","two-way communication with stakeholders","centralisation of power"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"A hotline lets the agency both give information and receive it from the public, which improves its response and builds trust. Option A describes communication that never listens. Options B and D work against openness."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 344, $official_bank_source${"itemId":"7e409d75-d6bb-5203-8e77-20dc1c70eafb","questionId":"335e9263-e476-5b63-85c3-ecc520c58c15","sourceKey":"bank:BUA205:STK-050","payload":{"prompt":"Which group would MOST appropriately be included on a public organisation's crisis management team?","options":["Only junior staff from the public relations unit","Only external journalists","Only the organisation's customers","Senior decision-makers, a communications lead, legal advice and the heads of the affected operations"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"A crisis team needs people with authority, communication skills, legal knowledge and operational expertise so it can decide and act quickly. Option A lacks authority, and Options B and C are external stakeholders the team communicates with, not the people who manage the crisis."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 345, $official_bank_source${"itemId":"4ca63869-58a3-5dbf-806c-d33daae6ffcf","questionId":"88c1a392-b190-50b2-8371-28697920b9e1","sourceKey":"bank:BUA205:NB-039","payload":{"prompt":"The process by which public institutions manage resources, implement policies and deliver services to citizens is called:","options":["Corporate governance","Public governance","Crisis management","Stakeholder analysis"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Public governance is the process by which public institutions manage resources, implement policies and deliver services to citizens. Option A concerns how business organisations are directed and controlled, Option D is one step in engaging stakeholders, and Option C deals with sudden threatening events."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 346, $official_bank_source${"itemId":"1464b80c-90ae-5762-adc1-4cd8864dd636","questionId":"c90b10fc-d0ac-5bcd-a43f-e644383dd277","sourceKey":"bank:BUA205:NB-040","payload":{"prompt":"Effective public governance depends mainly on:","options":["Secrecy in government decisions","The number of ministries a government creates","Stakeholder participation","The personal wealth of political leaders"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Effective public governance depends on stakeholder participation, because those who are affected by policies help shape, accept and monitor them. Option A undermines transparency, while Options D and B have no direct bearing on how well public institutions serve citizens."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 347, $official_bank_source${"itemId":"467b46a7-f429-5a45-b94a-5df47144c944","questionId":"964a344f-852d-56f5-a4bd-428c89ceb8d7","sourceKey":"bank:BUA205:NB-041","payload":{"prompt":"Traditional rulers, labour unions, the press, religious bodies and student unions are all examples of:","options":["Organs of the executive arm of government","Shareholders of public enterprises","The three arms of government","Stakeholders in public governance"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Each of these groups can affect or is affected by government decisions, so they are stakeholders in public governance, alongside citizens, NGOs, pressure groups, community leaders and civil servants. Option C refers to the legislature, executive and judiciary, Option A refers to ministries and agencies, and Option B refers to owners of company shares, none of which describes these groups."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 348, $official_bank_source${"itemId":"1f53eee1-c1b6-5d96-a412-635c6861bff8","questionId":"fa928db5-1153-59a7-aa6f-eda9402f5718","sourceKey":"bank:BUA205:NB-042","payload":{"prompt":"Residents of a community in Ogun State will live beside a new government landfill, bear its smell and health risks, and are demanding explanations from officials. In public governance terms, these residents are best described as:","options":["Stakeholders","Civil servants","Regulators","Shareholders"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"In public governance, stakeholders are those who gain from a public policy or bear its consequences and demand accountability, which fits the residents exactly. Option C enforces rules, Option D owns shares in companies, and Option B refers to government employees, none of which describes the community."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 349, $official_bank_source${"itemId":"337f8e89-b7d2-52b1-b192-3e9790b64090","questionId":"8387ef1b-027d-559b-9cef-c43daa6488fe","sourceKey":"bank:BUA205:NB-043","payload":{"prompt":"Stakeholder theory was popularised by:","options":["R. Edward Freeman","Thomas Hobbes","Robert Kelley","Max Weber"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"R. Edward Freeman popularised stakeholder theory in 1984, arguing that organisations must manage the interests of everyone who affects or is affected by them. Option D is linked with work on authority and bureaucracy, Option C with the followership model, and Option B with social contract theory."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 350, $official_bank_source${"itemId":"797e0dc3-8401-5163-b900-8f2ce1f64102","questionId":"37aeba7c-c9cc-5f3a-9f48-3cf6e498a46e","sourceKey":"bank:BUA205:NB-044","payload":{"prompt":"In which year did R. Edward Freeman popularise stakeholder theory?","options":["1984","1992","1997","1947"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Freeman popularised stakeholder theory in 1984. Option D is the year linked with Max Weber's work on authority and bureaucracy, Option B with Robert Kelley's followership model, and Option C with the stakeholder salience model of Mitchell, Agle and Wood."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 351, $official_bank_source${"itemId":"b9eed322-d6ed-5e29-9362-e47801add00f","questionId":"140c6956-3ec9-5735-a4aa-68935d5bde7d","sourceKey":"bank:BUA205:NB-045","payload":{"prompt":"According to stakeholder theory, an organisation's long-term success depends on its ability to:","options":["Concentrate every decision in the hands of top management","Identify, understand and manage the interests of multiple stakeholders","Avoid all contact with groups outside the organisation","Maximise returns to shareholders above all other interests"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Stakeholder theory holds that long-term success depends on identifying, understanding and managing the interests of the many groups that affect or are affected by the organisation. Option D is the shareholder-primacy view the theory rejects, and Options C and A shut stakeholders out instead of responding to them."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 352, $official_bank_source${"itemId":"da9a4c0b-5b7f-5550-b372-714ac0b9b6cd","questionId":"658b10ad-f2d3-5019-8c70-b74ccb88c0bb","sourceKey":"bank:BUA205:NB-046","payload":{"prompt":"Which of the following is a key governance implication of stakeholder theory?","options":["Policy information is kept confidential from citizens","Decisions are made by leaders alone without consultation","Profit for shareholders becomes the only goal","The public interest becomes a central priority"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Because stakeholder theory requires governments and organisations to serve everyone their decisions affect, the public interest becomes a central priority, alongside inclusiveness, ethical responsibility, accountability and transparency, and sustainable development. Option C is the narrow shareholder view, and Options B and A go against inclusiveness and transparency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 353, $official_bank_source${"itemId":"886197b0-3d7d-5c79-85fb-3d746e9eaa09","questionId":"f74820b6-4dbb-5c49-ae19-fa91ebd00ec0","sourceKey":"bank:BUA205:NB-047","payload":{"prompt":"Which of the following is NOT a governance implication of stakeholder theory?","options":["Sustainable development and implementation of policy","Ethical responsibility to society","Inclusiveness in decision-making","Concentrating decision-making in a small elite"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Stakeholder theory implies that the public interest is central and that decision-making should be inclusive, ethical, accountable and transparent, and aimed at sustainable development, so concentrating decisions in a small elite contradicts it. Options C, B and A are all genuine implications of the theory for governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 354, $official_bank_source${"itemId":"7c8524c8-8ba9-501e-84e6-0c6ad971949b","questionId":"526924ae-68fc-54a1-8381-aba86a90bfbe","sourceKey":"bank:BUA205:NB-048","payload":{"prompt":"Which statement best describes the relationship between stakeholder theory and stakeholder engagement?","options":["Stakeholder theory explains why stakeholders matter, while stakeholder engagement is how they are actually involved","Both terms mean exactly the same thing","Stakeholder engagement explains why stakeholders matter, while stakeholder theory is how they are involved","Stakeholder theory replaces the need for any stakeholder engagement"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Stakeholder theory supplies the 'why': organisations and governments should respond to all who affect or are affected by them. Stakeholder engagement is the 'how': identifying stakeholders, communicating with them and involving them in decisions. Option C reverses the two, Option B ignores the difference, and Option D is wrong because the theory is put into practice through engagement."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 355, $official_bank_source${"itemId":"eee6bccd-da8a-58dc-bcf5-a0213d6718f8","questionId":"1ebfe8c5-5ea4-50e7-af3b-967c33124026","sourceKey":"bank:BUA205:NB-049","payload":{"prompt":"Which of the following is a benefit of stakeholder engagement in governance?","options":["It reduces conflicts and resistance","It makes decisions faster by skipping consultation","It transfers accountability from government to citizens","It removes the need to communicate with citizens"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Engaging stakeholders reduces conflicts and resistance, and it also enhances policy acceptance, promotes transparency and accountability, improves service delivery, and strengthens trust and legitimacy. Options D and B contradict what engagement involves, and Option C is wrong because engagement makes government more accountable, not less."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 356, $official_bank_source${"itemId":"262fe630-1dc6-564a-b5e9-d83576ad4534","questionId":"01f4c8d5-01df-5a00-a524-cc9e0629546c","sourceKey":"bank:BUA205:NB-050","payload":{"prompt":"At a town-hall meeting, residents of a Lagos local government ask the chairman to explain exactly how last year's N200 million road budget was spent, and he presents the records. Which benefit of stakeholder engagement does this mainly illustrate?","options":["Promoting transparency and accountability","Reducing conflicts and resistance","Removing the need for audits","Improving service delivery"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"Engagement promotes transparency and accountability because it creates chances for stakeholders to demand explanations from officials, which is exactly what the residents did. Options D and B are also benefits of engagement, but the case is about officials answering for spending, not about better services or fewer disputes, and Option C is not a benefit at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 357, $official_bank_source${"itemId":"c900e773-e9f1-5f45-893c-5c2c02d7fde3","questionId":"f9440f6c-020b-5870-ae61-97700b05c391","sourceKey":"bank:BUA205:NB-051","payload":{"prompt":"Which option gives the steps of the stakeholder engagement process in the correct order?","options":["Engagement planning, identification, analysis, implementation and communication, monitoring and evaluation","Identification, engagement planning, analysis, monitoring and evaluation, implementation and communication","Analysis, identification, implementation and communication, engagement planning, monitoring and evaluation","Identification, analysis, engagement planning, implementation and communication, monitoring and evaluation"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Stakeholders must first be identified and then analysed, after which the method of engagement is planned, the plan is implemented and communicated, and the results are monitored and evaluated. Option C analyses before knowing who the stakeholders are, Option B plans before analysis and evaluates before implementing, and Option A plans before identifying anyone."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 358, $official_bank_source${"itemId":"15411d60-f2c6-5c00-8c11-d498acb63004","questionId":"c08e2243-5e19-54b9-805e-25eb15c83631","sourceKey":"bank:BUA205:NB-052","payload":{"prompt":"In the stakeholder engagement process, which step comes immediately after stakeholder analysis?","options":["Monitoring and evaluation","Implementation and communication","Stakeholder identification","Engagement planning"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Once stakeholders have been analysed, the next step is engagement planning, where the method of engaging each group is chosen. Option C comes before analysis, while Options B and A come after planning as the fourth and fifth steps."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 359, $official_bank_source${"itemId":"c85ab494-2b2e-5f22-b67f-0fd17bcee54c","questionId":"e968f665-4d6e-59cd-af5c-35991ca5d1d4","sourceKey":"bank:BUA205:NB-053","payload":{"prompt":"The final step in the stakeholder engagement process is:","options":["Stakeholder analysis","Implementation and communication","Monitoring and evaluation","Engagement planning"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"The process ends with monitoring and evaluation, which checks whether engagement achieved its aims and what should be improved. Option B is the fourth step, Option D is the third, and Option A is the second."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 360, $official_bank_source${"itemId":"f68bdc0f-8d8a-5a19-b8f0-c462d9afea7c","questionId":"c7225d53-6478-5829-a661-8869d0e6e2a4","sourceKey":"bank:BUA205:NB-054","payload":{"prompt":"Having worked out who its stakeholders are and what each group wants, a Kaduna State project team now decides whether to reach them through town-hall meetings, Hausa radio jingles or online surveys. Which step of stakeholder engagement is the team at?","options":["Stakeholder identification","Stakeholder analysis","Monitoring and evaluation","Engagement planning"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Choosing the method of engagement for each group is the engagement planning step, which follows identification and analysis. The team has already completed Options A and B, and Option C comes only after the engagement has been carried out."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 361, $official_bank_source${"itemId":"eaf2809f-67b5-58e2-8ca0-60d0a0302209","questionId":"30b8e96a-1ac9-536a-9971-80e343d1412c","sourceKey":"bank:BUA205:NB-055","payload":{"prompt":"A federal agency has listed all the groups affected by a new toll policy. It now studies each group's interests, influence and likely concerns about the policy. Which step of stakeholder engagement is this?","options":["Stakeholder identification","Stakeholder analysis","Engagement planning","Implementation and communication"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Studying the interests, influence and concerns of groups already identified is stakeholder analysis, the second step. Option A was completed when the groups were listed, while Options C and D come later, once the agency decides how to engage the groups and then carries that out."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 362, $official_bank_source${"itemId":"12649cef-0ae4-5aaa-a828-a95cb6140c16","questionId":"40964115-a8c9-5edf-833f-238d3c566d55","sourceKey":"bank:BUA205:NB-056","payload":{"prompt":"Which of the following is NOT a challenge of stakeholder engagement?","options":["High literacy levels and strong communication systems","Resistance to change","Political interference","Poor communication systems"],"correctOption":0,"section":"Stakeholder and Public Governance","explanation":"The challenges of stakeholder engagement are political interference, resistance to change, poor communication systems and low literacy levels, so high literacy and strong communication systems would help engagement rather than hinder it. Options C, B and D are all real challenges."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 363, $official_bank_source${"itemId":"d90cafec-a35c-505a-a455-01589a9ab596","questionId":"0c0cc030-c32f-5754-97f2-aea1db122cc5","sourceKey":"bank:BUA205:NB-057","payload":{"prompt":"A state ministry pastes printed notices about a new farm-input scheme in a rural community where most farmers cannot read them, so very few respond. Which challenge of stakeholder engagement is this?","options":["Poor communication systems","Resistance to change","Low literacy level","Political interference"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"The farmers cannot read the notices, so the message fails because of a low literacy level among the stakeholders. Option D would involve politicians distorting the process and Option B would involve people opposing the change itself. Option A would mean the channels were broken, but here the notices were delivered and simply could not be read."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 364, $official_bank_source${"itemId":"ea4fde39-437c-5e8f-85dd-699971f68f9c","questionId":"8a21ab1c-228c-5eeb-8f9f-93554d585e1a","sourceKey":"bank:BUA205:NB-058","payload":{"prompt":"A local politician pressures council officials to invite only his supporters to consultations on a new market, and to ignore other traders. Which challenge of stakeholder engagement is this?","options":["Poor communication systems","Political interference","Low literacy level","Resistance to change"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"A politician bending the consultation to suit partisan interests is political interference, a key challenge of stakeholder engagement. Nothing suggests stakeholders cannot read (Option C), oppose the market itself (Option D) or lack working communication channels (Option A)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 365, $official_bank_source${"itemId":"4d27d3de-c385-5a70-aa58-44c2e7d0567f","questionId":"f68c65fa-dc33-5972-990d-4f0fb1aee58a","sourceKey":"bank:BUA205:NB-059","payload":{"prompt":"Public panic, violent protests, destruction of property and loss of lives are typical marks of:","options":["Consensus-oriented governance","A crisis","Stakeholder analysis","Routine policy implementation"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"A crisis is a sudden, unexpected event that threatens the sustainability of a decision, and it is typically marked by public panic, violent protests, property damage and loss of lives. Options C and D are normal, planned activities, and Option A is a characteristic of good governance, not a threatening event."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 366, $official_bank_source${"itemId":"4897163b-aa0a-5cc9-b996-bc058fc11a90","questionId":"5f4bd138-5614-5fbf-864d-d174ede2d8d8","sourceKey":"bank:BUA205:NB-060","payload":{"prompt":"Which option arranges the steps of crisis management in the correct order?","options":["Quick response and communication, getting prepared for crisis, recovery strategy","Getting prepared for crisis, quick response and communication, recovery strategy","Getting prepared for crisis, recovery strategy, quick response and communication","Recovery strategy, getting prepared for crisis, quick response and communication"],"correctOption":1,"section":"Stakeholder and Public Governance","explanation":"Crisis management begins with getting prepared before a crisis strikes, then calls for a quick response and communication when it happens, and ends with a recovery strategy to restore normal life. Option A waits until the crisis to prepare, Option D starts with recovery, and Option C attempts recovery before responding."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 367, $official_bank_source${"itemId":"64dc77c3-d163-5252-a7b3-2a1cfdb2ff53","questionId":"2bca1182-484b-511b-9def-e34f3c71e390","sourceKey":"bank:BUA205:NB-061","payload":{"prompt":"Within an hour of a fuel tanker explosion at a busy Onitsha market, the state government issues a public statement, opens a hotline and sends fire and medical teams to the scene. Which step of crisis management is this?","options":["Getting prepared for crisis","Recovery strategy","Stakeholder identification","Quick response and communication"],"correctOption":3,"section":"Stakeholder and Public Governance","explanation":"Acting and informing the public immediately after a crisis breaks is the quick response and communication step. Option A happens before the crisis, Option B comes later when the damage is repaired and life is restored, and Option C is a step in stakeholder engagement rather than crisis management."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 368, $official_bank_source${"itemId":"f4caebda-5937-5d19-a080-d6aca38fb610","questionId":"e80a9686-37a4-5f67-aba6-a5bba5ee0ff8","sourceKey":"bank:BUA205:NB-062","payload":{"prompt":"Months after a fire destroyed part of a market in Ibadan, the state government rebuilds the stalls, gives affected traders soft loans and helps them reopen their businesses. Which step of crisis management is this?","options":["Getting prepared for crisis","Engagement planning","Recovery strategy","Quick response and communication"],"correctOption":2,"section":"Stakeholder and Public Governance","explanation":"Rebuilding and helping victims return to normal life after the emergency has passed is the recovery strategy, the last step of crisis management. Option A happens before any crisis, Option D happens in the first hours of the crisis, and Option B belongs to the stakeholder engagement process."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 369, $official_bank_source${"itemId":"f8ab1e11-4c75-5790-9da8-f77390e7cc66","questionId":"72eed491-11b7-5aa8-884b-829fb66ee55e","sourceKey":"bank:BUA205:PQ-149","payload":{"prompt":"Within public institutions, governance establishes procedures to resolve __________________","options":["Administrative conflicts","Social rivalry","Private disputes","Market competition"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Governance in public institutions sets out procedures such as grievance and review processes to resolve administrative conflicts. Options C and D are private and market matters, and B is a general social issue rather than something governance procedures in public institutions address."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 370, $official_bank_source${"itemId":"1509136f-606c-5c0d-b5d8-ce1fa0b7cd62","questionId":"d8518637-9c15-57f3-8889-311ef4eb8422","sourceKey":"bank:BUA205:PQ-169","payload":{"prompt":"Public sector governance builds public trust by ensuring:","options":["Expansion of authority","Predictability and fairness","Personalised treatment","Unchecked discretion"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Citizens trust public institutions when rules are applied consistently and everyone is treated equally, so people can predict how decisions will be made. Unchecked discretion (option D) and personalised treatment (option C) open the door to bias and favouritism, while expanding authority without checks (option A) tends to reduce trust rather than build it."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 371, $official_bank_source${"itemId":"2a286d86-f07e-52df-91c8-c926a600a038","questionId":"59f4b39a-06fd-553c-8799-fc201668a508","sourceKey":"bank:BUA205:PQ-214","payload":{"prompt":"Public governance can be distinguished from governance in the private sector primarily by its emphasis on:","options":["Competitive market dynamics and shareholder value","Public interest, equity, accountability and democratic participation","Cost reduction and operational efficiency above all else","Innovation and entrepreneurship in service delivery"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Public governance exists to serve citizens as a whole, so it stresses the public interest, fairness, accountability to the people and their participation in decisions. Shareholder value and market competition (option A) are private sector priorities, and innovation and efficiency (options D and C) matter in both sectors but are not what sets public governance apart."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 372, $official_bank_source${"itemId":"5ba723a9-9f65-5380-a9c3-f31e0d4c84e8","questionId":"88f1a014-10a3-5807-a2be-ebce0cdd0255","sourceKey":"bank:BUA205:PQ-215","payload":{"prompt":"Which of the following is NOT a generally accepted principle of good governance?","options":["Transparency","Nepotism","Rule of law","Accountability"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Nepotism means favouring relatives or friends in jobs, promotions or contracts instead of using merit, and it is treated as an ethical abuse that undermines good governance. Transparency, accountability and the rule of law (options A, D and C) are all core characteristics of good governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 373, $official_bank_source${"itemId":"5b26ff4e-6c95-5ba8-b067-979f91a0fde2","questionId":"9cf8e9d1-96b8-51ba-9815-ebbcd233e3bb","sourceKey":"bank:BUA205:PQ-216","payload":{"prompt":"Good governance is commonly described as having eight major characteristics. Which of the following is one of them?","options":["Responsiveness to the needs of stakeholders","Exclusion of minority groups from decision-making","Restriction of civil liberties for national security","Centralisation of power"],"correctOption":0,"section":"Governance in the Public Services","explanation":"The eight characteristics are participation, rule of law, transparency, responsiveness, consensus orientation, equity and inclusiveness, effectiveness and efficiency, and accountability. Responsiveness means institutions try to serve all stakeholders within a reasonable time. Options D, C and B contradict participation, rule of law and inclusiveness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 374, $official_bank_source${"itemId":"1347acd9-b902-5bf9-814b-6fcda3738935","questionId":"a34cc4d5-e99c-5ed6-9b25-7aa521c8047d","sourceKey":"bank:BUA205:PQ-217","payload":{"prompt":"A major hindrance to good governance in African public services is:","options":["Decentralisation of government functions to local authorities","Systemic corruption, weak institutions and lack of accountability mechanisms","A well-funded independent judiciary","A free and independent press"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Corruption diverts public funds, weak institutions cannot enforce rules or deliver services, and without accountability mechanisms officials face no consequences, so together they seriously undermine governance. An independent judiciary (option C) and a free press (option D) support good governance, and decentralisation (option A) is generally seen as a way to bring government closer to the people."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 375, $official_bank_source${"itemId":"c948e986-5a5d-5ffc-922c-3f7012ff8ca7","questionId":"384836a4-c9c8-597b-84e9-4ff08169edd6","sourceKey":"bank:BUA205:PQ-218","payload":{"prompt":"Accountability in public governance means that public officials:","options":["Must answer for their actions and decisions to the public and relevant oversight bodies","Are immune from prosecution while in office","Report exclusively to international development partners","Are accountable only to their political party leadership"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Accountability is the obligation to explain one's decisions, accept responsibility and face consequences when performance falls short, and in the public sector officials owe this to citizens and to bodies such as legislatures, auditors and courts. Options D and C name the wrong audience, and option B is the opposite of accountability."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 376, $official_bank_source${"itemId":"9dc31c79-185d-5fb8-9a99-088ed2830766","questionId":"0d447bf9-20cf-55d0-9e2d-f12d0ef33821","sourceKey":"bank:BUA205:PQ-219","payload":{"prompt":"The 'rule of law' as an element of good governance requires that:","options":["Military decrees can override constitutional provisions","All individuals and institutions are subject to laws that are publicly known, fairly enforced and independently adjudicated","Laws are applied selectively based on political affiliation","The executive branch has absolute authority over the judiciary"],"correctOption":1,"section":"Governance in the Public Services","explanation":"The rule of law means fair legal frameworks enforced impartially, so that no person or office is above the law and human rights, especially those of minorities, are protected. Selective application (option C), rule by decree (option A) and executive control of the courts (option D) all put power above the law."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 377, $official_bank_source${"itemId":"32f80d4f-98dd-5642-a929-fe01a4e27443","questionId":"9672c05d-664f-5e5a-8729-9ee3f6cf695e","sourceKey":"bank:BUA205:PQ-220","payload":{"prompt":"Governance in the public services is important primarily because:","options":["It protects the government from international criticism","It minimises the need for civil society oversight","It ensures the efficient, transparent and accountable delivery of services that meet citizens' needs","It allows civil servants to earn higher salaries than private sector workers"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Good public governance makes sure public services are delivered well, public money is used properly and those who abuse their position are sanctioned, which builds public trust. Higher pay (option D) and protection from criticism (option A) are not its purpose, and good governance welcomes civil society oversight rather than reducing it (option B)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 378, $official_bank_source${"itemId":"1aff9810-b411-5091-8f47-d212ae80b26b","questionId":"8e63ca42-c928-5eb1-a3ce-9bff798593bc","sourceKey":"bank:BUA205:PQ-236","payload":{"prompt":"In leadership and governance, the concept of ACCOUNTABILITY is MOST consistently associated with:","options":["The obligation of those in authority to report on, explain and be answerable for the consequences of their actions to those they serve","The subordination of individual rights to collective state interests","Financial auditing procedures limited to treasury departments","The discretionary use of power by those in authority without external checks"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Accountability means people in authority must explain their decisions, accept responsibility and face consequences, supported by mechanisms such as performance monitoring, public reporting, legal oversight and checks and balances. Option D is its opposite, option C is only one narrow accountability tool, and option B has nothing to do with being answerable."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 379, $official_bank_source${"itemId":"f00fa845-c4e2-58b4-84e2-c6915d8755eb","questionId":"5a898ab9-5c2a-5020-87b8-98db520f678a","sourceKey":"bank:BUA205:PQ-241-a","payload":{"prompt":"Which characteristic of good governance requires institutions and processes to try to serve all stakeholders within a reasonable timeframe?","options":["Responsiveness","Rule of law","Transparency","Consensus orientation"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Responsiveness means public institutions act on citizens' needs and complaints promptly rather than leaving them waiting indefinitely. Consensus orientation (option D) is about mediating diverse interests, rule of law (option B) about impartially enforced legal frameworks, and transparency (option C) about open decisions and freely available information."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 380, $official_bank_source${"itemId":"f2b7947f-19d9-505c-8338-7aebee7265ee","questionId":"2f799c5e-07e8-54ad-a665-30566f9b469f","sourceKey":"bank:BUA205:PQ-241-b","payload":{"prompt":"Under the good governance characteristic of equity and inclusiveness:","options":["Institutions produce results that meet needs while making the best use of what is available","Diverse interests are mediated to reach a broad consensus","All groups, especially the most vulnerable, have opportunities to take part in governance and improve their well-being","Decisions follow rules, and information is freely available to those affected"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Equity and inclusiveness means every member of society feels they have a stake in it and no group, particularly the poor or vulnerable, is shut out of decisions or their benefits. Option D describes transparency, option B describes consensus orientation, and option A describes effectiveness and efficiency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 381, $official_bank_source${"itemId":"d245235c-881c-5f90-a9e5-7c00a05c7016","questionId":"66a37ecc-625b-59ef-9a37-25e93f553c42","sourceKey":"bank:BUA205:GPS-001","payload":{"prompt":"The word 'governance' ultimately derives from a Greek verb (kubernaein or kubernao) meaning ____.","options":["to rule by force","to vote","to own property","to steer"],"correctOption":3,"section":"Governance in the Public Services","explanation":"The Greek root means to steer, which is why governance is pictured as guiding an organisation or society in a direction. Options A, B and C are not what the root word means, although force, voting and ownership can all feature in particular systems of government."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 382, $official_bank_source${"itemId":"52006c7d-b85b-5ed8-bab2-c64c61a6bb6a","questionId":"6676583a-7261-5720-a523-81e454e2d4de","sourceKey":"bank:BUA205:GPS-002","payload":{"prompt":"In simple words, governance means ____.","options":["the act of winning elections into public office","the process of decision-making and the process by which decisions are implemented or not implemented","the collection of taxes by the state","the total number of civil servants in a country"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Governance covers both how decisions are made and how they are, or are not, carried out. Option A is only one way of gaining authority, and Option C is a single government function. Option D is a statistic, not a process."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 383, $official_bank_source${"itemId":"f81196bf-bab1-50e1-b65e-3b64b56b43ed","questionId":"e56339c5-f54b-5cf1-8c9f-2f2e21ad2adc","sourceKey":"bank:BUA205:GPS-003","payload":{"prompt":"Which of the following is NOT one of the incidents that have fuelled growing discussion of corporate governance?","options":["Fraud and corruption","Agency problems and bankruptcies","Rising adult literacy rates","Excessive directors' remuneration"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Interest in corporate governance has grown because of failures such as fraud, corruption, agency problems, bankruptcies, failing auditors and excessive pay for directors. Rising literacy is a social development, not a governance failure. Options A, B and D are all recognised triggers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 384, $official_bank_source${"itemId":"f57de3da-d03d-5bae-a590-fe7fe85b5cb8","questionId":"f0da3b14-9fef-52a9-8b79-42c6c2e404c9","sourceKey":"bank:BUA205:GPS-004","payload":{"prompt":"The 'Four P's of governance' are ____.","options":["Profit, People, Planning and Power","Purpose, People, Process and Performance","Purpose, Policy, Procedure and Price","People, Politics, Property and Production"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Good governance is said to rest on Purpose, People, Process and Performance, which together drive growth, resilience and long-term success. Options A, C and D each swap in words such as profit, price, power or politics that are not part of the framework."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 385, $official_bank_source${"itemId":"2f3ca75c-be2e-5fd6-b89a-fcccdb3bb7ae","questionId":"006859b3-fd68-5cf6-834d-6521933d4d30","sourceKey":"bank:BUA205:GPS-005","payload":{"prompt":"Which of the following is NOT one of the 'Four P's of governance'?","options":["Purpose","Profit","Process","Performance"],"correctOption":1,"section":"Governance in the Public Services","explanation":"The Four P's are Purpose, People, Process and Performance. Profit may result from good governance, but it is not one of the four. Options A, C and D are all on the list."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 386, $official_bank_source${"itemId":"8f532c21-7fa5-5cdf-b0f4-2e5fc53857dc","questionId":"78eb5b29-c539-51c2-8e16-8b5ebc588aef","sourceKey":"bank:BUA205:GPS-006","payload":{"prompt":"The corporate governance principle that requires all shareholders, including minority and foreign shareholders, to have the opportunity to receive fair treatment is ____.","options":["Responsibility","Fairness","Transparency","Accountability"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Fairness means equal and just treatment of all shareholders, so that minority and foreign investors are not disadvantaged. Option A is about complying with laws and considering all stakeholders, and Option C is about timely disclosure. Option D is the board answering to shareholders and other stakeholders."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 387, $official_bank_source${"itemId":"254851b3-608f-55df-a91e-5a9f31dec54e","questionId":"c6f53a35-d080-5aa6-9f50-0bc9e82900d2","sourceKey":"bank:BUA205:GPS-007","payload":{"prompt":"The corporate governance principle that requires an organisation to comply with laws and regulations and to consider the interests of all stakeholders is ____.","options":["Fairness","Transparency","Participation","Responsibility"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Responsibility covers legal compliance and regard for all stakeholders. Option A focuses on equal treatment of shareholders, and Option B on disclosure. Option C is one of the eight characteristics of good governance, not one of the four corporate governance principles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 388, $official_bank_source${"itemId":"e937e55d-2a50-51dd-89c6-5fb941531fa5","questionId":"7f48732a-c666-5592-a4c2-8ff055670bdb","sourceKey":"bank:BUA205:GPS-008","payload":{"prompt":"As a principle of good corporate governance, transparency requires that the organisation ____.","options":["keeps its financial results secret from competitors and the public","treats all shareholders, including minority shareholders, fairly","appoints only family members to its board","provides timely and proper disclosure on all important matters, including its financial situation, performance and ownership"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Transparency is about timely, proper disclosure of key information such as finances, performance and ownership. Option A is the opposite of transparency. Option B describes fairness, and Option C would undermine governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 389, $official_bank_source${"itemId":"b276697a-b43c-583a-9ac5-9e8c4834b5fe","questionId":"2cafdd55-fa84-5b87-ac84-98339288a546","sourceKey":"bank:BUA205:GPS-009","payload":{"prompt":"How many major characteristics of good or effective governance are usually identified (participation, rule of law, transparency, and so on)?","options":["Eight","Four","Six","Ten"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Good governance is commonly described by eight characteristics: participation, rule of law, transparency, responsiveness, consensus orientation, equity and inclusiveness, effectiveness and efficiency, and accountability. Option B confuses this with the four corporate governance principles or the Four P's, while Options C and D are not the standard count."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 390, $official_bank_source${"itemId":"c4bfa20e-6da2-5fca-9a6b-2e960d181670","questionId":"6578a056-7f76-5eb4-8e1d-05983b21a5fc","sourceKey":"bank:BUA205:GPS-010","payload":{"prompt":"Which of the following is NOT one of the eight characteristics of good governance?","options":["Consensus oriented","Centralisation","Responsiveness","Equity and inclusiveness"],"correctOption":1,"section":"Governance in the Public Services","explanation":"The eight characteristics are participation, rule of law, transparency, responsiveness, consensus orientation, equity and inclusiveness, effectiveness and efficiency, and accountability. Centralisation is not on the list, and concentrating power can actually work against participation. Options A, C and D are all genuine characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 391, $official_bank_source${"itemId":"d3fc1051-abfa-5171-bd9e-b5fb1739a397","questionId":"aba9e19a-e64e-5480-97fb-f3601f9b66f3","sourceKey":"bank:BUA205:GPS-011","payload":{"prompt":"As a characteristic of good governance, participation means that ____.","options":["only elected officials take part in decisions","only those who pay the most tax may take part","citizens take part only by obeying laws","both men and women take part, either directly or through legitimate intermediate institutions or representatives"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Participation by both men and women, whether directly or through legitimate representatives and institutions, is a cornerstone of good governance. Options A and B exclude most citizens, and Option C confuses participation with mere compliance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 392, $official_bank_source${"itemId":"bcb95f94-efdc-5121-b4fe-0444c2ab13b0","questionId":"f018e5e6-56f2-5ffe-ac07-16284c74c628","sourceKey":"bank:BUA205:GPS-012","payload":{"prompt":"The characteristic of good governance that requires fair legal frameworks enforced impartially, together with full protection of human rights, particularly those of minorities, is ____.","options":["Rule of law","Responsiveness","Consensus orientation","Effectiveness and efficiency"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Rule of law means fair laws that are applied impartially, with human rights, especially minorities' rights, protected. Option B is about serving stakeholders within a reasonable time, and Option C is about reaching broad agreement. Option D is about results and the use of resources."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 393, $official_bank_source${"itemId":"fda11f72-ecb3-5379-8b94-6b49a4755e45","questionId":"8f71225f-d69f-52af-be14-00b97846dabb","sourceKey":"bank:BUA205:GPS-014","payload":{"prompt":"A Federal agency takes three years to process a citizen's simple pension claim, although the rules require a decision within 90 days. Which characteristic of good governance is MOST clearly lacking?","options":["Responsiveness","Consensus orientation","Participation","Equity and inclusiveness"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Responsiveness requires institutions to serve stakeholders within a reasonable timeframe, and a three-year delay on a 90-day process plainly fails that test. Option B is about building broad agreement among diverse interests, and Option C is about taking part in decisions. Option D is about not excluding groups, which the stem does not suggest."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 394, $official_bank_source${"itemId":"42e68b2c-b82b-5315-857d-f3efbd0e4b2b","questionId":"37da509e-5374-5e14-ae8e-5721865dc7d6","sourceKey":"bank:BUA205:GPS-015","payload":{"prompt":"The characteristic of good governance that requires mediation among the diverse interests in society to reach a broad agreement on what is in the best interest of the whole community, with a long-term perspective, is ____.","options":["Responsiveness","Accountability","Rule of law","Consensus orientation"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Consensus orientation means mediating different interests to reach broad agreement, with a long-term view of what society needs. Option A is about timely service, and Option B is about answering for decisions. Option C is about fair and impartial laws."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 395, $official_bank_source${"itemId":"da18b069-f8d6-5fa5-846a-341156ab16da","questionId":"4392734d-36c5-5996-a1d8-a7b327c53e07","sourceKey":"bank:BUA205:GPS-016","payload":{"prompt":"Before reviewing the minimum wage, the Federal Government brings labour unions, employers' associations and state governments together for months of negotiation until a broadly acceptable figure is agreed. This BEST illustrates which characteristic of good governance?","options":["Rule of law","Effectiveness and efficiency","Transparency","Consensus orientation"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Bringing diverse interests together and mediating until there is broad agreement is what consensus orientation means. Option A concerns impartial legal frameworks, and Option B concerns results and the use of resources. Option C concerns openness of information, which may support the process but is not the main idea here."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 396, $official_bank_source${"itemId":"e4732b91-df40-5e38-8725-dff08c3e8f62","questionId":"ac0c52d4-df9c-5ff4-8ebd-de5b386b5c68","sourceKey":"bank:BUA205:GPS-017","payload":{"prompt":"As a characteristic of good governance, equity and inclusiveness means ____.","options":["giving every citizen exactly the same income","allowing only the majority ethnic group to make decisions","ensuring all members of society, particularly the most vulnerable, feel they have a stake and have opportunities to improve or maintain their well-being","including only citizens who live in the capital city"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Equity and inclusiveness means nobody feels excluded from the mainstream of society, and vulnerable groups in particular get opportunities to take part. Option A confuses equity with identical incomes. Options B and D are forms of exclusion."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 397, $official_bank_source${"itemId":"76443528-8f2e-52c9-9968-80440d049a02","questionId":"f1943918-93f4-54c7-b47d-974e677b1ef8","sourceKey":"bank:BUA205:GPS-018","payload":{"prompt":"The characteristic of good governance under which procedures and institutions produce results that meet the needs of society while making the best use of the resources at their disposal is ____.","options":["Consensus orientation","Effectiveness and efficiency","Participation","Equity and inclusiveness"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Effectiveness is about meeting society's needs, and efficiency is about making the best use of resources, which together form this characteristic. Option A is about broad agreement, Option C is about taking part in decisions, and Option D is about not excluding any group."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 398, $official_bank_source${"itemId":"05cd9097-8b4b-5b0e-b7b7-2beb772f56f3","questionId":"eace39b3-474c-5d0b-af15-bcff15d485a4","sourceKey":"bank:BUA205:GPS-019","payload":{"prompt":"Accountability, a major requirement of good governance, can only be enforced when it is supported by ____.","options":["secrecy and discretion","centralisation and speed","transparency and the rule of law","profit and competition"],"correctOption":2,"section":"Governance in the Public Services","explanation":"People can only be held to account if information is available (transparency) and fair rules are enforced (rule of law). Option A would make accountability impossible, Option B has no necessary link to it, and Option D concerns markets rather than governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 399, $official_bank_source${"itemId":"8daf32db-0d18-58e8-b56f-cbe3359e5fb3","questionId":"b812d098-939a-5cb1-99f7-a0290d8e18a3","sourceKey":"bank:BUA205:GPS-020","payload":{"prompt":"Accountability in governance is BEST defined as ____.","options":["the obligation of leaders and institutions to explain their actions, accept responsibility for decisions and face consequences when performance falls short","the duty of citizens to pay taxes on time","the right of leaders to make decisions without being questioned","the practice of keeping detailed accounting records only"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Accountability means leaders must explain themselves, take responsibility and face consequences for poor performance. Option B is a citizen's duty, and Option C is the opposite of accountability. Option D confuses accountability with bookkeeping."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 400, $official_bank_source${"itemId":"75fb8e26-6295-5e90-b376-4e640bc0da59","questionId":"04a63c46-a4b2-502c-86f5-dd48ad2a8591","sourceKey":"bank:BUA205:GPS-021","payload":{"prompt":"Which of the following is NOT an accountability mechanism in governance?","options":["Performance monitoring","Executive immunity from all review","Legal oversight","Institutional checks and balances"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Accountability mechanisms include performance monitoring, legal oversight, public reporting and institutional checks and balances. Shielding executives from all review removes accountability rather than providing it. Options A, C and D are recognised mechanisms."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 401, $official_bank_source${"itemId":"311f483f-6aef-5bcd-98fd-d2c65c0284d6","questionId":"e20d3baa-a362-5518-9b36-6b908d0cbea7","sourceKey":"bank:BUA205:GPS-022","payload":{"prompt":"The 'three Es' commonly used to describe the general objectives of public sector organisations are ____.","options":["economy, efficiency and effectiveness","equity, ethics and elections","economy, equality and expansion","efficiency, enterprise and exports"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Public sector objectives are often summed up as economy, efficiency and effectiveness. Options B, C and D each contain words that may matter in public life but do not make up the standard three Es."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 402, $official_bank_source${"itemId":"afe21762-e6ce-5405-93c9-104fca8dfd09","questionId":"fce190e6-b9c3-530f-b501-db41fb7a6587","sourceKey":"bank:BUA205:GPS-023","payload":{"prompt":"Among the 'three Es' of the public sector, the one that means value for money and delivering the required service on budget, on time and within other resource limits is ____.","options":["Efficiency","Effectiveness","Economy","Equity"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Economy is about value for money: delivering the service on budget, on time and within resource limits. Option A is output relative to input, and Option B is whether the intended results are achieved. Option D is not one of the three Es."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 403, $official_bank_source${"itemId":"71a95653-701d-5718-8ebd-f9f598325e51","questionId":"d3ba51e0-393e-58e1-a87e-966e4e3dee64","sourceKey":"bank:BUA205:GPS-024","payload":{"prompt":"Among the 'three Es' of the public sector, the one defined as work output divided by work inputs is ____.","options":["Efficiency","Economy","Effectiveness","Equity"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Efficiency compares output with input, that is, getting an acceptable return on the money and resources invested. Option B focuses on staying within budget and time, and Option C focuses on achieving intended results. Option D is not one of the three Es."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 404, $official_bank_source${"itemId":"6cac98e2-8736-58b1-99df-5ec2f558d8ad","questionId":"0dedb8cf-01ac-5075-a7ec-5dbf48453fde","sourceKey":"bank:BUA205:GPS-025","payload":{"prompt":"A state primary health care board built every clinic it planned, on time and within budget, but a survey shows the clinics are not reducing child deaths as intended because they lack trained staff. Which of the 'three Es' is MOST clearly lacking?","options":["Economy","Effectiveness","Efficiency in procurement","Equity in budgeting"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Effectiveness is the extent to which an organisation delivers what it is intended to deliver, and these clinics are not achieving their purpose of reducing child deaths. Option A is satisfied, because the clinics were delivered on time and on budget. Options C and D are not what the evidence in the stem points to."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 405, $official_bank_source${"itemId":"9b06f88f-9996-5bcd-b171-9afc67e91377","questionId":"72d88297-4004-5a65-8d7f-c27eefdfc2aa","sourceKey":"bank:BUA205:GPS-026","payload":{"prompt":"The public sector is BEST described as ____.","options":["businesses owned by individuals that aim mainly to make profit","voluntary associations that operate between the state and the market","government organisations and agencies responsible for delivering public goods and services","foreign companies operating in a country"],"correctOption":2,"section":"Governance in the Public Services","explanation":"The public sector is made up of government bodies, such as ministries, public schools, hospitals and law enforcement agencies, that deliver public goods and services. Option A describes the private sector, and Option B describes civil society. Option D is a subset of the private sector."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 406, $official_bank_source${"itemId":"a4a5ba32-ac79-57a7-917b-382530eb1580","questionId":"66f8ef02-2377-5425-aa54-5508357a4a27","sourceKey":"bank:BUA205:GPS-027","payload":{"prompt":"What is the MAJOR difference between public and private sector enterprises?","options":["Size: public enterprises are always smaller than private ones","Location: public enterprises operate only in the capital","Ownership: public enterprises are owned and operated by government, private ones by individuals or shareholders","Technology: private enterprises never use computers"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Ownership is the key distinction: government owns public enterprises on behalf of the public, while individuals or shareholders own private ones. Options A, B and D are false generalisations that do not separate the two sectors."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 407, $official_bank_source${"itemId":"7244535b-2e3c-5b9e-a518-ff47ca6dff91","questionId":"f3d737bb-8021-5d67-8e4b-0538f2a517fb","sourceKey":"bank:BUA205:GPS-028","payload":{"prompt":"Which statement CORRECTLY contrasts decision-making in public and private sector enterprises?","options":["Public enterprises usually follow bureaucratic processes with several levels of approval, while private firms have more flexibility to respond quickly","Public enterprises decide faster because they face no rules","Private firms must obtain legislative approval for every decision","Both sectors use exactly the same approval processes"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Public enterprises typically go through bureaucratic, multi-level approval, while private firms can respond quickly to business opportunities. Option B reverses the usual pattern, and Option C wrongly applies public-sector controls to private firms. Option D ignores the difference altogether."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 408, $official_bank_source${"itemId":"a0c0ad29-cbad-5328-ae1d-f4a8b77ceedb","questionId":"36ca1fd8-5833-5c3f-9643-5985b4d89732","sourceKey":"bank:BUA205:GPS-029","payload":{"prompt":"To whom are public sector enterprises, as opposed to private sector enterprises, primarily accountable?","options":["Their shareholders only","Their suppliers","Foreign investors","The government and the public"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Public enterprises answer to the government and the public, while private enterprises are mainly accountable to their shareholders, who judge success by profit and growth. Option A describes the private sector, and Options B and C are not the primary line of accountability for either sector."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 409, $official_bank_source${"itemId":"ba2c893b-ee74-592a-9c18-33e18067af89","questionId":"5cacfa79-9caf-5690-8744-a4fb9e84f86b","sourceKey":"bank:BUA205:GPS-030","payload":{"prompt":"Which statement BEST contrasts the objectives of public and private sector enterprises?","options":["Both aim only to maximise profit","Public enterprises prioritise public needs and general welfare, while private enterprises mostly aim to maximise profit and shareholder value","Public enterprises aim to maximise shareholder value, while private enterprises aim at welfare","Neither sector has clear objectives"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Public enterprises exist mainly to meet public needs and serve the general welfare, while private enterprises mostly pursue profit and value for shareholders. Option A ignores the welfare purpose of the public sector, and Option C reverses the two. Option D is simply false."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 410, $official_bank_source${"itemId":"e2e41446-a6e4-568e-a1af-2e5c9b21635d","questionId":"1a4c6ce5-b327-506a-8215-cd67ae93324b","sourceKey":"bank:BUA205:GPS-031","payload":{"prompt":"In Nigeria, citizens' oversight of public sector entities is exercised mainly through ____.","options":["the boards of private companies","foreign embassies","the National and State Assemblies and, at local level, councillors","traditional rulers alone"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Citizens are the ultimate owners of public sector entities, and they exercise oversight through their elected representatives in the National and State Assemblies and through councillors at local level. Options A and B have no constitutional oversight role over public entities. Option D is too narrow, because traditional rulers are not the formal oversight channel."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 411, $official_bank_source${"itemId":"08610232-fa32-57ab-8fa5-a92af3f9bbe5","questionId":"059aa2af-0411-5117-b3a4-8a59bba93c7e","sourceKey":"bank:BUA205:GPS-032","payload":{"prompt":"As a characteristic of good governance, transparency means that ____.","options":["decisions and their enforcement follow rules and regulations, and information is freely available and directly accessible to those affected","government decides quickly without consulting anyone","only senior officials may see information about public decisions","every citizen must agree before any decision is taken"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Transparency has two parts: decisions and their enforcement follow the rules, and the people affected can freely and directly access information about them. Option B describes haste without openness, and Option C is secrecy. Option D confuses transparency with unanimous consent."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 412, $official_bank_source${"itemId":"898b8128-69a8-5873-a4e7-88b72b0d7096","questionId":"f9172c49-dc5a-506d-a903-548e829b9490","sourceKey":"bank:BUA205:GPS-033","payload":{"prompt":"The objective of public sector governance is BEST stated as ____.","options":["maximising returns to government shareholders","protecting the private interests of public officials","reducing the number of citizens who use public services","serving the public interest, providing essential services and ensuring national stability and well-being"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Public sector governance aims to serve the public interest, deliver essential services and secure national stability and well-being. Option A applies private-sector profit logic, and Option B describes corruption. Option C contradicts the purpose of public service."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 413, $official_bank_source${"itemId":"d0d793ac-d35e-5820-85c0-cbe6f6e56a98","questionId":"6990e3e1-3859-5c68-b68f-845b6323b735","sourceKey":"bank:BUA205:GPS-034","payload":{"prompt":"Which document is an example of a policy guideline for the governance of public sector entities in Nigeria?","options":["The articles of association of a private limited company","A commercial bank's loan agreement","The Corporate Governance Manual for Governing Boards/Councils of Federal Parastatals, Agencies and Commissions","A football club's membership handbook"],"correctOption":2,"section":"Governance in the Public Services","explanation":"The Corporate Governance Manual for Governing Boards/Councils of Federal Parastatals, Agencies and Commissions is one of the policy guidelines that steer federal public entities. Options A, B and D are private documents that do not govern public entities."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 414, $official_bank_source${"itemId":"e24c8a36-740e-5bed-8fdb-a75431865bf0","questionId":"cdf36dba-3a96-5c67-9b9e-f4036c88d367","sourceKey":"bank:BUA205:GPS-035","payload":{"prompt":"In corporate governance, the situation in which the people who manage a business do not own it but run it on behalf of the owners, and owe them a fiduciary duty, is described as ____.","options":["a social contract","an agency relationship","a partnership deed","a consensus orientation"],"correctOption":1,"section":"Governance in the Public Services","explanation":"In an agency relationship, managers act as agents for the owners (principals) and owe them a fiduciary duty to pursue the owners' goals. Option A concerns citizens and the state. Option C is a legal document for partners, and Option D is a characteristic of good governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 415, $official_bank_source${"itemId":"a6007c28-f22f-5bfa-b729-a63afa39e2fd","questionId":"25e774e3-da7c-51b1-bac4-104fb4871f95","sourceKey":"bank:BUA205:GPS-036","payload":{"prompt":"The founder of a family-owned Onitsha trading company is retiring, and his children are quarrelling over who should take over. This governance challenge, typical of private companies, is ____.","options":["succession planning","regulatory scrutiny of public disclosures","managing a large and diverse shareholder base","pressure from stock market analysts for quarterly results"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Moving leadership from one generation to the next is a major governance challenge for private, especially family-owned, firms. Options B, C and D are challenges typically faced by publicly listed companies with many shareholders and disclosure duties."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 416, $official_bank_source${"itemId":"ca89677a-7989-54fb-ad53-f564fcbcc821","questionId":"9411ef25-226e-523a-af0d-baaf2708cfae","sourceKey":"bank:BUA205:GPS-037","payload":{"prompt":"Which of the following is NOT a typical governance challenge for a private (unlisted) company?","options":["Lack of transparency and public accountability","Limited access to capital markets","Balancing growth with the owners' control","Managing a very large and diverse shareholder base"],"correctOption":3,"section":"Governance in the Public Services","explanation":"A very large, diverse shareholder base is a challenge for publicly listed companies, not for privately held ones owned by a small group. Options A, B and C are recognised private-company challenges: less scrutiny, harder fundraising, and the risk of diluting control when outside investors come in."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 417, $official_bank_source${"itemId":"4aadf25b-5385-59de-a497-ff52647d9a21","questionId":"1716b97a-b67f-58d4-b257-b3d51e585bf0","sourceKey":"bank:BUA205:GPS-038","payload":{"prompt":"A fast-growing private Lagos tech firm needs capital, but its founders fear that bringing in outside investors will reduce their say in the company's direction. This governance challenge is BEST described as ____.","options":["regulatory scrutiny and compliance burdens","pressure for short-term results from stock markets","managing diverse shareholder interests","balancing growth with control"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Private owners often face a trade-off between raising money for growth and keeping control, because new investors dilute the owners' influence. Options A, B and C are challenges usually associated with publicly listed companies."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 418, $official_bank_source${"itemId":"bc80811d-8ea4-536f-af32-cefc63fa919e","questionId":"043d0915-7035-5b9f-8ccc-c837617395ae","sourceKey":"bank:BUA205:GPS-039","payload":{"prompt":"Compared with private company boards, the boards of publicly listed companies are typically ____.","options":["smaller and made up only of the owners' family members","larger, with a blend of executive and non-executive directors and an emphasis on independence","free of any requirement for independent directors","appointed directly by the government"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Listed company boards tend to be larger and mix executive and non-executive directors, with independence and expertise stressed so that decisions serve all shareholders. Option A describes many private boards, and Option C reverses the usual rule. Option D confuses listed firms with state enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 419, $official_bank_source${"itemId":"287691a1-1cd0-5e61-b1d0-2cb0614ce24c","questionId":"ec0da663-b37d-5844-810b-f2f92af3e15b","sourceKey":"bank:BUA205:GPS-040","payload":{"prompt":"Why might a publicly listed company be MORE risk-averse than a private company?","options":["It has no shareholders to answer to","It is not required to publish any information","It faces greater scrutiny from regulators and the public","It is always owned by one family"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Heavier regulatory and public scrutiny tends to make listed companies more cautious, while private firms may have more freedom to take risks in pursuit of growth. Options A and B are false for listed companies. Option D describes a private, family-owned firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 420, $official_bank_source${"itemId":"eaae6b6e-5e55-52b9-8906-a1289597ef07","questionId":"8f7b7fab-8cf5-5d24-a4c7-6b8395d76b83","sourceKey":"bank:BUA205:GPS-041","payload":{"prompt":"Which of the following is NOT an importance of good public sector governance?","options":["It encourages global investors to invest in the economy","It removes the need for laws and regulations","It increases public trust and confidence in government institutions","It assures stakeholders that those who abuse public trust will be sanctioned"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Good governance works through laws, rules and regulations; it does not replace them. Options A, C and D are recognised benefits: attracting investment, building trust through transparency and accountability, and making sure wrongdoers are sanctioned."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 421, $official_bank_source${"itemId":"0cc03ddd-e292-5515-8836-d3fa9aa9596d","questionId":"194f52e8-e135-523e-8ae4-28d799ab8167","sourceKey":"bank:BUA205:GPS-042","payload":{"prompt":"Good public sector governance creates an enabling environment in which citizens are empowered to ____.","options":["voluntarily participate in governance and contribute to national development","avoid paying taxes","ignore public institutions","take over the duties of the courts"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Good governance empowers citizens to take part voluntarily in governance and contribute to national development. Options B and C are signs of weak governance and civic apathy. Option D would undermine the rule of law."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 422, $official_bank_source${"itemId":"2b866ac8-1a8f-54c1-b4f1-11e96e0f3898","questionId":"dd5095ea-82bc-5600-9888-83fee8c5910f","sourceKey":"bank:BUA205:GPS-043","payload":{"prompt":"Which of the following is listed among the major leadership challenges, or hindrances, to good governance?","options":["Independent judiciary","Political interference","Free press","Merit-based recruitment"],"correctOption":1,"section":"Governance in the Public Services","explanation":"Political interference, where outside actors push decisions for personal or partisan gain, is a key hindrance, alongside corruption, lack of transparency, weak institutions and low citizen trust. Options A, C and D are supports for good governance, not hindrances."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 423, $official_bank_source${"itemId":"1db5b985-aa55-565d-8d69-c522b0e96c5e","questionId":"5c3c5117-0164-5665-92f3-2098029f6c3e","sourceKey":"bank:BUA205:GPS-044","payload":{"prompt":"As a hindrance to good governance, corruption is BEST described as ____.","options":["leaders using their authority for personal gain rather than public or organisational benefit","leaders taking a long time to make decisions","citizens refusing to vote","government publishing its budget online"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Corruption occurs when authority is used for personal gain, through bribery, embezzlement, nepotism or abuse of resources. Option B is slowness, which relates to responsiveness. Option C is civic apathy, and Option D is transparency, a support for good governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 424, $official_bank_source${"itemId":"f68116e3-cf72-501b-9e4d-d225e14d073b","questionId":"fd04778b-922b-58c1-b589-dd403754848b","sourceKey":"bank:BUA205:GPS-045","payload":{"prompt":"The board of a federal agency is frequently overruled by politicians who insist on hiring their supporters and awarding contracts to party loyalists. Which hindrance to good governance does this BEST illustrate?","options":["Low voter turnout","Excessive transparency","Political interference","Consensus orientation"],"correctOption":2,"section":"Governance in the Public Services","explanation":"Political interference is when outside actors influence decisions for personal or partisan interests rather than collective welfare, which reduces autonomy and professional standards. Option A is about citizens not voting. Options B and D are features of good governance, not hindrances."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 425, $official_bank_source${"itemId":"34d8fa5f-d802-562f-90b8-e237b7a1c728","questionId":"4b7ede10-6786-5778-a3c2-4559263d5013","sourceKey":"bank:BUA205:GPS-047","payload":{"prompt":"The recommended leadership response to the governance hindrance of weak institutions is ____.","options":["relying more on personal loyalty networks","concentrating all decisions in one office","reducing public reporting","institutional reform, capacity building and strengthening governance frameworks"],"correctOption":3,"section":"Governance in the Public Services","explanation":"Weak institutions are addressed by reforming them, building their capacity and strengthening governance frameworks. Option A deepens dependence on informal networks. Options B and C weaken checks and transparency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 426, $official_bank_source${"itemId":"28ba1ce2-09b0-5dd3-84b1-0ec11dc1d2f7","questionId":"bdbd42eb-11f0-5013-bd62-813ed55718b1","sourceKey":"bank:BUA205:GPS-049","payload":{"prompt":"In a Nigerian state, fewer than one in four registered voters turned out in the last governorship election. In governance terms, persistently low voter turnout MAINLY ____.","options":["proves that citizens are fully satisfied with government","strengthens the rule of law","reduces leadership accountability and the legitimacy of governance","increases transparency of public spending"],"correctOption":2,"section":"Governance in the Public Services","explanation":"When few citizens vote, leaders face less pressure to answer to the public and their mandate looks weaker, so both accountability and legitimacy suffer. Option A reads too much into abstention. Options B and D are not effects of low turnout."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 427, $official_bank_source${"itemId":"eefc7fa3-b7dd-5f6d-a0bd-1a15522d4268","questionId":"ed70f097-e72c-5f06-bef3-755351a19e59","sourceKey":"bank:BUA205:GPS-050","payload":{"prompt":"Which of the following is NOT one of the conditions from which weak governance often results?","options":["Active followership","Civic apathy","Lack of accountability mechanisms","Weak institutional structures"],"correctOption":0,"section":"Governance in the Public Services","explanation":"Weak governance often results from passive followership, civic apathy, lack of accountability mechanisms and weak institutional structures. Active followership does the opposite, because engaged followers question unethical behaviour and help hold leaders to account. Options B, C and D are recognised causes of weak governance."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 428, $official_bank_source${"itemId":"7733b2f0-3c63-5910-a38c-bc9c6fb6c64c","questionId":"87662af0-7606-50c4-a375-c4333bfae53d","sourceKey":"bank:BUA205:PQ-086","payload":{"prompt":"The Open Government Partnership supports __________________, ensuring that reforms align with public values.","options":["Administrative detachment","Technocratic dominance","Value-driven governance","Executive insulation"],"correctOption":2,"section":"Open Government Partnerships","explanation":"The Open Government Partnership ties reforms to what citizens value, such as openness, participation and accountability, which is value-driven governance. Options A, B and D all describe government drifting away from citizens, which open government tries to reverse."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 429, $official_bank_source${"itemId":"a948eb7f-82ea-521f-ada3-b8a63ca10bf1","questionId":"1b21844a-86bb-5c93-bc90-5a9e1d835234","sourceKey":"bank:BUA205:PQ-136","payload":{"prompt":"The Open Government Partnership strengthens __________________, enabling citizens to challenge administrative decisions effectively.","options":["Institutional insulation","Administrative accountability","Executive immunity","Procedural opacity"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Open government strengthens administrative accountability by giving citizens information and channels to question and challenge official decisions. Options A, C and D shield officials from scrutiny, which is the opposite of what open government seeks."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 430, $official_bank_source${"itemId":"586f54af-5ac6-5a7f-b927-755bf10bd263","questionId":"d69c2f4b-d89e-5865-bcb4-939ce376788a","sourceKey":"bank:BUA205:PQ-159","payload":{"prompt":"A benefit of the Open Government Partnership is improved __________________, supporting openness in public-private partnerships.","options":["Partnership transparency","Selective disclosure","Contractual secrecy","Informal negotiation"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Open government aims for openness in public-private partnerships, such as publishing contract details, which improves partnership transparency. Options B, C and D keep partnership deals hidden from the public."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 431, $official_bank_source${"itemId":"8aaa3023-d44f-52de-ab7b-8f2f45fe3064","questionId":"84197287-4945-5570-9167-b3895249c719","sourceKey":"bank:BUA205:PQ-171","payload":{"prompt":"The Open Government Partnership encourages governments to build transparency into public service delivery by:","options":["Restricting citizen feedback","Limiting service information","Centralising management","Publishing performance indicators"],"correctOption":3,"section":"Open Government Partnerships","explanation":"When governments publish performance indicators, such as service waiting times or project completion rates, citizens can see how well services are delivered and demand improvement. Restricting feedback (option A) and limiting service information (option B) reduce openness, and centralising management (option C) does nothing by itself to make services visible to the public."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 432, $official_bank_source${"itemId":"c9ddc909-c57c-53a2-930d-f16960dfcdd5","questionId":"f75abb7a-a524-5406-a832-5efc2fec6862","sourceKey":"bank:BUA205:PQ-173","payload":{"prompt":"One benefit of the Open Government Partnership is that it normalises ______, which reduces public suspicion about government decisions.","options":["Confidential consultations","Transparent decision-making","Unilateral policymaking","Closed executive sessions"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Open government means decisions are made in ways the public can see, with reasons and information shared, so citizens have less cause to suspect hidden deals. Unilateral policymaking (option C) is the closed style that open government seeks to replace, and closed sessions and confidential consultations (options D and A) keep the public in the dark."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 433, $official_bank_source${"itemId":"55c5a64d-5cff-55e2-a86a-b86fd25dc724","questionId":"ca1f4473-1d7e-5b4c-8006-3936b318e2a2","sourceKey":"bank:BUA205:PQ-174","payload":{"prompt":"The Open Government Partnership supports openness in regulatory enforcement by strengthening:","options":["Discretionary compliance","Selective inspection","Regulatory transparency","Enforcement secrecy"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Regulatory transparency means the rules, how they are enforced and the results of inspections are open to the public, so businesses and citizens can see that regulation is applied fairly. Selective inspection (option B) and discretionary compliance (option A) invite favouritism and corruption, and enforcement secrecy (option D) is the direct opposite of openness."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 434, $official_bank_source${"itemId":"2a2e7060-2e0b-583b-8923-c1860140c26c","questionId":"5a07e081-7abf-5fb6-b519-0eb92f026bab","sourceKey":"bank:BUA205:PQ-176","payload":{"prompt":"The Open Government Partnership recognises that meaningful citizen participation must be supported by:","options":["Access to relevant information","Symbolic consultations","Political loyalty","Administrative hierarchy"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Citizens can only take part meaningfully in governance if they know what government is doing, which is why access to information is a core pillar of open government. Symbolic consultations (option B) only give the appearance of participation, while political loyalty and administrative hierarchy (options C and D) do nothing to empower citizens."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 435, $official_bank_source${"itemId":"60e60146-cfc5-5a46-a0f2-44f7e3339142","questionId":"9184325f-70d2-5a97-96e0-8609b3cdf044","sourceKey":"bank:BUA205:PQ-221","payload":{"prompt":"The Open Government Partnership (OGP) was formally launched in:","options":["2004","2016","1995","2011"],"correctOption":3,"section":"Open Government Partnerships","explanation":"OGP was launched in September 2011 in New York, on the sidelines of the UN General Assembly, by eight founding governments. Option B, 2016, is tempting because that is the year Nigeria joined, while 1995 and 2004 (options C and A) come before the initiative existed."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 436, $official_bank_source${"itemId":"67bf7b1a-767c-5d97-b0e9-9a67f5f4eb9d","questionId":"a7092b35-ec6f-5861-963d-1d45e614ed67","sourceKey":"bank:BUA205:PQ-222","payload":{"prompt":"A core aim of the Open Government Partnership is to:","options":["Secure concrete commitments from governments to promote transparency, empower citizens, fight corruption and harness technology","Create a unified global taxation framework for member states","Replace national parliaments with an international governance body","Promote the privatisation of all government services"],"correctOption":0,"section":"Open Government Partnerships","explanation":"OGP brings governments and civil society together to make concrete, monitored commitments that make government more open, accountable and responsive to citizens. It has nothing to do with privatisation (option D), it does not replace national institutions (option C), and it sets no global tax rules (option B)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 437, $official_bank_source${"itemId":"7a7a3e75-e0e4-52d4-9789-65dc3c7ac088","questionId":"66bd27c1-fc08-5799-a13c-ffc2ad3d0938","sourceKey":"bank:BUA205:PQ-223","payload":{"prompt":"A major benefit of the Open Government Partnership for citizens is:","options":["Consolidation of power within the executive branch","Improved access to government information and services, and greater ability to hold leaders accountable","Restriction of public access to government budget information","Mandatory transfer of public assets to private investors"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Open government gives citizens more information about how they are governed and more channels to take part and demand answers, which strengthens accountability. Restricting budget information (option C) and concentrating executive power (option A) are what open government works against, and OGP does not require privatisation (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 438, $official_bank_source${"itemId":"ff198e80-9ff7-5395-a9d3-b0e556d0f665","questionId":"fabe9734-d445-5d67-bfa6-8a6749ffd08d","sourceKey":"bank:BUA205:PQ-224","payload":{"prompt":"As of 2026, which of the following is a requirement for a country to join the Open Government Partnership?","options":["Membership of NATO","Permanent membership of the UN Security Council","Endorsing the Open Government Declaration and meeting minimum eligibility criteria in fiscal transparency, access to information, asset disclosure and citizen engagement","Reaching a minimum GDP per capita threshold"],"correctOption":2,"section":"Open Government Partnerships","explanation":"To join OGP, a government endorses the Open Government Declaration and must score enough points on four core eligibility areas: fiscal transparency, access to information, asset disclosure by public officials and citizen engagement. Military alliances, income level and Security Council status (options A, D and B) play no part in eligibility."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 439, $official_bank_source${"itemId":"95a47815-70cc-53aa-a918-0e3268013694","questionId":"a6ed71a5-ced9-5aab-831f-e8409f3d69d4","sourceKey":"bank:BUA205:PQ-225","payload":{"prompt":"Open government data initiatives primarily aim to:","options":["Restrict access to sensitive national data from foreign investors","Sell government information to private corporations for revenue generation","Store classified security information in a centralised government database","Make government datasets publicly accessible to promote innovation, accountability and civic engagement"],"correctOption":3,"section":"Open Government Partnerships","explanation":"Open data means publishing government information, such as budgets, contracts and service statistics, in free, usable formats so citizens, journalists and businesses can analyse it, track performance and build new services. Selling data (option B) contradicts free access, and options A and C are about restricting or securing data, not opening it."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 440, $official_bank_source${"itemId":"eb65db2d-1936-55a4-8a34-8f096428bfce","questionId":"4f3aa30a-464e-5dce-aaa9-88c4e218bc9a","sourceKey":"bank:BUA205:PQ-226","payload":{"prompt":"Technology is central to the Open Government Partnership because it:","options":["Enables surveillance of political opposition groups","Replaces human civil servants with automated systems","Centralises all government communication through a single platform","Facilitates transparency, citizen participation and service delivery innovation in government"],"correctOption":3,"section":"Open Government Partnerships","explanation":"Digital tools such as open data portals, online feedback platforms and e-government services make it easier to publish information, gather citizens' views and deliver services efficiently. Surveillance of opponents (option A) violates open government values, and options B and C are not aims of the partnership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 441, $official_bank_source${"itemId":"a261198b-618e-5ba1-9b26-e971e2f18921","questionId":"8804614e-5c31-521a-b5d2-c83bf5b54356","sourceKey":"bank:BUA205:PQ-227","payload":{"prompt":"Since Nigeria joined the Open Government Partnership in 2016, its national action plan commitments have focused mainly on:","options":["Fiscal transparency, extractive industries transparency, anti-corruption measures and improving access to public information","Privatising state-owned enterprises across all sectors","Removing all trade tariffs with neighbouring West African states","Military expenditure reduction and disarmament"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Nigeria's OGP action plans have centred on opening up budgets and public contracting, transparency in the oil and gas sector, anti-corruption steps such as disclosing the real owners of companies, and better access to information and citizen engagement. Privatisation (option B), disarmament (option D) and trade tariffs (option C) are not OGP commitment areas for Nigeria."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 442, $official_bank_source${"itemId":"807f87b0-b7ef-5b38-ba6f-c923f70f33e4","questionId":"ae522993-0c57-56a4-80ca-80dcbb08076f","sourceKey":"bank:BUA205:PQ-241-c","payload":{"prompt":"Which of the following was one of the eight founding governments of the Open Government Partnership in 2011?","options":["Brazil","Saudi Arabia","Nigeria","China"],"correctOption":0,"section":"Open Government Partnerships","explanation":"The eight founding governments of OGP were Brazil, Indonesia, Mexico, Norway, the Philippines, South Africa, the United Kingdom and the United States. Nigeria (option C) joined later, in 2016, while China and Saudi Arabia (options D and B) were not founding governments."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 443, $official_bank_source${"itemId":"c482da37-f5bd-5b16-b116-161c9994f02a","questionId":"afc5626d-cf63-5cd4-bfb3-0079cad5cab2","sourceKey":"bank:BUA205:PQ-241-d","payload":{"prompt":"In which year did Nigeria join the Open Government Partnership?","options":["2011","2016","2005","2020"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Nigeria joined OGP in 2016 and went on to develop national action plans on areas such as fiscal transparency and anti-corruption. 2011 (option A) is when OGP itself was launched by its eight founding governments, and 2005 (option C) is before OGP existed."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 444, $official_bank_source${"itemId":"6eaf7fdf-e3ad-5c94-ae71-ff54ce9b54e9","questionId":"e69b6356-7c39-5da7-a707-8bacec0b7066","sourceKey":"bank:BUA205:PQ-241-e","payload":{"prompt":"Member countries of the Open Government Partnership put their commitments into practice mainly through:","options":["Binding treaties enforced by the UN Security Council","National action plans of commitments co-created by government and civil society","Loans provided by the Open Government Partnership","Laws passed by an Open Government Partnership parliament"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Each OGP member works with civil society to draw up a national action plan of specific commitments, and progress is assessed by OGP's Independent Reporting Mechanism. OGP is a voluntary partnership, so it has no binding treaties (option A), it is not a lender (option C), and it has no parliament of its own (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 445, $official_bank_source${"itemId":"609d57f0-3151-56a2-92db-fd8138a774b0","questionId":"3483062f-d9f7-5186-80f0-980c7863a90b","sourceKey":"bank:BUA205:OGP-001","payload":{"prompt":"The Open Government Partnership (OGP) is BEST described as ____.","options":["a binding United Nations treaty that punishes corrupt governments with sanctions","an African Union agency that funds infrastructure projects","a private company that sells government data to investors","a voluntary partnership of governments and civil society that secures concrete government commitments to make governance more open, accountable and responsive to citizens"],"correctOption":3,"section":"Open Government Partnerships","explanation":"OGP is a voluntary, multi-stakeholder initiative in which governments work with civil society to make concrete commitments on transparency, participation and accountability. Option A is wrong because OGP is voluntary and is not a sanctions treaty. Options B and C describe completely different kinds of bodies."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 446, $official_bank_source${"itemId":"d46885fb-eee0-53ab-942a-c22ca1f5b64e","questionId":"ba5fea16-d416-5c4a-8159-e4ea9cbcf75b","sourceKey":"bank:BUA205:OGP-002","payload":{"prompt":"The Open Government Partnership was formally launched on 20 September 2011 ____.","options":["on the sidelines of the United Nations General Assembly in New York","at an African Union summit in Addis Ababa","at a G20 summit in London","at a World Bank meeting in Washington"],"correctOption":0,"section":"Open Government Partnerships","explanation":"OGP was launched in New York on the sidelines of the UN General Assembly in September 2011. Options B, C and D name other international meetings and cities that were not where OGP was launched."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 447, $official_bank_source${"itemId":"24529dc6-530b-5316-9341-df0996b8e889","questionId":"6af79691-9f87-5ff3-81bd-317b5253ac06","sourceKey":"bank:BUA205:OGP-003","payload":{"prompt":"How many founding governments launched the Open Government Partnership in 2011?","options":["Four","Eight","Twelve","Twenty"],"correctOption":1,"section":"Open Government Partnerships","explanation":"OGP began with eight founding governments: Brazil, Indonesia, Mexico, Norway, the Philippines, South Africa, the United Kingdom and the United States. Options A, C and D are not the founding number, and membership has since grown far beyond eight."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 448, $official_bank_source${"itemId":"23d9b0d9-fc51-5bf7-8e03-544adb0ac1f2","questionId":"ad17b99e-c8fb-545c-a56a-b1c96cb3fe70","sourceKey":"bank:BUA205:OGP-004","payload":{"prompt":"Which of the following countries was NOT one of the eight founding members of the Open Government Partnership in 2011?","options":["South Africa","Nigeria","Brazil","Indonesia"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Nigeria joined OGP later, in 2016, so it was not a founding member. Options A, C and D were among the eight founders, together with Mexico, Norway, the Philippines, the United Kingdom and the United States."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 449, $official_bank_source${"itemId":"9c827f34-11bb-55a6-8720-050981fd890f","questionId":"56f1e4e5-e573-562c-994e-280773703e3c","sourceKey":"bank:BUA205:OGP-005","payload":{"prompt":"Which African country was among the eight founding members of the Open Government Partnership in 2011?","options":["Nigeria","Kenya","South Africa","Ghana"],"correctOption":2,"section":"Open Government Partnerships","explanation":"South Africa was the only African country among the eight founders. Option A joined in 2016, and neither Option B nor Option D was on the founding list."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 450, $official_bank_source${"itemId":"febb6376-303d-55f1-bda3-10a000cdfc3e","questionId":"257a763d-f3c8-54bf-b3eb-4219802ae4e1","sourceKey":"bank:BUA205:OGP-006","payload":{"prompt":"The document whose principles every OGP participating government must endorse is called the ____.","options":["Universal Declaration of Human Rights","Open Government Declaration","Paris Declaration on Aid Effectiveness","Monrovia Declaration"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Every OGP member must endorse the Open Government Declaration, which sets out the partnership's principles of openness, participation, integrity and technology. Options A, C and D are other international declarations that are not the OGP membership document."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 451, $official_bank_source${"itemId":"0f9150f9-a84d-567f-bc27-a41eb6a8157a","questionId":"deeeafc2-b4c1-5e22-ac78-fa8af2a17627","sourceKey":"bank:BUA205:OGP-007","payload":{"prompt":"Which of the following is NOT among the commitments governments make under the Open Government Declaration?","options":["Increasing the availability of information about government activities","Restricting the activities of civil society organisations","Supporting civic participation","Increasing access to new technologies for openness and accountability"],"correctOption":1,"section":"Open Government Partnerships","explanation":"The Declaration commits governments to more information about government activities, more civic participation, high standards of professional integrity and the use of new technologies for openness. Restricting civil society contradicts all of these. Options A, C and D are genuine commitments."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 452, $official_bank_source${"itemId":"71dc0566-7c5f-5488-87d2-bebc4f3fcca3","questionId":"a3522fa5-390f-54ce-9b62-07c1bccaddef","sourceKey":"bank:BUA205:OGP-008","payload":{"prompt":"Implementing the highest standards of professional integrity throughout government is one of the commitments in the Open Government Declaration. This commitment is MOST directly aimed at ____.","options":["increasing tax rates","reducing the number of elections","expanding the military","fighting corruption"],"correctOption":3,"section":"Open Government Partnerships","explanation":"High standards of integrity, such as codes of conduct, asset disclosure and conflict-of-interest rules, are anti-corruption measures. Options A, B and C have nothing to do with the integrity commitment."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 453, $official_bank_source${"itemId":"34e5c236-1825-50ec-b1e9-c281b5b1a37e","questionId":"469e3669-fcf2-50ce-a428-e355f2a36ffe","sourceKey":"bank:BUA205:OGP-009","payload":{"prompt":"The OGP Steering Committee is composed of ____.","options":["equal numbers of government and civil society representatives","government representatives only","civil society representatives only","World Bank and IMF officials only"],"correctOption":0,"section":"Open Government Partnerships","explanation":"OGP's Steering Committee deliberately has equal numbers of government and civil society members, reflecting the partnership's shared ownership. Options B and C would leave out one of the two partners, and Option D names institutions that do not run OGP."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 454, $official_bank_source${"itemId":"3708dc6f-ef4f-5b4d-a9cd-3e9e1d76baf8","questionId":"74865caf-66f9-5133-8913-20347bf3b44e","sourceKey":"bank:BUA205:OGP-010","payload":{"prompt":"Leadership of the Open Government Partnership rotates every year between co-chairs. These co-chairs consist of ____.","options":["two heads of state","two World Bank directors","two judges of the International Court of Justice","one government co-chair and one civil society co-chair"],"correctOption":3,"section":"Open Government Partnerships","explanation":"OGP is co-chaired each year by one government and one civil society leader, which mirrors the partnership's balance. Options A, B and C do not reflect that structure."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 455, $official_bank_source${"itemId":"425c412a-b732-5947-9c6d-b05c256c107a","questionId":"d4adcbf7-18e6-5c3a-8a92-993cb0d5433d","sourceKey":"bank:BUA205:OGP-011","payload":{"prompt":"The small permanent secretariat that handles OGP's institutional memory, communications and partner relationships is the ____.","options":["Support Unit","Independent Reporting Mechanism","Steering Committee","International Court of Audit"],"correctOption":0,"section":"Open Government Partnerships","explanation":"The Support Unit is OGP's permanent secretariat. Option B produces independent reports on member progress, and Option C is the governing body that guides the initiative. Option D is not part of OGP."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 456, $official_bank_source${"itemId":"6e7e2df8-5aaa-576c-bae8-c432ecbd8f66","questionId":"c3683d6f-bba4-51fa-a21f-3c1168a11202","sourceKey":"bank:BUA205:OGP-012","payload":{"prompt":"The OGP body that produces independent reports assessing how each member government develops and implements its action plan is the ____.","options":["Independent Reporting Mechanism (IRM)","Support Unit","Steering Committee","Values Check"],"correctOption":0,"section":"Open Government Partnerships","explanation":"The IRM is OGP's accountability arm: it independently assesses the design and implementation of action plans and makes technical recommendations. Option B is the secretariat, and Option C is the governing body. Option D is an eligibility test for countries that want to join."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 457, $official_bank_source${"itemId":"d2b86199-6428-55a8-a838-be6acaa5a9a2","questionId":"0f6461ca-1969-597e-a060-5966a75f296c","sourceKey":"bank:BUA205:OGP-013","payload":{"prompt":"Why is the Independent Reporting Mechanism (IRM) important to the credibility of OGP?","options":["It allows governments to grade their own performance without outside review","It collects membership fees from governments","It provides an independent check on whether governments actually deliver the commitments they make","It writes national laws for member countries"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Without independent assessment, governments could make commitments and simply claim success, so the IRM's independent reports give citizens and civil society evidence to hold governments to account. Option A is the opposite of independence. Options B and D are not IRM functions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 458, $official_bank_source${"itemId":"3036a6ea-2c35-588f-b048-952207897625","questionId":"78a00d81-6d95-5a79-918a-676343074d35","sourceKey":"bank:BUA205:OGP-014","payload":{"prompt":"The work of OGP's Independent Reporting Mechanism is overseen by ____.","options":["the President of each member country","the United Nations Security Council","national police forces","an International Experts Panel"],"correctOption":3,"section":"Open Government Partnerships","explanation":"An International Experts Panel oversees the IRM, which helps keep its reports independent of the governments being assessed. Option A would compromise that independence, and Options B and C have no role in OGP."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 459, $official_bank_source${"itemId":"5af8f799-350e-5052-9499-7ba7752a0ae0","questionId":"61cb5e77-3438-5197-b8a4-ab35954ca14d","sourceKey":"bank:BUA205:OGP-015","payload":{"prompt":"The document in which an OGP member government sets out the specific open government commitments it will implement over a fixed period is called a(n) ____.","options":["annual appropriation act","letter of intent","audit report","national action plan"],"correctOption":3,"section":"Open Government Partnerships","explanation":"Members develop national action plans, together with civil society, containing concrete commitments for a set period. Option A is a budget law. Option B is the letter a country sends when it wants to join, and Option C is a financial review."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 460, $official_bank_source${"itemId":"52184b88-5257-536f-91d4-e2746c15d058","questionId":"6891235a-222d-50f1-8ec2-514abdec9561","sourceKey":"bank:BUA205:OGP-016","payload":{"prompt":"In OGP, the process by which government and civil society work together to design the commitments in an action plan is called ____.","options":["privatisation","deregulation","co-creation","centralisation"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Co-creation means government and civil society jointly developing the action plan, rather than government writing it alone. Options A, B and D are unrelated reform terms that do not describe this joint design process."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 461, $official_bank_source${"itemId":"129d76bf-c982-5109-85d1-71705ec68d9e","questionId":"b805ed7a-729a-57ca-ad2b-a983f6c7f953","sourceKey":"bank:BUA205:OGP-017","payload":{"prompt":"In an OGP action plan, a specific, time-bound reform that a government promises to carry out, such as publishing all public contracts online, is called a(n) ____.","options":["eligibility criterion","values check","steering committee","commitment"],"correctOption":3,"section":"Open Government Partnerships","explanation":"Each action plan is made up of commitments, which are concrete reforms that the government promises to deliver. Options A and B are tests used to decide whether a country can join. Option C is a governing body."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 462, $official_bank_source${"itemId":"240afb01-d0fb-5333-9998-22d2d7ab7db1","questionId":"e8be817e-5dfb-5a10-a286-b07d0a5d7768","sourceKey":"bank:BUA205:OGP-018","payload":{"prompt":"To be eligible to join OGP, a country is scored on four areas. These are ____.","options":["fiscal transparency, access to information, asset disclosure by public officials, and citizen engagement","GDP growth, inflation, unemployment and exports","military strength, population, land area and oil reserves","number of universities, hospitals, roads and airports"],"correctOption":0,"section":"Open Government Partnerships","explanation":"OGP's core eligibility criteria measure fiscal transparency, access to information, public officials' asset disclosure and citizen engagement, all of which are basic conditions for open government. Options B, C and D are economic, military or infrastructure measures that OGP does not use."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 463, $official_bank_source${"itemId":"bc03971f-9d55-5870-82e8-56283790fc09","questionId":"b811fb3f-2b4b-5cdd-bffa-108f5a9b945c","sourceKey":"bank:BUA205:OGP-019","payload":{"prompt":"Which of the following is NOT one of the four areas on which countries are scored for OGP eligibility?","options":["Fiscal transparency","Access to information","Citizen engagement","Gross domestic product per capita"],"correctOption":3,"section":"Open Government Partnerships","explanation":"OGP eligibility looks at fiscal transparency, access to information, asset disclosure and citizen engagement, not national income. Options A, B and C are three of the four scored areas."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 464, $official_bank_source${"itemId":"6af6b551-a395-5c94-8652-49e151cfcd12","questionId":"c06e98dc-74ee-54a2-91db-f82341477035","sourceKey":"bank:BUA205:OGP-020","payload":{"prompt":"To meet OGP's core eligibility threshold, a country must score at least what share of the points applicable to it?","options":["50 percent","60 percent","90 percent","75 percent"],"correctOption":3,"section":"Open Government Partnerships","explanation":"The threshold is 75 percent of applicable points, that is 12 of 16, or 9 of 12 where one area is not measured. Options A, B and C are not the OGP threshold."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 465, $official_bank_source${"itemId":"9d7393f3-6f3e-52c1-bab7-56bc4fdcfead","questionId":"3900d174-0ef5-5814-91ef-a40511536020","sourceKey":"bank:BUA205:OGP-021","payload":{"prompt":"Under OGP's access-to-information eligibility criterion, which situation earns a country the MAXIMUM points?","options":["Having only a draft access to information bill under consideration","Having no law but promising to publish some documents","Having a law that makes all government information secret","Having an access to information (freedom of information) law in force"],"correctOption":3,"section":"Open Government Partnerships","explanation":"A country with an access to information law in force earns the full 4 points. A constitutional guarantee alone earns 3 and a draft law under consideration earns only 1, so Option A scores much lower. Options B and C earn nothing."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 466, $official_bank_source${"itemId":"9b10af94-9d26-5697-8a64-71848dbcb73d","questionId":"d5d2b6e4-6ae4-56e8-add4-19db0b10850e","sourceKey":"bank:BUA205:OGP-022","payload":{"prompt":"Nigeria's Freedom of Information Act, which supports the access-to-information area of OGP eligibility, was signed into law in ____.","options":["2011","1999","2004","2016"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Nigeria's Freedom of Information Act was signed in 2011, and having such a law in force earns the maximum access-to-information points in OGP eligibility. Option B is the year of the current Constitution, and Option C is unrelated. Option D is the year Nigeria joined OGP, not the year the Act was passed."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 467, $official_bank_source${"itemId":"41761a30-787f-5c72-8929-c2ab94aca956","questionId":"0efb0ad8-f5da-525d-b4ab-61c8c18755d7","sourceKey":"bank:BUA205:OGP-023","payload":{"prompt":"Under OGP's asset disclosure eligibility criterion, a country earns the MAXIMUM points when ____.","options":["officials disclose assets but the information is kept secret","there is no law on asset disclosure","public officials are required by law to disclose their assets and the information is made public","only private company directors disclose assets"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Full points go to countries where officials must file asset declarations and those declarations are public. Option A earns only partial points because the information is not public, and Option B earns none. Option D is not about public officials at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 468, $official_bank_source${"itemId":"62323bf1-655a-5e0c-9900-55f81230a440","questionId":"d29ff9f6-f46c-5067-9790-4d04c9ddd2be","sourceKey":"bank:BUA205:OGP-024","payload":{"prompt":"In addition to the core eligibility criteria, a country seeking to join OGP must pass a 'Values Check'. This check mainly assesses ____.","options":["whether the country's currency is stable","whether civil society can operate freely in the country (civic space)","whether the country has a seaport","whether the country's leader is popular"],"correctOption":1,"section":"Open Government Partnerships","explanation":"The Values Check looks at civic space, meaning whether civil society organisations can form, operate and avoid repression, because OGP depends on government and civil society working together. Options A, C and D are not what the Values Check measures."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 469, $official_bank_source${"itemId":"ed29341d-4f7a-50de-b62e-1962028a4896","questionId":"7099c342-21fc-50a5-81b8-b80576e18f66","sourceKey":"bank:BUA205:OGP-025","payload":{"prompt":"To join OGP, a government that meets the eligibility requirements must submit ____.","options":["a payment equal to one percent of its national budget","a letter from a minister confirming agreement with the Open Government Declaration and intent to participate, naming a lead agency and a point of contact","a request approved by the UN Security Council","a copy of its national football team registration"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Joining requires a letter of intent from a minister endorsing the Open Government Declaration and identifying a lead agency and contact point. Options A, C and D are not OGP requirements."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 470, $official_bank_source${"itemId":"6aa87aef-d41e-5898-a5b8-af8e05d7d795","questionId":"e0570677-c56a-5d81-98ba-71e26f2b66aa","sourceKey":"bank:BUA205:OGP-027","payload":{"prompt":"Nigeria's decision to join OGP in 2016 followed commitments that President Buhari reiterated at which international event in May 2016?","options":["The Rio Earth Summit","The London Anti-Corruption Summit","The Paris Climate Conference","The Commonwealth Games"],"correctOption":1,"section":"Open Government Partnerships","explanation":"Nigeria joined OGP after commitments made at the Abuja Anti-Corruption Summit and reiterated by President Buhari at the London Anti-Corruption Summit in May 2016. Options A, C and D are unrelated international events."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 471, $official_bank_source${"itemId":"2e8a2e3b-8178-51c3-9f59-560f60354a2e","questionId":"6103cb25-97e4-5c46-a19d-2d5d561fe008","sourceKey":"bank:BUA205:OGP-028","payload":{"prompt":"Nigeria's FIRST OGP national action plan covered which period?","options":["2011-2013","2016-2017","2017-2019","2023-2025"],"correctOption":2,"section":"Open Government Partnerships","explanation":"Nigeria's first national action plan ran from 2017 to 2019, after it joined OGP in 2016. Option A predates Nigeria's membership, and Option B is not a plan period. Option D is the period of Nigeria's third plan."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 472, $official_bank_source${"itemId":"85a2c4dd-3e06-54d9-82c7-9f52ad210cc2","questionId":"4bf30645-b784-5420-af04-4605e1f21040","sourceKey":"bank:BUA205:OGP-031","payload":{"prompt":"Which of the following Nigerian subnational governments joined OGP's local programme in 2018?","options":["Lagos State","Kano State","Rivers State","Kaduna State"],"correctOption":3,"section":"Open Government Partnerships","explanation":"Kaduna State joined OGP's local programme in 2018, and Plateau State and Abuja followed in 2020. Options A, B and C are not listed as OGP local members as at October 2026."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 473, $official_bank_source${"itemId":"fe46746e-b5ae-5a88-8705-2c4b53dfc4b1","questionId":"179b9897-e930-5638-9493-50fab62d41f3","sourceKey":"bank:BUA205:OGP-032","payload":{"prompt":"One commitment Nigeria made in 2016, and which was expected to feature in its OGP action plan, was to create a public central register of company beneficial ownership. Such a register shows ____.","options":["the names of all employees in every company","the prices of goods sold by companies","the real people who ultimately own or control companies","the number of branches each company operates"],"correctOption":2,"section":"Open Government Partnerships","explanation":"A beneficial ownership register reveals who ultimately owns or controls a company, which makes it harder to hide stolen money or conflicts of interest behind shell companies. Options A, B and D are ordinary business data, not ownership information."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 474, $official_bank_source${"itemId":"b6752390-9ac9-57e8-96c2-9117136ab0de","questionId":"ed11676d-9833-5eaf-8b24-90317b7c2f1c","sourceKey":"bank:BUA205:OGP-033","payload":{"prompt":"Nigeria committed in 2016 to fully implement the Open Contracting Data Standard. Open contracting MAINLY means ____.","options":["publishing information and data about public contracts across the whole procurement process","awarding contracts without any competition","allowing only foreign firms to bid","keeping contract prices secret to protect suppliers"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Open contracting means publishing data at every stage of public contracting, from planning and tender to award and implementation, so that citizens can follow how public money is spent. Options B, C and D reduce openness or fairness instead."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 475, $official_bank_source${"itemId":"02979116-f35f-5e80-ae6d-d650335f43fd","questionId":"60d1715f-3ddc-5017-91f6-3cfd403512ac","sourceKey":"bank:BUA205:OGP-034","payload":{"prompt":"Nigeria's 2016 anti-corruption commitments linked to OGP included greater disclosure by companies of payments made to government for oil, gas and mineral sales. This complements the work of ____.","options":["the Extractive Industries Transparency Initiative (EITI)","the Nigerian Football Federation","the West African Examinations Council","the Nigerian Meteorological Agency"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Disclosure of payments from extractive companies to government is the core business of EITI, which Nigeria implements through NEITI. Options B, C and D are Nigerian bodies with no role in extractive revenue transparency."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 476, $official_bank_source${"itemId":"9fd17b29-d9b9-5877-a918-acdd591cf39e","questionId":"06a3775a-2dae-5ef8-a1a9-cf6cabcfb237","sourceKey":"bank:BUA205:OGP-035","payload":{"prompt":"Which of the following is NOT a realistic benefit of a country's participation in the Open Government Partnership?","options":["Greater citizen access to government information","Automatic cancellation of all the country's foreign debts","Peer learning from other member governments","Stronger public accountability through independent assessment"],"correctOption":1,"section":"Open Government Partnerships","explanation":"OGP brings more openness, peer learning and independent review of reforms, but it is not a debt relief scheme. Options A, C and D are genuine benefits that follow from action plans, the international network and the IRM."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 477, $official_bank_source${"itemId":"b2ebda69-c154-5083-8788-9dd47f012f83","questionId":"098d1fca-7e2f-5a6d-a207-81102bd16a3f","sourceKey":"bank:BUA205:OGP-036","payload":{"prompt":"Under its OGP action plan, a state government publishes its full budget and monthly spending online, and civil society groups use the data to question a road contract. This MAINLY illustrates which OGP aim?","options":["Using transparency to empower citizens to hold government accountable","Concentrating decision-making in the governor's office","Reducing the number of civil society groups","Replacing elections with online surveys"],"correctOption":0,"section":"Open Government Partnerships","explanation":"OGP's core idea is that openness, here published budget and spending data, lets citizens and civil society scrutinise government and demand accountability. Options B and C run against open government. Option D misreads participation as the abolition of elections."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 478, $official_bank_source${"itemId":"908df87b-1226-5463-ba73-dfabb9191be7","questionId":"a32825ad-a2d0-5edf-992e-08cf7b58960d","sourceKey":"bank:BUA205:OGP-037","payload":{"prompt":"Which set of ideas BEST captures the core values that the Open Government Partnership promotes?","options":["Secrecy, centralisation, loyalty and control","Transparency, civic participation, public accountability, and technology and innovation for openness","Privatisation, deregulation, tariffs and subsidies","Military strength, territorial expansion and censorship"],"correctOption":1,"section":"Open Government Partnerships","explanation":"OGP promotes transparency, citizen participation and accountability, supported by technology and innovation. Option A is the opposite of open government. Option C is a set of economic policy tools, and Option D is incompatible with OGP's values."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 479, $official_bank_source${"itemId":"cef9f6f4-2fad-5f83-8614-0fbd0f5e4a4d","questionId":"8fbf06a2-f62e-5c24-8674-f698ed089810","sourceKey":"bank:BUA205:OGP-038","payload":{"prompt":"A Nigerian civil society coalition helps draft commitments for the national OGP action plan and later monitors whether the agencies deliver them. Its role BEST reflects OGP's principle that ____.","options":["only government officials may take part in OGP processes","civil society must stay out of public policy","government and civil society work as partners in designing and monitoring reforms","OGP commitments are kept confidential from citizens"],"correctOption":2,"section":"Open Government Partnerships","explanation":"OGP is built on government and civil society partnership: they co-create action plans together, and civil society monitors delivery. Options A and B exclude civil society, and Option D contradicts OGP's emphasis on openness."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 480, $official_bank_source${"itemId":"ad7df74f-ba68-5039-afee-ab1517a58762","questionId":"14711143-a5d9-5de4-a5e2-fbb0ea6233dc","sourceKey":"bank:BUA205:OGP-039","payload":{"prompt":"Each of the four OGP eligibility areas carries a maximum of 4 points. What is the maximum total eligibility score for a country measured in all four areas?","options":["16 points","4 points","12 points","20 points"],"correctOption":0,"section":"Open Government Partnerships","explanation":"Four areas worth up to 4 points each give a maximum of 16, and a country needs at least 12 of them, which is 75 percent. Option B is the maximum for a single area. Option C is either the pass mark out of 16 or the maximum when one area is not measured, and Option D is not possible."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 481, $official_bank_source${"itemId":"aa201ec8-ac30-5e61-8a28-59be81773d45","questionId":"fcc7043c-1fff-5ced-ac8d-82ea82c940cb","sourceKey":"bank:BUA205:PQ-084","payload":{"prompt":"When initiating a public sector reform, it helps to appoint a __________________ responsible for day-to-day coordination and reporting.","options":["Decentralized audit unit","Temporary political taskforce","Ceremonial oversight body","Central reform secretariat"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Reform programmes usually set up a central reform secretariat or coordinating unit to manage day-to-day coordination, track progress and report to the leadership driving the reform. Option B is short-lived and political, while A and C would not give one clear point of continuous coordination."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 482, $official_bank_source${"itemId":"83c73cb6-cdb8-5c47-bdef-ad4366e2f085","questionId":"497cc339-ed95-5dd7-bdce-047f712ac7bf","sourceKey":"bank:BUA205:PQ-172","payload":{"prompt":"The effectiveness of a public sector reform increases when its implementation timelines are:","options":["Realistic","Unrealistic","Undefined","Arbitrary"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Realistic timelines match a reform's goals with the time, money and staff capacity actually available, so milestones can be met and progress tracked. Unrealistic deadlines (option B) lead to rushed or abandoned implementation, while undefined or arbitrary timelines (options C and D) make planning and monitoring impossible."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 483, $official_bank_source${"itemId":"4ccd79ce-f4e4-5e5e-8827-59877aad8221","questionId":"17123e60-317f-5eca-9676-a0a7840da1aa","sourceKey":"bank:BUA205:PQ-228","payload":{"prompt":"The primary objective of public sector reform is to:","options":["Reduce the size of government to eliminate all social programmes","Replace elected officials with technocratic managers","Improve the efficiency, effectiveness, accountability and responsiveness of government institutions and services","Transfer all public services to the private sector"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Public sector reforms are deliberate changes, such as restructuring, digitalisation and anti-corruption measures, meant to make government work better and deliver better services to citizens. Privatisation and downsizing can be tools of reform, but eliminating all social programmes (option A) or transferring every service (option D) are not the goal, and option B would undermine democracy."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 484, $official_bank_source${"itemId":"696958eb-9583-5eed-ab06-dd00c27e2c19","questionId":"fcb10414-0232-5438-a52d-021f7f546b09","sourceKey":"bank:BUA205:PQ-229","payload":{"prompt":"Which of the following is the FIRST critical step in initiating a public sector reform?","options":["Comprehensive diagnosis and problem identification, including stakeholder consultations","Hiring international consultants to design the reform blueprint","Immediate restructuring of all government ministries","Passing new legislation without prior assessment"],"correctOption":0,"section":"Public Sector Reforms","explanation":"A reform must start by understanding exactly what is wrong, why, and who is affected, because solutions designed without a clear diagnosis rarely fit local problems. Restructuring (option C) or new laws (option D) before assessment put action before understanding, and relying on outside consultants (option B) risks imported blueprints that do not fit the context."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 485, $official_bank_source${"itemId":"bccabc5f-47fc-51c1-a8e9-0654ff956bf2","questionId":"ea1de627-2261-5677-8e22-5d96b48b1b21","sourceKey":"bank:BUA205:PQ-230","payload":{"prompt":"A feature of a successful public sector reform is:","options":["Top-down imposition without consultation with affected stakeholders","Strong political will, clear leadership, broad stakeholder buy-in and sustained implementation commitment","Complete outsourcing of reform design to external consultants","Rapid implementation within a single budget cycle"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Reforms succeed when leaders are committed, the affected groups support the changes, and implementation is sustained long enough to change how institutions work. Lack of political will and resistance to change are common reasons reforms fail. Option A provokes resistance, option D is usually unrealistic, and option C weakens local ownership."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 486, $official_bank_source${"itemId":"39045d9e-0bf3-51c1-9723-edde993e88ec","questionId":"7fd8195c-996c-5ae4-a71c-403e53d999c1","sourceKey":"bank:BUA205:PQ-231","payload":{"prompt":"New Public Management (NPM) as a reform approach advocates:","options":["Eliminating all performance targets in the civil service","Expanding bureaucracy and centralising all decision-making","Restricting access to government services to reduce operational costs","Applying private sector management techniques to improve efficiency in public administration"],"correctOption":3,"section":"Public Sector Reforms","explanation":"NPM brings business-style practices into government, such as results-based management, performance contracts, competition and contracting out services, to make public administration more efficient and results-focused. Option B is the rigid bureaucracy NPM reacts against, and options A and C contradict its emphasis on performance and service."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 487, $official_bank_source${"itemId":"86d28564-d23b-5667-baeb-2fe25ce9f6eb","questionId":"ed268dd8-2241-58f4-8d2b-2f6008952dd8","sourceKey":"bank:BUA205:PQ-232","payload":{"prompt":"Which of the following is a supporting condition necessary for public sector reforms to succeed?","options":["Isolation from international best practices and peer learning","A politically neutral and capable civil service with reform capacity","Complete suppression of trade unions during reform implementation","Monopoly of the reform agenda by the presidency"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Reforms are carried out by public servants, so they need a professional, merit-based civil service with the skills and training to implement change. Option D removes broad ownership of the reform, option C breeds conflict and resistance, and option A cuts reformers off from useful lessons."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 488, $official_bank_source${"itemId":"1d51806f-b298-5efc-a5f2-fa6910aab91d","questionId":"1a366fbd-f9ad-5e7e-a1dd-576db9b629fe","sourceKey":"bank:BUA205:PQ-233","payload":{"prompt":"An appropriate tool to measure the effectiveness of a public sector reform programme is:","options":["The volume of legislation passed during the reform period","Independently verified performance indicators (KPIs), citizen satisfaction surveys and audit reports","Media sentiment analysis of government press releases","The personal judgment of the minister in charge"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Reform effectiveness should be measured objectively, using indicators such as revenue collected, service speed and quality, audited financial results and feedback from the citizens who use the services. A minister's opinion (option D) is not independent, and the number of laws passed (option A) or reactions to press releases (option C) measure activity or publicity rather than results."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 489, $official_bank_source${"itemId":"41d77ba2-88d2-56cb-bea0-e68c0c4660a5","questionId":"9935a5d8-6d88-57b6-9d85-4e93ced23a1a","sourceKey":"bank:BUA205:PQ-234","payload":{"prompt":"Nigeria's Integrated Payroll and Personnel Information System (IPPIS), introduced by the federal government in the mid-2000s, is an example of:","options":["A public sector reform tool aimed at eliminating ghost workers and improving payroll transparency","A private sector HR management platform","A civil society initiative to improve education funding","An international debt management initiative by the World Bank"],"correctOption":0,"section":"Public Sector Reforms","explanation":"IPPIS is a federal government digital payroll system that keeps personnel records and pays staff centrally, so that fictitious 'ghost workers' can be detected and removed and salary costs controlled. It is run by government, not civil society (option C) or a private company (option B), and although the World Bank helped fund its pilot, it is not a debt management scheme (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 490, $official_bank_source${"itemId":"17cf9ca1-a391-516c-b586-4f8bf73bc6d1","questionId":"077fa701-eeb3-5a50-be5e-56adfaac4cfe","sourceKey":"bank:BUA205:PQ-235","payload":{"prompt":"Which reform model focuses on building collaborative networks of public, private and civil society actors in service delivery?","options":["Traditional/Weberian bureaucratic model","Scientific management (Taylorism)","New Public Governance (NPG) model","Centralised command-and-control governance"],"correctOption":2,"section":"Public Sector Reforms","explanation":"New Public Governance sees public services as delivered through partnerships and networks in which government works with businesses, NGOs and communities. The Weberian model (option A) and command-and-control governance (option D) rely on hierarchy within government, and Taylorism (option B) is about scientific work methods, not collaboration."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 491, $official_bank_source${"itemId":"e50cc2ea-4079-5781-8fac-bb166f970bdb","questionId":"af296c4d-04c9-598d-9b84-08d641f9f0a5","sourceKey":"bank:BUA205:PQ-242-a","payload":{"prompt":"Which approach to public sector reform focuses on solving specific local problems through step-by-step experimentation rather than copying 'best practice' blueprints?","options":["Weberian bureaucracy","Wholesale privatisation","Problem-Driven Iterative Adaptation (PDIA)","New Public Management (NPM)"],"correctOption":2,"section":"Public Sector Reforms","explanation":"PDIA starts from a locally defined problem, tries out solutions, learns from the results and adapts, so reforms fit the real context instead of importing foreign templates. New Public Management (option D) applies private sector techniques, Weberian bureaucracy (option A) relies on fixed rules and hierarchy, and wholesale privatisation (option B) transfers services to private owners."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 492, $official_bank_source${"itemId":"52003154-a0a4-5f05-b5d6-762817dd97ab","questionId":"85d29e79-a115-54c6-ad59-91f6a12c8b75","sourceKey":"bank:BUA205:PQ-242-b","payload":{"prompt":"Which of the following is NOT a feature of a successful public sector reform?","options":["Retaining rigid, rule-bound procedures regardless of citizens' needs","Digital transformation of government processes","Merit-based recruitment and performance management","A citizen-centred focus on improved service delivery"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Successful reforms aim to turn rigid, rule-based administrations into flexible institutions that deliver better value to citizens, so keeping rigid procedures regardless of need is the opposite of reform. Citizen-centred service delivery, digital transformation and professionalisation through merit and performance management (options D, B and C) are all features of successful reform."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 493, $official_bank_source${"itemId":"be72638d-d57e-51c7-b106-6757869d5bf0","questionId":"cc2a8dd1-c0bf-5f2c-89cb-923e45b1bd41","sourceKey":"bank:BUA205:PQ-242-c","payload":{"prompt":"Nigeria's Treasury Single Account (TSA), which federal ministries, departments and agencies were directed to adopt in 2015, was mainly designed to:","options":["Allow each agency to keep its revenue in multiple commercial bank accounts","Replace the Central Bank of Nigeria as the government's banker","Pay federal workers' salaries directly from World Bank funds","Consolidate government revenues into a single account to improve oversight and reduce leakages"],"correctOption":3,"section":"Public Sector Reforms","explanation":"The TSA brings federal government revenues into a unified account structure so that the government can see and control all its cash, reducing hidden accounts, leakages and idle funds. Option A describes the fragmented system the TSA replaced, the TSA is operated with the Central Bank rather than replacing it (option B), and it has nothing to do with World Bank salary payments (option C)."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 494, $official_bank_source${"itemId":"a1cc8ba1-09c0-5869-ba84-5f9dc4b97cba","questionId":"ed17b073-3b8d-5d72-a03d-ed9f5a780910","sourceKey":"bank:BUA205:PQ-242-d","payload":{"prompt":"Nigeria's Government Integrated Financial Management Information System (GIFMIS) is mainly used as a reform tool to:","options":["Issue national identity numbers to citizens","Regulate the prices of goods in public markets","Register voters for national elections","Improve budgetary control and financial management across government"],"correctOption":3,"section":"Public Sector Reforms","explanation":"GIFMIS is an IT-based public financial management system that records government spending against the budget and improves financial reporting, so its results can be used to judge whether financial management reforms are working. Voter registration (option C), national identity numbers (option A) and market price regulation (option B) are handled by other bodies and systems."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 495, $official_bank_source${"itemId":"231c8adf-4343-517f-a028-8710dc7fa86e","questionId":"30cc3dd7-9e75-55dd-a86d-5c796dd35f8a","sourceKey":"bank:BUA205:PQ-242-e","payload":{"prompt":"Which of the following commonly limits the success of public sector reforms?","options":["Strong citizen support for the reform","Continuous training of public servants","A clear and coherent reform strategy","Lack of political will and resistance to change"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Reforms often stall when leaders lack the commitment to see them through and when officials or interest groups who benefit from the old system resist change. Citizen support, continuous training and a clear strategy (options A, B and C) are conditions that help reforms succeed rather than obstacles."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 496, $official_bank_source${"itemId":"06c84e8c-2fc7-57f7-be30-38b568cd31e7","questionId":"629fffeb-44e3-5a4b-8376-d2b206c97d04","sourceKey":"bank:BUA205:PSR-001","payload":{"prompt":"Deliberate, multifaceted initiatives designed to improve the efficiency, effectiveness, transparency and accountability of government machinery, in order to boost service delivery and institutional performance, are called ____.","options":["Public sector reforms","Monetary policies","Corporate mergers","Electoral reforms only"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Public sector reforms are planned, many-sided changes to how government works, aimed at better service delivery and institutional performance. Option B concerns money supply and interest rates. Option C is a private-sector transaction, and Option D covers only one narrow area of reform."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 497, $official_bank_source${"itemId":"38982885-cf2a-5729-ab8e-b8c3ac329ebf","questionId":"2ce780bf-94f9-58b2-99d5-1894883c2275","sourceKey":"bank:BUA205:PSR-002","payload":{"prompt":"The success of public sector reforms depends heavily on ____.","options":["the number of new ministries created","implementation and political will","foreign media coverage","the age of the head of service"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Reforms often look good on paper, but their success depends on how well they are implemented and on sustained political will. Options A, C and D are not recognised determinants of reform success."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 498, $official_bank_source${"itemId":"146d0f6d-74b9-5b26-b56f-c578321d33d2","questionId":"41527c36-aebc-573e-8327-b594c587816b","sourceKey":"bank:BUA205:PSR-003","payload":{"prompt":"Which of the following is NOT one of the major types of public sector reform initiative?","options":["Administrative and civil service restructuring","Digital transformation (e-governance)","Public-private partnerships","Abolition of the civil service"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Major reform types include civil service restructuring, e-governance, stronger financial management, anti-corruption measures and public-private partnerships. Reform aims to improve the civil service, not to abolish it. Options A, B and C are recognised types of reform."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 499, $official_bank_source${"itemId":"cddab973-8f84-5609-9a29-7ec9590c5995","questionId":"58e45936-0e50-5fb0-853a-6f69329bcda2","sourceKey":"bank:BUA205:PSR-004","payload":{"prompt":"The introduction of 'due process' mechanisms in public procurement is a reform that mainly drives performance through ____.","options":["increasing contract prices","reducing the number of bidders","transparency and accountability","centralising contract awards in one person"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Due process rules make procurement open and rule-based, which curbs corruption and improves accountability. Options A, B and D would weaken value for money and fairness rather than improve them."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 500, $official_bank_source${"itemId":"3bdf1623-6a61-5933-bbdd-355435453a0b","questionId":"4cc2eb9a-bdec-51ad-bbce-064028b651b7","sourceKey":"bank:BUA205:PSR-005","payload":{"prompt":"Re-professionalisation and training of public employees, which enhance professionalism and service delivery, are reform performance drivers classified under ____.","options":["digitalisation","privatisation","capacity building","decentralisation of revenue"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Training and re-professionalising staff is capacity building, which raises the skills and professionalism of the workforce. Option A is about technology systems, and Option B transfers enterprises to private owners. Option D is a fiscal arrangement."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 501, $official_bank_source${"itemId":"8a614a68-2df9-59d2-8006-18fbeb0b6085","questionId":"48c6a9fe-74bd-5a09-bfd8-4c1dad48a04b","sourceKey":"bank:BUA205:PSR-006","payload":{"prompt":"Which of the following is NOT a common obstacle limiting the success of public sector reforms?","options":["Strong and sustained political will","Political instability","Lack of clear strategies","Resistance to change"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Political instability, unclear strategies and resistance to change are common obstacles to reform. Strong political will is a condition for success, not an obstacle. Options B, C and D are the recognised challenges."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 502, $official_bank_source${"itemId":"76abf2ec-9a6a-5acd-af5d-001d45e005b4","questionId":"deff778d-f968-56b1-b179-a6a51a00bcd4","sourceKey":"bank:BUA205:PSR-007","payload":{"prompt":"Successful public sector reforms are characterised by a shift towards ____.","options":["citizen-centric service delivery","more rigid bureaucracy","secret decision-making","longer approval chains"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Successful reforms move from rigid, rule-bound bureaucracy towards user-friendly, citizen-centred services, with more transparency and efficiency. Options B, C and D describe the traditional problems that reforms try to fix."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 503, $official_bank_source${"itemId":"21b2dc1b-30b4-5a08-a641-2f52f3195d14","questionId":"2194579d-aae7-567f-bc11-58d29369310d","sourceKey":"bank:BUA205:PSR-008","payload":{"prompt":"A state government opens centres where citizens can register businesses, renew licences and obtain birth certificates under one roof instead of visiting several ministries. This BEST illustrates which feature of a successful reform?","options":["Organisational right-sizing","Problem-Driven Iterative Adaptation","Privatisation of public enterprises","Citizen-centric focus and improved service delivery (one-stop shops)"],"correctOption":3,"section":"Public Sector Reforms","explanation":"One-stop shops, such as Kenya's Huduma Centres, put citizens' convenience at the centre of service delivery. Option A is about cutting excess staff and ghost workers, and Option B is an experimental, problem-solving method of reform. Option C transfers ownership to private investors."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 504, $official_bank_source${"itemId":"8ea680f5-3967-59e3-9e36-ac5a5823866b","questionId":"d0baa54f-8c5a-5bd9-a2a4-c845a2d37f2f","sourceKey":"bank:BUA205:PSR-009","payload":{"prompt":"Huduma Centres, often cited as an example of citizen-centric one-stop shops for public services, are found in ____.","options":["Nigeria","Ghana","South Africa","Kenya"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Huduma Centres are Kenya's one-stop public service centres, used as an example of citizen-centric reform. Options A, B and C are other African countries that are not where these centres operate."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 505, $official_bank_source${"itemId":"45fbc60b-1997-5503-a0a7-e9413d6974bf","questionId":"fc78215f-392b-5a89-ad4a-536f80570e30","sourceKey":"bank:BUA205:PSR-010","payload":{"prompt":"Adopting private-sector practices in government, such as results-based management, performance contracting and contracting out services to create competition, is known as ____.","options":["New Public Management (NPM) techniques","Traditional bureaucracy","Feudalism","Command economy planning"],"correctOption":0,"section":"Public Sector Reforms","explanation":"New Public Management borrows private-sector tools such as results-based management, performance contracts and competition through contracting out. Option B is the rule-bound model that NPM tried to change. Options C and D are unrelated systems."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 506, $official_bank_source${"itemId":"dab23ea5-0504-5269-ac86-a77b1ec7a2ae","questionId":"06f41db0-aeff-5415-9824-458d83a032be","sourceKey":"bank:BUA205:PSR-011","payload":{"prompt":"A ministry signs agreements with its directors that set measurable targets for the year, and each director's continued appointment depends on meeting them. This NPM technique is called ____.","options":["performance contracting","right-sizing","e-governance","beneficial ownership disclosure"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Performance contracting ties managers to agreed, measurable targets and links their accountability to results. Option B reduces staff numbers or agencies, and Option C moves services onto digital platforms. Option D reveals who owns companies."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 507, $official_bank_source${"itemId":"44b9ddf0-b781-5f72-adeb-b3f328d2377d","questionId":"2ac80fbe-02d4-5b1f-8a85-ae8ae1504cbe","sourceKey":"bank:BUA205:PSR-012","payload":{"prompt":"Eliminating ghost workers, rationalising government agencies and streamlining processes to reduce costs is a reform feature known as ____.","options":["citizen-centric focus","digital transformation","organisational restructuring and right-sizing","inspirational motivation"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Right-sizing and restructuring cut waste, such as ghost workers and duplicated agencies, so that government runs at a sensible cost. Option A is about putting service users first, and Option B is about moving to digital platforms. Option D is a leadership concept."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 508, $official_bank_source${"itemId":"997ae780-8337-5fc8-bc0f-80215da7e0f5","questionId":"126ae0f5-69c0-5eb4-97fb-e6cd495968a1","sourceKey":"bank:BUA205:PSR-013","payload":{"prompt":"In public sector reform, a 'ghost worker' is ____.","options":["an employee who works night shifts","a contract worker hired through an agency","a retired officer receiving a legitimate pension","a name on the government payroll that does not correspond to a real, working employee"],"correctOption":3,"section":"Public Sector Reforms","explanation":"Ghost workers are fictitious or non-working names on the payroll whose salaries are stolen, and reforms such as IPPIS target them. Options A, B and C are all legitimate categories of workers or pensioners."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 509, $official_bank_source${"itemId":"6a4c82ad-76da-5ead-b037-8c2d83048bfa","questionId":"59cf8552-46f7-5e10-ad64-940b018cd17d","sourceKey":"bank:BUA205:PSR-014","payload":{"prompt":"Retraining staff, hiring on merit and using open performance appraisals are reform features grouped under ____.","options":["privatisation","decentralisation","professionalisation and performance management","Problem-Driven Iterative Adaptation"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Professionalisation and performance management build a competent, merit-based workforce held accountable through open appraisal. Option A transfers ownership of enterprises, and Option B shifts authority to lower levels. Option D is an approach to solving local problems through experimentation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 510, $official_bank_source${"itemId":"367bc304-fe2b-561c-b922-1a72a167ac38","questionId":"13b6bc93-ebcd-5763-921c-4823f943b632","sourceKey":"bank:BUA205:PSR-015","payload":{"prompt":"In public sector reform, PDIA stands for ____.","options":["Public Debt and Investment Analysis","Planned Development and Infrastructure Agenda","Performance Data and Internal Audit","Problem-Driven Iterative Adaptation"],"correctOption":3,"section":"Public Sector Reforms","explanation":"PDIA stands for Problem-Driven Iterative Adaptation, a step-by-step reform approach. Options A, B and C are invented expansions that sound plausible but do not exist as this reform approach."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 511, $official_bank_source${"itemId":"bd058226-6494-5def-bc28-0642bfe4c5fd","questionId":"2111ef31-5c74-596c-9b0b-31ba87e64ec5","sourceKey":"bank:BUA205:PSR-016","payload":{"prompt":"Problem-Driven Iterative Adaptation (PDIA) is an approach to reform that ____.","options":["copies successful reforms from other countries without change","solves specific local problems step by step through experimentation, rather than copying 'best practice' blueprints","implements all reforms at once in a single big-bang programme","leaves reform decisions entirely to foreign consultants"],"correctOption":1,"section":"Public Sector Reforms","explanation":"PDIA starts from a concrete local problem and tries, learns and adapts in small steps, because imported blueprints may not fit the context. Option A is exactly what PDIA warns against. Option C is the opposite of iterative, and Option D ignores local ownership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 512, $official_bank_source${"itemId":"b277dd75-ed8f-5c48-a236-88f84a72b911","questionId":"80d86591-234c-5844-aa76-5554b0c449a0","sourceKey":"bank:BUA205:PSR-017","payload":{"prompt":"Instead of adopting a foreign model wholesale, a state ministry of education tests three small changes in a few schools to reduce teacher absenteeism, keeps what works and adjusts the rest. This BEST illustrates ____.","options":["New Public Management contracting out","Treasury Single Account","Problem-Driven Iterative Adaptation (PDIA)","Right-sizing"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Testing small solutions to a specific local problem and adapting them based on results is the essence of PDIA. Option A hands services to outside providers. Option B is a cash-management reform, and Option D cuts staff or agencies."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 513, $official_bank_source${"itemId":"486e8f2c-d7a0-5136-8b8a-89408b3b5444","questionId":"4fb025cc-b7eb-5fac-a24a-2709f1815c98","sourceKey":"bank:BUA205:PSR-018","payload":{"prompt":"IPPIS, a key Nigerian public sector reform tool, stands for ____.","options":["Integrated Payroll and Personnel Information System","Internal Public Procurement Inspection Service","Integrated Public Pension Investment Scheme","Independent Personnel Performance Inspection Scheme"],"correctOption":0,"section":"Public Sector Reforms","explanation":"IPPIS is the Integrated Payroll and Personnel Information System, which centralises federal payroll and personnel records. Options B, C and D are invented names that sound similar but do not exist."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 514, $official_bank_source${"itemId":"fc1b91d8-5384-518c-afcc-4dfd248c302d","questionId":"be4a05c2-a736-5870-b2b3-f7282ba93309","sourceKey":"bank:BUA205:PSR-019","payload":{"prompt":"The main purpose of Nigeria's IPPIS is to ____.","options":["keep accurate personnel records and payroll, helping to detect and eliminate ghost workers","collect value added tax from companies","conduct national elections","regulate commercial banks"],"correctOption":0,"section":"Public Sector Reforms","explanation":"IPPIS keeps payroll and personnel records accurate in one system, which exposes ghost workers and reduces payroll fraud. Option B is the work of the tax authority, Option C is the electoral commission's job, and Option D is the central bank's role."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 515, $official_bank_source${"itemId":"8655205a-6dbd-5648-9f71-4f6ded796489","questionId":"fd03c74d-33aa-557c-adac-cfcee699a0b8","sourceKey":"bank:BUA205:PSR-020","payload":{"prompt":"Nigeria's IPPIS project went live in April 2007 with a pilot covering how many federal MDAs?","options":["Two","Fifty","All federal MDAs at once","Seven"],"correctOption":3,"section":"Public Sector Reforms","explanation":"IPPIS went live in April 2007 with seven pilot MDAs and was then extended to more agencies over time. Options A and B are wrong figures. Option C ignores the phased roll-out."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 516, $official_bank_source${"itemId":"063fd814-20a5-5461-a96b-900c49c5f17d","questionId":"0067dd09-d823-57a4-8da2-c5e1cb5e0f1b","sourceKey":"bank:BUA205:PSR-021","payload":{"prompt":"Since October 2008, IPPIS has been managed by which Nigerian federal office?","options":["The Independent National Electoral Commission","The Nigerian Communications Commission","The Office of the Accountant-General of the Federation","The National Population Commission"],"correctOption":2,"section":"Public Sector Reforms","explanation":"The Office of the Accountant-General of the Federation took over management of IPPIS in October 2008, which fits its role over federal payments. Options A, B and D are federal bodies with unrelated mandates."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 517, $official_bank_source${"itemId":"d605bbde-1594-5f91-b326-34e33dde3d8f","questionId":"3b391ba0-e67a-5a9e-9b69-e5ef5273c99f","sourceKey":"bank:BUA205:PSR-022","payload":{"prompt":"GIFMIS, a Nigerian public financial management reform, stands for ____.","options":["General Internal Fund Monitoring and Inspection Scheme","Government Integrated Financial Management Information System","Government Investment Fund for Micro Industries Scheme","Global Integrated Finance and Monetary Index System"],"correctOption":1,"section":"Public Sector Reforms","explanation":"GIFMIS is the Government Integrated Financial Management Information System, used to improve budgetary control and financial reporting. Options A, C and D are invented expansions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 518, $official_bank_source${"itemId":"de5b6938-442e-5809-9029-0795282e819f","questionId":"46feb423-da31-5f2b-904d-7c2ded55bc6b","sourceKey":"bank:BUA205:PSR-023","payload":{"prompt":"Which pairing of Nigerian reform tool and its main contribution is CORRECT?","options":["IPPIS - improving budgetary control; GIFMIS - reducing ghost workers","IPPIS - reducing payroll fraud (ghost workers); GIFMIS - improving budgetary control","IPPIS - conducting elections; GIFMIS - issuing passports","IPPIS - collecting customs duty; GIFMIS - regulating telecoms"],"correctOption":1,"section":"Public Sector Reforms","explanation":"IPPIS cleans up payroll and personnel records, cutting ghost workers, while GIFMIS strengthens budgeting and financial management. Option A swaps the two tools. Options C and D assign functions belonging to unrelated agencies."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 519, $official_bank_source${"itemId":"7a5c3187-ae90-5a41-8459-acae242772a6","questionId":"3a65a008-2450-54df-8483-6354e0615acf","sourceKey":"bank:BUA205:PSR-024","payload":{"prompt":"The Treasury Single Account (TSA) is a reform that ____.","options":["allows each ministry to open as many commercial bank accounts as it wishes","transfers all government money to foreign banks","abolishes government revenue collection","consolidates government revenues into a unified account to centralise revenue, improve oversight and reduce leakages"],"correctOption":3,"section":"Public Sector Reforms","explanation":"TSA brings government agencies' inflows together in a unified account structure at the Central Bank of Nigeria, which improves oversight and reduces leakages. Option A describes the fragmented system that TSA replaced. Options B and C are not what TSA does."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 520, $official_bank_source${"itemId":"b1fcc739-cb0e-517e-84d9-bb8513a949d5","questionId":"b020f439-1b29-55a7-b53f-21550f2454f1","sourceKey":"bank:BUA205:PSR-025","payload":{"prompt":"Nigeria's Treasury Single Account consolidates federal government agencies' inflows into an account held at ____.","options":["the World Bank","the Central Bank of Nigeria","the Nigerian Stock Exchange","the Federal Inland Revenue Service"],"correctOption":1,"section":"Public Sector Reforms","explanation":"The TSA is held at the Central Bank of Nigeria, which acts as the government's banker. Option A is an international lender, and Option C is a securities market. Option D collects taxes but does not hold the TSA."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 521, $official_bank_source${"itemId":"e5c2c331-34c7-54a2-ab0d-1a1e3d6f2396","questionId":"94588acb-1e87-5eed-a286-26cd1e69fdfb","sourceKey":"bank:BUA205:PSR-026","payload":{"prompt":"Nigeria's TSA was piloted in 2012. Under which administration was full implementation across all federal MDAs mandated in 2015?","options":["President Olusegun Obasanjo","President Umaru Musa Yar'Adua","President Muhammadu Buhari","President Bola Tinubu"],"correctOption":2,"section":"Public Sector Reforms","explanation":"TSA was initiated under President Jonathan, with a pilot in 2012, and the Buhari administration mandated full implementation across all federal MDAs in 2015. Options A and B led Nigeria before TSA was introduced. Option D took office in 2023, long after full implementation."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 522, $official_bank_source${"itemId":"bd5615ed-d525-5b05-a79a-5cf6dde69c24","questionId":"846f6c53-0da1-5723-adb2-66e7f6fba9f0","sourceKey":"bank:BUA205:PSR-027","payload":{"prompt":"Reforms such as the Treasury Single Account have been credited with which effect on Nigerian government finances?","options":["Boosting Internally Generated Revenue (IGR)","Eliminating the need for a national budget","Increasing the number of ghost workers","Ending all public borrowing"],"correctOption":0,"section":"Public Sector Reforms","explanation":"TSA and related reforms have been credited with raising Internally Generated Revenue and reducing ghost workers, although their overall impact is still mixed. Options B and D overstate any reform's effect. Option C is the opposite of what these reforms achieve."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 523, $official_bank_source${"itemId":"ecd48e5a-72ca-51c4-be84-ebfd4a2fd9a1","questionId":"fd09c31d-a5d4-5ed4-b17b-4a59f4c2536b","sourceKey":"bank:BUA205:PSR-028","payload":{"prompt":"Establishing anti-corruption bodies such as the EFCC and ICPC is classified as which kind of core public sector reform component?","options":["Digital transformation","Structural and institutional reform","Administrative and human resource reform","Monetary policy reform"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Restructuring agencies, privatising public enterprises and creating anti-corruption bodies such as the EFCC and ICPC are structural and institutional reforms. Option A covers systems such as IPPIS and GIFMIS, and Option C covers capacity, ethics and performance management. Option D is the central bank's domain."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 524, $official_bank_source${"itemId":"94562618-b2bf-52e0-8efc-46bbcf17dfa0","questionId":"735f470f-ca1e-5311-a2de-416cb40a658e","sourceKey":"bank:BUA205:PSR-029","payload":{"prompt":"Strengthening capacity, enforcing ethics and implementing performance management systems are grouped under which core component of public sector reform?","options":["Policy and regulatory improvements","Financial management and accountability","Administrative and human resource reforms","Digital transformation and efficiency"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Capacity, ethics and performance management concern people and administration, so they are administrative and human resource reforms. Option A covers regulators and procurement rules. Option B covers tools such as TSA, and Option D covers electronic systems."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 525, $official_bank_source${"itemId":"e4ea04a8-0bca-5ad8-8720-3776a6bf9657","questionId":"a935ef64-44d9-5531-8c20-dea32d078930","sourceKey":"bank:BUA205:PSR-031","payload":{"prompt":"The law that established Nigeria's Bureau of Public Procurement and put the 'due process' approach to public procurement on a statutory footing is the ____.","options":["Freedom of Information Act 2011","Companies and Allied Matters Act 2020","Fiscal Responsibility Act 2007","Public Procurement Act 2007"],"correctOption":3,"section":"Public Sector Reforms","explanation":"The Public Procurement Act 2007 created the Bureau of Public Procurement and gave legal backing to due process in procurement. Option A deals with access to information, and Option B regulates companies. Option C deals with fiscal discipline and budgeting, not procurement procedures."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 526, $official_bank_source${"itemId":"31694728-a849-5a56-a0c4-eef8410323c4","questionId":"50b5cf6f-5d97-59d3-bf4b-4872502281f5","sourceKey":"bank:BUA205:PSR-032","payload":{"prompt":"Which of the following is NOT one of the key objectives of public sector reforms?","options":["Enhancing service delivery","Increasing the cost of governance","Combating corruption","Strengthening institutions"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Reforms aim to enhance service delivery, combat corruption, modernise the economy by reducing the cost of governance, and strengthen institutions. Increasing the cost of governance is the opposite of economic modernisation. Options A, C and D are listed objectives."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 527, $official_bank_source${"itemId":"b9b6881f-8236-5fa5-ad05-7e73cdf9c26e","questionId":"d28660d4-d972-5cc8-84e7-371163eb28ff","sourceKey":"bank:BUA205:PSR-033","payload":{"prompt":"The public sector reform objective of 'economic modernisation' involves ____.","options":["increasing the number of government agencies","banning private sector participation","aligning public services with market demands and reducing the cost of governance","returning to manual record keeping"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Economic modernisation means aligning public services with the needs of the market and cutting the cost of running government. Option A usually raises costs, Option B contradicts reforms such as PPPs, and Option D reverses digitalisation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 528, $official_bank_source${"itemId":"1de7d227-c202-5fa5-be9f-5171ec25acd9","questionId":"83d35b4d-9a80-505c-b910-7badb218277a","sourceKey":"bank:BUA205:PSR-034","payload":{"prompt":"Nigeria's Bureau of Public Service Reforms (BPSR) was established by the Federal Government in ____.","options":["1999","2004","2011","2016"],"correctOption":1,"section":"Public Sector Reforms","explanation":"The BPSR was established by the Federal Government on 4 February 2004 to drive public service reforms. Option A is the year of the return to civil rule. Option C is the year of the Freedom of Information Act, and Option D is the year Nigeria joined OGP."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 529, $official_bank_source${"itemId":"fe019159-f7d5-5485-912a-ecbf6923eb67","questionId":"fd017cdf-1d4e-5048-8eda-d87c2a4e6ef3","sourceKey":"bank:BUA205:PSR-035","payload":{"prompt":"The mandate of Nigeria's Bureau of Public Service Reforms (BPSR) is BEST described as ____.","options":["to prosecute corrupt public officials in court","to initiate, coordinate, monitor and ensure full implementation of government reform policies and programmes","to print and issue the national currency","to conduct recruitment examinations for universities"],"correctOption":1,"section":"Public Sector Reforms","explanation":"The BPSR exists to initiate, coordinate, monitor and ensure full implementation of government reform policies and programmes. Option A is the role of anti-graft agencies and the courts. Option C belongs to the central bank, and Option D to examination bodies."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 530, $official_bank_source${"itemId":"c35ba4f1-438d-5f00-ae41-0551a16407c0","questionId":"b57e58a2-2300-58ed-982b-aaad0e9c2d0a","sourceKey":"bank:BUA205:PSR-036","payload":{"prompt":"When initiating a public sector reform, why should baseline data on current performance be collected before changes begin?","options":["So that later results can be compared with the starting position to show whether the reform worked","So that the reform can avoid having any targets","Because baseline data replaces the need for implementation","So that stakeholders do not need to be consulted"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Baseline data records performance before the reform, which makes it possible to measure improvement afterwards. Option B is wrong because baselines are used to set targets. Options C and D misunderstand what a baseline is for."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 531, $official_bank_source${"itemId":"0ae1c82e-e422-56c5-abe4-77bb57ea8fe4","questionId":"da0bdf8a-7e4e-588f-8f57-189c72e2830d","sourceKey":"bank:BUA205:PSR-037","payload":{"prompt":"Why do reformers often pilot a reform in a few agencies before rolling it out nationwide, as Nigeria did when IPPIS started with seven MDAs?","options":["To make sure most agencies never adopt the reform","To avoid measuring the reform's results","To test the reform, learn from problems and fix them before scaling up","Because piloting removes all resistance to change"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Piloting lets reformers test the design on a small scale, learn lessons and adjust it before national roll-out, which lowers risk. Option A defeats the purpose of reform, and Option B is wrong because pilots are evaluated. Option D overstates what piloting can do."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 532, $official_bank_source${"itemId":"35c1f68e-57de-5a43-bbf6-59c1afa3863d","questionId":"a18d8337-2cfd-5779-87bb-be8ad91b8164","sourceKey":"bank:BUA205:PSR-038","payload":{"prompt":"A state government plans to merge two overlapping agencies. Staff fear job losses and rumours are spreading. Which step in initiating the reform would MOST directly address this resistance?","options":["Announcing the merger only after it is complete","Communicating the reasons for the change clearly and engaging staff and unions early","Refusing to meet staff representatives","Dropping all performance targets"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Resistance to change is reduced when people understand why a reform is needed and are consulted early, so a clear communication and engagement plan is a key step when initiating reform. Options A and C would deepen distrust. Option D would undermine the reform's purpose."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 533, $official_bank_source${"itemId":"ef64ee2b-2634-5baf-a54a-f860f2084345","questionId":"5fdb916f-1913-54a7-ba7a-94fc358621f0","sourceKey":"bank:BUA205:PSR-039","payload":{"prompt":"When initiating a public sector reform, identifying a reform 'champion' at senior political level is important MAINLY because ____.","options":["it removes the need for any civil servants","it guarantees the reform will cost nothing","it provides the political will and leadership needed to drive the reform and overcome resistance","it ensures the reform will not be evaluated"],"correctOption":2,"section":"Public Sector Reforms","explanation":"A senior champion supplies the sustained political will that reforms depend on and helps to overcome resistance. Option A is unrealistic, and Option B is false. Option D is wrong because a good champion wants results to be measured."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 534, $official_bank_source${"itemId":"c60c97ef-d8d6-5700-a772-79db71590c14","questionId":"98937933-e60b-57e6-9443-3bfdcf569f64","sourceKey":"bank:BUA205:PSR-040","payload":{"prompt":"Which of the following is NOT a supporting condition for a successful public sector reform?","options":["Sustained political will and commitment","Frequent changes of reform leadership and strategy","Adequate funding and human capacity","Clear strategy and stakeholder buy-in"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Reforms need sustained political will, adequate resources, capable staff, a clear strategy and stakeholder support. Frequent changes in leadership and strategy cause the political instability and lack of clear strategy that block reforms. Options A, C and D are genuine supporting conditions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 535, $official_bank_source${"itemId":"90b23fff-e7c5-52f4-8fce-66b4d4418522","questionId":"5eaadd30-4fa1-516e-a093-13d2c727fb06","sourceKey":"bank:BUA205:PSR-041","payload":{"prompt":"Which of the following is a key challenge that limits the effectiveness of public sector reforms in Nigeria?","options":["Implementation gaps arising from lack of political will and poor strategic planning","Too much citizen participation","Excessive funding of reform agencies","Too many trained civil servants"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Implementation gaps caused by weak political will and poor planning, together with resource constraints and capacity needs, limit reform effectiveness. Options B, C and D describe conditions that would help reforms rather than hinder them."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 536, $official_bank_source${"itemId":"0efa7005-14bf-58f8-ada2-c1f66007cbfa","questionId":"d636aeef-d945-5baa-a53d-c718d7c912e5","sourceKey":"bank:BUA205:PSR-042","payload":{"prompt":"Measuring the effectiveness of public sector reforms in Nigeria involves assessing improvements mainly in ____.","options":["transparency, financial accountability and service delivery","the popularity of the ruling party","the number of new government buildings","the salaries of political office holders"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Reform effectiveness is judged by gains in transparency, financial accountability and service delivery, often tracked through systems such as IPPIS and GIFMIS. Options B, C and D are not valid measures of whether reforms are working."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 537, $official_bank_source${"itemId":"8f4a448a-5eb8-586b-bbc3-c4d95d5d922b","questionId":"1e0eb2b8-74a9-5936-8ee0-430b1bbd47f4","sourceKey":"bank:BUA205:PSR-043","payload":{"prompt":"Assessing the speed, quality and accessibility of public services, and the impact of due process in procurement, is which category of indicator for measuring reform effectiveness?","options":["Economic impact","Service delivery and efficiency","Institutional strengthening","Financial performance and accountability"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Speed, quality and accessibility of services, plus the effects of due process, are service delivery and efficiency indicators. Option A looks at growth and wider development indicators. Option C looks at anti-graft agencies and IPSAS, and Option D looks at revenue, payroll fraud and budget control."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 538, $official_bank_source${"itemId":"28923a7c-d214-5e25-a96a-32cd3bd66a13","questionId":"b3819fc8-8934-5e16-8f7f-f548611d87b1","sourceKey":"bank:BUA205:PSR-044","payload":{"prompt":"Evaluating how effective anti-graft agencies (EFCC, ICPC) are, and how well International Public Sector Accounting Standards (IPSAS) have been implemented, falls under which category of reform effectiveness indicator?","options":["Institutional strengthening","Service delivery and efficiency","Economic impact","Citizen-centric focus"],"correctOption":0,"section":"Public Sector Reforms","explanation":"The effectiveness of anti-corruption bodies and the adoption of IPSAS measure how much stronger institutions have become. Option B measures the speed and quality of services, and Option C measures broader growth. Option D is a feature of successful reform, not an indicator category."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 539, $official_bank_source${"itemId":"2dc9a111-60d5-5edd-8bd3-165e2d00f58c","questionId":"c9da66d5-4ada-52d0-bbe8-c48ae6055007","sourceKey":"bank:BUA205:PSR-045","payload":{"prompt":"In public sector reform, IPSAS stands for ____.","options":["Integrated Public Service Appraisal Scheme","Internal Personnel Salary Adjustment System","International Procurement and Supply Audit Standards","International Public Sector Accounting Standards"],"correctOption":3,"section":"Public Sector Reforms","explanation":"IPSAS are the International Public Sector Accounting Standards, used to improve the quality and comparability of government financial reports. Options A, B and C are invented expansions."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 540, $official_bank_source${"itemId":"1f51e744-83ae-5bde-b9e6-b6d846183e9a","questionId":"05407b47-f7c1-5891-921b-f9f06c50c246","sourceKey":"bank:BUA205:PSR-046","payload":{"prompt":"A tool in which citizens rate the availability, quality and responsiveness of public services through surveys, giving agencies direct user feedback on reform results, is called a ____.","options":["treasury single account","citizen report card (citizen satisfaction survey)","payroll audit","letter of intent"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Citizen report cards and satisfaction surveys measure reform effectiveness from the service user's point of view. Option A is a cash-management reform, and Option C checks payroll records. Option D is a request to join an initiative such as OGP."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 541, $official_bank_source${"itemId":"93541287-0c67-515f-a3fe-4908d0235faa","questionId":"fcdb7bdf-61de-5d62-b032-74b091924efd","sourceKey":"bank:BUA205:PSR-047","payload":{"prompt":"Comparing an agency's performance indicators with those of similar agencies, or with recognised good-practice standards, in order to judge reform progress is called ____.","options":["scapegoating","right-sizing","benchmarking","co-creation"],"correctOption":2,"section":"Public Sector Reforms","explanation":"Benchmarking measures performance against peers or standards to show where an agency stands and how far it has improved. Option A is a crisis-response strategy of blaming others. Option B is a restructuring feature, and Option D is joint design of plans with civil society."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 542, $official_bank_source${"itemId":"a5b8802e-6f7f-5ca7-a759-1bf0a69f3f6b","questionId":"ad9465cf-e76a-5f6a-a7c5-b97cfdf7b19a","sourceKey":"bank:BUA205:PSR-048","payload":{"prompt":"An independent examination, often carried out by the Auditor-General, of whether a public programme achieved economy, efficiency and effectiveness, is called a ____.","options":["financial statement audit only","census","holding statement","performance (value-for-money) audit"],"correctOption":3,"section":"Public Sector Reforms","explanation":"A performance or value-for-money audit tests whether a programme delivered the three Es, not just whether its accounts balance. Option A checks the accuracy of financial reports only. Option B counts the population, and Option C is a crisis communication tool."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 543, $official_bank_source${"itemId":"807146c9-f0bc-52c3-ba71-60ac7cf8270c","questionId":"9e4c1e2a-bda7-5f1c-b562-8122df40685d","sourceKey":"bank:BUA205:PSR-049","payload":{"prompt":"To evaluate a payroll reform, a ministry compares the number of names on its payroll and its monthly wage bill before and after the reform, and finds 1,200 fictitious names removed. The ministry is measuring reform effectiveness mainly through ____.","options":["financial performance and accountability indicators","economic impact indicators","citizen satisfaction surveys","institutional independence of the judiciary"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Reduced payroll fraud and a lower wage bill are financial performance and accountability indicators, the kind IPPIS is meant to improve. Option B would look at growth and wider development, and Option C would ask service users for their views. Option D is unrelated to payroll."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua205', 'add', 544, $official_bank_source${"itemId":"220bba02-76e4-55e5-b62c-6d588846fe90","questionId":"3fa0fc50-6b7d-5bd0-a717-aff358a42036","sourceKey":"bank:BUA205:PSR-050","payload":{"prompt":"A survey that follows public funds from the central government through each level down to frontline units such as schools and clinics, to find out how much actually arrives, is called a ____.","options":["citizen report card","population census","beneficial ownership register","Public Expenditure Tracking Survey (PETS)"],"correctOption":3,"section":"Public Sector Reforms","explanation":"A Public Expenditure Tracking Survey traces the flow of money to frontline service units and shows leakages along the way, which makes it a useful tool for measuring financial management reforms. Option A collects users' views of service quality rather than tracing funds. Options B and C measure population and company ownership."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 545, $official_bank_source${"itemId":"e2ee4017-84b5-5c48-8cbe-62f6a66f66d8","questionId":"9f5e2fb3-9809-5c73-921d-daae2a7bce23","sourceKey":"bank:BUA205:NB-063","payload":{"prompt":"Which list correctly states the key objectives of public sector reform?","options":["Decentralisation, PDIA, New Public Management techniques and digital transformation","Political instability, lack of strategy and resistance to change","Enhancing service delivery, combating corruption, economic modernisation and strengthening institutions","Civil service restructuring, IFMIS and public-private partnerships"],"correctOption":2,"section":"Public Sector Reforms","explanation":"The key objectives of public sector reform are to enhance service delivery, combat corruption, achieve economic modernisation and strengthen institutions. Option B lists common obstacles to reform, Option A lists features of successful reforms, and Option D lists major reform initiatives rather than the objectives they serve."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 546, $official_bank_source${"itemId":"9940f6bc-6567-5e37-8ce9-f069f7538e27","questionId":"3ea468db-1c65-54fb-8691-bef9bfe05609","sourceKey":"bank:BUA205:NB-064","payload":{"prompt":"A state government introduces a reform whose main aim is to stop officials from inflating contract prices and diverting public funds into private pockets. Which objective of public sector reform is it chiefly pursuing?","options":["Combating corruption","Strengthening institutions","Enhancing service delivery","Economic modernisation"],"correctOption":0,"section":"Public Sector Reforms","explanation":"Stopping contract inflation and the diversion of public funds is directly about combating corruption. Option C focuses on how well citizens are served, Option D on modernising the economy and the cost of governance, and Option B on building the capacity of public bodies, none of which is the main aim described."}}$official_bank_source$::jsonb),
  ('official_bank_bua205', 'add', 547, $official_bank_source${"itemId":"fa912f54-d967-51fa-aea8-5f7d5e77ded9","questionId":"fa8c9fba-1755-589e-9ebb-3f5adaf5e5f3","sourceKey":"bank:BUA205:NB-065","payload":{"prompt":"A federal reform cuts the time citizens wait to receive their international passports from six weeks to one week. Which objective of public sector reform does this mainly serve?","options":["Economic modernisation","Enhancing service delivery","Strengthening institutions","Combating corruption"],"correctOption":1,"section":"Public Sector Reforms","explanation":"Making a public service faster and easier for citizens to obtain is enhancing service delivery. Option D is about stopping abuse of office, Option A is about modernising the economy and reducing the cost of governance, and Option C is about building the capacity and independence of public bodies."}}$official_bank_source$::jsonb);
